/* Quiz pools, keyed by chapter slug. Schema: CLAUDE.md §9.
   window.QUIZ_POOLS[slug] = [{ id, type, question, options, answerIndex, explanation }]
   type is one of: concept | scenario | bug | compare */
window.QUIZ_POOLS = {
  "how-to-use-this-course": [
    { id: "htuc-01", type: "concept", question: "What does \"mastery\" mean in this course's own definition, as stated in chapter 0?", options: ["Being able to navigate the Keycloak admin console from memory", "Being able to explain why Keycloak is built the way it is, not just where its buttons are", "Passing every chapter quiz with a perfect score", "Memorizing every RFC referenced in the deep-dive links"], answerIndex: 1, explanation: "The course explicitly frames mastery as explaining the underlying IAM concept behind a Keycloak feature, not just operating the console." },
    { id: "htuc-02", type: "concept", question: "Where is your quiz score for a chapter actually stored?", options: ["On the course's server, tied to your account", "In a cookie that syncs across devices", "In your browser's localStorage, under a key like iam:quiz:<slug>", "Nowhere — scores are not retained between visits"], answerIndex: 2, explanation: "There is no server or account. QuizEngine reads/writes a per-chapter localStorage key such as iam:quiz:how-to-use-this-course." },
    { id: "htuc-03", type: "concept", question: "Which chapter contains the first hands-on lab against a real, running Keycloak instance?", options: ["Chapter 1", "Chapter 13", "Chapter 20", "Chapter 31"], answerIndex: 2, explanation: "Parts I-III (chapters 1-18) are concept-only; chapter 20, opening Part IV, is the first real Keycloak lab." },
    { id: "htuc-04", type: "concept", question: "According to this chapter's pitfall callout, what should you avoid doing before chapter 20?", options: ["Installing Docker", "Installing a JDK", "Installing and running Keycloak itself", "Installing curl or Postman"], answerIndex: 2, explanation: "The course deliberately delays Keycloak installation until chapter 20 so the concept chapters build a mental model first; installing it early tends to produce button-clicking without context." },
    { id: "htuc-05", type: "scenario", question: "A reader clears their browser's site data between sessions and finds all their quiz scores reset to zero. What's the most accurate explanation?", options: ["This is a bug in QuizEngine that should be reported", "Scores are stored only in that browser's localStorage, which clearing site data erases, and there's no other copy", "Scores are tied to the reader's IP address, which changed", "Quiz scores expire automatically after 24 hours"], answerIndex: 1, explanation: "There's no server-side copy of progress — localStorage is the only place scores live, so clearing it (or switching browsers/devices) loses them." },
    { id: "htuc-06", type: "scenario", question: "A reader is three chapters into Part I and has no Docker containers running at all. Should they be worried they've missed a setup step?", options: ["Yes, every chapter requires Keycloak running in the background", "No, Parts I-III are concept-only and need no Keycloak instance; the first lab is chapter 20", "Yes, but only if they skipped chapter 0's Docker installation", "No, but they should at least have Postman open"], answerIndex: 1, explanation: "Part I-III chapters are explicitly concept-only per chapter 0 — nothing needs to be running yet." },
    { id: "htuc-07", type: "concept", question: "What happens when you retake a chapter's quiz a second time?", options: ["You get the exact same questions in the exact same order", "A random subset of the pool is drawn again and both question order and each question's answer options are reshuffled", "The quiz becomes permanently locked after the first attempt", "Your previous best score is discarded and only the new attempt counts"], answerIndex: 1, explanation: "QuizEngine shuffles the pool, takes a subset, and shuffles each question's option order on every render — and it tracks best score across attempts, not just the latest." },
    { id: "htuc-08", type: "concept", question: "What is the stated purpose of the \"self-check\" questions that appear before the graded quiz in every chapter?", options: ["They are a harder, bonus version of the quiz", "They are open-ended thinking prompts with no shown answer, meant to be answered before the graded quiz", "They replace the quiz for chapters with no lab", "They are auto-graded along with the quiz"], answerIndex: 1, explanation: "Self-check questions have no inline answer shown — they're a check on your own understanding, separate from the scored quiz." },
    { id: "htuc-09", type: "concept", question: "How many Parts does the full 50-chapter curriculum have (including Part 0 orientation)?", options: ["8", "9", "11", "14"], answerIndex: 2, explanation: "Part 0 (orientation) plus Parts I through XI makes 11 Parts total." },
    { id: "htuc-10", type: "scenario", question: "A reader asks why the course doesn't let them skip straight to the Keycloak chapters since that's the product they actually want to learn. What's the course's own argument against doing that?", options: ["The Keycloak chapters technically require completing the quizzes from Parts I-III to unlock", "Keycloak chapters assume the Part I-III concepts and only recall them in one paragraph; skipping them risks being able to configure Keycloak without being able to explain why any of it works that way", "Keycloak chapters are harder and need the extra practice time from earlier chapters", "There is no argument — skipping ahead is explicitly supported and encouraged"], answerIndex: 1, explanation: "The course's stated failure mode is exactly this: knowing how to click through the console without understanding the underlying IAM concept." },
    { id: "htuc-11", type: "concept", question: "Which two commands does chapter 0 ask you to run right now, in its \"Try it\" callout, just to confirm your environment?", options: ["kcadm.sh --version and keycloak --version", "docker --version and java -version", "curl --version and postman --version", "node --version and python --version"], answerIndex: 1, explanation: "The try-it callout asks only for docker --version and java -version — confirming the two tools needed starting Part IV, without installing or configuring anything yet." },
    { id: "htuc-12", type: "scenario", question: "Starting in chapter 2, a quiz question references \"Riverside Health\" without further introduction. What should a reader who only read chapter 0 expect?", options: ["This is an error — chapter 0 should have defined Riverside Health already", "It's one of three recurring fictional organizations previewed in chapter 0 and formally introduced with detail in chapter 2", "It refers to a real healthcare company the course is case-studying", "It's unrelated background flavor text with no bearing on the question"], answerIndex: 1, explanation: "Chapter 0 deliberately previews the three orgs by name only, leaving Northwind/Riverside/Meridian's actual details to chapter 2, which owns that introduction." }
  ],

  "what-is-iam": [
    { id: "wii-01", type: "concept", question: "What is the core problem IAM exists to solve?", options: ["Making login pages visually consistent across apps", "Answering \"who is this\" and \"what can they do\" once, centrally, instead of per application", "Replacing passwords entirely with biometrics", "Reducing the number of applications a company runs"], answerIndex: 1, explanation: "IAM is fundamentally a de-duplication strategy for the authentication and authorization problem, not primarily a UI or password-elimination concern." },
    { id: "wii-02", type: "concept", question: "Which one-sentence description correctly distinguishes authentication from authorization?", options: ["Authentication decides what you can do; authorization proves who you are", "Authentication proves who you are; authorization decides what you can do", "They are two names for the same process", "Authentication only applies to passwords; authorization only applies to tokens"], answerIndex: 1, explanation: "Authentication answers \"who are you?\"; authorization answers \"what are you allowed to do, now that I know who you are?\" Chapter 3 covers both in depth." },
    { id: "wii-03", type: "scenario", question: "A company has ten internal applications, each built by a different team at a different time, each with its own login form and password storage. What is the most likely outcome described in this chapter, rather than ten solid independent login systems?", options: ["Ten identical, interchangeable login systems", "Ten slightly different login systems with uneven security quality and no shared audit trail", "One team eventually builds all ten logins to a consistent standard", "The applications automatically converge on a shared password store"], answerIndex: 1, explanation: "Without centralization, each team solves the same problem independently, at different quality levels, producing inconsistent security and no single audit answer." },
    { id: "wii-04", type: "compare", question: "How does identity brokering differ from federation, as introduced in this chapter?", options: ["Brokering delegates authentication to an external identity provider; federation connects to an existing external identity store like LDAP", "They are the same concept with different names", "Brokering only works with passwords; federation only works with biometrics", "Federation is a Keycloak-specific feature; brokering is vendor-agnostic"], answerIndex: 0, explanation: "Brokering is about delegating the authentication act itself (e.g. \"Login with Google\"); federation is about reusing an existing identity store's accounts and credentials. Both are covered in depth in chapter 7." },
    { id: "wii-05", type: "concept", question: "Which of the following is NOT listed in this chapter as part of the common IAM feature set?", options: ["Single Sign-On", "Self-service account management", "Fine-grained authorization", "Automatic code deployment pipelines"], answerIndex: 3, explanation: "Deployment pipelines are unrelated to IAM's feature set; SSO, self-service, and fine-grained authorization are all standard IAM capabilities covered in this chapter." },
    { id: "wii-06", type: "scenario", question: "Priya has access to three applications (HR portal, wiki, reporting dashboard) through one centrally managed identity. On her last day, an administrator disables that one identity. What happens?", options: ["Nothing changes until each app's admin separately disables her account", "Access to all three applications is revoked at once, from a single action", "Only the HR portal access is revoked automatically", "She retains read-only access to all three apps indefinitely"], answerIndex: 1, explanation: "This is the core benefit of centralized identity: disabling one identity propagates access removal everywhere that identity was trusted, instead of requiring N separate offboarding steps." },
    { id: "wii-07", type: "concept", question: "According to this chapter, is adopting a centralized IAM system equivalent to \"being secure\"?", options: ["Yes, IAM adoption automatically eliminates security risk", "No — it removes a recurring source of bugs but introduces its own configuration surface that must be secured carefully", "No, IAM systems are inherently less secure than per-app authentication", "Yes, as long as MFA is enabled"], answerIndex: 1, explanation: "The pitfall callout explicitly warns that centralizing authentication relocates risk to a new configuration surface (e.g. redirect URIs, role mappings) rather than eliminating it." },
    { id: "wii-08", type: "scenario", question: "A small internal tool has one trusted admin user and no plans to add more applications or users. Per this chapter's guidance, should the team adopt a full centralized IAM system?", options: ["Yes, always — IAM should be adopted for every application regardless of scale", "Probably not — this is a case where a dedicated IAM system is likely overkill", "Only if the tool uses passwords instead of SSH keys", "Yes, but only if the company has more than 50 employees"], answerIndex: 1, explanation: "The chapter explicitly lists a single small internal tool with a handful of trusted users as a legitimate case where full IAM adoption is overkill." },
    { id: "wii-09", type: "compare", question: "Which pairing correctly reflects a trade-off of adopting a centralized IAM system, per this chapter's pros/cons table?", options: ["Pro: reduces the chance of building authentication wrong — Con: introduces a new single point of failure if the IAM system goes down", "Pro: eliminates all operational overhead — Con: makes offboarding slower", "Pro: removes the need for audit trails — Con: requires more passwords per user", "Pro: guarantees compliance — Con: has no learning curve"], answerIndex: 0, explanation: "Centralizing reduces inconsistent, error-prone per-app authentication logic, but also means that if the shared IAM system is unavailable, every connected application's login is unavailable too." },
    { id: "wii-10", type: "concept", question: "What does an \"audit trail,\" as described in this chapter, primarily let an organization do?", options: ["Automatically fix misconfigured redirect URIs", "Answer \"who accessed what, and when\" consistently across connected applications", "Generate password reset emails", "Enforce multi-factor authentication"], answerIndex: 1, explanation: "A centralized audit trail consolidates authentication and access events into one consistent record, instead of scattering them across each application's own (or absent) logging." },
    { id: "wii-11", type: "scenario", question: "An enterprise customer wants to log in to a SaaS vendor's product using their own corporate directory rather than creating a new password. Which IAM capability, introduced in this chapter, most directly addresses this?", options: ["Self-service account management", "Federation / identity brokering with an external identity provider", "Password expiration policy", "Admin console audit logging"], answerIndex: 1, explanation: "Federation and identity brokering exist precisely to let users authenticate via an external directory or identity provider instead of creating yet another standalone credential." },
    { id: "wii-12", type: "concept", question: "Per this chapter, where does Keycloak fit relative to the IAM concepts being taught?", options: ["Keycloak defines what IAM is; the concepts only apply to Keycloak", "Keycloak is this course's chosen implementation vehicle for vendor-agnostic IAM concepts; other products (Okta, Auth0, Entra ID, Ping) implement the same ideas differently", "Keycloak is a compliance framework, not an IAM product", "Keycloak only handles authorization, not authentication"], answerIndex: 1, explanation: "The chapter is explicit that Keycloak is one of several mature IAM products implementing these ideas, with the wider market comparison deferred to chapter 12." },
    { id: "wii-13", type: "scenario", question: "A mobile app needs a secure, standardized way to prove to a backend API that its user is logged in, without inventing a custom session-cookie scheme. What does centralized IAM typically provide for this?", options: ["A custom per-app cookie format", "Standardized, interoperable tokens, covered in depth in Part III", "A shared plaintext password file", "Nothing — mobile apps must build this themselves"], answerIndex: 1, explanation: "Standardized tokens are one of the problems listed in the \"why centralizing matters\" table — mobile and API clients get an interoperable, standard way to carry proof of authentication instead of ad-hoc per-app schemes." },
    { id: "wii-14", type: "compare", question: "How does Workforce IAM differ from CIAM, as briefly introduced in this chapter?", options: ["Workforce IAM manages an organization's own employees/internal access; CIAM manages external customer-facing identities", "Workforce IAM is cloud-only; CIAM is on-premises only", "CIAM only supports SAML; Workforce IAM only supports OIDC", "They are identical, just different marketing terms"], answerIndex: 0, explanation: "Workforce IAM targets internal employee/system access, while CIAM targets external customers at consumer scale — chapter 12 covers this distinction in depth." },
    { id: "wii-15", type: "concept", question: "What does \"extensibility\" (or plugin architecture) mean in the context of an IAM system, per this chapter?", options: ["The ability to add more passwords per user", "The ability to customize authentication steps, data sources, or branding via a defined plugin interface instead of forking the product", "The ability to run on more servers simultaneously", "The ability to support more languages in the login page only"], answerIndex: 1, explanation: "Extensibility refers to a plugin/SPI-style architecture for customization without modifying the core product — Keycloak's version of this is covered in Part VIII." },
    { id: "wii-16", type: "scenario", question: "A compliance auditor asks a company using ten disconnected, home-grown login systems: \"who had access to the patient database last quarter?\" Based on this chapter, what is the most likely problem?", options: ["The company can answer instantly from a single audit log", "There is no single consistent answer, because access and logging are scattered across separate, uncoordinated systems", "The question is irrelevant to IAM", "Only the database administrator needs to answer this, not the application teams"], answerIndex: 1, explanation: "One of the core problems centralized IAM solves is exactly this: without it, there's no single, consistent audit trail spanning all applications." },
    { id: "wii-17", type: "concept", question: "Per this chapter, which statement about MFA within the IAM feature set is accurate?", options: ["MFA replaces authentication entirely and makes passwords unnecessary", "MFA requires more than one proof of identity, such as a password plus a one-time code or hardware key", "MFA is a form of authorization, not authentication", "MFA is unique to Keycloak and not found in other IAM products"], answerIndex: 1, explanation: "MFA adds additional authentication factors beyond (or instead of) a password alone; it is a standard, vendor-agnostic IAM capability, covered in depth in chapter 5." },
    { id: "wii-18", type: "compare", question: "Which best contrasts the \"without centralized IAM\" and \"with centralized IAM\" worlds for handling a departing employee?", options: ["Without IAM: one action disables access everywhere. With IAM: access must be revoked in each system separately", "Without IAM: access must be chased down and revoked in each separate system. With IAM: disabling one identity removes access everywhere it's connected", "Both worlds require exactly the same offboarding effort", "Centralized IAM has no effect on offboarding"], answerIndex: 1, explanation: "This is one of the clearest wins of centralization: offboarding collapses from N separate actions into one, as illustrated by the Priya example and the comparison table." }
  ],

  "identity-fundamentals": [
    { id: "idf-01", type: "concept", question: "Jane Doe's system record lists her identifier as jane.doe@northwindapps.com. Which of the following is also true of an identifier, by definition?", options: ["It must remain secret at all times", "It uniquely designates the identity for lookup within some namespace", "It changes every time the credential is rotated", "It always expires after a fixed lifetime"], answerIndex: 1, explanation: "An identifier only needs to be unique within its namespace; unlike a credential, it does not need to stay secret." },
    { id: "idf-02", type: "scenario", question: "At Meridian Trust, a teller is asked to enter a one-time code generated by an authenticator app in addition to her password before approving a wire transfer. In IAM terms, what role does that one-time code play?", options: ["It's an attribute", "It's an identifier", "It's a credential — evidence she controls a factor tied to her identity", "It's a principal"], answerIndex: 2, explanation: "A one-time code is evidence of control over a factor, which makes it a credential, just like a password." },
    { id: "idf-03", type: "scenario", question: "Riverside Health records patientsPortalEnabled: true as a flag on certain patient identities to control which app features they see. What IAM concept does this flag represent?", options: ["Credential", "Attribute — a recorded fact about the identity", "Identifier", "Subject"], answerIndex: 1, explanation: "A flag that describes the identity rather than proving control of it is an attribute, not a credential." },
    { id: "idf-04", type: "compare", question: "What is the formal distinction between a principal and a subject?", options: ["A principal is always a human; a subject is always a machine", "A principal is the entity being identified; a subject is that entity as represented in an active security context such as a token or session", "A subject always outlives the principal it represents", "There is no distinction — the terms are fully interchangeable in every IAM specification"], answerIndex: 1, explanation: "The principal is the real-world entity; the subject is that entity inside one active context, like a specific token." },
    { id: "idf-05", type: "scenario", question: "Jane logs into Northwind Apps and gets an access token. Later her session expires and she logs in again, getting a new token. Across these two logins, what stayed the same and what changed?", options: ["The principal changed; the subject stayed the same", "Both the principal and the subject changed completely", "The principal (Jane, the real identity) stayed the same; a new subject (a new token/session context) was created each time she authenticated", "Neither changed — tokens are principals"], answerIndex: 2, explanation: "One principal can produce many subjects over time, one per authentication event." },
    { id: "idf-06", type: "scenario", question: "Riverside Health's HR-integrated system has an admin create a new nurse's account before her first day, rather than letting her sign up herself. Which lifecycle entry point does this describe?", options: ["Self-registration", "Federated/brokered creation", "Manual creation", "Deprovisioning"], answerIndex: 2, explanation: "An administrator directly creating the account ahead of time is manual creation." },
    { id: "idf-07", type: "scenario", question: "Meridian Trust's fraud team flags suspicious activity on a teller's account and temporarily blocks her login while HR investigates, planning to restore access if she's cleared. Which lifecycle stage is this?", options: ["Delete", "Modify", "Suspend", "Activate"], answerIndex: 2, explanation: "Blocking access temporarily, with the possibility of reinstatement, is the suspend stage." },
    { id: "idf-08", type: "concept", question: "In the generalized identity lifecycle this chapter describes, which is the correct order of stages?", options: ["Activate → Create → Suspend → Modify → Delete", "Create → Activate → Modify → Suspend → Delete", "Create → Suspend → Activate → Delete → Modify", "Modify → Create → Activate → Delete → Suspend"], answerIndex: 1, explanation: "The generalized order is create, activate, modify, suspend, delete." },
    { id: "idf-09", type: "scenario", question: "A prospective customer signs up for a free Northwind Apps trial by filling out a signup form directly on Northwind's marketing site. Which entry point created this identity?", options: ["Manual creation", "Self-registration", "Federated/brokered creation", "Deprovisioning"], answerIndex: 1, explanation: "The principal created her own identity through a signup form, which is self-registration." },
    { id: "idf-10", type: "scenario", question: "Riverside Health's lab-results integration runs under a dedicated account that polls an imaging system every five minutes, with no human ever entering a password for it. What kind of identity is this?", options: ["Human identity", "A principal without a subject", "Service account / machine identity", "A self-registered identity"], answerIndex: 2, explanation: "An unattended account used by an automated process is a non-human identity — a service account." },
    { id: "idf-11", type: "concept", question: "Why does distinguishing human from non-human identities matter in practice?", options: ["Non-human identities never need any access controls", "Service accounts and workload identities often have long-lived, broad, or unattended access, so reviewing and least-privileging them requires different processes than reviewing a human employee's access", "Human identities are always more privileged than service accounts", "The distinction is purely cosmetic and has no security implications"], answerIndex: 1, explanation: "Non-human identities tend to be long-lived and unattended, which creates distinct governance risk." },
    { id: "idf-12", type: "compare", question: "A user logs into Northwind Apps for the first time by clicking 'Sign in with Microsoft,' and Northwind creates a local record for her automatically from the data Microsoft returns. Which entry point is this, and how does it differ from self-registration?", options: ["Self-registration — identical to filling out a signup form", "Federated/brokered creation — the identity is created automatically from an external identity provider's assertion rather than the user filling out a form directly", "Manual creation — an admin created it in advance", "Deprovisioning — the account is being removed"], answerIndex: 1, explanation: "Federated/brokered creation builds the local identity from an external IdP's data on first login, unlike a self-filled signup form." },
    { id: "idf-13", type: "concept", question: "In IAM terms, what is deprovisioning?", options: ["Creating a new identity for an employee's first day", "The process of removing or disabling an identity's access, typically at the end of its lifecycle (e.g., when an employee leaves)", "Issuing a new credential to replace an expired one", "Adding a new attribute to an existing identity"], answerIndex: 1, explanation: "Deprovisioning is removing or disabling access at the end of the identity lifecycle." },
    { id: "idf-14", type: "scenario", question: "Meridian Trust's auditors specifically want to know whether a flagged account was suspended-then-reinstated or deleted-then-recreated. Why does this distinction matter for an audit trail?", options: ["It doesn't matter — both produce identical records", "Suspend-then-reinstate preserves the original identity record and its history under one continuous identifier, while delete-then-recreate breaks that continuity and can obscure that it's the same real-world person", "Deletion is always reversible, so there's no difference", "Suspension always permanently deletes credentials"], answerIndex: 1, explanation: "Suspend preserves continuity of the record; delete-and-recreate breaks it, which matters for audit trails." },
    { id: "idf-15", type: "concept", question: "For the same person, which pairing correctly matches concept to example?", options: ["Identity = jane.doe@northwindapps.com; Identifier = Jane's full account record", "Credential = department: Engineering; Attribute = her password", "Identity = the full record representing 'Jane Doe, Northwind engineer'; Identifier = jane.doe@northwindapps.com; Credential = her password/OTP; Attribute = department: Engineering", "All four terms describe the same thing and are interchangeable"], answerIndex: 2, explanation: "Identity is the whole record, identifier is the lookup handle, credential is proof of control, and attribute is a recorded fact." },
    { id: "idf-16", type: "scenario", question: "A Northwind Apps access token is stolen and used by an attacker before it expires. In principal/subject terms, what happened?", options: ["The principal (Jane) was compromised directly; no subject was involved", "The attacker became a new principal", "The attacker gained control of a valid subject (the active session/token) without being the principal it was issued to", "Nothing changed, since principal and subject are identical"], answerIndex: 2, explanation: "Token theft compromises a subject (one active context), not the underlying principal, which is why the two concepts matter separately for incident response." }
  ],

  "authn-authz-accounting": [
    { id: "aaa-01", type: "concept", question: "In the formal AAA model, what question does the \"Accounting\" part answer?", options: ["Who are you?", "What are you allowed to do?", "What did you actually do, and when?", "Should this request be rate-limited?"], answerIndex: 2, explanation: "Accounting is the real-time recording of identity and access events — what happened, and when — distinct from the authentication (\"who\") and authorization (\"what can\") questions." },
    { id: "aaa-02", type: "concept", question: "What is the most accurate way to describe the relationship between accounting and audit?", options: ["They are two names for the exact same activity", "Accounting is the real-time recording act; audit is the later review of what was recorded", "Audit happens first and accounting happens afterward", "Accounting only applies to billing, audit only applies to security"], answerIndex: 1, explanation: "Accounting continuously records events as they occur; audit is a separate, later activity (scheduled or incident-triggered) that reviews those recorded events." },
    { id: "aaa-03", type: "concept", question: "Why does this chapter flag \"accounting\" as a term with some terminology ambiguity across fields?", options: ["Because it's a deprecated term nobody uses anymore", "Because in classic RADIUS/network-access contexts it leans toward usage metering for billing, while general modern IAM usage leans toward security-event logging", "Because only Keycloak uses the term", "Because accounting and authentication are legally synonymous"], answerIndex: 1, explanation: "The chapter is explicit that RADIUS-style usage of \"accounting\" (metering for billing/capacity) differs from the broader, security-logging sense most modern IAM writing uses." },
    { id: "aaa-04", type: "scenario", question: "Maria authenticates into Riverside Health's patient portal with a correct password and MFA code, then edits a URL to view a different patient's chart and succeeds. What failed?", options: ["Authentication — her credentials should have been rejected", "Authorization — the system never checked whether she has a care relationship with that patient", "Accounting — the event wasn't logged", "Nothing failed; this is expected behavior"], answerIndex: 1, explanation: "Her authentication was flawless. The system never asked the authorization question of whether she specifically may view that patient's record — a classic insecure-direct-object-reference-style authorization failure." },
    { id: "aaa-05", type: "bug", question: "A developer writes: `if (isLoggedIn(session)) { return db.getChart(patientId); }`. What is the specific bug?", options: ["The session check is performed in the wrong order", "It uses authentication as a substitute for authorization — it never checks whether this specific user may access this specific patientId", "It's missing a database index", "It incorrectly logs the access event twice"], answerIndex: 1, explanation: "This is the chapter's canonical AuthN/AuthZ conflation bug: a valid login is treated as sufficient to serve any record, when a separate permission/ownership check was required." },
    { id: "aaa-06", type: "bug", question: "A developer writes: `if (hasRole(user, \"employee\")) { invoices.approve(invoiceId); }`. Is this the same bug as checking `isLoggedIn`?", options: ["Yes, it's identical — both skip authorization entirely", "No — this one does perform an authorization check, but the check is scoped too broadly (any employee, instead of this specific employee for this specific invoice)", "No — this one is actually a correct and sufficiently scoped check", "Yes, because \"employee\" is an authentication role, not an authorization role"], answerIndex: 1, explanation: "This is a distinct bug from pure AuthN/AuthZ conflation: the shape is correct (it is a permission check), but the granularity is wrong — it authorizes at too broad a scope." },
    { id: "aaa-07", type: "scenario", question: "A Northwind Apps engineer at customer tenant \"Acme Corp\" authenticates successfully, but the backend only checks \"does this user belong to some paying tenant\" rather than \"does this user belong to this specific tenant\" before returning dashboard data. What's at risk?", options: ["Nothing — tenant checks aren't an IAM concern", "Cross-tenant data exposure — she could potentially view another customer's dashboard despite authenticating correctly", "Only her own data is at risk", "This is purely an accounting/audit-trail problem"], answerIndex: 1, explanation: "This mirrors the IDOR pattern: correct authentication, but an authorization check scoped incorrectly (any tenant instead of this specific tenant) exposes cross-tenant data." },
    { id: "aaa-08", type: "concept", question: "Which of these is a correct pairing of AAA question to example?", options: ["Authentication — \"does jane.doe have permission to approve this invoice?\"", "Authorization — \"is this password correct for jane.doe?\"", "Accounting — \"record that jane.doe approved invoice #4821 at 14:02 UTC\"", "Audit — \"issue jane.doe a one-time code\""], answerIndex: 2, explanation: "Accounting is the act of recording what happened, as structured timestamped data — exactly the invoice-approval log example." },
    { id: "aaa-09", type: "scenario", question: "HIPAA requires Riverside Health to be able to tell a patient exactly who accessed their chart and when, on request. Which part of AAA does this directly depend on?", options: ["Authentication only", "Authorization only", "Accounting — without continuous event recording, there is nothing to answer the request from", "None of AAA; this is purely a database backup requirement"], answerIndex: 2, explanation: "HIPAA's access-accounting requirement depends on Riverside having recorded (accounted for) every access as it happened — it can't be reconstructed after the fact without that trail." },
    { id: "aaa-10", type: "scenario", question: "Meridian Trust's PCI-DSS obligations require tracking and monitoring access to cardholder data. If Meridian has rigorous accounting but never actually reviews the resulting logs, what is missing?", options: ["Authentication", "Authorization", "Audit — the review step that compliance and assessors actually require, not just the raw recorded data", "Nothing is missing; recording alone satisfies PCI-DSS"], answerIndex: 2, explanation: "PCI-DSS expects both tracking (accounting) and regular review (audit) of access logs — accounting alone, unreviewed, doesn't satisfy the monitoring expectation." },
    { id: "aaa-11", type: "compare", question: "How does an authentication failure differ from an authorization failure, in terms of what an attacker needs?", options: ["They require the same attacker capability in all cases", "An authentication failure typically means proving a false identity (stolen/guessed credentials); an authorization failure can happen even with a fully legitimate, correctly authenticated identity", "Authorization failures only happen to administrators", "Authentication failures are always worse than authorization failures"], answerIndex: 1, explanation: "The chapter's running point: authorization failures (like IDOR) often require no stolen credentials at all — the attacker may be a fully legitimate, correctly authenticated user exploiting a missing permission check." },
    { id: "aaa-12", type: "concept", question: "In Keycloak, where does the \"Accounting\" part of AAA map most directly?", options: ["The Authentication flows screen", "The Roles and Groups screens", "The realm's Events subsystem (Realm settings → Events)", "The Clients screen"], answerIndex: 2, explanation: "Keycloak's Events subsystem records login and administrative actions — the concrete implementation of accounting. Full depth in chapter 28." },
    { id: "aaa-13", type: "bug", question: "A team says \"we have an audit trail\" but it turns out they only have generic web-server access logs (IP, URL, timestamp — no identity or permission context). What's the mistake?", options: ["There is no mistake — any log is an audit trail", "Conflating generic infrastructure logging with deliberate AAA-style accounting of identity and permission events — they overlap but aren't the same thing", "Web server logs are always sufficient for HIPAA and PCI-DSS", "This is an authentication bug, not an accounting bug"], answerIndex: 1, explanation: "The chapter's common-mistakes list calls this out directly: generic access logs are not the same as deliberate, identity-aware accounting data." },
    { id: "aaa-14", type: "scenario", question: "An attacker guesses a weak password and logs in as Jane (an authentication failure occurred), but a tight permission check on the one sensitive action they try still blocks them. What does this illustrate?", options: ["That authorization is irrelevant once authentication fails", "That authorization can act as an independent safety net even when authentication has already failed", "That this scenario is impossible in a real system", "That accounting should have prevented the login entirely"], answerIndex: 1, explanation: "This is the chapter's \"AuthN wrong, AuthZ correct\" quadrant: authorization, evaluated independently, can still block damage after authentication has already been compromised." },
    { id: "aaa-15", type: "concept", question: "What historical standard is most associated with popularizing the formal three-part AAA framing?", options: ["OAuth 2.0", "RADIUS (Remote Authentication Dial In User Service)", "SAML 2.0", "OpenID Connect"], answerIndex: 1, explanation: "RADIUS (RFC 2865) is the network-access-control standard most associated with formalizing Authentication, Authorization, and Accounting as a named model." },
    { id: "aaa-16", type: "compare", question: "How does this chapter's refined definition of \"audit trail\" differ from chapter 1's original one-line definition?", options: ["They are unrelated concepts with no connection", "Chapter 1's definition actually described accounting's recorded output; chapter 3 clarifies that audit itself is the separate, later review of that output", "Chapter 1's definition was about authentication, not audit", "There is no difference; the definitions are identical"], answerIndex: 1, explanation: "The chapter explicitly notes that chapter 1's audit-trail definition was describing what accounting produces, and sharpens the distinction between the recording act and the later review act." },
    { id: "aaa-17", type: "scenario", question: "A Meridian Trust teller, correctly authenticated as a bank employee, can open every customer account in the bank rather than only accounts tied to transactions they're actively handling. What is this a failure of?", options: ["Authentication — the teller shouldn't have been let in at all", "Authorization — the internal permission boundary is too broad for the teller's actual job scope", "Accounting — the teller's login wasn't logged", "This isn't a security issue since the teller is a legitimate employee"], answerIndex: 1, explanation: "The teller's authentication is entirely correct; the problem is an authorization boundary that's far too broad for what their role should actually permit." },
    { id: "aaa-18", type: "concept", question: "Why is it inaccurate to describe AuthN and AuthZ as \"basically the same check\"?", options: ["Because they always happen at completely different times, days apart", "Because a system can get one of them right while getting the other wrong — they are independently evaluated decisions that happen to be grouped under the same category of software", "Because authorization never depends on authentication at all", "Because only one of them is implemented in any real system"], answerIndex: 1, explanation: "The chapter's central point: authentication and authorization are genuinely separate decisions, each independently capable of being right or wrong, even though they're commonly bundled together conceptually." }
  ],

  "directory-services": [
    { id: "dir-01", type: "concept", question: "Which best describes a directory service?", options: ["A transactional database optimized for frequent writes", "A read-optimized, hierarchically organized store built for fast lookups about people, systems, and resources", "A synonym for any OAuth-compliant identity provider", "A caching layer that sits in front of an IAM product's token issuer"], answerIndex: 1, explanation: "Directory services are read-heavy and hierarchical, built for lookups like a phone book rather than for transactions like a bank ledger." },
    { id: "dir-02", type: "concept", question: "What is the relationship between X.500 and LDAP?", options: ["They are unrelated, competing standards from different eras", "LDAP is a lightweight, TCP/IP-based protocol for accessing directories that follow X.500's data model", "X.500 is Microsoft's proprietary successor to LDAP", "LDAP replaced X.500's data model entirely with a flat, non-hierarchical one"], answerIndex: 1, explanation: "X.500 defines the heavyweight original data model and protocols; LDAP is the lighter-weight protocol for accessing X.500-shaped directories over ordinary TCP/IP." },
    { id: "dir-03", type: "concept", question: "What does an entry's Distinguished Name (DN) represent?", options: ["A password hash stored for that entry", "The entry's full, unique path from the root of the Directory Information Tree", "A list of every attribute the entry carries", "The objectClass values assigned to the entry"], answerIndex: 1, explanation: "A DN is the entry's unique address in the DIT — the chain of RDNs from the entry up to the root." },
    { id: "dir-04", type: "scenario", question: "A nurse at Riverside Health enters her username and password into an application that authenticates against Active Directory via LDAP. Which LDAP operation is actually happening behind the scenes?", options: ["A search operation filtering entries by objectClass", "A bind operation, presenting her DN and password to the directory", "A compare operation checking her department attribute", "A modify operation updating her last-login timestamp"], answerIndex: 1, explanation: "A simple bind — presenting a DN and credential — is functionally an authentication attempt against the directory." },
    { id: "dir-05", type: "compare", question: "What is the difference between an entry's objectClass and its attributes?", options: ["They are two names for the same thing", "objectClass declares what kind of thing the entry is and which attributes it may carry; attributes are the actual facts recorded on it", "objectClass stores credentials; attributes store the DN", "attributes determine the entry's position in the DIT; objectClass does not"], answerIndex: 1, explanation: "objectClass is a type declaration (person, organizationalPerson, etc.); attributes are the named facts the entry actually carries, such as cn or mail." },
    { id: "dir-06", type: "scenario", question: "Northwind Apps' SaaS customers' end users log into Northwind's product every day. Where do their identities live?", options: ["In the same Active Directory as Northwind's own employees, in a dedicated OU", "In a completely separate CIAM identity store, not in Northwind's workforce Active Directory at all", "Nowhere centrally — each customer company's IT department issues its own LDAP bind credentials directly against Northwind's AD", "In Active Directory, but disabled until the customer's contract renews"], answerIndex: 1, explanation: "Northwind deliberately separates its internal workforce AD from the CIAM store holding its customers' end users — different populations, different governance." },
    { id: "dir-07", type: "concept", question: "What is a Relative Distinguished Name (RDN)?", options: ["The entire path from an entry to the root of the DIT", "The single naming component that distinguishes an entry from its siblings under the same parent", "A password hash used only for anonymous binds", "A Kerberos ticket issued by a domain controller"], answerIndex: 1, explanation: "A DN is a chain of RDNs; the RDN is just the one component distinguishing an entry from its siblings." },
    { id: "dir-08", type: "scenario", question: "Riverside Health's IT team wants clinicians and administrative staff to receive different Group Policy settings within the same Active Directory domain. What AD construct is designed for exactly this?", options: ["A separate domain controller per group", "Organizational Units (OUs), used to group objects for policy and delegated administration", "Anonymous bind scoped per department", "A second Directory Information Tree"], answerIndex: 1, explanation: "OUs exist specifically to group users/computers within one domain so different policy and administration can apply to each group." },
    { id: "dir-09", type: "concept", question: "What does a Domain Controller (DC) do in Active Directory?", options: ["It issues OAuth access tokens to connected applications", "It holds a copy of the domain's directory data and services authentication requests against it", "It stores only the DNS records for the domain, nothing else", "It is a synonym for an Organizational Unit"], answerIndex: 1, explanation: "A DC is the server holding the domain's directory data and handling authentication requests — the directory server itself in AD's vocabulary." },
    { id: "dir-10", type: "scenario", question: "A simple bind against a directory entry fails. What has been established?", options: ["The entry does not exist in the directory at all", "The presented credential was not correct for that DN — nothing more, and nothing about authorization either way", "The user's account has been permanently deleted", "The directory's schema does not permit that objectClass"], answerIndex: 1, explanation: "A bind failure just means the credential didn't match for that DN; it doesn't reveal which part was wrong, and a successful bind wouldn't have implied authorization either." },
    { id: "dir-11", type: "compare", question: "How does Active Directory relate to LDAP?", options: ["AD is unrelated to LDAP and uses a completely different data model", "AD implements the general directory-service shape and exposes an LDAP interface, while also using its own native mechanisms like Kerberos for everyday login", "LDAP is a feature that must be purchased separately and added on top of AD", "AD replaced LDAP as a protocol industry-wide"], answerIndex: 1, explanation: "AD is a concrete directory product that speaks LDAP (among other protocols) while also relying on Kerberos natively for day-to-day authentication." },
    { id: "dir-12", type: "concept", question: "What is this course's position on Kerberos?", options: ["It is covered in full cryptographic depth in this chapter", "It is AD's native authentication protocol, worth knowing exists, but deliberately out of scope for deep coverage in this course", "It is a deprecated protocol no longer used by any directory product", "It is a synonym for the LDAP bind operation"], answerIndex: 1, explanation: "The chapter explicitly flags Kerberos as AD's native protocol for day-to-day login, and explicitly scopes it out of further depth." },
    { id: "dir-13", type: "scenario", question: "Riverside Health is evaluating whether to deploy Keycloak. Its hospital already has ten thousand clinicians in an on-prem Active Directory. What does this chapter suggest is the right approach?", options: ["Migrate all ten thousand clinician accounts into Keycloak's own user store before go-live", "Connect Keycloak to the existing Active Directory via federation, so clinicians keep their existing credentials and HR keeps managing them in one place", "Disable Active Directory entirely and require clinicians to self-register in Keycloak", "Run Keycloak and Active Directory as two independent, unsynchronized sources of truth"], answerIndex: 1, explanation: "The whole point of federation (chapter 7) and Keycloak's user federation (chapter 32) is connecting to an existing authoritative directory instead of migrating its population." },
    { id: "dir-14", type: "scenario", question: "A security review finds that a production LDAP directory accepts anonymous bind for all queries, including ones that return employee phone numbers and departments. What is the most likely cause?", options: ["A deliberate, documented decision to support a public employee lookup kiosk", "A default setting nobody ever revisited, not a reasoned security decision", "A requirement of the LDAP protocol itself, which cannot be disabled", "Evidence that the directory has already been compromised"], answerIndex: 1, explanation: "Anonymous bind being left open in production is a classic case of an unreviewed default, not evidence of compromise or a documented requirement." },
    { id: "dir-15", type: "concept", question: "In chapter 2's terms, what is a directory attribute such as department or mail?", options: ["A credential, because it's stored alongside the password", "A concrete instance of the same general Attribute concept from chapter 2 — a fact recorded about an identity, not proof of anything", "A second identifier for the entry", "A synonym for the entry's Distinguished Name"], answerIndex: 1, explanation: "Directory attributes are the LDAP-specific, concrete form of chapter 2's general Attribute concept — descriptive facts, not proof." },
    { id: "dir-16", type: "scenario", question: "Meridian Trust keeps its bank employees in one Active Directory and its retail banking customers in a completely separate identity store. Why is this consistent with how Northwind Apps organizes its identities?", options: ["It isn't consistent — banks are required by PCI-DSS to use a single combined directory for all identities", "Both organizations separate their workforce directory from their customer-facing identity store, because employees and external end users are different populations with different governance needs", "Both organizations use Kerberos for both employee and customer authentication", "Meridian's structure is unrelated because it predates Northwind's CIAM store"], answerIndex: 1, explanation: "Workforce-directory vs. CIAM-store separation is a general pattern, illustrated by both Northwind and Meridian keeping employee and external-customer identities in distinct stores." },
    { id: "dir-17", type: "compare", question: "What is the key difference between an anonymous bind and a simple bind?", options: ["A simple bind is always encrypted; an anonymous bind never is", "An anonymous bind presents no credential at all; a simple bind presents a DN and a password as proof of identity", "Anonymous bind is only possible against Active Directory, never against generic LDAP", "Simple bind is used only for write operations, anonymous bind only for reads"], answerIndex: 1, explanation: "The defining difference is credential presence: simple bind authenticates with DN + password; anonymous bind authenticates with nothing, typically for unauthenticated read access." }
  ],

  "authentication-factors-mfa": [
    { id: "mfa-01", type: "concept", question: "Which three categories make up the classical authentication factors?", options: ["Knowledge, possession, inherence", "Password, PIN, biometric", "Device, location, behavior", "SMS, email, push notification"], answerIndex: 0, explanation: "Knowledge (something you know), possession (something you have), and inherence (something you are) are the three classical factor categories." },
    { id: "mfa-02", type: "scenario", question: "A system requires both a password and the answer to a security question before login. Does this qualify as genuine multi-factor authentication?", options: ["Yes, because two separate prompts are required", "No, because both are knowledge factors — compromising one method (e.g. phishing) likely compromises both", "Yes, but only if the security question is kept secret", "No, because security questions are never valid authentication factors"], answerIndex: 1, explanation: "Genuine MFA requires factors from different categories. Two knowledge factors share the same weaknesses, so defeating one tends to defeat both." },
    { id: "mfa-03", type: "concept", question: "What is the main vulnerability specific to inherence factors that doesn't apply to knowledge factors?", options: ["They can be guessed through brute force", "They cannot be rotated or reset if the stored template is compromised", "They require an internet connection to verify", "They expire automatically every 90 days"], answerIndex: 1, explanation: "A password can be changed after a breach; a compromised fingerprint or face template cannot be reissued the same way, since it corresponds to a physical trait." },
    { id: "mfa-04", type: "scenario", question: "Riverside Health's clinicians authenticate to shared workstations with a badge tap plus a short PIN. What factor category does the badge tap represent, and what is the stated trade-off for using it?", options: ["A knowledge factor, trading off memorability for cost", "A possession factor, trading off some security for speed clinicians need between patients", "An inherence factor, trading off accuracy for convenience", "A context signal, trading off accuracy for automation"], answerIndex: 1, explanation: "The badge is a possession factor. Riverside accepts a weaker standalone guarantee than full MFA in exchange for the speed clinicians need on shared workstations, compensating with session timeouts and audit logging." },
    { id: "mfa-05", type: "concept", question: "What role do context and behavior signals (device, location, typing rhythm) play in this chapter's framework?", options: ["They are a fourth classical authentication factor equal to knowledge, possession, and inherence", "They feed risk-based/adaptive authentication decisions about how much proof to demand, rather than counting as a traditional factor", "They replace the need for any authentication factor entirely", "They are only used for compliance reporting, not authentication decisions"], answerIndex: 1, explanation: "Context/behavior signals aren't proof of identity the way a factor is — they're evidence used to decide whether existing factors are sufficient or more proof should be demanded." },
    { id: "mfa-06", type: "concept", question: "In TOTP and HOTP, what is established once at enrollment and never transmitted again afterward?", options: ["The user's password", "The shared secret", "The six-digit code itself", "The user's device identifier"], answerIndex: 1, explanation: "The shared secret is set up once (often via QR code) and never sent again; both sides use it locally, combined with a moving factor, to compute matching codes." },
    { id: "mfa-07", type: "compare", question: "How does TOTP's moving factor differ from HOTP's?", options: ["TOTP uses a counter that increments on use; HOTP uses the current time", "TOTP uses the current time, rounded to a fixed step; HOTP uses a counter that increments each time a code is consumed", "They use the identical moving factor, just different code lengths", "TOTP has no moving factor; only HOTP does"], answerIndex: 1, explanation: "TOTP advances automatically with time; HOTP only advances when a code is actually used, which is also the source of its counter-desync weakness." },
    { id: "mfa-08", type: "bug", question: "A user reports their TOTP authenticator app codes are consistently rejected right after returning from an international trip. What is the most likely cause, per this chapter?", options: ["Their shared secret has become corrupted and must be reset", "Clock drift between their device and the server, since TOTP's moving factor is time-based", "The server's HOTP counter is out of sync", "Their password was changed at the same time"], answerIndex: 1, explanation: "TOTP depends on both sides agreeing on the time. A device clock that drifts (e.g. after travel or a time-zone change) produces codes the server computes differently — not a corrupted secret." },
    { id: "mfa-09", type: "concept", question: "What is the key property of a WebAuthn/FIDO2 private key that distinguishes it from a typed password or OTP code?", options: ["It changes every 30 seconds automatically", "It never leaves the device and is never seen or typed by the user", "It is shared between the device and server over an encrypted channel at every login", "It is identical across all of a user's registered devices"], answerIndex: 1, explanation: "The private key stays on the device (often in secure hardware); there is nothing the user types or copies, which removes the human-in-the-loop weakness that makes OTP codes phishable." },
    { id: "mfa-10", type: "scenario", question: "An attacker builds a convincing lookalike login page and captures a victim's password and OTP code, then immediately replays both against the real site. Why does an identical attack against a WebAuthn-protected login fail?", options: ["Because WebAuthn codes expire faster than OTP codes", "Because WebAuthn signatures are cryptographically bound to the real site's exact origin, so the lookalike site cannot obtain a usable signature at all", "Because WebAuthn requires a VPN connection", "Because WebAuthn disables itself automatically when phishing is detected"], answerIndex: 1, explanation: "The challenge-response signature is origin-bound. A different domain (the lookalike site) cannot produce or relay a signature that validates against the real site's origin." },
    { id: "mfa-11", type: "compare", question: "How does a passkey relate to WebAuthn and FIDO2?", options: ["A passkey is an entirely separate protocol unrelated to WebAuthn or FIDO2", "A passkey is the user-facing, syncable form of a FIDO2/WebAuthn credential", "WebAuthn is a type of passkey used only on mobile devices", "FIDO2 is a deprecated predecessor that passkeys replaced entirely"], answerIndex: 1, explanation: "Passkey is the consumer-facing branding for a FIDO2/WebAuthn credential, typically one that syncs across a user's devices via their platform account." },
    { id: "mfa-12", type: "concept", question: "What does 'phishing-resistant authentication' specifically mean, as defined in this chapter?", options: ["Any method that uses more than one factor", "A method whose proof cannot be captured and replayed from a fake site, because the proof itself has nothing a human can be tricked into typing or copying and is bound to the real origin", "Any method that requires biometrics", "A method that blocks known phishing domains via a blocklist"], answerIndex: 1, explanation: "Having multiple factors (MFA) is not the same as being phishing-resistant — a password plus a typed OTP code is still phishable, while origin-bound WebAuthn signatures are not." },
    { id: "mfa-13", type: "concept", question: "What is the defining difference between risk-based (adaptive) authentication and a flat 'always require MFA' policy?", options: ["Risk-based authentication never requires any additional factor", "Risk-based authentication raises or lowers the required proof based on contextual signals, instead of applying the same requirement to every login or action", "A flat policy is always more secure than a risk-based one", "Risk-based authentication only applies to administrator accounts"], answerIndex: 1, explanation: "Risk-based authentication varies the bar according to evaluated signals (device, location, action sensitivity) rather than treating every situation identically." },
    { id: "mfa-14", type: "scenario", question: "Meridian Trust's online banking customer logs in from their usual phone and transfers $20 to a payee they've paid monthly for two years — no extra prompt appears. The same customer then attempts a first-time $20,000 transfer from an unrecognized browser, and is challenged for an additional factor. What does this illustrate?", options: ["A flat MFA policy applied to every transaction equally", "Step-up authentication triggered by risk-based signals — the unusual amount, new payee context, and unfamiliar device raised the risk score for the second transaction", "A bug, since both transactions should require the same proof", "That Meridian Trust does not use MFA for routine transactions"], answerIndex: 1, explanation: "This is risk-based authentication in action: routine behavior passes with the normal factor set, while signals indicating elevated risk (new device, large amount, unusual payee) trigger step-up authentication specifically for the sensitive action." },
    { id: "mfa-15", type: "bug", question: "An application prompts every user for a fresh MFA code on every single click within the app, including harmless read-only actions. What is the most likely design flaw, per this chapter?", options: ["The application is using HOTP instead of TOTP", "A missing risk-based layer — treating all actions as equally sensitive instead of reserving step-up challenges for actions that actually warrant them", "The application does not support WebAuthn", "The application's shared secret was never rotated"], answerIndex: 1, explanation: "Constant re-prompting for low-sensitivity actions is a sign the system lacks risk-based differentiation, which also trains users to click through prompts without reading them — undermining the control's purpose." },
    { id: "mfa-16", type: "compare", question: "How does an Authenticator Assurance Level (AAL), per NIST SP 800-63B, relate to the factor categories discussed in this chapter?", options: ["AAL is a replacement term for 'factor category' with no additional meaning", "AAL is a tiered classification of how strong a combination of authentication factors is overall, used as a reference point for how much assurance a given requirement calls for", "AAL only applies to inherence factors", "AAL measures how fast an authentication method completes, not its strength"], answerIndex: 1, explanation: "AAL (AAL1-AAL3) classifies overall authentication strength based on the factors and implementation used, giving a standard reference point for how much assurance a given risk or compliance requirement needs." }
  ],

  "authorization-models": [
    { id: "azm-01", type: "concept", question: "What question does every one of the five authorization models (ACL, RBAC, ABAC, PBAC, ReBAC) ultimately answer?", options: ["Who is this subject, really?", "Can subject S perform action A on resource R?", "Has this subject's password expired?", "Which identity provider authenticated this subject?"], answerIndex: 1, explanation: "All five models are different structural answers to the same yes/no access question; they differ in where the decision logic lives, not in what question they answer." },
    { id: "azm-02", type: "concept", question: "In an Access Control List (ACL) model, where do permissions live?", options: ["Attached to a role that subjects are assigned to", "Computed from attributes at request time", "Attached directly to the resource, listing which subjects can do what", "Derived from a relationship graph"], answerIndex: 2, explanation: "ACLs attach permissions directly to the resource itself, per subject — the defining trait that also causes their N-resources-by-M-subjects scaling problem." },
    { id: "azm-03", type: "concept", question: "Why do ACLs scale poorly as an organization grows?", options: ["They require a graph database", "They roughly grow as N resources × M subjects of entries to maintain", "They cannot express read vs. write permissions", "They require every subject to have the same role"], answerIndex: 1, explanation: "Because every grant is listed explicitly per resource and per subject with no shared structure, the maintenance burden grows with both the resource count and the subject count." },
    { id: "azm-04", type: "concept", question: "What indirection does RBAC introduce that ACLs don't have?", options: ["Permissions attach to roles, and subjects are assigned to roles", "Permissions attach to a relationship graph", "Permissions are computed from environment attributes only", "Permissions require a policy engine to evaluate"], answerIndex: 0, explanation: "RBAC's defining feature is the role layer: permissions are defined once per role, and subjects are connected to roles, rather than permissions being listed per subject directly." },
    { id: "azm-05", type: "scenario", question: "Northwind Apps gives every customer tenant an \"admin\" role for managing that tenant's users and settings. What must be true for this to be safe in a multi-tenant product?", options: ["Every tenant must share the exact same admin account", "The role assignment must be scoped to that specific tenant, not just checked by role name", "The role must be renamed uniquely per tenant", "Tenant admins must also hold a global super-admin role"], answerIndex: 1, explanation: "A role name alone carries no scope. The permission check must verify the role applies to this specific tenant, or every tenant admin platform-wide would be able to administer every other tenant." },
    { id: "azm-06", type: "bug", question: "A SaaS platform's authorization code checks only `user.roles.includes(\"tenant-admin\")` before allowing a settings change, with no check of which tenant the request targets. What is the resulting bug?", options: ["The system will reject all legitimate admin requests", "Any tenant's admin can modify the settings of every other tenant on the platform", "The role check will always return false", "This is not a bug — RBAC doesn't support per-tenant scoping"], answerIndex: 1, explanation: "Without checking that the role applies to the specific tenant being accessed, the role check only confirms \"is an admin somewhere,\" letting any tenant admin reach every tenant's data — a classic missing-resource-scope RBAC bug." },
    { id: "azm-07", type: "concept", question: "What does an ABAC system use to compute an access decision?", options: ["A static per-resource list of subjects", "A pre-assigned role held by the subject", "Attributes of the subject, resource, and environment, evaluated at request time", "A fixed hierarchy of job titles"], answerIndex: 2, explanation: "ABAC decisions are computed live from attributes rather than looked up from a pre-assigned role or list, which is what lets it react to data that changes per request." },
    { id: "azm-08", type: "scenario", question: "At Meridian Trust, a teller's authorized wire-transfer ceiling depends on an account-risk attribute rather than the teller's job title alone. Which model does this best illustrate?", options: ["ACL, because each account has its own list of tellers", "RBAC, because the teller role determines the entire limit", "ABAC, because the decision is computed from an attribute of the resource (the account) combined with the subject", "ReBAC, because it depends on a care-team relationship"], answerIndex: 2, explanation: "The limit isn't fixed by the teller's role alone — it's computed from the account's risk attribute at decision time, which is the defining trait of ABAC." },
    { id: "azm-09", type: "bug", question: "An ABAC rule is intended to cap a teller's approval authority using the CURRENT account-risk attribute, but the application actually reads a cached risk score computed at login time and never refreshed during the session. What is the resulting problem?", options: ["The rule works exactly as intended", "A teller could approve a transfer based on a stale risk attribute that no longer reflects the account's real risk", "This turns the system into RBAC instead of ABAC", "The rule would simply fail to evaluate and deny everything"], answerIndex: 1, explanation: "ABAC's whole value is deciding from current attribute values; using a stale, session-cached value defeats that and can let a now-risky account get approvals based on an outdated, lower-risk snapshot." },
    { id: "azm-10", type: "compare", question: "What is the most honest way to describe the relationship between ABAC and PBAC?", options: ["They are unrelated, completely separate models with no overlap", "PBAC is strictly older and has been fully replaced by ABAC", "They overlap heavily — most PBAC systems evaluate policies over attributes, making PBAC often a way of implementing ABAC rather than a wholly separate model", "ABAC is only used for authentication, not authorization"], answerIndex: 2, explanation: "The literature and vendors don't draw a crisp line between the two; PBAC emphasizes how decision logic is packaged (as explicit policy), but that logic usually operates over attributes, so the two heavily overlap in practice." },
    { id: "azm-11", type: "concept", question: "What is a practical reason an organization might centralize ABAC-style checks into a dedicated policy engine (moving toward a PBAC approach)?", options: ["Policy engines eliminate the need for attributes entirely", "It lets policies be authored, versioned, and audited independently of the applications that enforce them", "It removes the need for any authentication step", "It converts the model into RBAC automatically"], answerIndex: 1, explanation: "Centralizing policy as its own governed artifact, separate from application code, is the main operational benefit — changes to policy don't require redeploying every consuming application." },
    { id: "azm-12", type: "concept", question: "What does a ReBAC model base its access decisions on?", options: ["A static list of permissions per resource", "Relationships between subjects and resources, modeled as a graph", "A fixed set of job-function roles", "Only attributes of the environment, such as time of day"], answerIndex: 1, explanation: "ReBAC's defining trait is evaluating relationships — edges in a graph, like \"owns\" or \"is on the care team for\" — rather than roles or attribute values alone." },
    { id: "azm-13", type: "scenario", question: "Riverside Health wants clinicians to access a patient's chart only if they're currently treating that patient, not just because they hold a \"clinician\" role somewhere in the hospital network. Which model fits this requirement best, and why?", options: ["RBAC, because \"clinician\" is already a role", "ABAC, because it only needs the clinician's department attribute", "ACL, because each chart can just list every clinician in the network", "ReBAC, because access should follow the specific, changing care-team relationship rather than a blanket role"], answerIndex: 3, explanation: "A flat \"clinician\" role would let every clinician in the network see every chart — a privacy and compliance problem. The correct scope is the specific, changing care-team relationship, which is what ReBAC is built to express." },
    { id: "azm-14", type: "compare", question: "Compared to RBAC, what is ReBAC's main scalability trade-off?", options: ["ReBAC always requires fewer infrastructure components than RBAC", "ReBAC fits relationship-driven access well, but requires maintaining an accurate, frequently changing relationship graph and evaluating graph traversals at request time", "ReBAC has no scalability trade-offs because it uses the same roles as RBAC", "ReBAC cannot express fine-grained access at all"], answerIndex: 1, explanation: "ReBAC's strength (precise, relationship-scoped access) comes with the cost of graph infrastructure: keeping relationships current and evaluating potentially multi-hop traversals, a different engineering problem than a role lookup." },
    { id: "azm-15", type: "concept", question: "Which statement best describes Zero Trust and least privilege in relation to the five authorization models?", options: ["They are a sixth authorization model, alternative to ACL/RBAC/ABAC/PBAC/ReBAC", "They are cross-cutting principles about how generous any of the five models' decisions should be, applicable regardless of which model is used", "They only apply to ReBAC systems", "They replace the need for authentication entirely"], answerIndex: 1, explanation: "Zero Trust (\"never trust, always verify\") and least privilege (grant only the minimum needed) are principles layered on top of whichever model is in use, not a model of their own." },
    { id: "azm-16", type: "compare", question: "Looking at the five-model comparison table, which model's typical scalability concern is described as 'grows as N resources × M subjects'?", options: ["RBAC", "ABAC", "ACL", "PBAC"], answerIndex: 2, explanation: "ACL is the model whose per-resource, per-subject listing structure directly produces this multiplicative scaling problem, unlike RBAC's role indirection or ABAC/PBAC's computed decisions." }
  ],

  "sso-and-federation": [
    { id: "sso-01", type: "concept", question: "SAML's 'Service Provider' and OIDC's 'Relying Party' refer to:", options: ["Two genuinely different roles in an SSO relationship", "The same role, named differently by two different protocol vocabularies", "The Service Provider only, with Relying Party being an OAuth-specific role", "A role that only exists in brokering, not federation"], answerIndex: 1, explanation: "SP (SAML) and RP (OIDC) both mean 'the application that trusts an external IdP's assertion instead of authenticating the user itself' — same role, different protocol vocabulary." },
    { id: "sso-02", type: "concept", question: "What does an Identity Provider (IdP) do in an SSO relationship?", options: ["Stores the relying application's business data", "Holds credentials, performs authentication, and asserts identity to another system", "Registers redirect URIs on behalf of the application", "Only applies to federation, not brokering"], answerIndex: 1, explanation: "The IdP is the system that authenticates the user and asserts the result; the relying application (SP/RP) trusts that assertion instead of authenticating directly." },
    { id: "sso-03", type: "scenario", question: "A user logs into Northwind Apps' dashboard, then later that day visits Northwind's separate billing portal, which is also configured to trust the same IdP. They are not asked to log in again. What made this possible?", options: ["Both apps store the same password hash", "The browser carries a session the shared IdP recognizes on the billing portal's redirect", "The billing portal silently reused the dashboard's local session cookie directly", "Northwind disabled authentication on the billing portal"], answerIndex: 1, explanation: "SSO works because the browser carries the IdP's session; a second app's redirect to the same IdP is recognized without re-authentication." },
    { id: "sso-04", type: "compare", question: "What is the key difference between identity brokering and identity federation?", options: ["Brokering is for SAML, federation is for OIDC", "Brokering delegates one login event to an external IdP; federation reuses an existing directory of accounts", "Federation is only used for customer-facing apps, brokering only for internal apps", "There is no meaningful difference — they are two names for the same pattern"], answerIndex: 1, explanation: "Brokering delegates authentication to an external IdP the user already has an account with; federation connects to an existing identity store/directory so its accounts can be reused." },
    { id: "sso-05", type: "scenario", question: "Riverside Health configures its Keycloak realm to check clinician logins directly against the hospital's existing Active Directory, rather than maintaining a second set of Keycloak-local passwords. This is an example of:", options: ["Identity brokering", "Identity federation", "JIT provisioning only, with no federation involved", "Social login"], answerIndex: 1, explanation: "Reusing an existing directory (AD) that the organization already runs, rather than delegating to an external IdP, is federation." },
    { id: "sso-06", type: "scenario", question: "Northwind Apps lets an enterprise customer's employees log in using the customer's own corporate IdP instead of a Northwind-issued password. In this relationship, Northwind is acting as the:", options: ["IdP, and the customer's system is the SP/RP", "SP/RP, trusting the customer's corporate IdP", "Directory being federated against", "Broker's external identity store"], answerIndex: 1, explanation: "Northwind's application relies on the customer's IdP's assertion instead of authenticating directly — Northwind is the SP/RP in this brokering relationship." },
    { id: "sso-07", type: "concept", question: "What is JIT (just-in-time) provisioning?", options: ["A scheduled nightly batch job that imports all directory accounts at once", "Automatically creating a local identity from external IdP/directory data on a user's first login", "A way to delete stale accounts automatically", "A SAML-only feature with no OIDC equivalent"], answerIndex: 1, explanation: "JIT provisioning creates the local identity automatically the first time a brokered or federated user logs in, instead of requiring manual pre-creation." },
    { id: "sso-08", type: "bug", question: "A support ticket says: 'A local account for an external user appeared in our system and nobody created it.' The user had just logged in for the first time via the company's brokered Google login. What is the most likely explanation?", options: ["A data breach created a fake account", "JIT provisioning created the account automatically on first successful login, as designed", "Someone bypassed the admin console", "The audit log is broken"], answerIndex: 1, explanation: "JIT provisioning silently creates a local account on first brokered/federated login — this is expected behavior, not a bug, though it can confuse a team unaware of it." },
    { id: "sso-09", type: "concept", question: "Which of the following is NOT one of the three ingredients of establishing trust between an IdP and an SP/RP?", options: ["Shared metadata describing endpoints and capabilities", "Certificates or signing keys to verify assertions", "Registered redirect URIs", "A shared database table storing both sides' user passwords"], answerIndex: 3, explanation: "Trust is built from metadata, certificates/signing keys, and registered redirect URIs — not a shared password store, which would defeat the point of not sharing credentials." },
    { id: "sso-10", type: "scenario", question: "Meridian Trust's mobile app redirects a customer to a login page, but the IdP refuses to send the login result back, citing an untrusted callback address. What is the most likely cause?", options: ["The customer's password was wrong", "The app's redirect URI was never registered with the IdP", "The IdP session expired mid-login", "Meridian disabled MFA"], answerIndex: 1, explanation: "IdPs only redirect to pre-registered redirect URIs as part of established trust; an unregistered one is rejected to prevent login results being hijacked elsewhere." },
    { id: "sso-11", type: "concept", question: "Why is 'everyone uses the same password' not the same thing as SSO?", options: ["Because SSO requires biometrics", "Because SSO means one authentication act is recognized across apps via a shared IdP session, not credential reuse", "Because password reuse is actually more secure", "Because SSO only works with social login"], answerIndex: 1, explanation: "True SSO is a shared-session handshake against one IdP; reusing the same password across independent apps is a weaker, insecure imitation with none of SSO's actual mechanics." },
    { id: "sso-12", type: "scenario", question: "A Northwind Apps engineer argues a new customer integration should 'federate' with the customer's Okta tenant so employees can use 'Login with Okta.' What pattern are they actually describing?", options: ["Federation, correctly described", "Brokering — delegating one login event to an external IdP, not reusing a directory", "User provisioning", "Service account creation"], answerIndex: 1, explanation: "'Login with X' where X authenticates the user and the app trusts the result is brokering, even though the word 'federate' is colloquially misused for it." },
    { id: "sso-13", type: "compare", question: "In an LDAP-federation setup, who remains the authoritative owner of the user's credential?", options: ["The IAM system doing the federating", "The external directory (e.g. Active Directory) being federated against", "Neither — the credential is discarded after first login", "The relying application (SP/RP)"], answerIndex: 1, explanation: "Federation reuses an existing directory; that directory remains the source of truth for the credential, checked via a bind operation rather than copied elsewhere." },
    { id: "sso-14", type: "scenario", question: "Riverside Health's clinicians are federated against hospital AD. Riverside now also wants to let clinicians who use personal Microsoft accounts sign in with those instead. What pattern does the new requirement call for?", options: ["Federation against Microsoft's directory", "Brokering — delegating that login to Microsoft as an external IdP", "The same federation configuration extended to cover Microsoft", "JIT provisioning is not applicable here"], answerIndex: 1, explanation: "Personal Microsoft accounts aren't an organization-owned directory to federate against — trusting Microsoft to authenticate the user is brokering, a different pattern and trust relationship than the AD federation." },
    { id: "sso-15", type: "concept", question: "Which statement best describes an 'assertion' in SSO/brokering/federation contexts?", options: ["A user's self-declared claim with no verification", "The message an IdP sends stating who the user is, after authenticating them", "A synonym for 'redirect URI'", "Only used in LDAP federation, never in brokering"], answerIndex: 1, explanation: "An assertion is the IdP's statement of identity (and often attributes) sent to the relying application after successful authentication — its exact format differs by protocol (SAML assertion vs. OIDC ID token) but the role is the same." },
    { id: "sso-16", type: "bug", question: "Two apps both trust the same Keycloak realm, but a user who is logged into App A still gets a full login prompt when visiting App B. Given SSO mechanics, what's a likely cause to investigate first?", options: ["App B's database is down", "The browser isn't carrying/sending the IdP's SSO session cookie to App B's redirect (e.g. cross-domain cookie issue), or App B isn't actually redirecting to the same IdP/realm", "The user's password expired", "JIT provisioning failed"], answerIndex: 1, explanation: "If both apps genuinely trust the same IdP, a forced re-login points to the SSO session not being recognized on the second redirect — often a cookie-scoping or misconfigured-realm issue, not a credential problem." }
  ],

  "tokens-and-sessions": [
    { id: "tok-01", type: "concept", question: "What is the defining property of a bearer token?", options: ["It can only be used from the IP address it was issued to", "Whoever holds and presents it can use it, with no proof they are the party it was issued to", "It automatically expires the moment it is copied", "It requires a second factor every time it is presented"], answerIndex: 1, explanation: "\"Bearer\" means possession is the only thing checked — the token itself carries no proof that the presenter is its original owner." },
    { id: "tok-02", type: "concept", question: "What is a claim, in the conceptual sense this chapter introduces?", options: ["The raw cryptographic signature bytes of a token", "A key-value assertion inside a token that the issuer is vouching for, such as who it's for or when it expires", "A support ticket filed when a token stops working", "The network protocol used to transmit the token"], answerIndex: 1, explanation: "Claims are the statements carried inside a token (subject, issuer, expiry, authorization data, audience); the exact wire format is chapter 16's job." },
    { id: "tok-03", type: "compare", question: "How do stateless and stateful authentication architectures differ in how a server checks a request?", options: ["Stateless requires a server-side lookup; stateful needs none", "Stateless verifies a self-contained token with no database lookup; stateful looks a session identifier up against a shared store", "They are identical in cost and revocability", "Stateful is always faster because it never touches a database"], answerIndex: 1, explanation: "Stateless tokens are self-verifying; stateful sessions require consulting a shared, server-side session store on every request." },
    { id: "tok-04", type: "scenario", question: "Meridian Trust deliberately issues very short-lived access tokens for its banking API. What is this directly a response to?", options: ["A limitation of its database hardware", "The revocation problem — it can't cleanly revoke a stolen stateless token early, so it shrinks the window a stolen token stays useful", "A regulatory requirement that tokens must be human-readable", "A preference for fewer total API calls per day"], answerIndex: 1, explanation: "Since Meridian can't revoke a plain stateless bearer token early, shrinking its lifetime is the direct mitigation it chooses given PCI-DSS and fraud exposure." },
    { id: "tok-05", type: "scenario", question: "Northwind Apps wants customers to stay logged in for weeks without re-entering credentials. What trade-off does this force onto its refresh-token lifetime decision?", options: ["No trade-off exists — longer refresh tokens are strictly better", "User convenience (staying logged in longer) against greater exposure if a stolen refresh token stays usable for that same longer window", "Refresh tokens have no effect on login duration", "The trade-off only matters for access tokens, not refresh tokens"], answerIndex: 1, explanation: "A longer-lived refresh token means more convenience but a longer usable window for a thief who steals one — there's no setting that gives both for free." },
    { id: "tok-06", type: "concept", question: "Why can't a stateless bearer token be cleanly revoked early, in the general case?", options: ["Because tokens are legally required to remain valid until expiry", "Because adding a central early-revocation check reintroduces the server-side lookup that statelessness exists to avoid", "Because revocation is a solved problem that all systems already implement correctly", "Because tokens are encrypted and therefore cannot be inspected"], answerIndex: 1, explanation: "The moment you add a revocation check, you've reintroduced the stateful lookup — it's a structural consequence of choosing statelessness, not a missing feature." },
    { id: "tok-07", type: "bug", question: "An incident-response runbook says: \"If an access token is compromised, revoke it immediately from the admin console.\" The system issues plain, short-lived stateless bearer tokens with no introspection endpoint. What is the actual outcome when this step is attempted during a real incident?", options: ["It works exactly as written, instantly invalidating the token everywhere", "There may be no mechanism to revoke that specific already-issued token at all — the team discovers the honest answer is \"wait for it to expire\"", "The token automatically re-issues itself with new claims", "Revoking it also revokes every other user's token as a side effect"], answerIndex: 1, explanation: "This is the exact pitfall the chapter calls out: a plain stateless design may have no way to revoke one specific token early, and teams that assumed otherwise get burned mid-incident." },
    { id: "tok-08", type: "bug", question: "A team adds a central revocation-check step so every server calls a shared service before honoring any token, then is confused that their system no longer scales the way their original stateless design promised. What is the cause?", options: ["Their database hardware degraded over time", "The revocation check reintroduced the exact server-side lookup that statelessness was chosen specifically to avoid, turning the system stateful in practice", "They forgot to enable caching on their load balancer", "Tokens became larger after the change, slowing parsing"], answerIndex: 1, explanation: "Adding any central \"is this still valid\" check converts a stateless system into a stateful one in all but name — the scaling benefit that motivated statelessness is gone." },
    { id: "tok-09", type: "concept", question: "What does token introspection let a resource server do, and what does it cost?", options: ["Rewrite a token's claims locally with no issuer involvement, at no cost", "Call back to the issuer on each request to ask whether a token is still valid, at the cost of reintroducing a server-side lookup", "Decrypt any token without a key, at no cost", "Permanently disable all tokens system-wide, at the cost of an outage"], answerIndex: 1, explanation: "Introspection (full mechanics in chapter 14) works, but it trades back part of the stateless benefit by requiring a real-time check against the issuer." },
    { id: "tok-10", type: "concept", question: "Why is signing-key rotation described as a \"blunt\" mitigation for the revocation problem?", options: ["It only works for refresh tokens, never access tokens", "It invalidates every token signed with the old key at once, rather than targeting one specific token", "It requires the attacker's cooperation to take effect", "It has no effect on any already-issued token"], answerIndex: 1, explanation: "Rotating the signing key invalidates everything signed with the old key — effective after a suspected key compromise, but not a way to revoke one token selectively. Full depth in chapter 16." },
    { id: "tok-11", type: "scenario", question: "An attacker intercepts a copy of a customer's valid access token and presents it to the same API the customer uses. What does the API see?", options: ["A request it correctly flags as fraudulent because tokens carry an owner's fingerprint", "A request indistinguishable from the real customer's, because possession of the token is the only thing being checked", "An automatic rejection, because bearer tokens can only be used once", "A request that is silently ignored"], answerIndex: 1, explanation: "Bearer tokens carry no proof of who is presenting them — the API cannot tell the attacker's request apart from the legitimate owner's." },
    { id: "tok-12", type: "compare", question: "What is the key structural difference between what a client holds under a token-based scheme versus a session-based scheme?", options: ["A token is always encrypted; a session identifier is always plaintext", "A token is self-contained data describing the subject; a session identifier is opaque and means nothing without a server-side lookup", "There is no structural difference, only a naming difference", "A session identifier always contains more claims than a token"], answerIndex: 1, explanation: "A token carries its own verifiable content; a session identifier is just a pointer into a server-side record." },
    { id: "tok-13", type: "concept", question: "What does refresh-token rotation actually mitigate, and what does it NOT do?", options: ["It eliminates the revocation problem entirely for all tokens", "It limits how long a stolen refresh token stays useful by keeping access tokens short-lived, but it does not make a stolen access token instantly revocable", "It makes every token permanently valid", "It removes the need for any token expiry at all"], answerIndex: 1, explanation: "Rotation narrows the exposure window by moving trust checks to the refresh step; it's a partial mitigation, not a full fix for the underlying revocation problem." },
    { id: "tok-14", type: "scenario", question: "A product team is deciding how long a refresh token should live for a consumer SaaS app. Which question best reflects the trade-off this chapter describes?", options: ["Should we skip refresh tokens entirely and only use passwords?", "How much convenience (staying logged in longer) are we willing to trade against how much exposure a stolen refresh token would create for that same duration?", "Should refresh tokens be stored in plaintext for easier debugging?", "Does the refresh token need to contain the user's password?"], answerIndex: 1, explanation: "This is exactly Northwind's dilemma: refresh-token lifetime is a direct trade between user convenience and security exposure, with no setting that avoids the trade entirely." },
    { id: "tok-15", type: "concept", question: "Which claim category answers \"which service is this token meant to be used against\"?", options: ["Issuer", "Audience", "Validity window", "Subject"], answerIndex: 1, explanation: "The audience claim identifies the intended recipient service, preventing a token issued for one API from being silently reused against another." },
    { id: "tok-16", type: "bug", question: "A support engineer insists \"the token proves it was really her\" after a disputed transaction traced to a valid access token. What is the flaw in that reasoning?", options: ["There is no flaw — token validity always proves principal identity", "A bearer token only proves someone possessed it; it does not prove the presenter is the principal it was originally issued to", "Tokens cannot be used to trace transactions at all", "The flaw is that tokens never contain a subject claim"], answerIndex: 1, explanation: "This is the core pitfall: conflating bearer-token possession with principal identity. A stolen token says exactly the same thing a legitimate one does." },
    { id: "tok-17", type: "compare", question: "How do short token lifetimes and token introspection differ as mitigations for the revocation problem?", options: ["Short lifetimes shrink the exposure window passively without a lookup; introspection actively checks validity on each request but reintroduces a server-side lookup", "They are functionally identical mitigations", "Short lifetimes require a database; introspection never does", "Introspection eliminates the need for token expiry entirely"], answerIndex: 0, explanation: "Short lifetimes work without adding any lookup cost, just a smaller window; introspection adds real-time control at the cost of the lookup statelessness was meant to avoid." },
    { id: "tok-18", type: "concept", question: "What must a stateful authentication architecture provide that a stateless one does not need?", options: ["A signing key", "A shared session store reachable by every server handling requests", "A refresh token", "An audience claim"], answerIndex: 1, explanation: "Stateful designs require a shared, server-side session store every server can reach; stateless designs need no such shared infrastructure." }
  ],

  "iam-threat-landscape": [
    { id: "thr-01", type: "concept", question: "What makes credential stuffing effective, even though the attacker never guesses or cracks a password?", options: ["The attacker uses real username/password pairs leaked from an unrelated site's breach, betting on password reuse", "The attacker exploits a flaw in the hashing algorithm used to store passwords", "The attacker intercepts passwords in transit over an unencrypted connection", "The attacker brute-forces a single account with a dictionary of common passwords"], answerIndex: 0, explanation: "Credential stuffing relies entirely on password reuse across sites; the credentials being tried are already valid somewhere, just not necessarily at the target." },
    { id: "thr-02", type: "scenario", question: "Meridian Trust sees hundreds of thousands of failed logins over a weekend, each IP trying exactly one username/password pair before moving on, and the credentials match an unrelated retail site's breach dump. What is this attack, and why does it succeed for some accounts despite Meridian's passwords never being compromised?", options: ["Credential stuffing; it succeeds for customers who reused their retail-site password on their banking account", "Brute-force attack; it succeeds because Meridian's password policy was too weak", "Session hijacking; it succeeds because Meridian's session cookies weren't marked HttpOnly", "Token replay; it succeeds because Meridian's access tokens never expire"], answerIndex: 0, explanation: "The one-attempt-per-IP, known-credential pattern is the signature of credential stuffing; it only succeeds against customers who reused a password Meridian never stored or leaked." },
    { id: "thr-03", type: "scenario", question: "After the credential-stuffing wave, Meridian adds a CAPTCHA to the login form, but a measurable number of attacks still succeed because the submitted passwords are genuinely correct for those accounts. What should Meridian add next to stop a correct-password-but-wrong-person login from succeeding?", options: ["A second authentication factor (MFA), since a CAPTCHA only slows automation, it doesn't verify the real account owner", "A longer minimum password length requirement", "Encrypting passwords at rest instead of hashing them", "Moving the login form to a different URL"], answerIndex: 0, explanation: "CAPTCHA defends against automation, not against a correct-but-stolen password; MFA is what verifies the attempt actually comes from the legitimate account owner." },
    { id: "thr-04", type: "concept", question: "What distinguishes phishing from credential stuffing as an attack on authentication?", options: ["Phishing manufactures a brand-new credential disclosure directly from the victim; credential stuffing reuses credentials already leaked elsewhere", "Phishing only works against API clients, not browser-based logins", "Phishing requires the attacker to already have network access to the victim's organization", "Phishing is a defense technique, not an attack technique"], answerIndex: 0, explanation: "Credential stuffing bets on reuse of already-breached credentials; phishing actively tricks the victim into disclosing a credential for the first time, regardless of reuse." },
    { id: "thr-05", type: "scenario", question: "Riverside Health clinicians receive an email impersonating the hospital IT help desk, linking to a pixel-perfect copy of the real SSO login page on a lookalike domain. What makes this attack effective against busy clinicians specifically?", options: ["A believable urgent pretext (account lockout) combined with a convincing fake page, exploiting trust and time pressure rather than any system flaw", "A flaw in the hospital's Active Directory password hashing", "The hospital's SSO system failing to issue tokens correctly", "A brute-force attack against the clinicians' MFA codes"], answerIndex: 0, explanation: "Phishing exploits human trust and urgency, not a technical flaw in the real system — the fake page and pretext are the entire attack." },
    { id: "thr-06", type: "scenario", question: "A Meridian Trust employee's credentials are phished through an adversary-in-the-middle (AiTM) proxy that relays their OTP code to the real service in real time, giving the attacker a live session. Which MFA approach would have resisted this specific technique, and why?", options: ["WebAuthn/passkeys, because they're bound to the real site's origin and can't be relayed through a lookalike proxy domain", "SMS-based OTP, because text messages can't be intercepted", "A longer OTP code, because longer codes are harder to relay", "Security questions, because they aren't tied to a specific login page"], answerIndex: 0, explanation: "AiTM phishing works by relaying whatever the victim enters, including OTP codes. WebAuthn/passkeys are origin-bound, so a credential registered for the real site simply won't authenticate against the attacker's proxy domain." },
    { id: "thr-07", type: "scenario", question: "Northwind Apps learns that an enterprise customer's own browser-based integration has an XSS flaw — code Northwind didn't write — and an attacker used it to read a Northwind-issued bearer token out of that customer's browser storage. Whose design choice determines how much damage results from this XSS bug?", options: ["Northwind's, because the token's scope and lifetime it chose determine the attacker's blast radius and window, regardless of whose code had the bug", "The customer's alone, because the vulnerable code is entirely theirs", "Neither party's, because XSS attacks can't be mitigated by token design", "The browser vendor's, because XSS is a browser-level flaw"], answerIndex: 0, explanation: "The XSS bug is the customer's, but Northwind's own choice of how long-lived and broadly-scoped the token is determines how much an attacker can do with it once stolen — that's the provider's design decision, not the customer's." },
    { id: "thr-08", type: "scenario", question: "What broader lesson does Northwind Apps' incident illustrate about being a SaaS provider?", options: ["A SaaS provider can inherit real risk from vulnerabilities in a customer's own integration code it doesn't control, and its own token design determines how much that risk costs", "SaaS providers are never responsible for incidents that originate in customer-side code", "Multi-tenant SaaS platforms are immune to token theft because tenants are isolated", "The only way to prevent this kind of incident is to ban customers from writing their own integrations"], answerIndex: 0, explanation: "The scenario is specifically chosen to show that a provider's blast radius extends into customer-side code it can't control, and that scoping/lifetime choices are the provider's real lever for containing that risk." },
    { id: "thr-09", type: "compare", question: "How does token replay differ from token theft?", options: ["Token theft is the act of stealing the token; token replay is the subsequent act of reusing the stolen token to authenticate again before it expires", "Token theft only applies to SAML assertions; token replay only applies to OAuth tokens", "Token replay happens before theft, and theft happens after", "They are the same attack described with two different names for the same single step"], answerIndex: 0, explanation: "Theft is acquiring the token; replay is what the attacker does with it afterward — reusing it as if they were the legitimate holder." },
    { id: "thr-10", type: "concept", question: "What is session hijacking?", options: ["Stealing a session identifier or cookie to impersonate an already-authenticated session", "Sending repeated MFA push notifications until one is approved", "Using breached credentials from another site against a login form", "Tricking a user into disclosing their password via a fake login page"], answerIndex: 0, explanation: "Session hijacking targets the session identifier itself, not the credential or token that created it." },
    { id: "thr-11", type: "compare", question: "What is the key mechanical difference between session hijacking and token theft, even though both produce the same outcome (impersonating the user)?", options: ["Session hijacking steals a server-side-looked-up identifier (a cookie); token theft steals a self-contained bearer credential", "Session hijacking only affects mobile apps; token theft only affects web browsers", "Session hijacking requires physical access to the victim's device; token theft never does", "There is no mechanical difference — they are the same attack under two names"], answerIndex: 0, explanation: "A session cookie is typically an opaque reference the server looks up; a bearer token is self-contained proof. Different mechanics, same consequence: whoever holds either one is treated as the user." },
    { id: "thr-12", type: "concept", question: "What does MFA fatigue (push bombing) require the attacker to already possess before it can work?", options: ["A valid password for the target account — the push bombing is how they get past the second factor, not the first", "Physical access to the victim's phone", "A copy of the target's biometric data", "Administrative access to the identity provider"], answerIndex: 0, explanation: "Push bombing only makes sense once the attacker already has a correct password; the technique exists specifically to get past MFA once the first factor is already compromised." },
    { id: "thr-13", type: "scenario", question: "A Meridian Trust employee receives five MFA push notifications between 23:58 and 00:04, well outside normal login hours, and approves the fifth one assuming it's a glitch. What attack is this, and what single system-level change would have prevented the approval regardless of the employee's tiredness?", options: ["MFA fatigue / push bombing; switching to a phishing-resistant factor with no approve/deny prompt to fatigue, such as WebAuthn, removes the option to mistakenly approve", "Credential stuffing; adding a CAPTCHA to the push notification screen", "Session hijacking; shortening the session cookie's lifetime", "Token replay; rotating the signing key used to issue tokens"], answerIndex: 0, explanation: "The repeated-push, eventual-approval pattern is push bombing. A factor like WebAuthn has no notification to repeatedly send and approve, which removes the attack's mechanism entirely rather than relying on the user staying vigilant." },
    { id: "thr-14", type: "bug", question: "A login endpoint accepts unlimited login attempts per account with no delay, lockout, or CAPTCHA. Which attack does this specifically enable at scale, and why?", options: ["Credential stuffing, because an attacker can fire millions of breached username/password pairs at the endpoint without ever being slowed down or blocked", "Phishing, because the missing rate limit makes the fake login page more convincing", "Session hijacking, because unlimited attempts let an attacker guess a session cookie", "MFA fatigue, because unlimited attempts let an attacker send unlimited push notifications"], answerIndex: 0, explanation: "Missing rate limiting / lockout is precisely what lets credential stuffing operate at the scale needed for even a tiny reuse rate to produce many account takeovers; chapter 30 covers configuring exactly this control in Keycloak." },
    { id: "thr-15", type: "bug", question: "A system logs only successful logins and discards failed-login attempts entirely. What does this specifically prevent the security team from detecting?", options: ["An ongoing credential-stuffing or brute-force campaign, since the pattern of many failed attempts is the main early signal that one is underway", "Successful account takeovers, since those are logged as successful logins either way", "Phishing emails arriving in employee inboxes", "Token theft via a client-side XSS vulnerability"], answerIndex: 0, explanation: "Credential stuffing and brute-force attacks are visible primarily through volume and patterns of failed attempts; discarding that data blinds the team to the attack while it's still in progress, not just after it succeeds." },
    { id: "thr-16", type: "scenario", question: "Riverside Health's security lead, after the clinician phishing incident, asks which later chapter in this course covers the authentication factor that would have resisted it. Which chapter, and which factor?", options: ["Chapter 5, which covers WebAuthn/passkeys as phishing-resistant, origin-bound authentication", "Chapter 10, which covers joiner-mover-leaver provisioning", "Chapter 17, which covers SAML assertions and bindings", "Chapter 27, which covers the Keycloak Admin REST API"], answerIndex: 0, explanation: "Chapter 5 introduces WebAuthn/FIDO2/passkeys specifically as the phishing-resistant authentication factor category that AiTM-style phishing can't relay." },
    { id: "thr-17", type: "scenario", question: "Northwind Apps' engineering lead asks which later chapter covers hardening token issuance and storage against the kind of theft Northwind experienced. Which chapter?", options: ["Chapter 18, which covers OAuth/OIDC security best current practice, including safe token storage and sender-constrained tokens", "Chapter 11, which covers compliance frameworks like GDPR and HIPAA", "Chapter 32, which covers LDAP and Active Directory user federation", "Chapter 4, which covers directory services and identity stores"], answerIndex: 0, explanation: "Chapter 18 is where this course covers the OAuth 2.0 Security Best Current Practice guidance (token storage pitfalls, sender-constrained tokens) that directly answers token theft." },
    { id: "thr-18", type: "scenario", question: "Meridian Trust's compliance team asks which later chapter covers the Keycloak-specific control that would have slowed down its credential-stuffing wave automatically, without waiting for a human to notice the spike. Which chapter?", options: ["Chapter 30, which covers password policies, brute-force protection, and MFA configuration in Keycloak", "Chapter 21, which covers realms and realm settings", "Chapter 37, which covers Keycloak Authorization Services (UMA 2.0)", "Chapter 13, which covers OAuth 2.0 grant types"], answerIndex: 0, explanation: "Chapter 30 is where this course configures Keycloak's realm-level brute-force detection — the automated lockout/delay mechanism that answers credential stuffing without manual intervention." }
  ],

  "identity-governance": [
    { id: "iga-01", type: "concept", question: "What does IGA (Identity Governance & Administration) primarily refer to, as this course uses the term?", options: ["A specific vendor product category like SailPoint or Saviynt", "The discipline of provisioning, reviewing, and governing access over an identity's entire lifetime", "A synonym for single sign-on", "The encryption method used to protect access tokens"], answerIndex: 1, explanation: "IGA is the process discipline — granting, reviewing, and governing access over time. The tooling market category that automates it is a separate subject covered in chapter 12." },
    { id: "iga-02", type: "concept", question: "Joiner-Mover-Leaver (JML) maps onto which lifecycle stages from chapter 2?", options: ["It replaces chapter 2's lifecycle with a new five-stage model", "Joiner = create+activate, Mover = modify, Leaver = suspend+delete", "Joiner = modify, Mover = create+activate, Leaver = delete only", "JML has no relationship to chapter 2's lifecycle"], answerIndex: 1, explanation: "JML is HR vocabulary laid on top of the same create/activate/modify/suspend/delete stages, not a new or competing lifecycle model." },
    { id: "iga-03", type: "scenario", question: "Northwind Apps moves Priya from the support team to the platform engineering team. The system grants her the platform engineering role but leaves her existing support-team role untouched. What is the problem?", options: ["There is no problem — Mover events should only add access", "This is a correctly handled Mover event", "This treats Mover as purely additive, leaving stale, no-longer-justified access from her old role", "Priya should have been deleted and recreated instead"], answerIndex: 2, explanation: "A Mover event should remove access tied to the old role, not just add access for the new one. Leaving the old role in place is the classic Mover-trap mistake." },
    { id: "iga-04", type: "bug", question: "An access review at Northwind Apps finds several staff members hold role-scoped access from two or three teams they've rotated through over the years, with no single event ever having removed any of it. What caused this?", options: ["A bug in the authentication protocol", "Deprovisioning events were never configured", "Role-change (Mover) events were implemented as additive-only, never removing prior access", "The organization has too many case-study orgs"], answerIndex: 2, explanation: "This is the textbook Mover-trap pattern: access accumulates because role changes only grant, never revoke, the previous role's access." },
    { id: "iga-05", type: "concept", question: "What specifically makes a combination of permissions \"toxic\" under Segregation of Duties?", options: ["Either permission alone is dangerous", "The two permissions are rarely used together", "One identity holding both the ability to perform an action and the sole check on that same action", "The permissions span two different systems"], answerIndex: 2, explanation: "A toxic combination is defined precisely: the ability to both perform an action and be the only check on it. Neither permission needs to be dangerous in isolation." },
    { id: "iga-06", type: "scenario", question: "A Meridian Trust teller can both create a wire transfer request and approve it. What kind of problem is this?", options: ["A performance optimization, since one person can complete the task faster", "A toxic combination — Segregation of Duties is violated because the same identity both performs and checks the same action", "Not a problem as long as the teller is trustworthy", "An authentication (AuthN) issue, not an authorization (AuthZ) issue"], answerIndex: 1, explanation: "This is the canonical SoD violation: the teller could originate a fraudulent transfer and approve it themselves with no independent check." },
    { id: "iga-07", type: "scenario", question: "Riverside Health runs periodic access certification campaigns over clinician EHR access. Which compliance concept does this operationally support?", options: ["PCI-DSS cardholder data isolation", "GDPR's right to erasure", "HIPAA's minimum necessary standard — limiting access to what's currently needed", "SOC 2's availability trust service criterion"], answerIndex: 2, explanation: "Recurring certification is the mechanism that makes HIPAA's 'minimum necessary' standard demonstrable rather than just asserted, since chart access tends to outlive the clinical reason for it." },
    { id: "iga-08", type: "concept", question: "Why can't event-driven provisioning and deprovisioning alone keep an identity's access correct over time?", options: ["Because provisioning and deprovisioning are deprecated concepts", "Because they only react to events someone remembered to trigger — they can't catch access that accumulated without any triggering event", "Because Keycloak doesn't support provisioning events", "Because access reviews are required by law in every jurisdiction"], answerIndex: 1, explanation: "Stale access, by definition, has no triggering event pointing at it — only a deliberate, scheduled access review looks for it anyway." },
    { id: "iga-09", type: "compare", question: "How do an access review, an access certification, and attestation relate to each other?", options: ["They are three unrelated controls with no connection", "A review is the overall periodic exercise; a certification is the act of judging one entitlement within it; attestation is the reviewer's formally recorded confirmation", "Attestation happens before the review; certification happens after", "Certification is a synonym for deprovisioning"], answerIndex: 1, explanation: "Review is the umbrella activity, certification is the per-entitlement decision inside it, and attestation is the recorded proof that the decision was made." },
    { id: "iga-10", type: "bug", question: "A manager clicks \"certify all\" on a list of forty entitlements for twelve direct reports in under two minutes, and the campaign record shows it completed on schedule. What is wrong here?", options: ["Nothing — the campaign record proves compliance", "This is rubber-stamping: the record looks like a real review but no entitlement was actually evaluated, providing none of the review's security value", "The manager should have used a different Keycloak role", "This is a correct and efficient use of a recertification campaign"], answerIndex: 1, explanation: "A review's value comes entirely from the judgment applied, not from the existence of a dated record — rubber-stamping produces the record without the judgment." },
    { id: "iga-11", type: "concept", question: "What is \"stale access\"?", options: ["Access that was never granted correctly in the first place", "Access an identity still holds but no longer has a legitimate business reason to hold", "A session token that has expired", "A role with no permissions attached"], answerIndex: 1, explanation: "Stale access is specifically about access that was once legitimate but has outlived its justification — the thing access reviews are designed to find." },
    { id: "iga-12", type: "scenario", question: "At Meridian Trust, \"can approve wire transfers up to $5,000\" is reviewed as one specific grant during a recertification campaign, separately from everything else the teller can do. What is this specific grant called?", options: ["An attestation", "An entitlement", "A toxic combination", "A compensating control"], answerIndex: 1, explanation: "An entitlement is a single, specific grant — reviewed on its own merits rather than as part of an undifferentiated bundle of everything the identity can do." },
    { id: "iga-13", type: "compare", question: "Why is it accurate to say Keycloak is an IAM product but not an IGA product?", options: ["Because Keycloak is open source and IGA products are always commercial", "Because Keycloak enforces whatever access is configured but has no built-in feature for periodic access review, recertification campaigns, or SoD-conflict detection", "Because Keycloak doesn't support roles or groups at all", "Because IGA products don't support authentication"], answerIndex: 1, explanation: "Keycloak authenticates and enforces configured authorization, but it has no native mechanism asking whether previously-granted access is still justified — that's a genuine product-category distinction, not a missing feature to apologize for." },
    { id: "iga-14", type: "scenario", question: "Four months after an employee leaves Northwind Apps, an access review discovers their account is still active with its original permissions. What is this an example of?", options: ["A toxic combination", "An orphaned account — a missed Leaver trigger that deprovisioning never caught, found instead by the periodic review backstop", "A correctly functioning Joiner event", "An access certification"], answerIndex: 1, explanation: "An orphaned account results from a missing trigger for an existing deprovisioning process, not usually a missing process — exactly what periodic review exists to catch as a backstop." },
    { id: "iga-15", type: "concept", question: "What is the \"four-eyes principle\" (dual control)?", options: ["A requirement that every system have four administrators", "A sensitive action requires two different people — one to perform it, one to independently verify it — before it takes effect", "A biometric authentication factor using both eyes", "A rule that applies only to banking systems"], answerIndex: 1, explanation: "Four-eyes / dual control is the principle underlying SoD: two different people must be involved before a sensitive action takes effect." },
    { id: "iga-16", type: "scenario", question: "A two-person back office at Meridian Trust cannot fully separate the duties of creating and approving a transaction because there's no third person available. What is the appropriate response?", options: ["Ignore the conflict since the team is small", "Document an explicit compensating control, such as a mandatory secondary review by someone outside the team or an automatic flag on self-approved transactions", "Disable approval requirements entirely for this team", "Merge the two roles permanently since separation is impossible"], answerIndex: 1, explanation: "When true separation isn't feasible, the honest response is an explicit, documented compensating control — not a silent, unacknowledged gap." },
    { id: "iga-17", type: "compare", question: "How does a Joiner event differ from a Mover event in terms of what makes it error-prone?", options: ["Joiner events are harder because they require deleting old access", "Joiner events mostly need correct initial grants; Mover events are more error-prone because they require removing old access as well as adding new access, which is easy to skip", "Mover events never involve any access changes", "There is no meaningful difference between the two"], answerIndex: 1, explanation: "Joiner is largely a clean-slate grant. Mover is riskier precisely because it requires both an addition and a removal, and the removal half is the part beginners tend to skip." }
  ],

  "compliance-for-iam": [
    { id: "cmp-01", type: "concept", question: "What is this chapter's central argument about compliance frameworks and IAM?", options: ["Each framework defines a wholly new body of access-control theory that IAM specialists must learn separately", "Compliance frameworks largely restate the same underlying IAM fundamentals (authentication, authorization, accounting, data handling) under their own names and numbering", "Compliance frameworks are legally binding supersets of IAM theory that override earlier course concepts", "IAM concepts and compliance requirements are unrelated; compliance is a legal subject, IAM is a technical one"], answerIndex: 1, explanation: "The chapter's central claim is that GDPR, SOC 2, HIPAA, PCI-DSS, and ISO 27001 each independently converge on the same small set of IAM fundamentals under different vocabulary." },
    { id: "cmp-02", type: "scenario", question: "A Northwind Apps customer's employee emails asking what personal data Northwind holds about them and requests a copy in a machine-readable format. Which GDPR concept(s) is this request invoking?", options: ["Right to erasure only", "Data subject rights of access and portability (Articles 15 and 20)", "Lawful basis for processing only", "Data minimization"], answerIndex: 1, explanation: "A request to see and export personal data invokes the rights of access (Art. 15) and portability (Art. 20), not erasure." },
    { id: "cmp-03", type: "scenario", question: "A former Northwind customer employee invokes their GDPR right to erasure. Northwind's engineering team wants to also scrub every mention of that person from the access/audit logs used for security investigations. What does this chapter suggest they consider instead of full deletion of the logs?", options: ["Deleting all audit log entries referencing the person, since erasure requests override every other obligation", "Retaining the audit log entries but pseudonymizing the identifying fields, with legal sign-off, to balance erasure rights against audit-trail retention needs", "Ignoring the erasure request entirely because audit trails always take priority", "Moving the audit logs to a different jurisdiction to avoid GDPR scope"], answerIndex: 1, explanation: "Pseudonymizing (not deleting) log entries is the commonly used compromise, though it requires legal sign-off and isn't a universal clean answer." },
    { id: "cmp-04", type: "scenario", question: "An engineer at a SaaS company responds to a GDPR erasure request by writing a script that deletes every row in the audit log table referencing the requesting user's ID, including login and permission-change events from years prior. What is the risk in this approach?", options: ["None — this is exactly what GDPR erasure requires", "It may destroy evidence other frameworks (SOC 2, PCI-DSS Requirement 10) require retaining, and pseudonymization usually serves both obligations better", "GDPR erasure requests cannot legally be honored at all, so the script should never have run", "Audit logs are never considered personal data under GDPR, so this step was unnecessary"], answerIndex: 1, explanation: "Full deletion of audit records can conflict with other frameworks' retention requirements; pseudonymizing identifying fields is the better-reasoned middle ground." },
    { id: "cmp-05", type: "concept", question: "SOC 2 reports can cover up to five Trust Services Criteria categories. Which one is required in every SOC 2 report?", options: ["Privacy", "Availability", "Security", "Processing Integrity"], answerIndex: 2, explanation: "Security is the only Trust Services Criteria category mandatory in every SOC 2 report." },
    { id: "cmp-06", type: "scenario", question: "Meridian Trust is legally required to comply with PCI-DSS because it processes card payments. Why might Meridian also pursue a SOC 2 report even though no law mandates it?", options: ["SOC 2 legally supersedes PCI-DSS for banks", "Enterprise banking partners and fintech integrators commonly require a clean SOC 2 report before signing a contract, making it a commercial rather than legal necessity", "SOC 2 is required for any company with more than 50 employees", "PCI-DSS compliance automatically satisfies SOC 2 requirements, so pursuing both is redundant"], answerIndex: 1, explanation: "SOC 2 is frequently a commercial requirement (B2B partners demand it) layered on top of a separate legal requirement like PCI-DSS." },
    { id: "cmp-07", type: "scenario", question: "Meridian Trust is primarily scoped to PCI-DSS and SOC 2 in this course's case studies. What additional compliance exposure should a specialist check for before assuming that's the complete list?", options: ["None — banks are automatically exempt from every other framework", "Whether Meridian has any EU-based retail customers or staff, which would bring GDPR obligations into scope as well", "Whether Meridian has ever been audited before, which determines all future scope", "HIPAA, since all financial institutions are covered entities"], answerIndex: 1, explanation: "Real organizations often carry overlapping obligations; EU customer or staff exposure would bring GDPR into scope regardless of industry." },
    { id: "cmp-08", type: "concept", question: "The HIPAA Security Rule organizes its requirements into three categories of safeguards. What are they?", options: ["Preventive, detective, and corrective", "Administrative, physical, and technical", "Strategic, tactical, and operational", "Confidentiality, integrity, and availability"], answerIndex: 1, explanation: "The HIPAA Security Rule's three safeguard categories are administrative, physical, and technical." },
    { id: "cmp-09", type: "bug", question: "A compliance document states: \"Per the HIPAA Security Rule, covered entities must apply the minimum necessary standard to all ePHI access.\" What's imprecise about this statement?", options: ["Nothing — this is an accurate description", "The minimum necessary standard is codified in the HIPAA Privacy Rule (45 CFR §164.502(b)/§164.514(d)), not the Security Rule, even though access control design is one of the main ways it's operationally satisfied", "HIPAA has no minimum necessary standard at all", "The minimum necessary standard only applies to paper records, not ePHI"], answerIndex: 1, explanation: "Minimum necessary is a Privacy Rule term, a sibling regulation to the Security Rule — commonly blurred together but formally distinct." },
    { id: "cmp-10", type: "scenario", question: "Riverside Health wants to satisfy HIPAA's minimum necessary standard for clinician access to patient charts without giving every clinician blanket access to every patient. Which concept from this course's authorization-models chapter is the natural fit for implementing this concretely?", options: ["A flat ACL granting all clinicians the same fixed permission set", "A relationship-based access control (ReBAC) model that grants chart access only while an active clinician-patient care-team relationship exists", "A single shared \"clinician\" role with no further distinctions", "Removing audit logging to simplify access decisions"], answerIndex: 1, explanation: "Minimum necessary is the compliance requirement; care-team ReBAC is one concrete way to implement it." },
    { id: "cmp-11", type: "scenario", question: "An investigation at Riverside Health finds that three nurses on a shift share one login account to save time between patient rounds. Which specific HIPAA Security Rule requirement does this violate?", options: ["Audit controls (§164.312(b))", "Unique user identification, a required implementation specification under access control (§164.312(a))", "Data minimization", "The right to erasure"], answerIndex: 1, explanation: "Unique user identification requires every user to have their own distinct identifier, never a shared login." },
    { id: "cmp-12", type: "concept", question: "PCI-DSS Requirement 10 represents which IAM concept under a different name?", options: ["Least privilege", "Multi-factor authentication", "Accounting / audit trail", "Data minimization"], answerIndex: 2, explanation: "Requirement 10 (\"track and monitor all access\") is accounting/audit trail by PCI-DSS's own name." },
    { id: "cmp-13", type: "scenario", question: "At Meridian Trust, the tellers who process routine deposits and the staff who approve outbound wire transfers have deliberately different access profiles, even though both work in retail banking operations. Which PCI-DSS requirement is this separation most directly satisfying, and which IAM principle does it map to?", options: ["Requirement 10; accounting", "Requirement 8; authentication", "Requirement 7; least privilege (restricting access by business need-to-know)", "Requirement 3; encryption at rest"], answerIndex: 2, explanation: "Requirement 7's need-to-know restriction is least privilege by PCI-DSS's own name." },
    { id: "cmp-14", type: "scenario", question: "Meridian Trust requires every employee logging into any system that touches cardholder data to use MFA, not just a password. Which PCI-DSS requirement specifically mandates this, and which earlier chapter already covered the underlying mechanism?", options: ["Requirement 7; chapter 6 (authorization models)", "Requirement 8; chapter 5 (authentication factors & MFA)", "Requirement 12; chapter 9 (threat landscape)", "Requirement 1; chapter 4 (directory services)"], answerIndex: 1, explanation: "Requirement 8 mandates MFA for all access into the Cardholder Data Environment; chapter 5 covers MFA mechanics." },
    { id: "cmp-15", type: "compare", question: "Compare ISO/IEC 27001's 2013 and 2022 editions in terms of Annex A structure.", options: ["Both editions have identical Annex A numbering; only the main clauses changed", "The 2013 edition had 114 controls across 14 categories; the 2022 edition reorganized this into 93 controls across 4 themes, renumbering access-control content into the 5.x/8.x ranges", "The 2022 edition added 50 new controls not present in 2013", "ISO 27001 has never had an Annex A; that's a feature unique to ISO 27002"], answerIndex: 1, explanation: "The 2022 edition cut Annex A from 114 controls/14 categories to 93 controls/4 themes, with access-control content moving into the 5.x/8.x ranges." },
    { id: "cmp-16", type: "concept", question: "In ISO/IEC 27001:2022's Annex A, which control covers identity management specifically, as distinct from the overarching access control policy?", options: ["A.5.15", "A.5.16", "A.8.2", "A.8.5"], answerIndex: 1, explanation: "A.5.15 is the overarching access control policy; A.5.16 is identity management specifically." },
    { id: "cmp-17", type: "bug", question: "A specialist reviews a client's Statement of Applicability and sees it cites \"A.9.4.1 — Information access restriction\" as evidence of their current ISO 27001 certification. What should the specialist check before accepting this?", options: ["Nothing — A.9.4.1 is valid in every edition of ISO 27001", "Whether the document is citing the 2013 edition's numbering (which the 2022 edition renumbered, e.g., into the 8.x range) rather than confirming current 2022-edition compliance", "Whether the client has ever read the standard at all", "Whether A.9.4.1 refers to a PCI-DSS requirement instead"], answerIndex: 1, explanation: "A.9.4.1 is 2013-edition numbering; the 2022 edition renumbered this content, so the citation needs checking against the edition actually in force." },
    { id: "cmp-18", type: "scenario", question: "Northwind Apps needs SOC 2 so enterprise buyers will sign contracts, and also has GDPR exposure because of its EU customers. What does this combination illustrate about real-world compliance work?", options: ["Organizations only ever need to satisfy one framework, chosen based on industry", "Commercial requirements (like a customer demanding a SOC 2 report) and legal requirements (like GDPR, triggered by data subject location) can both apply to the same organization simultaneously, and a specialist must map actual data/people populations against all applicable frameworks rather than assuming a single one", "GDPR only applies to companies headquartered in the EU", "SOC 2 compliance automatically satisfies GDPR requirements"], answerIndex: 1, explanation: "Real organizations commonly carry overlapping legal and commercial compliance obligations simultaneously." },
    { id: "cmp-19", type: "bug", question: "A vendor's marketing page states: \"As required under the newly finalized 2025 HIPAA Security Rule overhaul, all covered entities must now implement mandatory encryption with no addressable exceptions.\" What's the problem with this claim, based on this chapter's research?", options: ["Nothing — the overhaul was finalized exactly as described", "As of this chapter's research, the January 2025 NPRM proposing that overhaul had not been finalized, with its target final-action date having already slipped toward 2027 — the claim treats a proposal as if it were already law", "HIPAA has never proposed any changes to encryption requirements", "The Security Rule does not cover encryption at all, so the claim is unrelated"], answerIndex: 1, explanation: "The 2025 NPRM is still a proposal, not a final rule, as of the research done for this chapter." },
    { id: "cmp-20", type: "compare", question: "Compare GDPR's data minimization principle with PCI-DSS's Cardholder Data Environment (CDE) scoping practice.", options: ["They are unrelated concepts from entirely different domains with no common theme", "Both are, at heart, strategies for reducing exposure — GDPR by limiting what personal data is collected/retained in the first place, PCI-DSS by limiting which systems are considered in-scope for cardholder data — even though one is a legal principle and the other an audit-scoping practice", "GDPR data minimization is a subset of PCI-DSS Requirement 7", "PCI-DSS CDE scoping is the IAM concept being referred to when GDPR says \"lawful basis\""], answerIndex: 1, explanation: "Both principles reduce exposure/risk by shrinking scope, even though they come from different regulatory traditions." }
  ],

  "iam-market-landscape": [
    { id: "mkt-01", type: "concept", question: "What is the key difference between Workforce IAM and CIAM?", options: ["Workforce IAM manages a bounded, HR-backed population of an organization's own people; CIAM manages an unbounded, self-registering population of external customers at consumer scale", "Workforce IAM only applies to on-premises directories; CIAM only applies to cloud directories", "CIAM is a subset of Workforce IAM used for contractors", "There is no meaningful difference; the terms are interchangeable"], answerIndex: 0, explanation: "Workforce IAM's population roughly tracks headcount and is HR-backed; CIAM's population is unbounded and self-registering, at a very different scale." },
    { id: "mkt-02", type: "concept", question: "What does PAM (Privileged Access Management) specifically add on top of ordinary authentication and authorization?", options: ["A faster login page for executives", "Credential vaulting, session recording, and just-in-time privilege elevation for the highest-risk accounts", "Social login buttons for consumer apps", "A replacement for multi-factor authentication"], answerIndex: 1, explanation: "PAM targets the smaller, higher-risk slice of privileged accounts with vaulting, recording, and JIT elevation — distinct from everyday AuthN/AuthZ." },
    { id: "mkt-03", type: "concept", question: "Why does this chapter only reference IGA rather than redefining it?", options: ["IGA isn't a real market category", "Chapter 10 already owns the full definition of IGA as a governance/process discipline; this chapter only discusses IGA as a tooling/market category to avoid duplicating that definition", "IGA was renamed to PAM", "Keycloak implements IGA natively, so no separate definition is needed"], answerIndex: 1, explanation: "The course avoids duplicate definitions across chapters; ch10 owns IGA's definition, ch12 only discusses the tooling category." },
    { id: "mkt-04", type: "concept", question: "Which of these is an example of a privileged account in the PAM sense?", options: ["A help-desk agent who can reset passwords for one department", "A regular employee's email login", "A domain-controller admin account with broad access across the network", "A customer's self-registered account on a public website"], answerIndex: 2, explanation: "Scope and blast radius determine 'privileged' status, not just the word 'admin' — a domain-controller admin is privileged; a narrowly-scoped help-desk admin is not, in the PAM sense." },
    { id: "mkt-05", type: "concept", question: "What is just-in-time (JIT) privilege elevation designed to reduce?", options: ["The number of MFA prompts a user sees", "The length of time an elevated permission exists, shrinking how long a compromised credential would be dangerous", "The cost of a SaaS subscription", "The number of applications an SSO session covers"], answerIndex: 1, explanation: "JIT elevation grants elevated access for a limited window tied to a task, instead of standing privileged access held permanently." },
    { id: "mkt-06", type: "compare", question: "How does 'open-source vs. commercial IAM' differ as an axis from 'self-hosted vs. SaaS/managed IAM'?", options: ["They are the same axis described two different ways", "Open-source vs. commercial is about licensing/cost model; self-hosted vs. SaaS is about who operates the running system — a commercial product can still be self-hosted, and some open-source projects are offered as managed SaaS", "Open-source products can never be self-hosted", "SaaS products are always open-source"], answerIndex: 1, explanation: "These are genuinely separate axes: licensing model vs. operational responsibility. A commercial product can be self-hosted; an open-source product can be consumed as a managed SaaS offering." },
    { id: "mkt-07", type: "concept", question: "Why is 'Keycloak has no license fee' an incomplete answer to 'which is cheaper overall'?", options: ["Keycloak actually does have a license fee", "Total cost of ownership also includes operational expertise, infrastructure, patching, and tuning labor that a self-hosted deployment must supply itself", "SaaS products are always cheaper regardless of scale", "License fees are the only real cost in any IAM system"], answerIndex: 1, explanation: "TCO is the right lens — 'free to license' doesn't mean 'cheap overall' once operational burden is counted." },
    { id: "mkt-08", type: "concept", question: "What is data residency, in the IAM context?", options: ["How long a user session stays active before timing out", "Where identity data is physically stored and which jurisdiction's laws govern it", "The number of data centers a vendor operates", "A synonym for vendor lock-in"], answerIndex: 1, explanation: "Data residency concerns the physical location and governing jurisdiction of identity data, a real driver toward self-hosting for regulated organizations." },
    { id: "mkt-09", type: "scenario", question: "Northwind Apps runs a multi-tenant B2B SaaS product with thousands of end-customer logins across many tenant companies. Which market category does it most likely need first?", options: ["PAM", "IGA", "CIAM", "A directory service only"], answerIndex: 2, explanation: "Northwind's consumer-scale, self-registering end-customer population is a textbook CIAM shape." },
    { id: "mkt-10", type: "scenario", question: "Riverside Health, a hospital network under HIPAA, is weighing a self-hosted Keycloak deployment against a commercial SaaS workforce IAM product. What is the strongest category-specific reason it might lean toward self-hosting?", options: ["Self-hosting is always cheaper in absolute dollar terms", "Data residency and regulatory control concerns push it toward wanting full visibility into where identity data lives", "SaaS products cannot support MFA", "CIAM products are mandatory under HIPAA"], answerIndex: 1, explanation: "HIPAA-driven data-residency and control concerns are a real, defensible reason to prefer self-hosting, independent of raw cost comparisons." },
    { id: "mkt-11", type: "scenario", question: "Meridian Trust, a retail bank, has workforce IAM in place for everyday employee access to internal systems. A security review finds that admins with direct access to core banking infrastructure have no session recording or time-boxed elevation. What gap does this describe?", options: ["A CIAM gap", "A missing PAM layer on top of its existing workforce IAM", "A missing MFA requirement", "An IGA access-certification gap only"], answerIndex: 1, explanation: "Workforce IAM answers 'who is this and what role do they hold'; it doesn't by itself vault, record, or time-box the smaller set of highest-risk privileged sessions — that's PAM's job." },
    { id: "mkt-12", type: "scenario", question: "A team says, 'We already have Okta for workforce SSO, so we don't need to evaluate anything else for privileged admin access to our production database.' What is wrong with this reasoning?", options: ["Nothing — workforce IAM always covers privileged access needs too", "Workforce IAM and PAM are different market categories solving different problems; having one doesn't imply the other is covered", "Okta cannot be used for workforce SSO", "PAM is only relevant for IGA-regulated industries"], answerIndex: 1, explanation: "This is the chapter's core pitfall: 'we have IAM' doesn't answer 'do we have PAM' — they're separate purchases solving different problems." },
    { id: "mkt-13", type: "concept", question: "As of this chapter's live research (November 2026), what is the current corporate/branding relationship between Auth0 and Okta?", options: ["Auth0 was spun off from Okta into an independent company in 2026", "Auth0 remains part of Okta (acquired 2021); current branding is 'Okta Customer Identity Cloud, powered by Auth0' / 'Auth0 by Okta,' with product/engineering orgs unifying further in 2026", "Auth0 was acquired by Microsoft in 2026", "Auth0 and Okta have always been fully separate companies"], answerIndex: 1, explanation: "The 2021 acquisition stands; what changed in 2026 was branding/org structure, not ownership." },
    { id: "mkt-14", type: "concept", question: "What is the current, live-verified status of ForgeRock relative to Ping Identity, and why does this chapter hedge on part of it?", options: ["ForgeRock was shut down entirely in 2023", "ForgeRock was acquired by Thoma Bravo and folded into Ping Identity (settled fact), but how far the product-line/brand merge has gone is disputed across sources, so the chapter states that honestly rather than asserting a specific integration depth", "ForgeRock acquired Ping Identity", "ForgeRock and Ping Identity remain entirely unrelated companies"], answerIndex: 1, explanation: "The acquisition itself is settled; the degree of product/brand integration is genuinely ambiguous in current sources, which the chapter flags rather than guessing." },
    { id: "mkt-15", type: "concept", question: "What is Microsoft's current branding for its identity product, as of November 2026?", options: ["Azure Active Directory (Azure AD)", "Microsoft Entra ID — unchanged since its 2023 rename from Azure AD, with no further rebrand found", "Microsoft Identity Cloud", "Windows Active Directory Online"], answerIndex: 1, explanation: "The 2023 Azure AD → Microsoft Entra ID rename is still current; no evidence of a further rebrand as of this chapter's research." },
    { id: "mkt-16", type: "concept", question: "What is the single most surprising, easy-to-miss corporate fact this chapter's live research turned up in the PAM category?", options: ["CyberArk went out of business in 2025", "Palo Alto Networks acquired CyberArk in February 2026 and rebranded the product line 'Idira' in May 2026 — most practitioners still say 'CyberArk,' but the current corporate/product name has changed", "BeyondTrust acquired CyberArk", "CyberArk merged with SailPoint to form a combined PAM/IGA company"], answerIndex: 1, explanation: "This is confirmed across multiple independent sources (including Palo Alto Networks' own site) and is flagged in the chapter as the most consequential fact to get right." },
    { id: "mkt-17", type: "compare", question: "Why does this chapter name both SailPoint and Saviynt for the IGA category, and both CyberArk/Idira and BeyondTrust for PAM, rather than naming one clear 'winner' for each?", options: ["Because the course avoids being specific about anything", "Because no neutral, up-to-date source found in live research named one undisputed market leader for 2026 in either category — naming both candidates honestly reflects that rather than asserting a precise ranking the research couldn't confirm", "Because SailPoint and Saviynt are actually the same company", "Because PAM and IGA are the same market category"], answerIndex: 1, explanation: "This follows the course's no-invented-facts discipline: when sources disagree or can't confirm a clean 'winner,' the chapter says so rather than asserting a precise claim." },
    { id: "mkt-18", type: "scenario", question: "An organization is deciding between Keycloak and a commercial SaaS IAM product. It has a small team with limited time to run new infrastructure, wants extremely fast time-to-value, and is willing to pay a premium to avoid operational work. Which choice does this chapter suggest fits better, and why?", options: ["Keycloak, because it's free to license", "A commercial SaaS alternative, because it outsources operational burden in exchange for subscription cost — exactly the trade-off this organization is describing wanting", "Neither — the organization should build its own IAM system from scratch", "Keycloak, because commercial products cannot be trusted with sensitive data"], answerIndex: 1, explanation: "The chapter's honest framing: Keycloak suits orgs with (or willing to build) real operational capacity; commercial SaaS suits orgs that want to pay to outsource that burden entirely — this scenario describes the latter." }
  ],

  "oauth2-core": [
    { id: "oac-01", type: "concept", question: "Which OAuth 2.0 role is best described as \"a protected API\"?", options: ["Resource Owner", "Client", "Authorization Server", "Resource Server"], answerIndex: 3, explanation: "Resource Server hosts protected resources and accepts requests bearing an access token — in plain terms, an API." },
    { id: "oac-02", type: "concept", question: "Which OAuth 2.0 role most closely maps onto chapter 7's Identity Provider (IdP)?", options: ["Resource Owner", "Client", "Authorization Server", "Resource Server"], answerIndex: 2, explanation: "The Authorization Server authenticates the resource owner and issues tokens — roughly the IdP function, though the mapping isn't a clean 1:1 rename." },
    { id: "oac-03", type: "compare", question: "Chapter 7's IdP/SP/RP vocabulary has no named equivalent for which OAuth 2.0 role?", options: ["Authorization Server, because it's identical to IdP", "Resource Owner and Resource Server, because SSO/federation never needed to name the end user or a protected API as formal roles", "Client, because SP and RP already cover it exactly", "All four roles have exact chapter 7 equivalents"], answerIndex: 1, explanation: "OAuth introduces Resource Owner (the end user, named directly because OAuth is a delegation protocol) and Resource Server (a protected API) — neither has a chapter 7 equivalent." },
    { id: "oac-04", type: "scenario", question: "Northwind Apps is registering a new OAuth client for an enterprise customer's dashboard integration. The customer asks Northwind to accept any redirect_uri under *.customer-co.example for convenience during setup. What should Northwind's security team do?", options: ["Approve it — broader patterns are fine as long as the domain is correct", "Refuse, and register only the exact, full callback URL the dashboard will actually use", "Approve it only if the customer uses HTTPS", "Approve it but require client authentication instead"], answerIndex: 1, explanation: "RFC 6749 requires exact, simple-string-comparison redirect URI matching specifically because anything broader lets an attacker who controls any page under that domain hijack a real user's authorization code." },
    { id: "oac-05", type: "scenario", question: "Meridian Trust's mobile banking app uses the authorization code flow with PKCE. Why is PKCE valuable here even though the app also uses TLS everywhere?", options: ["PKCE replaces the need for TLS", "PKCE protects against a different threat: if the authorization code itself is intercepted (e.g. by another app on the same device via a custom URL scheme), it's useless without the matching code_verifier, which was never transmitted", "PKCE is only relevant for client-credentials grants", "PKCE prevents the access token from expiring"], answerIndex: 1, explanation: "PKCE closes the code-interception gap specifically — the verifier never travels in plaintext until the final token exchange, so an intercepted code alone isn't enough." },
    { id: "oac-06", type: "bug", question: "A Riverside Health engineer debugging a clinician-portal login notices the access_token appears directly in the browser's URL fragment immediately after the redirect, with no separate code-exchange step. What's the most likely cause?", options: ["Correct authorization code flow behavior", "The app is using the deprecated Implicit grant, which returns the token directly in the fragment instead of an intermediate code", "A PKCE misconfiguration", "A client_credentials misconfiguration"], answerIndex: 1, explanation: "The Implicit grant skips the code-exchange step and puts the access token straight into the redirect URL's fragment — exactly the symptom described, and one reason it's now discouraged." },
    { id: "oac-07", type: "scenario", question: "A new Riverside Health patient-portal SPA needs to log users in via OAuth without a backend that could hold a client secret. Which combination is the current best-practice choice?", options: ["Resource Owner Password Credentials, since there's no secret to protect anyway", "Implicit grant, since it's designed for browsers", "Authorization code flow with PKCE, treating the SPA as a public client", "Client credentials grant, impersonating the logged-in user"], answerIndex: 2, explanation: "Authorization code + PKCE is exactly the pattern designed for public clients that can't hold a secret safely, and is current best practice regardless." },
    { id: "oac-08", type: "concept", question: "What specifically does PKCE protect against?", options: ["Weak passwords at the authorization server's login page", "An intercepted authorization code being redeemed for tokens by someone other than the client that requested it", "Expired access tokens being accepted", "Resource servers accepting tokens from the wrong issuer"], answerIndex: 1, explanation: "PKCE's whole point is binding the eventual code exchange to whoever holds the original code_verifier, so an intercepted code alone isn't redeemable." },
    { id: "oac-09", type: "concept", question: "In the authorization code flow, which value is exchanged at the token endpoint, and which never leaves the browser's redirect?", options: ["The access token is exchanged at the token endpoint; the authorization code stays in the browser", "The authorization code is exchanged, server-to-server, at the token endpoint for an access token; only the short-lived code ever appears in the browser's redirect", "Both the code and the access token travel through the browser", "Neither travels through the browser — both are sent server-to-server from the start"], answerIndex: 1, explanation: "The browser only ever sees the short-lived code; the actual access token exchange happens over a direct, server-to-server call to the token endpoint." },
    { id: "oac-10", type: "bug", question: "A token endpoint returns the identical {\"error\":\"invalid_grant\"} for a bad authorization code, a reused code, and a wrong PKCE verifier. Is this a bug?", options: ["Yes — it should return a distinct error for each case to help debugging", "No — returning a generic error for all three is a deliberate choice, since a more specific error would help an attacker determine which part of a forged request is wrong", "Yes — it violates the OAuth 2.0 spec", "No, but only because PKCE is optional"], answerIndex: 1, explanation: "A token endpoint intentionally collapses distinct failure causes into one generic error to avoid leaking information useful to an attacker probing a forged request." },
    { id: "oac-11", type: "scenario", question: "Northwind's security team is reviewing a candidate authorization server that validates redirect_uri by checking whether the submitted value starts with the registered one, rather than exact string comparison. What's the concrete risk?", options: ["None — prefix matching is equivalent to exact matching in practice", "An attacker who controls any path extending the registered prefix (e.g. a sibling route, a misconfigured subpath) could receive a real user's authorization code and exchange it for tokens issued in that user's name", "It only affects client_credentials grants, not authorization code", "It would cause logins to fail entirely"], answerIndex: 1, explanation: "Prefix/substring matching lets anything sharing that prefix qualify as a valid destination — exactly the gap RFC 6749's exact-match requirement exists to close." },
    { id: "oac-12", type: "concept", question: "Per RFC 6749 §3.1.2.3, how must an authorization server compare a submitted redirect_uri against a fully-registered redirect URI?", options: ["Case-insensitive domain match only", "Same-origin check (scheme + host)", "Simple string comparison — an exact match", "Substring containment is sufficient"], answerIndex: 2, explanation: "RFC 6749 §3.1.2.3 requires the authorization server to compare the two URIs using simple string comparison when the full redirect URI was registered — an exact match, not a looser check." },
    { id: "oac-13", type: "scenario", question: "Meridian Trust needs its nightly batch-reporting service to call an internal API with no human user involved at any point. Which OAuth grant type fits?", options: ["Authorization code with PKCE", "Implicit grant", "Client credentials grant", "Device authorization grant"], answerIndex: 2, explanation: "Client credentials is the machine-to-machine grant: the client authenticates as itself with no resource owner or browser step at all — exactly this scenario." },
    { id: "oac-14", type: "compare", question: "What's the key difference between the client credentials grant and the device authorization grant?", options: ["Client credentials needs a browser; device code doesn't", "Client credentials involves no resource owner or browser at all; device code involves a human approving a code on a separate device that does have a browser", "They're the same grant under two names", "Device code is for confidential clients only; client credentials is for public clients only"], answerIndex: 1, explanation: "Client credentials is pure machine-to-machine with no human step; device code specifically exists for devices without a usable browser, requiring a human to approve on a second device." },
    { id: "oac-15", type: "scenario", question: "Riverside Health is building a CLI tool for lab technicians with no browser available on the terminal it runs on. Which grant type, previewed in this chapter and covered in full in chapter 14, fits this case?", options: ["Resource Owner Password Credentials", "Implicit grant", "Device authorization grant", "Authorization code without PKCE"], answerIndex: 2, explanation: "Device authorization grant is designed exactly for this: the CLI tool displays a code, and the technician approves it on a separate device with a browser." },
    { id: "oac-16", type: "concept", question: "What is the relationship between a PKCE code_verifier and code_challenge?", options: ["They are the same value, just named differently", "code_challenge is an encrypted version of code_verifier that the server can decrypt", "code_challenge = base64url(SHA-256(code_verifier)) under the S256 method — a one-way derivation that cannot be reversed", "code_verifier is derived from code_challenge after login"], answerIndex: 2, explanation: "Under S256, the challenge is a one-way SHA-256 hash of the verifier, base64url-encoded — it can be checked against a verifier but never reversed back into one." },
    { id: "oac-17", type: "bug", question: "A developer sets code_challenge_method=plain and sets code_challenge equal to code_verifier directly, reasoning \"it's simpler and still checks the value matches.\" What's wrong with this?", options: ["Nothing — plain is just as secure as S256", "Under \"plain,\" the challenge sent in the clear in the authorize request IS the verifier itself — so anyone who intercepts the authorize request already has the verifier, defeating PKCE's entire purpose", "plain mode is rejected by all authorization servers", "This only matters for confidential clients"], answerIndex: 1, explanation: "The plain method sends the verifier itself as the challenge, visible in the authorize request — exactly the value PKCE is supposed to keep secret until the token exchange, so it offers no real protection if that initial request is observed." },
    { id: "oac-18", type: "scenario", question: "After learning that a public demo authorization server didn't enforce exact-match redirect_uri validation for one of its clients — and that an authorization code could be redirected to an attacker-controlled domain and exchanged for real tokens — what's the correct lesson for Northwind Apps to take into its own production client registrations?", options: ["Public demo servers are never a useful reference, so the finding is irrelevant", "Exact-match redirect_uri validation is a real, exploitable security control, not a formality — Northwind must ensure its own Authorization Server enforces it strictly, since a loosely configured one would permit the identical attack against real user accounts", "The finding proves PKCE is unnecessary if redirect_uri validation exists", "The finding only applies to the client_credentials grant"], answerIndex: 1, explanation: "The live finding is a concrete demonstration of exactly what RFC 6749's exact-match requirement is meant to prevent — a production system without strict enforcement is genuinely exploitable, not just theoretically non-compliant." }
  ],

  "oauth2-extended": [
    { id: "oax-01", type: "concept", question: "Why does the device authorization grant need no registered redirect_uri at all?", options: ["Because it doesn't use HTTPS", "Because the interactive step happens entirely on a separate, browser-capable device the user already has, not on the constrained device itself", "Because device flow doesn't support scopes", "Because the device client always has a client secret"], answerIndex: 1, explanation: "The constrained device never receives a browser redirect at all — a second device handles login/approval and the first device only ever talks to the token endpoint directly." },
    { id: "oax-02", type: "scenario", question: "A CLI tool polls the token endpoint during a device-flow login and gets back {\"error\": \"authorization_pending\"}. What should the CLI do?", options: ["Abort immediately and show an error to the user", "Treat it as the expected, normal response and keep polling at the server-advertised interval", "Immediately retry as fast as possible to beat a race condition", "Fall back to the authorization code flow"], answerIndex: 1, explanation: "authorization_pending is the expected response on every poll until the human finishes logging in and approving — not a failure." },
    { id: "oax-03", type: "bug", question: "A device-flow client ignores a slow_down response and keeps polling at its original rate. What is the likely consequence, per RFC 8628?", options: ["Nothing — slow_down is purely informational", "The client should expect further rate-limiting or its device code being invalidated", "The access token will be issued faster", "The client's client_id will be permanently revoked"], answerIndex: 1, explanation: "RFC 8628 expects a client to back off its polling interval after receiving slow_down; ignoring it risks further throttling or an invalidated code." },
    { id: "oax-04", type: "concept", question: "What distinguishes the client credentials grant from every other OAuth grant covered in this course so far?", options: ["It requires a refresh token", "It has no resource owner at all — the client authenticates as itself, with no user context in the request", "It can only be used over HTTP, not HTTPS", "It always issues an ID token"], answerIndex: 1, explanation: "Client credentials is pure machine-to-machine: the request identifies the client, not any user, because there is no user." },
    { id: "oax-05", type: "scenario", question: "Meridian Trust's nightly fraud-scoring job calls the core banking ledger service with no human involved. Which grant type fits, and why?", options: ["Authorization code with PKCE, because it's the most secure option", "Client credentials, because this is exactly the no-resource-owner, service-to-service case it exists for", "Device authorization grant, because the job runs on a server with no browser", "Implicit grant, because it's the simplest"], answerIndex: 1, explanation: "No user is involved at all — one internal service calling another is the textbook client credentials use case, contrasted directly with chapter 13's user-present authorization code flow." },
    { id: "oax-06", type: "compare", question: "How does an access token obtained via client credentials typically differ from one obtained via a user-present flow, at the claims level?", options: ["It has no exp claim", "It typically has no sub claim identifying a human subject — it identifies the client instead (e.g. client_id)", "It is always a reference token", "It cannot be introspected"], answerIndex: 1, explanation: "A client credentials token represents the client itself, not a user — there is no resource owner to put in a sub claim." },
    { id: "oax-07", type: "concept", question: "What does an RFC 7662 token introspection response's active field mean?", options: ["Whether the token was ever issued by this specific client", "Whether the authorization server currently considers the token valid", "Whether the token has a refresh_token attached", "Whether the token was issued less than a minute ago"], answerIndex: 1, explanation: "active is the central fact introspection exists to report: is this token still good, right now, according to the authorization server." },
    { id: "oax-08", type: "bug", question: "Introspecting a token string that the authorization server has never issued returns {\"active\": false} with almost no other fields, while introspecting a real expired token returns the full claim set plus active:false. Why the difference in response shape?", options: ["It's a bug in most implementations", "RFC 7662 deliberately keeps the unknown-token response minimal so the endpoint can't be used to fish for information about which tokens are real", "Expired tokens are always reference tokens", "Only JWTs get the full claim set back"], answerIndex: 1, explanation: "Minimizing the response for unrecognized tokens prevents using introspection as an oracle to discover valid token values." },
    { id: "oax-09", type: "scenario", question: "A team revokes a compromised access token via the revocation endpoint and gets back HTTP 200. They tell their incident commander 'access was cut off immediately.' What should be verified before accepting that claim?", options: ["Nothing — HTTP 200 always means the token stopped working", "Whether the token was a reference (server-tracked) token or a self-contained JWT — only the former is guaranteed to actually stop working immediately", "Whether the token had an aud claim", "Whether the client used HTTP Basic or POST body authentication"], answerIndex: 1, explanation: "RFC 7009 permits returning 200 even when nothing was actually invalidated; a self-contained JWT with no server-side record may keep reporting active:true until it naturally expires." },
    { id: "oax-10", type: "bug", question: "This chapter's own lab revoked a self-contained JWT access token via /connect/revocation (got HTTP 200), then immediately introspected the same token and got active:true. What explains this, precisely?", options: ["The revocation call failed silently", "The authorization server never stored a server-side record of that specific token to delete, so introspection re-checked only the token's own signature and expiry, both still valid", "Introspection always ignores revocation", "The wrong client credentials were used for introspection"], answerIndex: 1, explanation: "A self-contained JWT carries its own proof and typically has no corresponding server-side row — there's nothing for revocation to delete, so introspection (checking signature + exp) still reports it valid." },
    { id: "oax-11", type: "compare", question: "Why does a reference (opaque) access token revoke more reliably than a self-contained JWT access token?", options: ["Reference tokens are encrypted and JWTs are not", "A reference token's validity is backed by a real server-side record that revocation can delete; introspecting it after deletion correctly finds nothing. A JWT's validity is self-proven by its own signature, with nothing server-side to delete.", "JWTs cannot be introspected at all", "Reference tokens never expire"], answerIndex: 1, explanation: "The difference is architectural: one design relies on a server-side lookup (deletable), the other relies on self-contained cryptographic proof (nothing to delete)." },
    { id: "oax-12", type: "concept", question: "What problem does token exchange (RFC 8693) solve that neither client credentials nor the device flow addresses?", options: ["Issuing the very first token in a session", "Letting a client trade an existing token for a new one — e.g. with a narrower scope/audience (downscoping), or to let one service act for another", "Encrypting a token's claims", "Rotating a signing key"], answerIndex: 1, explanation: "Token exchange is specifically about converting one already-issued token into another, differently-scoped or differently-actored one." },
    { id: "oax-13", type: "compare", question: "What is the practical difference between delegation and impersonation as token-exchange outcomes (RFC 8693)?", options: ["Delegation issues a longer-lived token than impersonation", "Delegation keeps an act claim showing who is really acting on a subject's behalf; impersonation drops it, making the new request indistinguishable from the original subject's own", "Impersonation is only available to public clients", "There is no real difference — they are two names for the same mechanism"], answerIndex: 1, explanation: "The act claim is the entire distinction: delegation preserves traceability of who is really making the downstream call, impersonation erases it." },
    { id: "oax-14", type: "bug", question: "A chapter covering token exchange wants to include a live lab against the demo server used throughout Part III. What should it do, given that server's discovery document does not list a token-exchange grant in grant_types_supported?", options: ["Simulate the request and present invented but plausible-looking output", "Say plainly that no live lab exists for this piece and cover the mechanism conceptually only, grounded in the RFC", "Skip the topic entirely without explanation", "Use a different, undocumented endpoint on the same server to fake the behavior"], answerIndex: 1, explanation: "This course's no-invented-facts rule requires saying so honestly rather than fabricating a lab the server doesn't actually support." },
    { id: "oax-15", type: "scenario", question: "Northwind Apps builds northwind-cli, a terminal tool with no embedded browser, for customers to manage their tenant config. Why is the device authorization grant a better fit than embedding a static long-lived API key in the tool?", options: ["Because device flow is faster to implement", "Because a static long-lived key in a CLI tool installed on many laptops/build servers is a large, hard-to-revoke blast radius if one copy leaks, while device flow issues a short-lived, revocable access token (and a server-tracked refresh token) per login instead", "Because device flow doesn't require any authentication at all", "Because static API keys are not supported by OAuth"], answerIndex: 1, explanation: "Device flow avoids embedding a permanent secret in software distributed to many machines, trading it for a per-session, more easily revoked credential." },
    { id: "oax-16", type: "concept", question: "In a device authorization grant, what is the purpose of the interval field returned alongside the device_code and user_code?", options: ["It sets how long the access token will be valid once issued", "It tells the polling device the minimum number of seconds to wait between token-endpoint polling attempts", "It sets the expiry of the user_code only, not the device_code", "It specifies how many scopes can be requested"], answerIndex: 1, explanation: "interval is the server's instruction for polling frequency; ignoring it risks a slow_down response or worse." }
  ],

  "openid-connect": [
    { id: "oidc-01", type: "concept", question: "What does OpenID Connect add on top of plain OAuth 2.0?", options: ["A completely different set of grant types that replace OAuth's", "An identity layer: the openid scope, the ID token, discovery, and UserInfo, built on OAuth's existing grants", "A mandatory requirement that all tokens be encrypted rather than signed", "A replacement for the access token that removes the need for scopes"], answerIndex: 1, explanation: "OIDC is additive. It reuses OAuth's grants unchanged and adds the openid scope, the ID token, a discovery document, and the UserInfo endpoint." },
    { id: "oidc-02", type: "scenario", question: "A developer at Meridian Trust fetches their OIDC provider's discovery document before writing any integration code. Which of these can that single JSON response tell them?", options: ["Only the authorization_endpoint, nothing else", "The authorization, token, userinfo, and jwks endpoints, plus supported scopes and claims", "The actual password hash algorithm used by the provider", "The private signing key used to sign ID tokens"], answerIndex: 1, explanation: "The discovery document exposes endpoint URLs and capability lists (scopes_supported, claims_supported, etc.) — never private keys or credential internals." },
    { id: "oidc-03", type: "concept", question: "Which claims must always be present in a valid ID token, independent of which scopes were requested?", options: ["name, email, picture", "iss, sub, aud, exp, iat", "preferred_username, email_verified", "tenant_id, subscription_tier"], answerIndex: 1, explanation: "iss, sub, aud, exp, and iat are the minimum claims OIDC Core requires on every ID token so it is independently verifiable; profile/email claims only appear if those scopes were requested." },
    { id: "oidc-04", type: "concept", question: "Why does an ID token carry an aud (audience) claim naming the client itself?", options: ["So a resource server can safely accept it in place of an access token", "So a verifier (and a careful resource server) can tell an ID token apart from an access token and reject it if it is presented where an access token is expected", "Because aud is required by TLS, not by OIDC", "To let any application on the internet reuse the token freely"], answerIndex: 1, explanation: "An ID token's audience is the client, not an API — exactly the detail that should make a resource server reject it if someone mistakenly sends an ID token instead of an access token." },
    { id: "oidc-05", type: "concept", question: "What does the email_verified claim specifically distinguish?", options: ["Whether the user has two-factor authentication enabled", "Whether the email address was confirmed through a verification flow, versus merely typed into a form", "Whether the email scope was requested at all", "Whether the user's account is currently active"], answerIndex: 1, explanation: "email_verified is a separate signal from the mere presence of an email claim — it answers whether that address was actually confirmed, not just supplied." },
    { id: "oidc-06", type: "scenario", question: "Northwind Apps checks its OIDC provider's claims_supported list and finds no \"department\" claim listed anywhere. What is the correct way to get that data into a logged-in user's tokens?", options: ["Request a scope called department and hope the provider honors it", "Nothing can be done; claims_supported is fixed forever", "Ask the provider to define and advertise a custom claim (in Keycloak, via a client scope's protocol mapper)", "Decode the JWT header instead of the payload"], answerIndex: 2, explanation: "claims_supported is an advertised ceiling set by the provider. A client cannot invent a claim by requesting an arbitrary scope — the provider must add and advertise it." },
    { id: "oidc-07", type: "scenario", question: "Meridian Trust's integration team adds a nonce value to their authorization request and later checks that the same value comes back in the ID token. What is that check protecting against?", options: ["Encrypting the ID token payload", "Confirming the returned ID token was actually issued in response to this specific request, as a replay/mix-up defense", "Setting the token's expiry time", "Requesting the refresh token grant"], answerIndex: 1, explanation: "A client-supplied nonce, echoed back unchanged in the ID token, lets the client confirm the token corresponds to the request it actually sent." },
    { id: "oidc-08", type: "compare", question: "What is the key functional difference between reading a claim from an already-held ID token versus calling the UserInfo endpoint for the same claim?", options: ["UserInfo claims are always encrypted and ID token claims never are", "They are entirely different datasets with no overlap", "Reading the ID token is free (no network call) but only as fresh as login time; UserInfo requires a live call but reflects current data", "UserInfo only works for machine-to-machine clients"], answerIndex: 2, explanation: "Both paths return the same underlying claims, filtered by the same requested scopes — the trade-off is freshness (UserInfo) versus zero extra network cost (ID token)." },
    { id: "oidc-09", type: "compare", question: "How does chapter 7's general metadata concept map onto this chapter's content?", options: ["It doesn't relate at all — metadata was only ever a SAML concept", "The OIDC discovery document is the concrete, JSON implementation of the general metadata/trust idea introduced in chapter 7", "Metadata refers only to HTTP response headers in OIDC", "Metadata and the ID token are the same thing"], answerIndex: 1, explanation: "Chapter 7 defined metadata generally as a machine-readable description of endpoints/capabilities exchanged to establish trust; OIDC's discovery document is exactly that, implemented concretely." },
    { id: "oidc-10", type: "scenario", question: "Riverside Health's patient portal requests openid profile email at login and wants to greet the patient by name immediately after the redirect back, with no extra API call. Where should it read preferred_username from?", options: ["A separate call to the token introspection endpoint", "The ID token it already received in the token response", "The jwks_uri endpoint", "A hardcoded default value"], answerIndex: 1, explanation: "Because profile was requested, preferred_username rides inside the ID token already returned — no second call is needed, which is exactly why the portal can render immediately." },
    { id: "oidc-11", type: "scenario", question: "A patient at Riverside Health clicks an email verification link in a second browser tab while their portal session (and its already-issued ID token) is still open in the first tab. The portal wants to show the up-to-date verification status. What should it do?", options: ["Trust the ID token's email_verified value forever, since it was true at login", "Call the UserInfo endpoint to get a fresh email_verified value, since the ID token's claim is only as current as the moment it was issued", "Discard the session and force a full re-login", "Ignore the claim entirely since it cannot change"], answerIndex: 1, explanation: "An ID token's claims are a snapshot from login time. A live UserInfo call is exactly the mechanism OIDC provides for getting current data without a full re-authentication." },
    { id: "oidc-12", type: "scenario", question: "Northwind Apps wants every connected customer application to know which customer tenant a logged-in user belongs to, without a second API call after login. What is the right mechanism?", options: ["Ask the user to type their tenant ID into a form every time", "Add a custom tenant_id claim via a Keycloak client scope's protocol mapper, so it rides inside the ID token", "Store the tenant ID only in a database the client has no access to", "Request the tenant OAuth scope, which is a standard scope"], answerIndex: 1, explanation: "tenant_id is not a standard OIDC claim, so it has to be added and advertised by the provider — a Keycloak protocol mapper on a client scope is exactly how that is configured." },
    { id: "oidc-13", type: "scenario", question: "A developer at Northwind Apps hardcodes the authorization, token, and UserInfo endpoint URLs for a customer's OIDC provider directly into the client config, rather than fetching the discovery document. Six months later the provider migrates to a new domain and all three URLs change. What breaks, and why?", options: ["Nothing breaks — OIDC endpoints never change", "The integration breaks because the hardcoded URLs are now stale; fetching discovery at startup would have picked up the new URLs automatically", "Only the ID token stops working, not the access token", "The client automatically redirects to the new domain because of DNS"], answerIndex: 1, explanation: "Discovery exists specifically so a client never has to hardcode endpoint URLs — exactly the failure mode avoided by fetching the document instead." },
    { id: "oidc-14", type: "scenario", question: "A client at Meridian Trust successfully exchanges a device code for tokens, including an access token scoped with only api (no openid). It then calls the UserInfo endpoint with that access token and gets a 401 invalid_token. What is the most likely cause?", options: ["The UserInfo endpoint is down", "The access token was never issued with the openid scope, so it was never entitled to call an OIDC-specific endpoint in the first place", "The device code expired before the token exchange", "The client used the wrong HTTP method"], answerIndex: 1, explanation: "A perfectly valid OAuth access token issued without the openid scope is not entitled to UserInfo — this is one of the two most common causes of a UserInfo 401 in practice." },
    { id: "oidc-15", type: "scenario", question: "During this chapter's own research, a live curl request to https://demo.duendesoftware.com/connect/userinfo with no Authorization header at all returned which status and header?", options: ["200 OK with an empty JSON object", "401, with a WWW-Authenticate header naming error=invalid_token", "302 redirect to the login page", "500 Internal Server Error"], answerIndex: 1, explanation: "Confirmed live: calling UserInfo with no token, or an invalid one, returns 401 with a WWW-Authenticate: Bearer realm=\"IdentityServer\",error=\"invalid_token\" header — a well-formed rejection, not a crash or silent success." },
    { id: "oidc-16", type: "scenario", question: "A reader runs this chapter's device-flow lab and polls the token endpoint before completing the login step in their browser. What response should they expect?", options: ["An empty 200 OK response", "HTTP 400 with {\"error\": \"authorization_pending\"}", "A fully issued access token immediately", "A permanent 403 Forbidden"], answerIndex: 1, explanation: "Confirmed live for this chapter: polling before the human login step completes returns a specific, well-defined 400 authorization_pending error, not a generic failure." },
    { id: "oidc-17", type: "concept", question: "Which of these is a standard OIDC scope with a fixed, spec-defined bundle of claims?", options: ["tenant_id", "department", "profile", "subscription_tier"], answerIndex: 2, explanation: "profile (along with openid and email) is one of OIDC's standard scopes, unlocking a fixed, spec-defined set of claims like name, given_name, and preferred_username. The others are examples of custom, provider-defined claims." },
    { id: "oidc-18", type: "compare", question: "Chapter 13/14 covered OAuth 2.0's access and refresh tokens in depth. What is genuinely new about the ID token this chapter introduces, as opposed to just another renamed access token?", options: ["Nothing — an ID token is just an access token with a different name", "The ID token is specifically about proving who authenticated (identity), carries standardized identity claims, and is scoped to the client itself rather than a resource server — a different purpose from an access token's authorization role", "ID tokens never expire, unlike access tokens", "ID tokens are only issued for machine-to-machine clients"], answerIndex: 1, explanation: "The ID token is OIDC's distinct contribution: a token about identity and authentication, not API authorization, with its own standardized claim set and its own audience (the client itself)." }
  ],

  "jwt-and-crypto": [
    { id: "jwt-01", type: "concept", question: "What does JWS (JSON Web Signature) actually protect?", options: ["Confidentiality — nobody but the recipient can read the payload", "Integrity and authenticity — the payload is still readable, but tampering is detectable", "Nothing by default; it only works combined with JWE", "The transport channel the token travels over"], answerIndex: 1, explanation: "JWS proves a payload hasn't been altered and, for asymmetric algorithms, who signed it. It does not hide the payload — that's JWE's job." },
    { id: "jwt-02", type: "concept", question: "A token uses JWS, not JWE. Which statement is correct?", options: ["The payload is ciphertext and requires a decryption key to read", "The payload is base64url-encoded JSON, readable by anyone who has the token", "The header is encrypted but the payload is not", "JWS tokens cannot carry claims at all"], answerIndex: 1, explanation: "Base64url is a reversible encoding, not encryption. Anyone holding a JWS token can decode its header and payload." },
    { id: "jwt-03", type: "bug", question: "An engineer at Northwind Apps adds a customer's internal discount code directly into an access token's payload as a custom claim, reasoning 'it's inside the token, so only our API can see it.' What's wrong?", options: ["Nothing — JWTs are encrypted by default so the claim is safe", "The claim is base64url-encoded, not encrypted; anyone who obtains the token (browser dev tools, a proxy log) can decode it in seconds", "JWTs can't carry custom claims, so the code would be silently dropped", "The problem is only that the claim name wasn't namespaced"], answerIndex: 1, explanation: "This is the classic 'JWT is automatically encrypted' misconception. A JWS payload is plain, readable JSON once decoded." },
    { id: "jwt-04", type: "concept", question: "A JWT's compact serialization is made of which three segments, joined by dots?", options: ["issuer.subject.audience", "header.payload.signature", "kid.alg.sig", "claims.key.hash"], answerIndex: 1, explanation: "header.payload.signature, each independently base64url-encoded." },
    { id: "jwt-05", type: "concept", question: "Why can't you meaningfully 'decode' a JWT's signature segment the way you can its header and payload?", options: ["The signature segment is also JSON but uses a different schema", "The signature is opaque bytes produced by a cryptographic operation, not JSON — it's checked by recomputing and comparing, not decoded for meaning", "Only the payload is base64url-encoded; the signature uses plain base64", "The signature segment is actually a second copy of the payload, encrypted"], answerIndex: 1, explanation: "Header and payload decode to JSON because that's what was encoded. The signature is raw cryptographic output — verified by recomputation, never decoded into meaning." },
    { id: "jwt-06", type: "concept", question: "What is a JWK (JSON Web Key)?", options: ["A one-time code used during the device authorization grant", "A single cryptographic key represented as a JSON object, carrying its type, use, algorithm, key id, and key material", "A hashed version of a client secret", "The JSON Web Key is another name for the whole JWT"], answerIndex: 1, explanation: "A JWK (RFC 7517) is one key as JSON. A JWKS is a set of them." },
    { id: "jwt-07", type: "concept", question: "On the live Duende demo server, where does a client learn the URL of the JWKS endpoint without hardcoding it?", options: ["It's only documented in the server's source code", "The jwks_uri field inside the OIDC discovery document (/.well-known/openid-configuration)", "It's always exactly /jwks on every OIDC server by spec, no discovery needed", "Inside every access token's header as a claim"], answerIndex: 1, explanation: "Confirmed live: the discovery document's jwks_uri field resolves to https://demo.duendesoftware.com/.well-known/openid-configuration/jwks." },
    { id: "jwt-08", type: "scenario", question: "A verifier receives a JWT whose header contains kid: '0202F0E3BCADB53E5E62DBBF25BC31FC'. What does the verifier do with that value?", options: ["Ignores it and always uses whichever key is listed first in the JWKS response", "Uses it to find the JWK in the fetched JWKS response whose own kid matches, then uses that key's material to check the signature", "Treats it as the signature itself", "Uses it as a cache key only, unrelated to which key verifies the token"], answerIndex: 1, explanation: "kid-based lookup is exactly what lets a verifier pick the one correct key out of a JWKS response that may list several." },
    { id: "jwt-09", type: "concept", question: "Why does kid-based key lookup specifically matter for making key rotation possible?", options: ["It lets JWKS responses stay small by listing only one key at a time", "It lets multiple keys coexist in a JWKS response at once, so tokens signed with an older key keep verifying while newer tokens use a new key", "It removes the need for a JWKS endpoint entirely", "It allows a verifier to skip signature verification for trusted kid values"], answerIndex: 1, explanation: "Without kid, a verifier would have no principled way to know which of several published keys applies to a given token during an overlap period." },
    { id: "jwt-10", type: "scenario", question: "Meridian Trust suspects one of its signing keys was compromised. Relative to the four revocation mitigations chapter 8 introduced, what is key rotation here actually doing?", options: ["Revoking one specific stolen access token without affecting any others", "Invalidating every token signed with the compromised key at once — a blunt instrument, but the right tool when the key itself, not one token, is the thing that's compromised", "Nothing — rotation only applies to refresh tokens, never access tokens", "Permanently disabling the entire authentication system until a new deployment ships"], answerIndex: 1, explanation: "Signing-key rotation is blunt by nature: it invalidates everything signed with the retired key, not a single token — which is exactly appropriate when the key itself is suspect." },
    { id: "jwt-11", type: "scenario", question: "Put these key-rotation steps in the order they must happen to avoid an outage: (1) retire the old key from JWKS, (2) publish the new key into JWKS, (3) start signing new tokens with the new key.", options: ["1, 2, 3", "2, 3, 1", "3, 2, 1", "2, 1, 3"], answerIndex: 1, explanation: "Publish the new key first (so verifiers can already find it), then start signing with it, then retire the old key only once every token it signed has expired." },
    { id: "jwt-12", type: "bug", question: "A team rotates keys by immediately removing the old key from JWKS the moment they start signing with the new key, skipping any overlap period. What breaks?", options: ["Nothing breaks; removing the old key immediately is best practice", "Every still-valid, unexpired token that was signed with the old key now fails verification, because its kid no longer matches anything in JWKS", "Only refresh tokens are affected, never access tokens", "The new key stops working until the old key is restored"], answerIndex: 1, explanation: "This is exactly the overlap-period pitfall: removing the old key too early breaks verification for tokens that are still legitimately in use." },
    { id: "jwt-13", type: "compare", question: "Compare HS256 (symmetric) and RS256 (asymmetric) signing: which one can safely have its verification key published at a public JWKS endpoint, and why?", options: ["Both can be published safely — JWKS is designed for either", "Only RS256 — its public key can only verify signatures, never create valid ones, unlike an HS256 shared secret which can do both", "Only HS256 — RSA keys are too large to publish in JSON", "Neither — JWKS only works with elliptic-curve algorithms"], answerIndex: 1, explanation: "Publishing an HS256 secret hands out forging ability, not just verification. RS256's public key is safe to publish precisely because it can't be used to forge a signature." },
    { id: "jwt-14", type: "concept", question: "Why would publishing an HMAC (HS256) secret at a JWKS-style public endpoint be a serious mistake?", options: ["It would make verification slightly slower for everyone", "The same secret used to verify a signature is also the secret needed to create one, so publishing it hands out forging capability, not just verification", "JWKS endpoints technically can't contain HMAC keys at all, so it would just fail silently", "It would only be a mistake if the secret were also used as a database password"], answerIndex: 1, explanation: "Symmetric algorithms use one key for both directions — that's the whole reason asymmetric algorithms (RS256/ES256), not HS256, are the ones meant to have a public verification key published." },
    { id: "jwt-15", type: "concept", question: "What is 'algorithm confusion' as a JWT security issue?", options: ["A user being confused about which OAuth grant type to use", "A verifier that trusts the alg value from an untrusted token's own header rather than enforcing an algorithm it already expects, which an attacker can exploit to forge a token", "A client sending a token with a typo in the algorithm name", "A server supporting too many algorithms, making audits slow"], answerIndex: 1, explanation: "Named here, with full defenses deferred to chapter 18: never derive the expected algorithm from the untrusted token itself." },
    { id: "jwt-16", type: "scenario", question: "Riverside Health's patient portal caches a JWKS response at service startup and never refreshes it. What's the risk, specifically tied to key rotation?", options: ["No risk — JWKS responses never change once published", "If the IdP rotates its signing key after the cache was fetched, tokens signed with the new key will fail verification until the service refreshes its cache and picks up the new kid", "The cached response would cause every token to be accepted without verification", "The risk only applies to refresh tokens, not ID tokens"], answerIndex: 1, explanation: "A verifier needs to periodically refresh its cached JWKS (or refresh on a kid miss) specifically so it can pick up new keys introduced during rotation." }
  ],

  "saml2": [
    { id: "saml-01", type: "concept", question: "What does the <saml:Subject> element of a SAML assertion most directly provide?", options: ["Identifies who the assertion is about via NameID, and binds it to this exchange via SubjectConfirmation", "Lists the bindings the IdP supports", "Declares the assertion's validity window", "Specifies which attributes the IdP is willing to share"], answerIndex: 0, explanation: "Subject carries the NameID (who this is about) and SubjectConfirmation (ties the assertion to this specific browser exchange). Validity windows live in Conditions, not Subject." },
    { id: "saml-02", type: "scenario", question: "A Northwind Apps SP receives a SAML assertion from an enterprise customer's IdP and checks the <Conditions><AudienceRestriction> before trusting it. What is this check specifically protecting against?", options: ["An assertion issued for a different SP being replayed and accepted here", "The user's password being too weak", "The assertion being too old to parse", "The IdP's certificate being self-signed"], answerIndex: 0, explanation: "AudienceRestriction names exactly which SP may accept the assertion, preventing cross-SP replay of an assertion issued for someone else." },
    { id: "saml-03", type: "scenario", question: "Riverside Health's EHR vendor's SP only checks that a SAML Response arrived over HTTPS from Riverside's known IdP hostname, and never validates the embedded XML signature. What risk does this create?", options: ["A forged or tampered assertion could be accepted as genuine, since TLS alone doesn't verify who authored the assertion content", "None — TLS already guarantees the assertion's authenticity", "This only matters for IdP-initiated flows", "SAML assertions aren't signed, so there's nothing to validate"], answerIndex: 0, explanation: "Transport security (TLS) and assertion-signature validation are different checks. Skipping signature validation means the SP is trusting the network path, not the actual issuer of the XML content." },
    { id: "saml-04", type: "concept", question: "Which binding typically carries the initial SAML AuthnRequest from SP to IdP, and why?", options: ["HTTP-Redirect, because the request is small enough to fit as a URL parameter", "HTTP-POST, because browsers can't process redirects", "The SOAP binding, because it requires full web-services machinery", "The Artifact binding, because requests must always be looked up out-of-band"], answerIndex: 0, explanation: "AuthnRequests are small, so Redirect's URL-parameter transport is simple and sufficient." },
    { id: "saml-05", type: "scenario", question: "Meridian Trust's IdP engineer is configuring the binding for the assertion response, which will include several AttributeStatement entries about the employee. Which binding should be used, and why?", options: ["HTTP-POST, because signed assertions with attributes routinely exceed practical URL length limits", "HTTP-Redirect, because it's faster for large payloads", "Either binding works identically regardless of payload size", "Neither — assertions must use SOAP"], answerIndex: 0, explanation: "POST carries the message via an auto-submitting form with no practical size ceiling, unlike Redirect's URL-parameter transport." },
    { id: "saml-06", type: "scenario", question: "A Meridian Trust engineer sees a SAML integration fail intermittently with 'URL too long' errors, and only for users with many group memberships. What's the most likely cause?", options: ["The assertion response is being sent over the HTTP-Redirect binding instead of HTTP-POST", "The user's NameID format is invalid", "The IdP's signing certificate expired", "The SP's ACS URL is misconfigured"], answerIndex: 0, explanation: "More attributes/groups means a larger assertion; carrying it over Redirect's URL-length-limited transport is the classic cause of this exact symptom." },
    { id: "saml-07", type: "compare", question: "Which pairing correctly matches a SAML concept to its closest OIDC equivalent?", options: ["saml:Assertion ↔ ID Token", "saml:Assertion ↔ Access Token", "EntityDescriptor ↔ Client Secret", "AttributeStatement ↔ Redirect URI"], answerIndex: 0, explanation: "Both the SAML assertion and the OIDC ID token are the IdP's signed statement of who the user is." },
    { id: "saml-08", type: "compare", question: "SAML metadata and the OIDC discovery document serve the same underlying purpose. What's the key practical difference?", options: ["SAML metadata is XML typically exchanged once during integration setup; OIDC discovery is JSON typically fetched live over HTTP by the RP", "SAML metadata is never signed, while OIDC discovery always is", "OIDC has no equivalent of metadata at all", "SAML metadata is fetched per-login, while discovery is exchanged once during setup"], answerIndex: 0, explanation: "Same job (describe endpoints/capabilities), different wire format and exchange pattern." },
    { id: "saml-09", type: "scenario", question: "Northwind Apps is integrating with a large enterprise customer whose IT team hands over a metadata XML file and says 'configure SSO from this.' What should Northwind's engineer expect to find inside it?", options: ["The customer IdP's entityID, its signing certificate, and its SSO endpoint URLs for each supported binding", "An export of the customer's user database", "A list of OAuth scopes the customer supports", "The customer's internal firewall rules"], answerIndex: 0, explanation: "SAML metadata (EntityDescriptor) describes exactly this: identity, certificate, and endpoints — not user data or firewall config." },
    { id: "saml-10", type: "concept", question: "What distinguishes SP-initiated from IdP-initiated SAML SSO?", options: ["Whether an AuthnRequest precedes the assertion response, or the Response arrives unsolicited", "Whether the assertion is signed", "Whether HTTP-POST or HTTP-Redirect is used for the response", "Whether the user authenticates with MFA"], answerIndex: 0, explanation: "SP-initiated: SP sends an AuthnRequest first. IdP-initiated: the IdP sends an unsolicited Response with no preceding request." },
    { id: "saml-11", type: "scenario", question: "Riverside Health's intranet portal lists every connected clinical system as a clickable tile; clicking one logs the clinician straight into that system, with Riverside's IdP never having received a request from it first. Which flow is this?", options: ["IdP-initiated SSO", "SP-initiated SSO", "OAuth client credentials grant", "LDAP federation"], answerIndex: 0, explanation: "The login originates at the IdP's own portal with no preceding AuthnRequest — the defining shape of IdP-initiated SSO." },
    { id: "saml-12", type: "scenario", question: "Riverside Health's security team reviews IdP-initiated SSO logins from the intranet portal and asks why these are considered harder to protect against replay than SP-initiated logins. What's the accurate answer?", options: ["There's no AuthnRequest to correlate the Response against via InResponseTo, so the SP must rely more heavily on Conditions validation", "IdP-initiated assertions are never signed", "IdP-initiated flows don't use TLS", "There's no concept of assertion expiry in IdP-initiated flows"], answerIndex: 0, explanation: "Without a prior request to correlate against, the SP's main defense is strict Conditions (validity window, audience) checking — not request correlation." },
    { id: "saml-13", type: "scenario", question: "A Meridian Trust security reviewer asks whether the bank should drop SAML entirely in favor of OIDC across every integration. Which answer best reflects accurate, current industry practice?", options: ["No — SAML remains widely used in long-lived enterprise/legacy integrations and migrating working, certified integrations has real cost; OIDC is preferred for new builds but doesn't make existing SAML integrations obsolete", "Yes — OASIS formally deprecated SAML and it must no longer be used", "Yes — SAML cannot be used securely under PCI-DSS", "No — OIDC cannot be used for enterprise SSO at all"], answerIndex: 0, explanation: "SAML hasn't been deprecated; it coexists with OIDC, with a large installed base in legacy/regulated/long-lived federations." },
    { id: "saml-14", type: "concept", question: "Why does this chapter not include a hands-on curl-based lab, unlike chapters 13-15?", options: ["Real SAML exchanges require XML signing, canonicalization, and signature validation against a trust anchor — mechanics curl can't exercise without a full SAML library", "There is no live public test IdP available anywhere for SAML", "Keycloak doesn't support SAML", "The OASIS specification prohibits hands-on testing of SAML"], answerIndex: 0, explanation: "SAML's XML-signing/validation requirements are heavier than a curl-only lab can reasonably cover — an honest scoping choice, not a gap." },
    { id: "saml-15", type: "scenario", question: "Riverside Health's EHR vendor's SP receives a SAML assertion whose AudienceRestriction names a completely different SP's entityID. What should happen, and why?", options: ["The SP should reject the assertion — AudienceRestriction exists specifically to stop an assertion issued for one SP from being accepted by another", "The SP should accept it, since AudienceRestriction only matters for IdP-initiated flows", "The SP should accept it as long as the signature is valid", "The SP should accept it and relabel the assertion for its own entityID"], answerIndex: 0, explanation: "A mismatched AudienceRestriction is exactly the scenario this field exists to catch; accepting it anyway defeats its purpose regardless of signature validity." },
    { id: "saml-16", type: "compare", question: "Which statement correctly compares SAML's role vocabulary to OIDC's?", options: ["SAML calls the relying application the SP; OIDC calls the same role the RP — they're the same role under two protocol-specific names, not two different architectures", "SAML's SP and OIDC's RP are unrelated concepts", "OIDC has no relying-role concept at all", "SAML's SP is actually the same thing as the IdP"], answerIndex: 0, explanation: "Chapter 7 established this: SP and RP name the same role, just under different protocol vocabularies." },
    { id: "saml-17", type: "scenario", question: "Northwind Apps integrates with an enterprise customer's SAML IdP that returns a NameID with Format urn:oasis:names:tc:SAML:1.1:nameid-format:persistent instead of an email address. What does this tell Northwind about how to identify the user?", options: ["The NameID is an opaque, stable identifier that isn't necessarily human-readable or an email — Northwind should key its local account mapping on this value rather than assume it's an email", "Authentication failed", "The IdP doesn't support attributes", "The assertion is unsigned"], answerIndex: 0, explanation: "NameID format varies by declaration; a persistent-format NameID is a stable opaque value, not guaranteed to be an email address." },
    { id: "saml-18", type: "concept", question: "Which statement best distinguishes an AuthnStatement from an AttributeStatement inside a SAML assertion?", options: ["AuthnStatement records that and how authentication happened (when, by what method); AttributeStatement carries additional, optional user attributes", "AuthnStatement is optional; AttributeStatement is mandatory", "They are two names for the same element", "AuthnStatement carries user attributes; AttributeStatement records the authentication method"], answerIndex: 0, explanation: "AuthnStatement is about the authentication event itself; AttributeStatement (optional) is about additional data on the user." }
  ],

  "oauth-oidc-security": [
    { id: "sec-01", type: "concept", question: "What is the current status of the OAuth 2.0 Security Best Current Practice document?", options: ["Still an early-stage IETF draft, not yet stable enough to cite by number", "A published, final RFC — RFC 9700, also catalogued as BCP 240", "Withdrawn and replaced entirely by RFC 6819", "Published only as a vendor whitepaper, never formally standardized"], answerIndex: 1, explanation: "RFC 9700 / BCP 240 was published in January 2025 and is the final, consolidated Best Current Practice — not a draft." },
    { id: "sec-02", type: "concept", question: "Why does RFC 9700 recommend PKCE even for confidential clients, which already hold a client secret?", options: ["Because client secrets are being deprecated entirely", "Because PKCE replaces the need for a redirect URI", "Because the client secret only protects the token-endpoint exchange, not the authorization code while it's in transit", "Because confidential clients are no longer allowed to use the authorization code grant"], answerIndex: 2, explanation: "A stolen authorization code can't be redeemed without the original code_verifier, a layer the client secret never covered — it only matters one step later, at the token endpoint." },
    { id: "sec-03", type: "scenario", question: "Revisiting Northwind Apps' chapter 9 incident: an enterprise customer's integration had an XSS flaw, and the attacker read the bearer token Northwind had issued. Which single architectural change to that integration would have prevented the token from being readable, even with the XSS flaw still present?", options: ["Increasing the token's scope so it covers more resources", "Switching the authorization grant from authorization code to client credentials", "Keeping the token somewhere JavaScript cannot read it at all, such as behind a BFF or in an httpOnly cookie instead of localStorage", "Adding a longer client secret to the integration's backend"], answerIndex: 2, explanation: "The XSS flaw gave the injected script the same privileges as legitimate page code; if the token had been held outside JS-readable storage, that script would have had nothing to steal." },
    { id: "sec-04", type: "scenario", question: "Meridian Trust's client application is configured to accept logins from both Meridian's own realm and a partner bank's authorization server. An attacker who compromises the partner bank's server tries to trick the client into sending a code issued by Meridian's real server to the attacker's server instead. What is this attack called?", options: ["Credential stuffing", "A mix-up attack", "MFA fatigue", "A brute-force attack"], answerIndex: 1, explanation: "A mix-up attack exploits a client trusting more than one authorization server with no reliable way to tell which one actually issued a given response." },
    { id: "sec-05", type: "bug", question: "A client generates a random state value for each authorization request and checks that the callback's state matches what was sent, but stores the expected value in a global JavaScript variable readable by any script on the page. What's wrong with this implementation?", options: ["Nothing — state only needs to be random, not protected after generation", "The value isn't bound securely to the initiating browser session, so its CSRF protection is effectively decorative", "state should never be stored anywhere, only transmitted", "The bug is that state should be a fixed, predictable value instead of random"], answerIndex: 1, explanation: "state's security property comes from being bound to the session that initiated the request; storing it somewhere any page script (including injected script) can read or tamper with defeats that binding." },
    { id: "sec-06", type: "compare", question: "Compare storing an access token in localStorage versus in an httpOnly cookie. Which statement is accurate?", options: ["Both are equally exposed to XSS, since both are accessible from any script on the page", "localStorage is JavaScript-readable (exposed to XSS); an httpOnly cookie is not JS-readable but is auto-attached by the browser, reintroducing CSRF exposure", "httpOnly cookies are exposed to XSS in the same way localStorage is", "localStorage is immune to XSS because it is origin-scoped"], answerIndex: 1, explanation: "Each storage choice trades one exposure category for another: localStorage trades CSRF-safety for XSS-readability; httpOnly cookies trade XSS-readability for CSRF exposure that needs its own defense." },
    { id: "sec-07", type: "concept", question: "What does iss validation (per RFC 9207) require the client to check?", options: ["That the access token's audience claim matches the resource server", "That the authorization response's iss value matches the issuer identifier the client expected, aborting on any mismatch", "That the redirect URI uses HTTPS", "That the client secret was transmitted over TLS"], answerIndex: 1, explanation: "The authorization server states its own identity via the iss parameter; the client must compare it to the expected issuer before proceeding, which is exactly the check a mix-up attack defeats if it's missing." },
    { id: "sec-08", type: "scenario", question: "Riverside Health's patient portal is being updated to let patients authenticate either through Riverside's own identity provider or through a partner lab's IdP, side by side in the same client. What risk does this specific setup introduce that a single-IdP client wouldn't have?", options: ["Credential stuffing becomes impossible to defend against", "A mix-up attack becomes possible, since the client now has to correctly tell two authorization servers' responses apart", "MFA fatigue attacks become more likely", "The access token's lifetime automatically becomes longer"], answerIndex: 1, explanation: "Trusting more than one authorization server is exactly the precondition for a mix-up attack; iss validation (or, as a fallback, distinct redirect URIs per IdP) is the defense." },
    { id: "sec-09", type: "bug", question: "A developer argues: \"Our client is confidential and holds a secret, so we don't need PKCE.\" What's the flaw in that reasoning?", options: ["There is no flaw — confidential clients genuinely don't need PKCE under any current guidance", "The client secret protects the token-endpoint exchange, but does nothing to stop an attacker who intercepts the authorization code before it ever reaches that exchange", "PKCE is only relevant to the implicit grant, which confidential clients never use", "Confidential clients can't technically implement PKCE even if they wanted to"], answerIndex: 1, explanation: "RFC 9700 recommends PKCE for confidential clients too, precisely because it closes a gap (code interception) that the secret was never positioned to close." },
    { id: "sec-10", type: "concept", question: "What is the specific role of RFC 9207 in this chapter's guidance?", options: ["It defines the PKCE code_verifier/code_challenge mechanics", "It defines the iss authorization-response parameter that lets a client verify which authorization server actually issued a response", "It deprecates the implicit grant", "It defines the state parameter's CSRF semantics"], answerIndex: 1, explanation: "RFC 9207, \"OAuth 2.0 Authorization Server Issuer Identification,\" is the spec behind iss validation, RFC 9700's preferred mix-up-attack defense." },
    { id: "sec-11", type: "scenario", question: "Northwind Apps is evaluating a Backend-for-Frontend (BFF) architecture for a new customer-facing SPA, instead of having the SPA hold tokens itself. What does the BFF pattern specifically buy them, per RFC 10017?", options: ["Faster token issuance from the authorization server", "The token never reaches the browser or browser-visible JavaScript at all, removing the XSS-reads-the-token exposure as a category rather than just hardening where the token sits", "Automatic exemption from needing PKCE", "A longer-lived refresh token than other architectures allow"], answerIndex: 1, explanation: "RFC 10017 calls the BFF pattern \"strongly recommended for business applications\" specifically because the token-in-the-browser exposure is eliminated, not merely reduced." },
    { id: "sec-12", type: "compare", question: "Compare an httpOnly-cookie-based browser client against a full BFF architecture. Which is accurate?", options: ["They are identical in every respect; BFF is just a rebranding of httpOnly cookies", "In the plain httpOnly-cookie case the browser app can still hold the access token itself; in the full BFF case the token is held entirely server-side and the browser gets only a session cookie", "httpOnly cookies are less secure than storing the token in localStorage", "A full BFF cannot use cookies at all"], answerIndex: 1, explanation: "An httpOnly cookie alone protects a token from JS-reads if the token itself is in the cookie; the BFF pattern goes further by keeping the token server-side entirely and issuing the browser only a session cookie." },
    { id: "sec-13", type: "concept", question: "Why must the state value be bound to the specific browser session that initiated the authorization request, rather than just being random?", options: ["Randomness alone is sufficient; binding to a session adds nothing", "Without session binding, an attacker's own legitimately-generated state value could still pass a naive comparison check, since the client isn't verifying that the responding browser is the one that started the request", "Binding to a session is required only for public clients, not confidential ones", "state values expire automatically after being generated, making binding unnecessary"], answerIndex: 1, explanation: "The CSRF protection's actual strength comes from tying the expected value to the initiating session — a value stored unbound (e.g. readable by any script, or not scoped to that session) fails to prevent a forged callback from a different flow." },
    { id: "sec-14", type: "scenario", question: "An internal auditor at Meridian Trust flags that a teller-facing single-page application stores its OAuth access token in sessionStorage. Which remediation directly addresses the auditor's concern, per this chapter's guidance?", options: ["Increase the access token's lifetime so tellers are logged in longer", "Move the token to a location JavaScript cannot read — an httpOnly cookie or, more completely, a BFF — since sessionStorage is just as JS-readable as localStorage for the lifetime of the tab", "Switch the grant type from authorization code to device authorization", "No remediation is needed, since sessionStorage clears when the tab closes"], answerIndex: 1, explanation: "sessionStorage is still plain JavaScript-accessible storage; clearing on tab-close doesn't change that an XSS flaw during the session can read it just as it could read localStorage." },
    { id: "sec-15", type: "bug", question: "An authorization server in a client's trust list doesn't support the iss authorization-response parameter. Per RFC 9700, what fallback mix-up defense is described, and what is its explicit downside?", options: ["No fallback exists; the client simply cannot defend against mix-up attacks against that server", "Giving each trusted authorization server a distinct, dedicated redirect URI — described as a fallback to be used only when iss support isn't available, not the preferred mechanism", "Disabling PKCE for that specific authorization server", "Extending the access token's audience claim to cover both servers"], answerIndex: 1, explanation: "RFC 9700 §4.4.2.2 names distinct-redirect-URIs-per-AS as a weaker fallback, explicitly framed as a last resort relative to iss validation." },
    { id: "sec-16", type: "concept", question: "A colleague claims RFC 9700 makes PKCE mandatory for every OAuth client, confidential or public, with no distinction. Is this an accurate reading of the RFC?", options: ["Yes, RFC 9700 §2.1.1 uses MUST language for both client types equally", "No — RFC 9700 §2.1.1 says PKCE MUST be used by public clients, but is only RECOMMENDED (not MUST) for confidential clients", "No, RFC 9700 doesn't mention PKCE at all", "Yes, but only for clients using the implicit grant"], answerIndex: 1, explanation: "Several secondary sources overstate this as a blanket MUST; the RFC's actual normative language keeps public clients at MUST and confidential clients at RECOMMENDED — an important distinction when citing it precisely." }
  ],

  "keycloak-architecture": [
    { id: "kca-01", type: "concept", question: "What is the Quarkus-based distribution's main practical benefit for Keycloak as a containerized workload?", options: ["Fast startup and a small memory footprint", "Built-in support for every database vendor without configuration", "Automatic multi-site clustering with no setup", "A graphical installer replacing the command line"], answerIndex: 0, explanation: "Quarkus is designed for fast startup and low memory use in containers — directly relevant to how quickly a container can become ready in an orchestrated environment." },
    { id: "kca-02", type: "concept", question: "Which Keycloak distribution did the Quarkus-based distribution replace?", options: ["A WildFly-based (Java EE) distribution", "A Tomcat-based distribution", "A Node.js-based distribution", "There was no prior distribution — Keycloak always ran on Quarkus"], answerIndex: 0, explanation: "Keycloak originally shipped on a WildFly-based distribution; the Quarkus distribution became fully supported starting Keycloak 17 (December 2021), with WildFly phased out over the following releases." },
    { id: "kca-03", type: "concept", question: "Which of the following is a build-time configuration option in Keycloak's Quarkus distribution?", options: ["The database vendor (--db)", "The database connection URL", "The HTTP port", "The log level"], answerIndex: 0, explanation: "The database vendor is baked in via kc build; the connection URL, HTTP port, and log level are runtime values read fresh at kc start." },
    { id: "kca-04", type: "concept", question: "What has to happen if you need to change a build-time configuration option after the server is already running?", options: ["Re-run kc build to produce a new optimized server image", "Just restart the server with the new value", "Nothing — build-time options can't ever be changed", "Edit conf/keycloak.conf and the change applies on the next request"], answerIndex: 0, explanation: "Build-time options are baked into the server image during kc build; changing one requires rebuilding, unlike runtime options which only need a restart." },
    { id: "kca-05", type: "scenario", question: "A team at Northwind Apps spins up Keycloak with kc start-dev to quickly demo a feature to a customer, then leaves that same instance running as the customer's production login system. What's the core problem?", options: ["start-dev is a development-only mode that relaxes production checks (e.g. database, HTTPS) and was never meant to stay running in production", "Nothing — start-dev and start are functionally identical", "start-dev only works for 24 hours before shutting down", "start-dev doesn't support OAuth 2.0 at all"], answerIndex: 0, explanation: "start-dev auto-enables an in-memory/file database and skips HTTPS and other production checks specifically to make a first run frictionless — exactly the kind of shortcut that becomes a real misconfiguration if never swapped out." },
    { id: "kca-06", type: "concept", question: "Which database vendor does this course's own lab environment (chapter 20 onward) use?", options: ["PostgreSQL", "Oracle Database", "dev-file (embedded)", "MongoDB"], answerIndex: 0, explanation: "The course's Docker Compose lab stack pairs Keycloak 26.8.2 with PostgreSQL 17 — the most common production choice and the one every later lab assumes." },
    { id: "kca-07", type: "concept", question: "Why is Keycloak's dev-file database value explicitly deprecated as the default in production mode?", options: ["It's a development-only embedded database not meant to back real production data", "It only supports 10 users at a time", "It requires a separate license", "It doesn't support the OAuth 2.0 protocol"], answerIndex: 0, explanation: "dev-file and dev-mem are strictly for local experimentation; Keycloak's own docs require explicitly naming a real production database vendor instead." },
    { id: "kca-08", type: "compare", question: "How does a containerized Keycloak deployment (e.g. Docker Compose) differ from a Kubernetes deployment?", options: ["Containerized runs Keycloak/DB as plain containers wired manually; Kubernetes adds an Operator/Helm chart managing scheduling, restarts, and elastic scaling across a cluster", "They are the same thing, just different names", "Containerized deployment requires a database; Kubernetes deployment does not", "Kubernetes deployment cannot run Keycloak in a container at all"], answerIndex: 0, explanation: "Containerized deployment (this course's own lab shape) wires containers together directly; Kubernetes adds an orchestration layer (Operator/Helm) that automates scheduling, self-healing, and elastic scaling on top of that." },
    { id: "kca-09", type: "concept", question: "Which chapter in this course covers Keycloak on Kubernetes in full depth?", options: ["Chapter 42", "Chapter 20", "Chapter 29", "Chapter 12"], answerIndex: 0, explanation: "Chapter 19 only names Kubernetes as the far end of the deployment spectrum; chapter 42 covers the Operator and Helm chart in depth." },
    { id: "kca-10", type: "concept", question: "What is Infinispan's role in a clustered Keycloak deployment?", options: ["A distributed, in-memory data grid that lets multiple nodes share session and authentication-session state", "The relational database that stores realms and users permanently", "A load balancer that routes requests to nodes", "A build tool used to compile the Quarkus distribution"], answerIndex: 0, explanation: "Infinispan is the embedded caching layer Keycloak uses so any node in a cluster can serve a request and still see consistent session state, configured by default via conf/cache-ispn.xml." },
    { id: "kca-11", type: "compare", question: "How does single-cluster Keycloak HA differ from multi-site (multi-cluster) HA?", options: ["Single-cluster shares an embedded Infinispan cache within one site with no external dependency; multi-site spans multiple data centers/regions and needs either an external Infinispan cluster per site or a database-centric approach", "They are identical concepts with different names", "Single-cluster requires Kubernetes; multi-site does not", "Multi-site HA eliminates the need for a database entirely"], answerIndex: 0, explanation: "Keycloak's own HA docs distinguish single-cluster (no external dependency beyond the database) from multi-site architectures, which solve a different problem — resilience across sites — at a different operational cost." },
    { id: "kca-12", type: "concept", question: "In Keycloak, what concretely plays the OAuth 2.0 'Authorization Server' role chapter 13 defined?", options: ["A realm", "A client", "A protocol mapper", "The admin console UI itself"], answerIndex: 0, explanation: "A Keycloak realm — an isolated namespace of users, clients, roles, and flows — is the concrete Keycloak entity that authenticates resource owners and issues tokens, fulfilling the Authorization Server role." },
    { id: "kca-13", type: "scenario", question: "Starting chapter 20, the reader stops using demo.duendesoftware.com and instead creates their own Keycloak realm for OAuth/OIDC labs. What changes conceptually, in OAuth 2.0 role terms?", options: ["The reader now controls and can inspect the Authorization Server themselves instead of relying on a third party's", "The reader becomes the Resource Owner instead of the Client", "OAuth 2.0 no longer applies once Keycloak is self-hosted", "The Authorization Server role disappears and is replaced by the Resource Server role"], answerIndex: 0, explanation: "The OAuth 2.0 roles don't change — what changes is who operates the Authorization Server: a third-party demo server (ch13-15) versus the reader's own Keycloak realm (ch20+)." },
    { id: "kca-14", type: "scenario", question: "Riverside Health, a hospital network, is choosing a Keycloak deployment model. Given chapter 11/12's HIPAA data-residency reasoning, which deployment model best fits its stated priorities?", options: ["Self-hosted, on-premises standalone or containerized deployment, for full control over where identity data lives", "A public multi-tenant SaaS IAM product with no visibility into physical data location", "A Kubernetes deployment chosen purely because it sounds more production-grade", "No deployment is appropriate — Riverside Health should not centralize IAM at all"], answerIndex: 0, explanation: "Riverside Health's HIPAA-driven need for direct control over data residency pushes toward self-hosted infrastructure it fully controls, not toward outsourcing that control to a third party." },
    { id: "kca-15", type: "scenario", question: "Meridian Trust, a retail bank under PCI-DSS, is deciding between a single-node Keycloak deployment and a clustered, Infinispan-backed one. Which is the better fit, and why?", options: ["Clustered — a bank's authentication system going down is a business-stopping, possibly regulator-notifying event, so the uptime a multi-node cluster provides is warranted", "Single-node — banks prioritize simplicity over uptime", "Neither — banks should not use Keycloak under any circumstances", "Single-node, because clustering is only relevant for CIAM traffic, not workforce authentication"], answerIndex: 0, explanation: "The high uptime expectations and regulatory stakes of a retail bank's authentication system justify the added operational complexity of clustering, unlike a lower-stakes internal tool." }
  ],

  "installing-keycloak": [
    { id: "ick-01", type: "concept", question: "What does Keycloak's own documentation mean when it labels a bootstrap admin account \"temporary\"?", options: ["It has reduced privileges until an admin confirms it", "It is fully functional but meant to be removed once a real administrator account exists", "It automatically expires after 24 hours", "It can only be used from the Admin Console, not the REST API"], answerIndex: 1, explanation: "Keycloak's bootstrap-admin-recovery docs state the account is fully functional; \"temporary\" is a lifecycle/governance label, not a technical restriction — which is exactly why kcadm.sh could use it to create a real realm in this chapter's lab." },
    { id: "ick-02", type: "concept", question: "When does Keycloak actually create the bootstrap admin user from KC_BOOTSTRAP_ADMIN_USERNAME/PASSWORD?", options: ["On every single container start", "Only during the very first start, when the master realm doesn't exist yet", "Only when KC_HEALTH_ENABLED=true is also set", "Only if no other realms exist at all"], answerIndex: 1, explanation: "The docs are explicit: these options are created only during the initial start, specifically when the master realm doesn't exist yet. On later restarts the variables are silently ignored." },
    { id: "ick-03", type: "scenario", question: "A Northwind Apps engineer restarts the lab Keycloak container after changing KC_BOOTSTRAP_ADMIN_PASSWORD in the compose file, expecting the admin password to update. What actually happens?", options: ["The password updates immediately on restart", "Nothing — the master realm already exists, so the bootstrap variables are ignored", "Keycloak creates a second admin user with the new password", "The container refuses to start until the old password is removed"], answerIndex: 1, explanation: "Bootstrap admin creation only fires once, on first start. Once master exists, KC_BOOTSTRAP_ADMIN_* changes do nothing — recovering access instead requires the separate bootstrap-admin command (with all nodes stopped) or editing the existing user directly." },
    { id: "ick-04", type: "compare", question: "Which of these does start-dev relax compared to Keycloak's production (start) mode, per Keycloak's own configuration guide?", options: ["Database connection pooling only", "Strict hostname resolution, HTTPS/TLS enforcement, and the startup configuration gate", "Only the admin password length requirement", "Session timeout values"], answerIndex: 1, explanation: "start-dev specifically disables strict hostname checking, allows plain HTTP, and starts with no configuration at all — three distinct, named relaxations, not a vague \"less secure\" blanket statement." },
    { id: "ick-05", type: "bug", question: "A reader runs docker compose up -d and immediately tries to curl Keycloak's discovery endpoint, getting a connection-refused error. What's the most likely cause?", options: ["The docker-compose.yml file is corrupted", "Keycloak hasn't finished starting yet — Quarkus boot plus container overhead takes real time", "The wrong port was used", "Postgres's healthcheck failed permanently"], answerIndex: 1, explanation: "This chapter's own lab run needed 9 failed poll attempts (about 27-30 seconds) before Keycloak answered with 200 — startup takes real, variable time, which is why polling rather than assuming instant readiness is correct." },
    { id: "ick-06", type: "concept", question: "Why does kcadm.sh config credentials always authenticate against --realm master, even when the command that follows will act on a different realm like northwind-apps?", options: ["Because kcadm.sh cannot authenticate against any other realm", "Because admin accounts and the permission to manage other realms live in the master realm", "Because master is simply the default and has no special meaning", "Because northwind-apps doesn't have an admin login endpoint yet"], answerIndex: 1, explanation: "The master realm exists specifically to hold administrative accounts and realm-management permissions. You authenticate to master to get an admin session, then act on whichever realm a command's own arguments target." },
    { id: "ick-07", type: "scenario", question: "A new hire at Northwind Apps registers the company's first internal dashboard as an OAuth client directly inside the master realm because \"it was the realm that was already there.\" What's the concrete risk?", options: ["No real risk — master is just a name", "The dashboard's application-level risk now sits one hop from the account that can create, delete, or reconfigure every realm on the instance, including master itself", "The client will simply fail to register", "Master realm clients get slower token issuance"], answerIndex: 1, explanation: "Master exists only to manage Keycloak itself. Mixing ordinary application clients into it means an application-level bug or breach is one hop away from instance-wide administrative control — exactly why chapter 20 creates northwind-apps instead." },
    { id: "ick-08", type: "concept", question: "What command did this chapter actually run to create the northwind-apps realm?", options: ["kcadm.sh update realms --target northwind-apps", "kcadm.sh create realms -s realm=northwind-apps -s enabled=true", "kcadm.sh new-realm northwind-apps --enable", "A POST to /admin/realms/create with a JSON body typed by hand in curl"], answerIndex: 1, explanation: "This is the exact kcadm.sh command run in this chapter's lab, confirmed by a separate get realms --fields realm,enabled call afterward." },
    { id: "ick-09", type: "concept", question: "Per Keycloak's official Server Administration Guide, what happens automatically once a new realm is created through the Admin Console?", options: ["Nothing else happens until an admin manually configures it", "It automatically becomes the current realm, and a key pair plus self-signed certificate are generated for it", "All existing users are copied into it", "It is disabled by default and must be manually enabled"], answerIndex: 1, explanation: "The docs state the newly created realm becomes the current realm, and that a key pair and self-signed certificate are generated automatically for every new realm." },
    { id: "ick-10", type: "bug", question: "Why couldn't this chapter personally curl Keycloak's /health/ready endpoint from inside the running container during the actual lab run?", options: ["The health endpoint was disabled", "The Keycloak container image has neither curl nor wget installed, and this chapter's compose file doesn't expose the management port to the host", "Port 9000 doesn't exist in Keycloak 26", "The realm hadn't been created yet"], answerIndex: 1, explanation: "This was independently confirmed live in this chapter's lab run and matches Keycloak's own health-check documentation, which explicitly notes the container image lacks curl." },
    { id: "ick-11", type: "concept", question: "On what port does Keycloak serve its health-check endpoints by default when KC_HEALTH_ENABLED=true?", options: ["8080, the same port as the Admin Console", "9000, the separate management interface port", "8443 only", "A random ephemeral port each start"], answerIndex: 1, explanation: "Keycloak's observability docs state health endpoints are served on the management port, 9000 by default, separate from the main HTTP(S) port the Admin Console and Admin REST API use." },
    { id: "ick-12", type: "scenario", question: "Riverside Health's ops team wants to run a quick production-readiness sanity check on a Keycloak instance someone configured. Which single observation from this chapter should worry them most?", options: ["The instance logs admin logins", "The container is running with command: start-dev and is reachable from outside the host that runs it", "The instance uses PostgreSQL instead of an in-memory database", "The instance has more than one realm"], answerIndex: 1, explanation: "start-dev disables HTTPS enforcement and strict hostname checking and is explicitly documented as unsafe for anything beyond a local lab — reachability from outside the host is exactly the scenario those relaxations make dangerous." },
    { id: "ick-13", type: "compare", question: "What is the functional difference between the Admin Console's \"Create realm\" button and running kcadm.sh create realms -s realm=...?", options: ["The Console creates a more fully-featured realm", "None in substance — the Console is a UI layer over the same Admin REST API that kcadm.sh calls directly", "kcadm.sh cannot set enabled=true", "The Console requires a different admin account"], answerIndex: 1, explanation: "This chapter frames the Admin Console steps (described from documentation, since no browser tool was available) and the kcadm.sh command (personally run and verified) as mechanically equivalent — both end up calling the same Admin REST API endpoint." },
    { id: "ick-14", type: "concept", question: "Why does this chapter clearly separate what was \"personally verified via kcadm.sh\" from what is \"described from Keycloak's official documentation\"?", options: ["Because kcadm.sh and the Admin Console produce different results", "Because no browser tool was available to click through the Admin Console directly, so the two sources of claims have different levels of first-hand verification", "Because the documentation is outdated", "Because the Admin Console doesn't exist in Keycloak 26.8.2"], answerIndex: 1, explanation: "The course's content rules require being honest about this split rather than presenting documentation-sourced UI claims as if they were personally observed." },
    { id: "ick-15", type: "bug", question: "A reader sees docker compose down leave the Postgres volume intact and complains the next chapter's lab \"isn't starting clean.\" What should they have run instead?", options: ["docker compose stop", "docker compose down -v, which also deletes the Postgres volume", "docker compose restart", "docker compose rm -f"], answerIndex: 1, explanation: "docker compose down keeps the named volume by design; -v additionally removes it, giving the next chapter's lab a genuinely clean slate — exactly what this chapter's own teardown used." },
    { id: "ick-16", type: "scenario", question: "Meridian Trust's PCI-DSS auditors ask why a newly stood-up Keycloak instance has two realms (master and a second one) instead of one. What's the correct explanation?", options: ["It's a mistake; realms should be consolidated", "master exists only to manage Keycloak itself; the second realm is where the bank's own application users, roles, and clients live, kept deliberately separate from administrative control", "Keycloak requires at least two realms to function", "The second realm is a backup of master"], answerIndex: 1, explanation: "This is precisely the master-realm application-boundary rule this chapter establishes: master for managing Keycloak, a dedicated realm for the organization's actual applications." },
    { id: "ick-17", type: "concept", question: "What specifically did the Keycloak 26.8.2 boot log report as its own internal startup time in this chapter's real lab run?", options: ["About 5 seconds", "About 19.4 seconds (Quarkus boot), separate from container-runtime overhead before the first successful HTTP request", "Exactly 15 seconds, matching the README's guidance precisely", "Startup time isn't logged"], answerIndex: 1, explanation: "The real boot log captured in this chapter read \"started in 19.441s\" — and the full wait until a 200 from outside the container was longer, since container-runtime overhead and the TCP listener coming up aren't counted in that internal figure." }
  ],

  "realms": [
    { id: "rst-01", type: "concept", question: "Which realm-level setting implements the inactivity half of chapter 7's generic SSO-session concept?", options: ["SSO Session Idle", "SSO Session Max", "Access Token Lifespan", "Client Session Idle"], answerIndex: 0, explanation: "SSO Session Idle invalidates the session once inactivity exceeds the configured timeout; SSO Session Max is an absolute ceiling regardless of activity." },
    { id: "rst-02", type: "concept", question: "What is the key difference between SSO Session Idle and SSO Session Max?", options: ["Idle is an inactivity timeout; Max is an absolute ceiling regardless of activity", "They are two names for the same setting", "Idle applies only to admins; Max applies only to end users", "Idle controls access tokens; Max controls refresh tokens"], answerIndex: 0, explanation: "Idle resets with activity and ends the session after a period of inactivity; Max fires at a fixed point no matter how active the user has been." },
    { id: "rst-03", type: "concept", question: "Why can an SSO session outlive many access tokens over its lifetime?", options: ["Access Token Lifespan is a separate, typically much shorter clock than the SSO session, and tokens are reminted via refresh while the session persists", "Access tokens never actually expire in Keycloak", "SSO sessions are stored inside the access token itself", "Access Token Lifespan and SSO Session Max are always set to the same value"], answerIndex: 0, explanation: "The two are independent timeouts; a session can survive dozens of access-token mint/expire/refresh cycles." },
    { id: "rst-04", type: "scenario", question: "Northwind Apps' customer-success team reports that users reviewing long reports keep getting logged out mid-task, even though they're clicking around the whole time. Which realm setting most directly addresses this?", options: ["SSO Session Idle (raise it)", "Access Token Lifespan (lower it)", "Require SSL (set to None)", "Revoke Refresh Token (disable it)"], answerIndex: 0, explanation: "Getting logged out despite ongoing activity points to the inactivity timeout being too short relative to natural pauses, not a token or transport setting." },
    { id: "rst-05", type: "scenario", question: "Northwind's security team raised SSO Session Idle to 1 hour but simultaneously lowered SSO Session Max from 10 hours to 8 hours. What's the reasoning tying these two opposite moves together?", options: ["A longer idle timeout makes it easier for a technically 'active' session to drift on indefinitely, so the absolute ceiling was tightened to cap it at one working day", "The two settings must always sum to the same total", "Lowering Max was an unrelated, separate decision about a different feature", "Max was lowered by mistake and should be reverted"], answerIndex: 0, explanation: "The chapter's case study frames this as a deliberate trade-off: convenience within a session, paired with a hard stop at the end of a working day." },
    { id: "rst-06", type: "bug", question: "A realm has Remember Me enabled, and an admin tightens the regular SSO Session Idle/Max values to reduce exposure. A pen tester later finds Remember Me sessions lasting far longer than the new values. What's the most likely cause?", options: ["Remember Me has its own separate Idle/Max fields that were never updated", "Remember Me sessions are immune to all timeouts by design", "The admin edited the wrong realm", "Access Token Lifespan overrides session timeouts when Remember Me is checked"], answerIndex: 0, explanation: "SSO Session Idle Remember Me and SSO Session Max Remember Me are distinct fields from the regular SSO Session Idle/Max \u2014 tightening one pair doesn't touch the other." },
    { id: "rst-07", type: "bug", question: "A user clicks 'Forgot Password?' on a realm where the setting is enabled, but no reset email ever arrives. What should be checked first?", options: ["Whether SMTP (host and From address) is actually configured for the realm/server", "Whether Require SSL is set to None", "Whether the user's access token has expired", "Whether Remember Me is disabled"], answerIndex: 0, explanation: "Keycloak's own documentation is explicit that the Forgot Password link only works once email settings are configured so Keycloak can send the message." },
    { id: "rst-08", type: "bug", question: "An admin disables Remember Me on a realm, expecting all previously-remembered sessions to end immediately. They don't. Why?", options: ["Invalidation of existing Remember-Me sessions is lazy \u2014 it happens on next use of that session's cookie/token or via a background process, not instantly", "Disabling Remember Me only affects new realms, not existing ones", "Remember Me sessions cannot be disabled once created", "This is a bug in Keycloak, not documented behavior"], answerIndex: 0, explanation: "The official guide notes invalidation happens the next time the cookie/token is used, or in background cleanup \u2014 not the moment the setting is flipped." },
    { id: "rst-09", type: "compare", question: "How does Client Session Max differ from SSO Session Max?", options: ["Client Session Max is scoped to one client's session and its refresh token; SSO Session Max is the ceiling on the overall user session across all clients", "They are identical settings with different names for backward compatibility", "Client Session Max only applies to confidential clients", "SSO Session Max is always shorter than Client Session Max"], answerIndex: 0, explanation: "Client Session Max governs a specific client session and when its refresh token expires; SSO Session Max governs the realm-wide SSO session." },
    { id: "rst-10", type: "compare", question: "How does Offline Session Idle differ from SSO Session Idle?", options: ["Offline Session Idle governs offline tokens (offline_access scope, long-lived refresh without re-login); SSO Session Idle governs the regular browser SSO session", "They are the same field, just renamed in newer Keycloak versions", "Offline Session Idle only applies to admin users", "SSO Session Idle has no idle concept, only a max"], answerIndex: 0, explanation: "Offline sessions are a distinct mechanism from the browser SSO session, with their own idle (and optionally capped max) timeout." },
    { id: "rst-11", type: "concept", question: "Which Require SSL mode does Keycloak's own documentation describe as applying 'only in development'?", options: ["None", "External requests", "All requests", "Loopback only"], answerIndex: 0, explanation: "None disables the SSL requirement entirely and is documented as a development-only choice." },
    { id: "rst-12", type: "concept", question: "Which Realm Settings tab hosts brute-force detection, and which chapter covers it in full depth?", options: ["Security Defenses \u2014 chapter 30", "Tokens \u2014 chapter 29", "Login \u2014 chapter 25", "Themes \u2014 chapter 26"], answerIndex: 0, explanation: "Security Defenses hosts headers and brute-force detection; this chapter only previews it, deferring configuration to chapter 30." },
    { id: "rst-13", type: "concept", question: "Which Realm Settings tab controls which theme renders the Account Console, Admin Console, Login screens, and emails?", options: ["Themes", "General", "Tokens", "Security Defenses"], answerIndex: 0, explanation: "The Themes tab assigns a theme to each of those four surfaces; localization/internationalization is a related, separate tab." },
    { id: "rst-14", type: "scenario", question: "Northwind decides customer accounts should only ever be created by each customer company's own admin, never by strangers filling out a public form. Which Login-tab setting should stay disabled to enforce this?", options: ["User registration", "Forgot password", "Remember Me", "Login with email"], answerIndex: 0, explanation: "User registration controls self-service sign-up; leaving it off keeps account creation administrative, consistent with Northwind's CIAM provisioning model." },
    { id: "rst-15", type: "bug", question: "A lab session runs kcadm.sh update realms/northwind-apps -s accessTokenLifespan=600 and the command returns with no error output. What's the correct way to be sure the change actually took effect, per this chapter's own lab discipline?", options: ["Run a separate kcadm.sh get realms/northwind-apps --fields accessTokenLifespan call and read the real value back", "Trust the absence of an error as sufficient confirmation", "Restart the Keycloak container and check the boot log", "Re-run the exact same update command a second time"], answerIndex: 0, explanation: "Every change in this chapter's lab is confirmed with an independent get call, not inferred from the update command's own (often silent) response." }
  ],

  "users-and-credentials": [
    { id: "usr-01", type: "concept", question: "By default, what does Keycloak's Declarative User Profile do with a custom user attribute that isn't declared in the realm's user profile configuration?", options: ["Rejects the request with a 400 error", "Saves it but marks it read-only", "Silently ignores it \u2014 no error, attribute not saved", "Automatically declares it as a new managed attribute"], answerIndex: 2, explanation: "Keycloak's own docs state it plainly: the server ignores any attribute not explicitly declared. This chapter's lab hit exactly this \u2014 no error, attribute simply absent afterward." },
    { id: "usr-02", type: "bug", question: "A kcadm.sh update users/{id} -s 'attributes.department=[\"Engineering\"]' command returns no error, but a follow-up get shows no attributes field at all. What's the most likely cause?", options: ["A typo in the attribute name", "The realm's unmanagedAttributePolicy is at its default (DISABLED)", "kcadm.sh doesn't support setting attributes at all", "The user doesn't exist"], answerIndex: 1, explanation: "This is exactly what this chapter's lab ran into: identical syntax failed under the default policy and succeeded once unmanagedAttributePolicy was set to ENABLED." },
    { id: "usr-03", type: "scenario", question: "Northwind Apps wants every user to reliably carry a department custom attribute long-term, not just for a one-off lab demo. Per Keycloak's own recommendation, what's the better approach than leaving unmanagedAttributePolicy set to ENABLED realm-wide?", options: ["Leave it ENABLED \u2014 it works, so there's no reason to change anything", "Formally declare department in the user profile configuration (or use ADMIN_EDIT) instead of allowing all unmanaged attributes", "Store the attribute in a separate database instead of Keycloak", "Switch to a different realm"], answerIndex: 1, explanation: "Keycloak's docs specifically recommend the strictest workable policy \u2014 declaring the attribute formally gets real validation; ADMIN_EDIT is the narrower fallback. ENABLED realm-wide was used in this chapter only to demonstrate the mechanism." },
    { id: "usr-04", type: "compare", question: "What is the difference between unmanagedAttributePolicy values ADMIN_VIEW and ADMIN_EDIT?", options: ["ADMIN_VIEW allows end users to edit; ADMIN_EDIT doesn't", "ADMIN_VIEW makes unmanaged attributes read-only from the admin context; ADMIN_EDIT allows admins to both read and write them", "They are identical aliases", "ADMIN_VIEW only applies to built-in attributes"], answerIndex: 1, explanation: "Per Keycloak's docs: ADMIN_VIEW exposes unmanaged attributes as read-only to admins; ADMIN_EDIT additionally allows admins to write them. Neither exposes them to end users the way ENABLED does." },
    { id: "usr-05", type: "concept", question: "Per Keycloak's own Server Administration Guide, what exactly is a required action?", options: ["A password complexity rule enforced at creation time", "An action a user must perform at first login, after a correct credential check but before login completes", "A role automatically assigned on signup", "A log entry recorded for compliance"], answerIndex: 1, explanation: "The docs define it directly: actions a user must perform at the first login, running after credentials are supplied and gating login completion, not authentication itself." },
    { id: "usr-06", type: "scenario", question: "priya.patel was created in this chapter with requiredActions set to [\"CONFIGURE_TOTP\"]. What happens the next time she submits a correct username and password to Keycloak's login form?", options: ["Login completes immediately since her password was correct", "Her credential is verified, but login does not complete until she enrolls an OTP generator", "She is locked out entirely until an admin intervenes", "Keycloak ignores the required action on first login only"], answerIndex: 1, explanation: "Required actions run after a successful credential check \u2014 her password being correct doesn't skip the gate; she must complete OTP enrollment before the login finishes." },
    { id: "usr-07", type: "concept", question: "What is kcadm.sh set-password's own default for the --temporary flag, confirmed directly in this chapter's lab?", options: ["Temporary (true) by default \u2014 a required action is always added", "Not temporary (false) by default \u2014 no required action is added unless --temporary=true is explicitly passed", "It prompts interactively every time", "The flag has no effect on requiredActions"], answerIndex: 1, explanation: "This chapter ran both cases on a disposable test user: without --temporary, requiredActions stayed empty; with --temporary=true, Keycloak automatically added UPDATE_PASSWORD." },
    { id: "usr-08", type: "scenario", question: "A Northwind Apps admin runs kcadm.sh set-password --username new.hire --new-password 'Welcome123' --temporary=true for a brand-new employee. What should that employee's requiredActions list contain immediately afterward?", options: ["Nothing \u2014 temporary only affects display, not behavior", "[\"UPDATE_PASSWORD\"], added automatically by Keycloak", "[\"CONFIGURE_TOTP\"], since all temporary passwords require MFA setup", "An error, since temporary passwords aren't allowed for new users"], answerIndex: 1, explanation: "This is the exact mechanism this chapter verified: --temporary=true causes Keycloak to add UPDATE_PASSWORD automatically, without any separate command." },
    { id: "usr-09", type: "bug", question: "This chapter observed kcadm.sh get users/{id} --fields attributes print { } for a user that genuinely had an attribute set (confirmed moments later by a plain, unfiltered get). What does this suggest about trusting --fields on nested objects?", options: ["--fields is always reliable and this was a one-off fluke not worth noting", "A nested-field filter result that looks suspiciously empty is worth double-checking with a full, unfiltered get before concluding the data is missing", "attributes can never be reliably read from kcadm.sh", "The attribute had actually been deleted between the two calls"], answerIndex: 1, explanation: "The chapter documents this exact discrepancy as a common mistake \u2014 the raw REST response and the unfiltered get both showed the attribute correctly; only the --fields-filtered nested read showed it empty." },
    { id: "usr-10", type: "concept", question: "What did this chapter's GET users/{id}/credentials call actually show was stored for jane.doe's password credential?", options: ["The plaintext password, for admin recovery purposes", "An Argon2 hash plus hashing parameters (iterations, memory, parallelism) \u2014 no plaintext anywhere in the response", "A reversible encryption of the password", "Nothing \u2014 passwords aren't retrievable via the Admin REST API at all"], answerIndex: 1, explanation: "The real captured response showed credentialData containing an Argon2 hash and its parameters; the password \"JaneDoe!Lab2026\" itself appears nowhere in it." },
    { id: "usr-11", type: "scenario", question: "Riverside Health enables realm-level email verification for its patient portal. What happens to a newly self-registered patient's account as a result, per this chapter's case study?", options: ["Nothing changes until an admin manually reviews the account", "Keycloak automatically attaches a Verify Email required action, blocking full portal access until the patient confirms their email address", "The account is disabled until a clinician approves it", "Email verification only affects employees, not patients"], answerIndex: 1, explanation: "This is the same required-action mechanism used for priya.patel's CONFIGURE_TOTP, applied to a different realm-level trigger and a different risk (unconfirmed email ownership on a patient portal)." },
    { id: "usr-12", type: "compare", question: "What is the concrete mechanical difference between disabling a Keycloak user (enabled: false) and deleting it, confirmed directly in this chapter's lab?", options: ["No real difference \u2014 both remove all access permanently", "Disabling flips one field and leaves the record, attributes, and id intact; deleting removes the record entirely, confirmed by a subsequent get returning a real 404", "Deleting is reversible; disabling is not", "Disabling only works on users without credentials set"], answerIndex: 1, explanation: "This chapter's lifecycle-demo walkthrough confirmed exactly this: disable left a fully intact, re-enableable record; delete produced \"Resource not found\" on the next lookup." },
    { id: "usr-13", type: "scenario", question: "A Meridian Trust auditor asks for proof that suspending a teller's account preserves her access history while deleting it would not. Which two pieces of real evidence from this chapter's lab would support that claim?", options: ["Server CPU usage logs before and after", "A get call showing the disabled user's attributes/id intact after disabling, versus a 404 from the same get call after deletion", "The Keycloak version number", "The realm's token lifetime setting"], answerIndex: 1, explanation: "This chapter captured exactly that pair of results on its own demo user: a full record after disabling, and a genuine \"Resource not found\" error after deleting \u2014 the same distinction chapter 2's Meridian Trust example cared about." },
    { id: "usr-14", type: "concept", question: "jane.doe has both a username (\"jane.doe\") and a server-generated id (a UUID). In chapter 2's vocabulary, what are both of these?", options: ["The UUID is a credential; the username is an identifier", "Both are identifiers \u2014 unique, not secret \u2014 but only the username is what a human actually types in", "The UUID is the only true identifier; the username is just a display label", "Neither qualifies as an identifier under chapter 2's definition"], answerIndex: 1, explanation: "Chapter 2 only requires an identifier to be unique, not secret or human-typed. Keycloak's internal id satisfies that for every REST call; the username satisfies it for the human logging in \u2014 different audiences, same concept." },
    { id: "usr-15", type: "scenario", question: "On Keycloak's Users screen, where does chapter 2's \"credential\" concept concretely live for jane.doe?", options: ["The Details tab", "The Credentials tab, confirmed in this chapter via the dedicated /credentials REST endpoint", "The Attributes tab", "The realm's General settings"], answerIndex: 1, explanation: "This chapter mapped all four of chapter 2's concepts onto concrete Keycloak locations (Figure 22.1); Credential specifically maps to the Credentials tab and its backing REST endpoint." },
    { id: "usr-16", type: "compare", question: "What distinguishes a built-in user attribute (like email) from a custom one (like department) in Keycloak 26?", options: ["Built-in attributes are always encrypted; custom ones never are", "Custom attributes require a password; built-in ones don't", "Built-in attributes are already declared in the realm's user profile and validated automatically; custom ones are unmanaged unless explicitly declared or allowed by policy", "There is no real distinction in Keycloak 26"], answerIndex: 2, explanation: "This chapter's lab demonstrated the practical consequence directly: email/firstName/lastName saved without issue, while department required either declaring it or changing unmanagedAttributePolicy." },
    { id: "usr-17", type: "scenario", question: "priya.patel was created in this chapter with a team attribute and a required action, but no roles or groups. Whose job is assigning her roles and replaying chapter 10's Mover-trap scenario?", options: ["This chapter should have done it, since she's already created", "Chapter 23 (roles & groups)", "Chapter 24 (clients & scopes)", "Chapter 29 (sessions)"], answerIndex: 1, explanation: "Per this chapter's explicit scope and BUILD_STATUS.md's Northwind Apps realm plan, role/group assignment \u2014 including the real Mover-trap replay \u2014 is chapter 23's job, not chapter 22's." },
    { id: "usr-18", type: "bug", question: "An admin assigns a required action to a user, then that user's account is accessed through some path that doesn't go through Keycloak's own full login flow (e.g. a cached session or a direct token grant). The required action never seems to trigger. What's the likely explanation, per this chapter's framing?", options: ["Required actions are decorative and don't actually enforce anything", "Required actions specifically gate the completion of Keycloak's own authentication flow \u2014 a path that bypasses that flow bypasses the gate too", "The required action was assigned to the wrong realm", "Required actions only work for the first user created in a realm"], answerIndex: 1, explanation: "This chapter's common-mistakes section raises exactly this: required actions gate login completion at a specific point in Keycloak's own flow, documented as running after credential verification \u2014 a path that skips that flow won't hit the gate." }
  ],

  "roles-and-groups": [
    { id: "rlg-01", type: "concept", question: "What is the scope difference between a Keycloak realm role and a client role?", options: ["A realm role is visible to every client in the realm; a client role lives in a namespace dedicated to one specific client", "A realm role can only be assigned via groups; a client role can only be assigned directly", "A client role is visible realm-wide; a realm role is scoped to one client", "There is no difference \u2014 the terms are interchangeable"], answerIndex: 0, explanation: "Keycloak's own documentation describes a client role as \"basically a role namespace dedicated to the client,\" in contrast to a realm role's realm-wide visibility." },
    { id: "rlg-02", type: "concept", question: "Per Keycloak's documentation, what does assigning a user to a composite role actually grant?", options: ["Only the composite role's own name, with no further permissions", "Every role the composite role is \"associated with,\" in addition to the composite role itself", "A temporary role that expires after one session", "Nothing, until an administrator manually also assigns each associated role"], answerIndex: 1, explanation: "\"A composite role is a role that can be associated with other roles\" \u2014 mapping a user to it grants every associated role too, from one assignment." },
    { id: "rlg-03", type: "concept", question: "What happens to a user's effective access when they are added to a Keycloak group that carries role mappings?", options: ["Nothing changes until the user logs out and back in with a new password", "The user inherits the group's role mappings and attributes automatically", "The group's roles only apply to new resources created after the join date", "Group membership has no effect on role mappings in Keycloak"], answerIndex: 1, explanation: "Keycloak's docs state it directly: \"Users that become members of a group inherit the attributes and role mappings that group defines.\"" },
    { id: "rlg-04", type: "scenario", question: "Northwind Apps assigns jane.doe the realm role tenant-admin. What does this role's scope mean for her access?", options: ["She can administer every tenant on every Keycloak instance in the world", "The role is checked the same way by every client registered in the northwind-apps realm", "The role only applies inside the northwind-dashboard client's own namespace", "The role is invisible to kcadm.sh and only usable from the Admin Console"], answerIndex: 1, explanation: "A realm role lives in the realm's own namespace, so any client in that realm can check for it \u2014 unlike a client role, which is scoped to one client." },
    { id: "rlg-05", type: "scenario", question: "Priya moves from Northwind's support team to its platform engineering team. Which sequence correctly reproduces chapter 10's Mover-event guidance in Keycloak?", options: ["Assign platform-engineer and add her to Engineering; nothing else is required", "Assign platform-engineer, add her to Engineering, remove support-agent, and remove her from Support", "Remove support-agent and her Support membership only; platform-engineer is optional", "Create a new user account for her platform-engineer identity"], answerIndex: 1, explanation: "A correctly implemented Mover event both grants the new access and explicitly removes the old access \u2014 two adds and two removes, not two adds alone." },
    { id: "rlg-06", type: "bug", question: "A script runs kcadm.sh add-roles --rolename platform-engineer for a moved employee but never calls remove-roles for their old role. After running, which statement is true?", options: ["Keycloak automatically revokes the old role once a new one is added", "The employee now holds both the old and new roles at once, until someone explicitly removes the old one", "The script will fail with an error, since a user can only hold one realm role at a time", "The old role silently expires after 24 hours"], answerIndex: 1, explanation: "Keycloak does nothing automatically here \u2014 role removal is a separate, deliberate action. Skipping it is exactly the beginner mistake chapter 10 warned about, reproduced hands-on in this chapter." },
    { id: "rlg-07", type: "compare", question: "Northwind Apps needs a role meaning \"can view reports inside the northwind-dashboard application\" specifically. Which role type fits better than a realm role, and why?", options: ["A realm role, because realm roles are always more secure", "A client role on northwind-dashboard, because the permission only makes sense inside that one application's namespace", "Neither \u2014 this must be modeled as a group", "A composite role is required for any application-specific permission"], answerIndex: 1, explanation: "A permission scoped to one specific application's own context fits a client role's dedicated namespace better than a realm-wide role." },
    { id: "rlg-08", type: "scenario", question: "Which kcadm.sh pattern actually adds a user to a Keycloak group?", options: ["kcadm.sh create groups -r <realm> -s name=<group>", "kcadm.sh add-roles --uusername <user> --rolename <group>", "kcadm.sh update users/<id>/groups/<groupId> -s realm=<realm> -s userId=<id> -s groupId=<groupId> -n", "kcadm.sh get users/<id>/groups"], answerIndex: 2, explanation: "Group membership is managed via a PUT to users/{id}/groups/{groupId}, invoked in kcadm.sh as an update call against that path \u2014 create groups only creates the group itself, and get only reads existing membership." },
    { id: "rlg-09", type: "concept", question: "Every user's role-mappings query in this chapter's lab showed a role called default-roles-northwind-apps. What is it?", options: ["A role accidentally left over from a previous chapter's testing", "An automatically created composite role every user in the realm holds, bundling baseline roles like offline_access", "A role that only appears if MFA is enabled", "A client role scoped to the master realm"], answerIndex: 1, explanation: "Keycloak automatically creates a default-roles-<realm> composite role for every realm, held by every user, bundling baseline roles such as offline_access and uma_authorization." },
    { id: "rlg-10", type: "scenario", question: "Meridian Trust wants its role set to make a create-transfer-plus-approve-transfer toxic combination easier to catch in an access review. What role design choice helps most?", options: ["Bundle both abilities into one broad teller role for simplicity", "Define transfer-creator and transfer-approver as two separate, narrow roles so holding both requires two distinct, visible assignments", "Avoid roles entirely and hard-code permissions per employee", "Make transfer-approver a composite role containing transfer-creator"], answerIndex: 1, explanation: "Narrow, independent roles make a dangerous combination a simple query against role assignments; folding both abilities into one broad role (or nesting one inside the other via composition) hides the combination instead." },
    { id: "rlg-11", type: "bug", question: "An access review finds one Meridian Trust teller holds both transfer-creator and transfer-approver. What pattern does this represent, and what should happen?", options: ["This is normal and requires no action, since each role was individually reasonable to grant", "This is a toxic combination (chapter 10) and at least one of the two roles should be removed or a compensating control documented", "This is a composite role working as intended", "This indicates a Keycloak bug, since it should have blocked the second assignment automatically"], answerIndex: 1, explanation: "Keycloak enforces whatever roles are assigned; it has no concept of a toxic combination. Catching and resolving this is the access review's job, not the IAM product's." },
    { id: "rlg-12", type: "concept", question: "In the Admin Console, how is an existing realm role converted into a composite role?", options: ["Realm Roles > select the role > Action menu > Add associated roles", "Users > select a user > Role mapping > Assign role", "Groups > Create group > Associated roles tab", "Composite roles cannot be created through the Admin Console, only via kcadm.sh"], answerIndex: 0, explanation: "Per Keycloak's Server Administration Guide: open the role under Realm Roles, then use its Action list's \"Add associated roles\" option to associate other roles with it." },
    { id: "rlg-13", type: "scenario", question: "Which kcadm.sh command removes a user from a Keycloak group?", options: ["kcadm.sh remove-roles --uusername <user> --rolename <group>", "kcadm.sh delete users/<id>/groups/<groupId> -r <realm>", "kcadm.sh update users/<id>/groups/<groupId> -s enabled=false", "kcadm.sh create groups -r <realm> -s name=<group> --remove"], answerIndex: 1, explanation: "Group membership removal is a DELETE against users/{id}/groups/{groupId} \u2014 the exact mirror of the update/PUT call used to join the group." },
    { id: "rlg-14", type: "compare", question: "What's the practical difference between assigning a role directly to a user versus granting it through group membership?", options: ["There is no difference \u2014 Keycloak treats both identically with no distinction possible", "A directly assigned role stays with the user regardless of group changes; a group-inherited role is granted or lost automatically as group membership changes", "Group-inherited roles can never be checked by a client, only directly assigned ones can", "Direct role assignment is only available via kcadm.sh, never the Admin Console"], answerIndex: 1, explanation: "A direct role assignment persists until explicitly removed from the user; a group-mapped role tracks group membership, which is exactly why chapter 23's Mover sequence removed Priya's old group membership as well as her old direct role." },
    { id: "rlg-15", type: "concept", question: "Why were tenant-admin, support-agent, and platform-engineer created in the northwind-apps realm rather than in master?", options: ["Keycloak requires all custom roles to live in master", "master is reserved for managing Keycloak itself, not for an organization's own application-facing roles and users", "Roles created in master are automatically composite roles", "There is no functional difference; it was an arbitrary choice"], answerIndex: 1, explanation: "Chapter 20 established that master exists only to manage Keycloak itself \u2014 mixing an organization's own roles, users, and clients into it puts ordinary application risk one hop from instance-wide administrative control." },
    { id: "rlg-16", type: "scenario", question: "When Priya first joined Northwind's support team (before any Mover event), which two actions correctly set up her starting access?", options: ["Assign her the tenant-admin role and add her to Engineering", "Assign her the support-agent role and add her to the Support group", "Create a composite role combining every role at once", "Add her to Support only; roles are unnecessary if group membership exists"], answerIndex: 1, explanation: "Her starting state in this chapter's lab was exactly this: the support-agent realm role assigned directly, plus membership in the Support group." },
    { id: "rlg-17", type: "bug", question: "Suppose platform-engineer had been built as a composite role that also associated support-agent (so every platform engineer silently also held support-agent). What would break about the Mover payoff in this chapter?", options: ["Nothing \u2014 composite roles have no effect on removal logic", "Removing support-agent directly from Priya's assignment wouldn't remove her support-agent access, since it would still be transitively granted through platform-engineer", "The realm would refuse to let platform-engineer be assigned at all", "Priya would be unable to log in until the composite role was fixed"], answerIndex: 1, explanation: "This is exactly why the chapter kept the three roles independent and non-composite: nesting one inside another would have hidden the old role's access one level deeper instead of actually removing it." },
    { id: "rlg-18", type: "concept", question: "What does a Keycloak subgroup inherit from its parent group?", options: ["Nothing \u2014 subgroups are fully independent of their parent", "The parent group's role mappings, in addition to any role mappings defined on the subgroup itself", "Only the parent's name, not its role mappings", "The parent group's members are automatically removed when a subgroup is created"], answerIndex: 1, explanation: "A subgroup inherits its parent's role mappings on top of whatever role mappings it defines on its own." }
  ],

  "clients-and-scopes": [
    { id: "cli-01", type: "concept", question: "What is the key functional difference between a confidential and a public Keycloak client?", options: ["Confidential clients can only use the device flow", "Confidential clients receive a client secret and are expected to run where that secret stays hidden; public clients get no secret and rely on PKCE", "Public clients are only for internal staff tools", "Confidential clients cannot use the authorization code grant"], answerIndex: 1, explanation: "publicClient: false issues a client secret required at the token endpoint; publicClient: true issues none, relying on PKCE instead \u2014 matching whether the client's runtime can actually keep a secret hidden." },
    { id: "cli-02", type: "scenario", question: "Northwind Apps is building northwind-dashboard, a staff-facing tool that runs on a server Northwind controls. How should it be registered?", options: ["Public client, no secret, PKCE only", "Confidential client, standard flow enabled, direct access grants disabled", "Confidential client with direct access grants enabled for convenience", "Public client with a client secret for extra safety"], answerIndex: 1, explanation: "A server-side app that Northwind controls can safely hold a secret, so it should be confidential; it logs users in via a browser redirect, so standard flow is the grant it needs \u2014 direct access grants (ROPC) should stay off for a real product." },
    { id: "cli-03", type: "bug", question: "A protocol mapper is configured exactly per Keycloak's documentation to add a department claim from a user attribute, but the claim never appears in any issued token or UserInfo response, and no step reported an error. What's the most likely cause?", options: ["The mapper's claim.name field is case-sensitive and was mistyped", "The client scope was never attached to the client at all", "The source user attribute was never actually persisted, because it isn't declared in the realm's declarative User Profile schema and unmanagedAttributePolicy isn't enabled", "Access tokens cannot carry custom claims under any configuration"], answerIndex: 2, explanation: "Keycloak 26's declarative User Profile silently drops writes to attributes outside its declared schema unless unmanagedAttributePolicy is enabled \u2014 the mapper can be perfectly correct and still have nothing to read, with no error surfaced anywhere." },
    { id: "cli-04", type: "compare", question: "How does a Keycloak client role differ from a realm role (chapter 23)?", options: ["Client roles are only visible to Keycloak administrators", "A client role's meaning is scoped to the one client it's created under; a realm role applies across the whole realm", "Client roles cannot be assigned to users, only to groups", "There is no functional difference \u2014 it's purely a naming convention"], answerIndex: 1, explanation: "A client role (clientRole: true) lives under that specific client's own role list and never appears in the realm's own role listing \u2014 confirmed live in this chapter by checking both lists directly." },
    { id: "cli-05", type: "concept", question: "What distinguishes a default client scope from an optional client scope?", options: ["Default scopes cost more API calls to resolve", "A default scope is always included in a client's tokens automatically; an optional scope is only included if a token request's scope= parameter names it explicitly", "Optional scopes can only contain role mappings, never protocol mappers", "Default scopes cannot be attached to more than one client"], answerIndex: 1, explanation: "Default vs. optional controls whether the client has to ask for the scope by name in its token request \u2014 both are the same kind of object otherwise." },
    { id: "cli-06", type: "scenario", question: "Northwind's customer-facing product will eventually be a browser-based SPA that customers load directly, with no server Northwind controls in between. Why is this chapter registering it as northwind-spa in name only, as a public client, rather than building it in full now?", options: ["Public clients cannot be registered until chapter 35 for technical reasons", "It mirrors a real platform team's sequencing \u2014 internal tooling clients get built first, and a public client with no secret needs the full SPA integration (PKCE, redirect handling) chapter 35 covers to be meaningful", "Keycloak does not support public clients in development mode", "northwind-spa does not need a client scope at all"], answerIndex: 1, explanation: "There's no technical blocker \u2014 it's a deliberate sequencing choice matching how a real team would prioritize its own internal tooling client before its customer-facing product's integration is ready." },
    { id: "cli-07", type: "concept", question: "What three things does a Keycloak protocol mapper's config need to specify, at minimum, to add a claim from a user attribute?", options: ["Only the claim name \u2014 everything else is inferred automatically", "Which user attribute to read (user.attribute), what claim name to write it under (claim.name), and which token types/responses to include it in (the id.token.claim/access.token.claim/userinfo.token.claim flags)", "Only the client scope's own name", "The realm's signing key alias"], answerIndex: 1, explanation: "The mapper needs a source, a destination claim name, and explicit flags for each place the claim could appear \u2014 none of these are inferred for you." },
    { id: "cli-08", type: "compare", question: "A client role named dashboard-admin is created under northwind-dashboard. A different client, say a future reporting tool, checks a user's roles. Will it see dashboard-admin?", options: ["Yes, automatically, because all roles in a realm are globally visible", "No \u2014 a client role's resource_access entry is scoped to the client it belongs to; another client's token would not carry it unless explicitly configured to", "Only if the user is also a realm administrator", "Only if the two clients share the same redirect URI"], answerIndex: 1, explanation: "Client roles live in the resource_access claim keyed by client \u2014 they don't leak into another client's view of a user's permissions by default." },
    { id: "cli-09", type: "scenario", question: "A teammate registers northwind-dashboard's Valid Redirect URIs as a bare * \"to avoid redirect_uri headaches during testing.\" What's the concrete risk, per this chapter and chapter 13?", options: ["No real risk \u2014 Keycloak validates the client_id separately regardless", "It reintroduces exactly the exact-match gap chapter 13's live demo-server finding demonstrated: any redirect URI, including an attacker-controlled one, would be accepted, letting an intercepted authorization code be redirected anywhere", "It only affects public clients, not confidential ones", "It would simply cause Keycloak to refuse to start the client"], answerIndex: 1, explanation: "Keycloak's own docs explicitly warn against the bare wildcard in production for exactly this reason \u2014 it defeats the exact-match protection the field exists to provide." },
    { id: "cli-10", type: "bug", question: "A client is created with publicClient: true but someone also tries to configure it with a fixed client secret value, believing this adds a layer of protection. What's wrong with this setup?", options: ["Nothing \u2014 more credentials are always safer", "A secret embedded in a public client's code (browser JS, decompiled mobile binary) isn't actually secret at all \u2014 anyone with access to the client can read it, so it provides no real protection and the client should instead be using PKCE", "Public clients technically cannot have secrets configured at all, so this would fail outright", "The secret would only be used for refresh tokens, not initial login"], answerIndex: 1, explanation: "Confusing 'has a secret field filled in' with 'is actually secure' is the mistake \u2014 anywhere an attacker can read the client's own code, an embedded secret is already compromised." },
    { id: "cli-11", type: "concept", question: "What does setting directAccessGrantsEnabled: true on a client actually permit?", options: ["It permits the authorization code flow to skip PKCE", "It permits the client to use the Resource Owner Password Credentials grant \u2014 trading a username/password directly for a token with no browser redirect at all", "It permits the client to act as an identity broker", "It permits custom claims to be added without a protocol mapper"], answerIndex: 1, explanation: "directAccessGrantsEnabled toggles ROPC specifically \u2014 chapter 13 already named this grant as legacy/discouraged for real applications." },
    { id: "cli-12", type: "scenario", question: "A future Northwind integration needs pure machine-to-machine access to an internal API, with no human user involved at all. Which client setting from this chapter's survey is the relevant one to enable, and which grant does it unlock (previewed in chapter 13, full depth chapter 14)?", options: ["standardFlowEnabled, unlocking the authorization code grant", "serviceAccountsEnabled, unlocking the client credentials grant", "directAccessGrantsEnabled, unlocking the device code grant", "publicClient: true, unlocking the implicit grant"], answerIndex: 1, explanation: "serviceAccountsEnabled gives the client its own dedicated service-account user and enables the client credentials grant \u2014 the correct fit for machine-to-machine access with no resource owner." },
    { id: "cli-13", type: "concept", question: "Why are id.token.claim, access.token.claim, and userinfo.token.claim modeled as three independent flags on a protocol mapper, rather than one single on/off switch?", options: ["Keycloak requires redundant configuration as a safeguard against typos", "Different consumers need the same claim in different places \u2014 a resource server reading an access token, a client reading an ID token, and a UserInfo caller may each need different claims available, and a single claim might only be needed in one of the three", "Only the id.token.claim flag actually has any effect; the other two are legacy fields", "They control three different realms, not three different token types"], answerIndex: 1, explanation: "Each destination serves a different consumer with different needs, so Keycloak lets an admin route a given claim to exactly the destinations it's actually needed in." },
    { id: "cli-14", type: "scenario", question: "Riverside Health wants every clinician's access token to carry a clinic_location claim sourced from a user attribute, visible to its backend API but not necessarily shown on a consent screen. Which Keycloak mechanism from this chapter does that, and what single config flag controls whether it's shown on a consent prompt?", options: ["A realm role; display.on.consent.screen controls consent-screen visibility", "A protocol mapper on a client scope sourcing the clinic_location user attribute; the client scope's display.on.consent.screen attribute controls consent-screen visibility", "A client role; introspection.token.claim controls consent-screen visibility", "This requires custom Java SPI code, not a mapper"], answerIndex: 1, explanation: "A user-attribute protocol mapper on a client scope is exactly this chapter's mechanism; display.on.consent.screen is the specific attribute controlling whether the scope's claims are shown to the user before granting." },
    { id: "cli-15", type: "compare", question: "In this chapter's real lab, the department claim appeared in both the access token and a live UserInfo call for the same user. What determines whether a given claim shows up in one, the other, or both?", options: ["Whichever grant type was used to obtain the token", "The mapper's own access.token.claim and userinfo.token.claim flags, set independently of each other", "UserInfo always mirrors the access token exactly with no separate configuration possible", "Only claims from the openid scope can ever appear in UserInfo"], answerIndex: 1, explanation: "The two paths are controlled by two separate flags on the same mapper \u2014 in this chapter's lab both were set to true, which is why the claim appeared in both places." },
    { id: "cli-16", type: "bug", question: "A mapper is configured with id.token.claim: true but userinfo.token.claim: false. A developer complains the claim is missing when they call the UserInfo endpoint, even though it shows up fine when they decode the ID token. What's the explanation?", options: ["This is a Keycloak bug \u2014 the two should always match", "This is working exactly as configured \u2014 userinfo.token.claim: false means that specific destination was deliberately excluded for this claim, independent of the ID token flag", "UserInfo only ever returns claims from the openid scope, nothing custom", "The access token needs to be refreshed first"], answerIndex: 1, explanation: "Each flag is independent by design \u2014 excluding a claim from UserInfo while keeping it in the ID token is a legitimate, deliberate configuration, not a bug." },
    { id: "cli-17", type: "concept", question: "Keycloak's Valid Redirect URIs field supports a trailing wildcard like https://host.com/path/*. What does Keycloak's own documentation say is explicitly excluded from this wildcard matching, to avoid security issues?", options: ["Query string parameters", "A redirect URI containing a userinfo part, or whose path attempts to manage access to a parent directory (/../)", "Any redirect URI longer than 255 characters", "Redirect URIs using the https scheme specifically"], answerIndex: 1, explanation: "Keycloak's docs specifically carve out userinfo-containing and path-traversal URIs from wildcard matching, falling back to exact string matching for those cases instead." },
    { id: "cli-18", type: "scenario", question: "Northwind decides the department claim should only appear on tokens for clients that specifically ask for it, not automatically on every token northwind-dashboard requests. What single change would accomplish this?", options: ["Delete the protocol mapper and recreate it", "Attach the northwind-profile client scope to northwind-dashboard as an optional scope instead of a default scope", "Set multivalued to true on the mapper", "Disable standardFlowEnabled on the client"], answerIndex: 1, explanation: "Switching the scope's attachment mode from default to optional is exactly the lever for this \u2014 the mapper itself doesn't need to change at all." }
  ],

  "authentication-flows": [
    { id: "afl-01", type: "concept", question: "What distinguishes a CONDITIONAL subflow from an ALTERNATIVE execution in a Keycloak authentication flow?", options: ["CONDITIONAL subflows are evaluated at all only if their own REQUIRED condition executions evaluate true first; ALTERNATIVE just means \"one of several acceptable paths\"", "CONDITIONAL is just a renamed ALTERNATIVE for subflows", "ALTERNATIVE always runs after CONDITIONAL in every flow", "CONDITIONAL executions cannot contain other executions"], answerIndex: 0, explanation: "CONDITIONAL gates an entire subflow (and everything nested inside it) behind its REQUIRED condition executions passing first; ALTERNATIVE just means Keycloak accepts success at any one of several peer executions." },
    { id: "afl-02", type: "concept", question: "Which requirement level means Keycloak skips an execution entirely, as if it weren't configured at all?", options: ["ALTERNATIVE", "CONDITIONAL", "DISABLED", "REQUIRED"], answerIndex: 2, explanation: "DISABLED executions are never evaluated \u2014 this chapter's lab used it to turn off WebAuthn and Recovery Codes, and to turn off the two enrollment-based conditions it replaced." },
    { id: "afl-03", type: "scenario", question: "Northwind Apps wants every tenant-admin challenged for OTP at login, while ordinary engineering users log in with just a password. Which authenticator does this chapter's lab actually add to the browser flow's conditional 2FA subflow to implement this?", options: ["Condition - user configured", "Condition - user role", "Condition - client scope", "OTP Form, set REQUIRED at the flow's top level"], answerIndex: 1, explanation: "Condition - user role (provider conditional-user-role), configured with condUserRole=tenant-admin, is the real execution this chapter's lab added and verified via the Admin REST API." },
    { id: "afl-04", type: "bug", question: "A Northwind admin sets OTP Form's requirement to REQUIRED directly inside the top-level browser flow (not inside any conditional subflow), and now every single user \u2014 enrolled in OTP or not \u2014 gets challenged for a code at login. What's the cause?", options: ["OTP Form is broken in this Keycloak version", "REQUIRED at that level applies to literally every authentication passing through the flow, with no condition gating it", "The Condition - user configured execution overrides it automatically", "REQUIRED only applies to newly created users"], answerIndex: 1, explanation: "A flat REQUIRED execution outside any conditional subflow has no gate at all \u2014 it demands OTP from every single login, which is exactly why this chapter nested OTP Form's REQUIRED setting inside a conditional subflow instead." },
    { id: "afl-05", type: "compare", question: "Northwind's mobile backend uses Direct Grant while its customer-facing portal uses the Browser flow. How do the two differ in what they protect?", options: ["Direct Grant is for non-interactive, API-style credential submission; Browser is for interactive, redirect-based web login", "They are functionally identical, just named differently", "Direct Grant is only used for brokered logins", "Browser flow is deprecated in favor of Direct Grant"], answerIndex: 0, explanation: "Direct Grant has no redirect and no login page \u2014 credentials arrive directly in a token request; Browser is the interactive, redirect-to-a-login-page path." },
    { id: "afl-06", type: "concept", question: "Which Keycloak built-in flow executes the first time, and only the first time, a user signs in through a brokered external identity provider?", options: ["Reset Credentials", "First Broker Login", "Registration", "Direct Grant"], answerIndex: 1, explanation: "First Broker Login runs exactly once per user on their first brokered login, before Keycloak decides whether to link, create, or reject a local account \u2014 distinct from every ordinary login flow." },
    { id: "afl-07", type: "scenario", question: "Meridian Trust wants its online banking app to demand an extra OTP challenge only when a customer initiates a wire transfer above a threshold, not on every login. In the vocabulary this chapter built, which mechanism would implement that kind of step-up?", options: ["Setting OTP Form to REQUIRED in the main browser flow for every login", "A CONDITIONAL subflow whose condition execution evaluates the triggering transaction context before escalating an otherwise-ALTERNATIVE factor to REQUIRED", "Disabling the Direct Grant flow entirely", "Creating a new realm per transaction type"], answerIndex: 1, explanation: "The shape is the same condition-gates-a-factor mechanism this chapter built for Northwind's tenant-admin role; Meridian's condition would need to evaluate transaction context, which requires a custom authenticator provider (chapters 39-40) since no built-in condition answers 'what is the user about to do.'" },
    { id: "afl-08", type: "bug", question: "A Northwind reader tries to edit Keycloak's built-in \"browser\" flow directly in the Admin Console and finds every dropdown and add-step control greyed out. What's the cause?", options: ["A permissions bug in their admin account", "Built-in flows are read-only by design \u2014 Keycloak requires duplicating a built-in flow before any of its steps can be changed", "The realm needs restarting before flows become editable", "Only the master realm's flows can be edited"], answerIndex: 1, explanation: "Built-in flows are deliberately protected from in-place edits so a known-good default always exists; this chapter's lab duplicated \"browser\" first (via the real copy endpoint) and edited the copy." },
    { id: "afl-09", type: "concept", question: "What does cloning (duplicating) a Keycloak flow actually copy?", options: ["Only the top-level flow's name", "The entire flow, including every nested subflow and execution, as a new independently editable tree", "Nothing \u2014 a clone just creates an alias pointing at the original", "Only the REQUIRED executions"], answerIndex: 1, explanation: "This chapter's lab confirmed this directly: re-fetching the clone's executions reproduced the exact same tree as the original browser flow, under new display names, before any further edits were made." },
    { id: "afl-10", type: "scenario", question: "After duplicating the browser flow and customizing its conditional 2FA subflow, a Northwind admin notices real logins still behave exactly like before. What's the most likely missing step?", options: ["The realm's browserFlow binding still points at the original \"browser\" alias, not the new clone, so the clone has no effect on real logins yet", "The clone needs to be deleted and recreated from scratch", "Users need to log out of every existing session first", "Keycloak caches flow bindings for 24 hours before applying changes"], answerIndex: 0, explanation: "Cloning and editing a flow changes nothing about real authentications until the realm's corresponding binding field (browserFlow here) is explicitly repointed at the new alias \u2014 this chapter's lab did that as its final step." },
    { id: "afl-11", type: "concept", question: "What is the real difference between a required action and an authentication-flow execution?", options: ["They are the same mechanism with two different names", "A required action runs after authentication otherwise succeeds, before a session is issued; a flow execution runs during the credential check itself", "Required actions only ever apply to administrator accounts", "Flow executions cannot be configured on a per-realm basis"], answerIndex: 1, explanation: "Timing is the key distinction: a flow execution can block a session from ever being issued at all, while a required action is a one-time gate that only runs once authentication has already otherwise succeeded." },
    { id: "afl-12", type: "scenario", question: "Northwind wants every newly created user forced into OTP enrollment the first time they'd otherwise need it, without an admin flagging each account individually. Which realm-level setting, actually changed in this chapter's lab, accomplishes this?", options: ["Setting CONFIGURE_TOTP's defaultAction to true", "Adding OTP Form as REQUIRED in the Direct Grant flow", "Disabling the Registration flow entirely", "Setting browserFlow to \"direct grant\""], answerIndex: 0, explanation: "defaultAction=true on CONFIGURE_TOTP adds \"Configure OTP\" to every newly created user's required-actions list automatically \u2014 this chapter's lab set it and confirmed the change via a separate GET." },
    { id: "afl-13", type: "compare", question: "For a Northwind conditional 2FA subflow, how does \"Condition - user configured\" differ from \"Condition - user role\" as a gate?", options: ["user configured checks whether the user already enrolled a relevant credential; user role checks role membership regardless of enrollment status", "The two conditions are fully interchangeable in every case", "Condition - user role only works for client roles, never realm roles", "Condition - user configured requires a browser session and user role does not"], answerIndex: 0, explanation: "Keycloak's default flow uses enrollment status as its gate (don't force 2FA on someone with nothing configured yet); this chapter's custom flow replaced that with role membership, which doesn't care whether the user has enrolled yet." },
    { id: "afl-14", type: "concept", question: "In the Admin REST API's executions listing, which fields, together with level, order executions within a Keycloak flow tree?", options: ["priority and index", "alias", "requirementChoices", "providerId"], answerIndex: 0, explanation: "level places an execution within the tree's nesting; index/priority order it relative to its siblings at that level \u2014 this chapter's captured JSON output showed exactly these fields on every execution." },
    { id: "afl-15", type: "scenario", question: "A Northwind engineer configures a Condition - user role execution with condUserRole set to \"tenant-admin\", not realizing this particular realm doesn't actually have a role by that exact name yet. What happens when Keycloak saves this configuration?", options: ["Keycloak rejects the save with a validation error", "Keycloak accepts and stores the string reference as-is; the condition simply never evaluates true until a role with that exact name exists and is assigned", "Keycloak auto-creates the missing role", "The execution silently reverts to Condition - user configured"], answerIndex: 1, explanation: "This is a real, confirmed finding from this chapter's own lab run: the config saved and read back cleanly even though the tenant-admin role didn't exist in that disposable test realm \u2014 Keycloak doesn't validate the role exists at config-save time." },
    { id: "afl-16", type: "concept", question: "Chapter 5 described OTP as a possession factor and step-up authentication as an extra check triggered by risk rather than a fixed schedule. Which mechanism, actually configured in this chapter's lab, most directly implements that concept for real?", options: ["The Direct Grant flow", "A CONDITIONAL subflow gating an OTP Form execution on a triggering condition", "The master realm", "A client scope's protocol mapper"], answerIndex: 1, explanation: "This chapter turned chapter 5's abstract 'raise the bar when a signal says to' into a concrete, scripted artifact: a condition execution gating OTP Form from ALTERNATIVE to REQUIRED." },
    { id: "afl-17", type: "scenario", question: "Riverside Health's clinicians mostly use fast badge-tap login (chapter 5), but IT security wants pharmacy-system administrators specifically to always provide OTP. Which single change maps onto this requirement, using the mechanism this chapter built?", options: ["Disable the Browser flow entirely for pharmacy admins", "Add a Condition - user role execution scoped to the pharmacy-admin role inside a conditional 2FA subflow, with OTP Form set REQUIRED beneath it", "Require OTP only in the Direct Grant flow", "Move pharmacy admins into the Registration flow"], answerIndex: 1, explanation: "This is structurally identical to what this chapter actually built for Northwind's tenant-admin role, just with a different role name \u2014 the same conditional-user-role + REQUIRED OTP Form pattern." },
    { id: "afl-18", type: "bug", question: "A Northwind reader sets Condition - user role to REQUIRED but leaves the original Condition - user configured also REQUIRED in the same subflow, expecting \"OTP for tenant-admins.\" Instead, no one \u2014 not even tenant-admins \u2014 gets challenged until they've already enrolled OTP some other way. What's the cause?", options: ["Multiple REQUIRED condition executions in the same subflow are implicitly ANDed, so leaving the old condition in place silently adds \"and already has a credential configured\" to the rule", "Keycloak only ever evaluates the first condition in a subflow", "REQUIRED conditions are evaluated in reverse alphabetical order", "Condition - user role always loses a tie-break against Condition - user configured"], answerIndex: 0, explanation: "This is the exact pitfall this chapter's own lab hit and documented: it had to explicitly disable the old Condition - user configured (and Condition - credential) rather than leaving them REQUIRED alongside the new role condition." }
  ],

  "themes-and-branding": [
    { id: "thm-01", type: "concept", question: "In the Keycloak 26.8.2 image this course's labs run, where do the actual built-in theme template/CSS files physically live?", options: ["As plain directories directly under /opt/keycloak/themes/", "Inside a JAR (org.keycloak.keycloak-themes-26.8.2.jar) on the classpath", "In a database table inside the configured realm database", "Bundled only inside the Admin Console's own JavaScript bundle"], answerIndex: 1, explanation: "ls /opt/keycloak/themes/ in this chapter's lab returned only a README.md; the README itself says built-in theme files are inside the themes JAR, openable with any zip tool." },
    { id: "thm-02", type: "concept", question: "Which realm REST field controls the username/password entry, OTP entry, and registration screens?", options: ["accountTheme", "adminTheme", "loginTheme", "emailTheme"], answerIndex: 2, explanation: "loginTheme is the field this chapter's lab actually set and confirmed (kcadm.sh update realms/northwind-apps -s loginTheme=keycloak)." },
    { id: "thm-03", type: "scenario", question: "Northwind Apps wants its customer companies' employees to see Northwind's own logo and colors, not a generic vendor look, when they log in. Which realm setting is the direct mechanism for that?", options: ["supportedLocales", "loginTheme", "internationalizationEnabled", "adminTheme"], answerIndex: 1, explanation: "loginTheme controls the login screens customers actually see; this is the branding/conversion concern chapter 12 flagged for CIAM-adjacent products." },
    { id: "thm-04", type: "bug", question: "An engineer runs kcadm.sh update realms/northwind-apps -s adminTheme=base. The command succeeds with no error, and base is marked abstract=true in its own theme.properties (meant only to be inherited from, not used directly). What does this tell you?", options: ["abstract=true themes are rejected by the REST API automatically", "The Admin REST API performs no validation that a theme name is a sane, directly-usable theme for that type", "adminTheme ignores abstract themes silently and falls back to keycloak.v2", "kcadm.sh caught the mistake and printed a warning"], answerIndex: 1, explanation: "This chapter tested exactly this and confirmed the write succeeds and persists \u2014 the abstract restriction is only enforced by the Admin Console's own dropdown UI, not the REST API." },
    { id: "thm-05", type: "compare", question: "What's the real, confirmed difference between the keycloak and keycloak.v2 built-in themes in this Keycloak 26.8.2 image?", options: ["keycloak is PatternFly v3/v4 with login/email/welcome types; keycloak.v2 is PatternFly v5 with darkMode=true and only a login type in this image", "keycloak.v2 is deprecated and keycloak is the current default", "Both are identical except for their names", "keycloak.v2 supports internationalization and keycloak does not"], answerIndex: 0, explanation: "Confirmed by reading both themes' real theme.properties files directly out of the jar." },
    { id: "thm-06", type: "concept", question: "What does abstract=true inside a theme's theme.properties actually do?", options: ["Deletes the theme after first use", "Disables the theme's CSS entirely", "Marks it as meant only to be inherited (parent=) from, hidden from the Admin Console's Themes-tab dropdown as a direct selection \u2014 but not blocked by the REST API", "Forces the theme to always use English regardless of locale settings"], answerIndex: 2, explanation: "base/login/theme.properties sets abstract=true; this chapter confirmed the REST API still accepts it as a direct realm setting despite the UI hiding it." },
    { id: "thm-07", type: "scenario", question: "Northwind declares supportedLocales=[\"en\",\"de\",\"fr\",\"es\"] on northwind-apps, but a French-speaking customer still sees English text on parts of a custom login page. What's the most likely real cause?", options: ["French isn't a real ISO locale code", "internationalizationEnabled must have been left false", "The custom theme (or an override) is missing a messages_fr.properties file with the needed keys \u2014 declaring a locale supported and actually translating it are independent facts", "supportedLocales can only ever hold 3 entries"], answerIndex: 2, explanation: "The chapter states explicitly: nothing on the write path checks that a declared supportedLocales entry has matching translated strings." },
    { id: "thm-08", type: "concept", question: "How is Keycloak's welcome theme configured, and how does that differ from the other four theme types?", options: ["Via the same realm REST fields as loginTheme/accountTheme/adminTheme/emailTheme", "Via a per-user profile attribute", "Via a server startup option (--spi-theme--welcome-theme=<name>), since it's an instance-wide default page rather than a per-realm setting", "It cannot be changed at all"], answerIndex: 2, explanation: "The welcome page appears before any realm is selected, so it can't be a per-realm REST field \u2014 it's an instance-level SPI option instead." },
    { id: "thm-09", type: "scenario", question: "Before this chapter's lab touched anything, what did kcadm.sh get realms/northwind-apps --fields internationalizationEnabled actually return on the fresh realm?", options: ["{ \"internationalizationEnabled\" : true }", "An error, since the field doesn't exist until set", "{ \"internationalizationEnabled\" : false }", "An empty object with no fields at all"], answerIndex: 2, explanation: "Confirmed live: a fresh realm's internationalizationEnabled defaults to false, while loginTheme/accountTheme/adminTheme/emailTheme/supportedLocales were simply absent (unset) from the same response." },
    { id: "thm-10", type: "concept", question: "In Keycloak's documented locale resolution order, which of these is checked first?", options: ["The realm's defaultLocale", "The browser's Accept-Language header", "A language the user explicitly selected on the login page", "English, as a hardcoded first guess"], answerIndex: 2, explanation: "The order is: user-selected, user-profile locale, client-requested (e.g. ui_locales), cookie, Accept-Language header, realm defaultLocale, then English \u2014 each step only checked if the previous produced nothing." },
    { id: "thm-11", type: "bug", question: "A reader runs docker compose exec keycloak ls /opt/keycloak/themes/ expecting to see folders named base, keycloak, and keycloak.v2, but only sees README.md, and concludes the lab environment is broken. What's actually going on?", options: ["The lab environment genuinely is broken and the image is missing its themes", "Nothing is broken \u2014 Keycloak 26.x bundles its built-in themes inside a JAR rather than extracting them to that directory; the README explains this and points at the jar", "The themes were deleted by the realm-creation step", "Only custom themes appear there; this is expected Keycloak behavior since version 1.0"], answerIndex: 1, explanation: "This chapter's lab hit exactly this and resolved it by copying the real jar out with docker compose cp and inspecting it with Python's zipfile module." },
    { id: "thm-12", type: "scenario", question: "Northwind wants to actually build and ship a branded login theme, not just assign a bundled one. Per Keycloak's official UI Customization Guide, what's the real mechanism (not visually verified in this course, since no browser tool exists here)?", options: ["Edit the keycloak theme's files directly inside the running container", "Create themes/<name>/login/ with its own theme.properties declaring parent=<existing theme>, a resources/ folder for assets, a messages/ folder for translations, and FTL overrides only where markup itself must change", "Fork Keycloak's entire source code and recompile it", "Set loginTheme to any string; Keycloak will auto-generate a theme from the realm's display name"], answerIndex: 1, explanation: "This is the real override structure read from the official guide and from the shipped themes' own theme.properties files \u2014 and the guide explicitly warns against modifying built-in themes directly." },
    { id: "thm-13", type: "compare", question: "In a theme.properties file, what's the difference between parent= and import=?", options: ["They are synonyms; either works identically", "parent declares the theme this one extends (inheriting templates/resources not overridden); import additionally pulls in resources (like common/keycloak) from another theme", "import is for CSS only; parent is for JavaScript only", "parent is required for login themes; import is required for email themes"], answerIndex: 1, explanation: "Confirmed by reading keycloak/login/theme.properties and keycloak.v2/login/theme.properties directly: both declare parent=base and import=common/keycloak as distinct properties." },
    { id: "thm-14", type: "scenario", question: "A CI pipeline runs kcadm.sh update realms/northwind-apps -s loginTheme=notrhwind (a typo of a real custom theme name that was never actually created). What happens?", options: ["kcadm.sh rejects the command with a theme-not-found error", "The write succeeds and persists silently; the mistake only surfaces later when someone actually looks at the rendered login page", "Keycloak automatically corrects the typo to the closest matching real theme name", "The realm refuses to start until the typo is fixed"], answerIndex: 1, explanation: "This chapter's lab confirmed the REST API validates nothing about whether a theme name resolves to a real, renderable theme." },
    { id: "thm-15", type: "concept", question: "Which theme type controls the self-service console a logged-in user uses to manage their own profile, credentials, and sessions?", options: ["Login theme", "Account theme", "Admin console theme", "Welcome theme"], answerIndex: 1, explanation: "Per Keycloak's own Server Administration Guide, the account theme is \"the console used by the user to manage his or her account\" \u2014 chapter 1's generic self-service concept, made concrete." },
    { id: "thm-16", type: "scenario", question: "Northwind's design team specifically wants a modern, dark-mode-capable login look rather than the older PatternFly v3/v4 style. Based on this chapter's real inspection of the bundled themes, which existing theme name is the closer starting point to extend via parent=?", options: ["base", "keycloak", "keycloak.v2", "welcome"], answerIndex: 2, explanation: "keycloak.v2's own theme.properties sets darkMode=true and uses PatternFly v5, confirmed by reading the file directly; it would be the sensible parent= choice for a modern, dark-mode-aware custom theme." }
  ],

  "admin-api-and-cli": [
    { id: "api-01", type: "concept", question: "What is the base path pattern every Admin REST API endpoint hangs off?", options: ["/realms/{realm}/protocol/openid-connect/...", "/admin/realms/{realm}/{resource}", "/admin/{resource}/realms/{realm}", "/kcadm/{realm}/{resource}"], answerIndex: 1, explanation: "Confirmed live in chapter 27: every admin endpoint follows {server}/admin/realms/{realm}/{resource}, with the realm name (not id) as the path segment." },
    { id: "api-02", type: "concept", question: "What is kcadm.sh, precisely, relative to the Admin REST API?", options: ["A separate administrative protocol with its own authentication scheme", "A thin command-line wrapper that builds and sends the same REST calls the Admin Console makes", "A GraphQL interface layered on top of the REST API", "A deprecated tool replaced by the Admin Console in modern Keycloak versions"], answerIndex: 1, explanation: "Chapter 27 confirmed this directly by reproducing a kcadm.sh action with a raw curl call against the identical endpoint \u2014 same base path, same bearer-token auth." },
    { id: "api-03", type: "scenario", question: "A Northwind automation engineer runs kcadm.sh create users -r northwind-apps -s username=new-admin ... and the terminal prints nothing at all, with exit code 0. What should they do next?", options: ["Assume the command failed and re-run it immediately", "Assume it succeeded because nothing complained", "Run a separate kcadm.sh get call (or re-run with -o) to confirm what actually happened, since some endpoints print nothing either way", "Restart the Keycloak container"], answerIndex: 2, explanation: "Chapter 27 hit exactly this on the partial-export endpoint: silent output doesn't distinguish success from no-op. Confirm independently." },
    { id: "api-04", type: "bug", question: "This chapter's own lab ran kcadm.sh create partial-export -r northwind-apps -s exportClients=true and got zero printed output despite exit code 0. What was the real cause?", options: ["The command actually failed silently due to a permissions error", "partial-export returns a response body but no Location header, so kcadm.sh's default create output (built from that header) has nothing to print; -o reveals the real body", "partial-export is not a real endpoint in this Keycloak version", "The realm did not exist yet"], answerIndex: 1, explanation: "Confirmed live: adding -o printed the full ~61KB real export body that was there all along." },
    { id: "api-05", type: "concept", question: "Which two query parameters does the Admin REST API's users list endpoint use for pagination, confirmed live in this chapter?", options: ["offset and limit", "page and size", "first and max", "skip and take"], answerIndex: 2, explanation: "kcadm.sh get users -q first=0 -q max=2 and -q first=2 -q max=2 were both run live and returned the expected two pages." },
    { id: "api-06", type: "scenario", question: "Meridian Trust's engineer wants to know the total number of users in a realm without paging through every result page. Which call should they make?", options: ["GET /admin/realms/{realm}/users with max=0", "GET /admin/realms/{realm}/users/count", "Read the X-Total-Count response header from any users list call", "There is no way to get a total without paging through everything"], answerIndex: 1, explanation: "Chapter 27 confirmed live that no total-count header exists on a paginated users response; /count is the real, separate mechanism." },
    { id: "api-07", type: "compare", question: "Compare the REST partial-export endpoint and the server-CLI full export (kc.sh export) on one axis: do they include user accounts?", options: ["Both include users", "Neither includes users", "partial-export (REST) never includes users; full export (kc.sh CLI) does, including hashed credentials", "partial-export includes users but full export does not"], answerIndex: 2, explanation: "Both facts were confirmed live in chapter 27 \u2014 a partial-export response has no users key at all; a full export produces a separate users file with real Argon2-hashed credential data." },
    { id: "api-08", type: "bug", question: "A reader writes a disaster-recovery restore script that parses a realm's partial-export JSON and expects a users array to loop over. What actually happens, and why?", options: ["It works fine, since all exports include users by default", "The script fails or silently does nothing to users, because partial-export's response has no users key at all \u2014 confirmed live in this chapter", "It works, but only for the first 100 users", "partial-export only works for realms with fewer than 50 users"], answerIndex: 1, explanation: "The exact test chapter 27 ran: python3 -c \"'users' in d\" on a real partial-export response returned False." },
    { id: "api-09", type: "scenario", question: "Riverside Health needs a realm backup for disaster recovery that genuinely includes every patient-portal user account for restore purposes. Which mechanism should they use, and what must be true of the server when they run it?", options: ["The Admin Console's own export button, with the server running normally", "REST partial-export with exportClients=true, server running normally", "The server-CLI full export (kc.sh export), which requires the Keycloak server process to not be running at the time", "kcadm.sh get realms, which exports everything by default"], answerIndex: 2, explanation: "Keycloak's own docs state only this boot-time CLI export is suitable for backup/transfer; chapter 27 confirmed it live, including the server-stopped requirement." },
    { id: "api-10", type: "concept", question: "Why does kc.sh export/import require the Keycloak server process not to be running, unlike an ordinary Admin REST API call?", options: ["It's an arbitrary restriction with no technical reason", "It is a separate, one-shot server launch mode (not a REST call at all), and consistency across a cluster isn't guaranteed unless every node is stopped first", "The REST API is disabled by default and must be manually re-enabled", "It only applies to realms with custom themes"], answerIndex: 1, explanation: "Per Keycloak's own docs (fetched live) plus chapter 27's own run: export/import are separate server launches that perform the operation then exit, distinct from the running server's REST surface." },
    { id: "api-11", type: "scenario", question: "Meridian Trust's compliance team finds a full realm export JSON file sitting on a shared drive, apparently left over from a migration. What's the precise risk, per what this chapter actually found inside one?", options: ["No real risk \u2014 full exports only contain realm settings, not user data", "It contains every user's real, plaintext password", "It contains every user's hashed-and-salted credential data, which is still sensitive secret material even though it isn't plaintext", "It contains only usernames, which is low-risk PII"], answerIndex: 2, explanation: "Chapter 27 read a real exported user's credential block directly: an Argon2 hash with its own salt, not plaintext \u2014 still real secret material for every user in the realm." },
    { id: "api-12", type: "scenario", question: "Northwind's bulk-onboarding script creates several new customer-admin accounts in seconds via kcadm.sh. A week later, nobody can find any admin-event record of those creations. What is the most likely cause, based on this chapter's own reproduced failure mode?", options: ["Admin events are never recorded for kcadm.sh actions, only Admin Console actions", "adminEventsEnabled was false (the realm default) at the time the script ran, and enabling it afterward does not retroactively create records for past actions", "The events were recorded but deleted automatically after 24 hours", "kcadm.sh bypasses event logging entirely by design and cannot be logged"], answerIndex: 1, explanation: "Chapter 27 deliberately reproduced this: 4 accounts created with adminEventsEnabled false left zero admin-event records; a 5th, created after enabling it, left a full real record." },
    { id: "api-13", type: "concept", question: "What does the partialImport endpoint's ifResourceExists parameter control?", options: ["Whether the import runs synchronously or asynchronously", "The conflict-resolution policy (SKIP, OVERWRITE, or FAIL) applied when an incoming resource's name or id already exists in the target realm", "Whether the server restarts after the import", "The maximum number of resources that can be imported in one call"], answerIndex: 1, explanation: "Confirmed live with ifResourceExists: SKIP against a realm that already had other users \u2014 the response reported added/overwritten/skipped counts explicitly." },
    { id: "api-14", type: "bug", question: "A CI pipeline authenticates kcadm.sh once per job on a shared build runner without passing --no-config. A later, unrelated job on the same runner unexpectedly succeeds using what looks like stale admin credentials. What's the cause?", options: ["kcadm.sh re-authenticates automatically for every command regardless of configuration", "kcadm.sh caches the access/refresh token from config credentials in a config file (kcadm.config) by default, and that file persists across invocations on the same machine unless --no-config or an isolated config path is used", "The bootstrap admin password never expires", "This is impossible; kcadm.sh never persists any session state"], answerIndex: 1, explanation: "Chapter 27 found this config file directly at /opt/keycloak/.keycloak/kcadm.config, holding a cached access and refresh token reused across subsequent commands." },
    { id: "api-15", type: "scenario", question: "Northwind's bulk-onboarding script needs to give each new support account both the support-agent realm role and membership in the Support group. Which two separate kcadm.sh operations accomplish that, per this chapter's own working script?", options: ["A single kcadm.sh create users call with both a role and group field set directly", "kcadm.sh add-roles --rolename support-agent, followed by kcadm.sh update on the user's /groups/{groupId} sub-resource", "kcadm.sh update realms with a roleToGroupMapping field", "Role and group assignment happen automatically based on the user's email domain"], answerIndex: 1, explanation: "This is exactly what bulk-onboard.sh did and chapter 27 confirmed live: add-roles for the role, then a group-id lookup plus update users/{id}/groups/{groupId} for the group." },
    { id: "api-16", type: "compare", question: "Compare the admin-cli client's password grant and a dedicated service-account client's client-credentials grant as ways to authenticate against the Admin REST API for an unattended CI pipeline that provisions Keycloak clients on every deploy. Which fits better, and why?", options: ["admin-cli's password grant fits better, since it's the built-in default and needs no extra setup", "Neither fits; CI pipelines cannot authenticate against the Admin REST API at all", "The dedicated service-account client's client-credentials grant fits better, since it needs no human password or interactive step and matches the machine-to-machine pattern chapter 36 describes for applications", "Both are equally unsuitable; only SAML assertions can authenticate automation"], answerIndex: 2, explanation: "admin-cli's password grant needs a real human admin's password embedded somewhere, which is exactly the anti-pattern a dedicated service account with client-credentials avoids." },
    { id: "api-17", type: "concept", question: "In the admin-scoped access token this chapter decoded, what did its aud (audience) claim target, and how does that differ from an ordinary OIDC client's access token?", options: ["It targeted the issuing realm's own token endpoint, same as any access token", "It targeted the Admin REST API itself (.../admin/realms/{realm}), distinguishing it from a token meant for some other application's own resource server", "It targeted the master realm regardless of which realm was being administered", "Admin-scoped tokens have no aud claim at all"], answerIndex: 1, explanation: "Chapter 27 base64url-decoded a real token and found aud: \".../admin/realms/master\" plus scope including kc-admin-api \u2014 confirmed, not assumed." }
  ],

  "events-and-auditing": [
    { id: "evt-01", type: "scenario", question: "Northwind's security team flips adminEventsEnabled to true on northwind-apps but leaves eventsEnabled at its default. After an admin changes a client's redirect URI and a user later logs in, which statement is true?", options: ["Neither the admin event nor the login event is recorded, because eventsEnabled gates both streams.", "The admin event is recorded, but the later login event still will not be recorded, since the two booleans are independent.", "The admin event is recorded only in the server log, never through the REST API.", "Admin events cannot exist unless eventsEnabled is also true."], answerIndex: 1, explanation: "eventsEnabled and adminEventsEnabled are fully independent booleans on RealmEventsConfigRepresentation; admin events don't require eventsEnabled to be on." },
    { id: "evt-02", type: "concept", question: "Which RealmEventsConfigRepresentation field controls whether an admin event record includes the full JSON body of what was created, updated, or deleted?", options: ["adminEventsEnabled", "eventsListeners", "adminEventsDetailsEnabled", "enabledEventTypes"], answerIndex: 2, explanation: "adminEventsDetailsEnabled is a third, independent switch layered on top of adminEventsEnabled; it controls the representation field specifically." },
    { id: "evt-03", type: "scenario", question: "Riverside Health enables adminEventsEnabled=true but leaves adminEventsDetailsEnabled=false. After a clinician's access is upgraded to full chart access, what can Riverside's audit team see in the resulting admin event?", options: ["Nothing at all \u2014 no admin event is created.", "That a REALM_ROLE_MAPPING resource was CREATEd, on a specific resourcePath, by whom and when (via authDetails) \u2014 but not the exact representation of what was granted.", "The full before-and-after JSON of the role mapping, identical to adminEventsDetailsEnabled=true.", "Only the HTTP status code of the underlying REST call."], answerIndex: 1, explanation: "adminEventsEnabled alone gives the who/what-resource/when; adminEventsDetailsEnabled is the separate switch for the representation field." },
    { id: "evt-04", type: "scenario", question: "Northwind's ops team wants to see only the admin events related to role-mapping changes on northwind-apps, without scrolling through every other admin action. Which mechanism accomplishes this directly?", options: ["GET /admin/realms/northwind-apps/admin-events with resourceTypes=REALM_ROLE_MAPPING as a query parameter", "Manually grep the JSON response client-side, since the REST API has no server-side filter", "DELETE /admin/realms/northwind-apps/admin-events first, then recreate the role mapping", "Switch eventsListeners to jboss-logging only"], answerIndex: 0, explanation: "resourceTypes is a real, documented query parameter on GET /admin/realms/{realm}/admin-events." },
    { id: "evt-05", type: "bug", question: "A resource-owner-password-credentials grant fails with \"error_description\": \"Account is not fully set up\", even though GET on the user shows requiredActions: []. What's the most likely real cause?", options: ["The user's password credential was never actually set.", "The client making the grant has directAccessGrantsEnabled=false.", "The realm's declarative user profile marks an attribute (e.g. firstName/lastName) as required, and the user record never had it set, even though it's not reflected in requiredActions.", "The realm has adminEventsEnabled=false."], answerIndex: 2, explanation: "This is the exact bug this chapter's own lab hit and fixed live \u2014 confirmed via the events stream's own resolve_required_actions error record." },
    { id: "evt-06", type: "compare", question: "Compare Keycloak's built-in Logging Event Listener and Email Event Listener. Which statement correctly distinguishes them?", options: ["Both send emails; the Logging listener just adds a log-file copy.", "The Logging Event Listener writes error events to the org.keycloak.events log category by default; the Email Event Listener sends a message to the affected user's own email address for a smaller set of event types (e.g. Login Error, Update Password).", "The Email Event Listener is the only one enabled by default on a new realm.", "Both are third-party SPI providers that must be installed separately; neither ships with Keycloak."], answerIndex: 1, explanation: "Both ship built-in, but they do different things with the same events \u2014 one logs, one emails the affected user." },
    { id: "evt-07", type: "scenario", question: "Meridian Trust (PCI-DSS) wants Keycloak's events flowing into their existing SIEM platform. Based on what this chapter confirmed exists, which statement is accurate?", options: ["Keycloak ships a built-in SIEM connector that only needs a target URL configured.", "There is no way to get events out of Keycloak except manually reading the Admin Console's Events screen.", "Meridian's team would need to build one of: a scheduled poll of the events/admin-events REST endpoints, a log-shipper on the jboss-logging listener's log category, or a custom Event Listener SPI provider \u2014 none pre-built.", "SIEM export only works if Meridian disables adminEventsDetailsEnabled."], answerIndex: 2, explanation: "Keycloak has no built-in SIEM connector; all three real mechanisms require the integrating team to build something." },
    { id: "evt-08", type: "concept", question: "On a freshly created Keycloak realm that has never been touched by an admin, what is true of eventsEnabled, adminEventsEnabled, and enabledEventTypes?", options: ["All three are already fully configured and recording; nothing needs to change.", "eventsEnabled and adminEventsEnabled both default to false, while enabledEventTypes already defaults to a large list (102 entries, confirmed live) and eventsListeners already defaults to [\"jboss-logging\"].", "enabledEventTypes defaults to an empty list until an admin adds types manually.", "adminEventsEnabled defaults to true, while eventsEnabled defaults to false."], answerIndex: 1, explanation: "Confirmed live in this chapter's lab: only the two main booleans are off by default; everything about \"what to record\" is already populated." },
    { id: "evt-09", type: "scenario", question: "An engineer runs curl http://localhost:8080/health against a Keycloak 26.8.2 instance with KC_HEALTH_ENABLED=true already set, and gets a 404. What's the most likely explanation?", options: ["KC_HEALTH_ENABLED only affects /metrics, not /health.", "/health is served on the separate management interface (port 9000 by default in this version), not the main port 8080 \u2014 the engineer needs to hit port 9000 instead.", "/health only works over HTTPS.", "/health requires a bearer token even for a liveness check."], answerIndex: 1, explanation: "Confirmed live: 200 on port 9000, 404 on the identical path on port 8080." },
    { id: "evt-10", type: "bug", question: "A compliance review of a PCI-scoped realm's admin events finds the representation field contains more of a user record's attributes than expected. What's the actual cause, and what should the team have decided earlier?", options: ["This is a Keycloak bug; representation should never contain user data.", "adminEventsDetailsEnabled captures the full submitted JSON body verbatim with no field-level filtering \u2014 the team should have decided beforehand whether that detail level is acceptable to retain.", "The representation field is encrypted and this cannot actually happen.", "Only enabledEventTypes controls this; adminEventsDetailsEnabled is unrelated."], answerIndex: 1, explanation: "This is a real, non-hypothetical property of adminEventsDetailsEnabled confirmed in this chapter's lab output." },
    { id: "evt-11", type: "concept", question: "By default in Keycloak 26.x, which port serves the /metrics endpoint (once KC_METRICS_ENABLED is set)?", options: ["8080", "8443", "9000 (the management interface)", "9990"], answerIndex: 2, explanation: "Confirmed live alongside /health on the same management-interface port." },
    { id: "evt-12", type: "scenario", question: "Riverside Health's compliance officer cites \"Audit controls\" as a HIPAA Security Rule requirement. Which citation and Keycloak mechanism correctly match this?", options: ["45 CFR \u00a7164.502(b), satisfied by Keycloak's password policy.", "45 CFR \u00a7164.312(b), satisfied by Keycloak's admin/login events subsystem.", "45 CFR \u00a7164.312(d), satisfied by Keycloak's brute-force detection.", "45 CFR \u00a7164.514(d), satisfied by a minimum-necessary scope mapper."], answerIndex: 1, explanation: "Chapter 11 already pinned Audit controls to \u00a7164.312(b); this chapter makes the Keycloak-side mechanism concrete." },
    { id: "evt-13", type: "compare", question: "Compare an EventRepresentation (login/user event) to an AdminEventRepresentation (admin event). Which statement is accurate?", options: ["Both representations carry identical fields; only the realm differs.", "EventRepresentation has a \"type\" field naming the login-event type (e.g. LOGIN); AdminEventRepresentation instead has operationType/resourceType/resourcePath describing a REST write, plus an optional representation field.", "AdminEventRepresentation always includes a sessionId; EventRepresentation never does.", "Only EventRepresentation supports an error field."], answerIndex: 1, explanation: "The two representations are genuinely different shapes for different kinds of events, confirmed from the REST API reference." },
    { id: "evt-14", type: "scenario", question: "One of Northwind's single-page clients exchanges an authorization code for a token, then later refreshes it. Which two login-event types, per Keycloak's own documentation, correspond to these two actions respectively?", options: ["Login, then Logout", "Code to Token, then Refresh Token", "Register, then Update Profile", "Client Login, then Client Login Error"], answerIndex: 1, explanation: "Quoted directly from the Server Administration Guide's event-type table." },
    { id: "evt-15", type: "concept", question: "What does the eventsExpiration field on RealmEventsConfigRepresentation actually control?", options: ["How long a client session stays idle before expiring.", "How long a recorded login/user event is retained before it ages out of storage.", "The expiration of the admin's own bearer token used to call the events endpoint.", "How long the jboss-logging listener buffers events before writing them."], answerIndex: 1, explanation: "A separate concept from session/token lifetimes (chapters 21/29) \u2014 this is event retention specifically." },
    { id: "evt-16", type: "scenario", question: "Meridian Trust's infrastructure team is deciding whether to expose Keycloak's management interface (port 9000) externally the way an internal dashboard might be. What does this chapter's material suggest?", options: ["Expose it externally so any external monitoring tool can reach it without a VPN.", "Treat it like the Admin Console/API: keep it reachable only by internal infrastructure (orchestrator probes, an internal Prometheus scraper), not exposed externally.", "It doesn't matter, since /health and /metrics never return sensitive data.", "Port 9000 is automatically firewalled by Keycloak itself, so no decision is needed."], answerIndex: 1, explanation: "Consistent with chapter 21's \"don't expose admin endpoints externally\" guidance, extended to the management interface." },
    { id: "evt-17", type: "bug", question: "An admin enables adminEventsEnabled, performs several role/client changes, then complains \"events aren't being saved anywhere useful, just to the log file.\" What's the most likely missing piece in their understanding?", options: ["Nothing is missing; admin events were never meant to be queryable via REST.", "They're confusing the jboss-logging listener's error-level log output with the actual stored admin-event records, which are already queryable via GET /admin/realms/{realm}/admin-events regardless of the listener.", "adminEventsEnabled must be paired with eventsEnabled or nothing is stored.", "Admin events require a server restart before they appear anywhere."], answerIndex: 1, explanation: "The listener's log output and the stored, REST-queryable event records are two separate things." },
    { id: "evt-18", type: "scenario", question: "Riverside Health sets eventsExpiration=2592000 on its realm. Approximately how many days of login/user events will Riverside retain before they age out?", options: ["3 days", "7 days", "30 days", "90 days"], answerIndex: 2, explanation: "2,592,000 seconds \u00f7 86,400 seconds/day = 30 days \u2014 the exact value this chapter's own lab set." },
    { id: "evt-19", type: "scenario", question: "Meridian Trust wants an aggregate count of failed password validations per realm, without reading individual event records. Which real, confirmed Keycloak surface gives them this directly?", options: ["GET /admin/realms/{realm}/events, read one at a time", "The /metrics endpoint's keycloak_credentials_password_hashing_validations counter, broken out by realm and outcome", "The Admin Console's Events screen only, with no REST equivalent", "The eventsExpiration field"], answerIndex: 1, explanation: "Confirmed live in this chapter's own metrics capture \u2014 a real Prometheus counter, labeled by realm and outcome." }
  ],

  "sessions-deep-dive": [
    { id: "sdd-01", type: "scenario", question: "A Meridian Trust security operator is told a teller's laptop was just stolen mid-shift, still logged into the internal banking console. The operator already has the teller's user id from the Admin Console but hasn't looked up a session id yet. What is the fastest correct Admin REST API sequence?", options: ["POST /admin/realms/{realm}/logout-all immediately \u2014 it's the only logout endpoint that exists", "GET /admin/realms/{realm}/users/{user-id}/sessions to find the session id(s), then DELETE /admin/realms/{realm}/sessions/{session} for each, or POST /admin/realms/{realm}/users/{user-id}/logout to end all of them at once", "Wait for SSO Session Idle to expire naturally \u2014 it's already configured to a safe value", "Rotate the client secret for every client in the realm"], answerIndex: 1, explanation: "The user-level logout endpoint (or listing then deleting individual sessions) targets exactly this employee without disturbing anyone else. logout-all is realm-wide and far too broad; waiting for idle timeout isn't an immediate response; rotating client secrets doesn't touch an existing session at all." },
    { id: "sdd-02", type: "concept", question: "Which real Admin REST API call lists a user's currently active sessions?", options: ["GET /admin/realms/{realm}/users/{user-id}/sessions", "GET /admin/realms/{realm}/sessions", "POST /admin/realms/{realm}/users/{user-id}/logout", "GET /admin/realms/{realm}/clients/{client-uuid}"], answerIndex: 0, explanation: "Confirmed both from Keycloak's published OpenAPI definition and by actually calling it live: GET .../users/{user-id}/sessions returns 200 with an array of session objects." },
    { id: "sdd-03", type: "bug", question: "An engineer calls DELETE /admin/realms/{realm}/sessions/{session}, sees a 204 response, and immediately tells their team \"confirmed, the session is dead.\" What's the bug in this reasoning?", options: ["204 means the request failed silently", "A 204 only confirms the server accepted the delete request \u2014 it does not, by itself, prove the session is actually gone; a separate GET users/{id}/sessions call is the real proof", "DELETE calls never return 204 for sessions, only for users", "The session will come back automatically after 204"], answerIndex: 1, explanation: "This chapter's own lab discipline: never trust a mutating call's own response. Every revoke in the lab was confirmed with a second, independent read that came back empty." },
    { id: "sdd-04", type: "compare", question: "How does DELETE /admin/realms/{realm}/sessions/{session} differ from POST /admin/realms/{realm}/users/{user-id}/logout?", options: ["They are identical; both end exactly one session", "DELETE ends one specific session by its own session id; the logout endpoint ends every session belonging to one user at once, regardless of how many devices/sessions that user has", "DELETE only works on offline sessions; logout only works on SSO sessions", "logout requires the session id; DELETE requires the user id"], answerIndex: 1, explanation: "DELETE targets a single session precisely (useful when a user should keep their other sessions). POST .../logout is broader \u2014 it clears every session tied to that user, confirmed live in this chapter against a user with two concurrent sessions." },
    { id: "sdd-05", type: "scenario", question: "Meridian Trust's security team suspects a credential-stuffing breach may have compromised an unknown number of accounts across the entire realm, not just one employee. Which Admin REST API tool is actually designed for this (even though the lab in this chapter didn't run it, as too destructive for a shared lab realm)?", options: ["DELETE /admin/realms/{realm}/sessions/{session}, called once per suspected account", "POST /admin/realms/{realm}/logout-all \u2014 ends every session in the entire realm at once", "GET /admin/realms/{realm}/users/{user-id}/sessions", "Disabling the realm entirely"], answerIndex: 1, explanation: "logout-all is the realm-wide tool for exactly a breach scenario \u2014 a blunt instrument appropriate only when the scope of compromise is genuinely realm-wide, not for routine single-user actions." },
    { id: "sdd-06", type: "scenario", question: "A Northwind Apps support engineer revokes a stolen session via DELETE sessions/{session}, then tries the refresh token that was minted under that same session. What real, observed result should they expect?", options: ["The refresh succeeds normally \u2014 revoking a session doesn't affect its tokens", "A new access token is issued but with reduced scope", "invalid_grant with \"Session not active\" \u2014 the refresh token dies along with the session it belonged to", "The refresh token is automatically converted into an offline token"], answerIndex: 2, explanation: "This is the exact, real error this chapter's lab captured: revoking a session invalidates every token tied to it, confirmed by actually attempting the refresh afterward." },
    { id: "sdd-07", type: "scenario", question: "A Northwind Apps single-page app has two browser tabs open. Revoke Refresh Token is enabled on the realm. Tab A refreshes and rotates to a new refresh token. Tab B, holding the now-stale refresh token, tries to refresh a few seconds later. What happens, and is the user's underlying session affected?", options: ["Tab B's refresh succeeds too \u2014 Keycloak allows a short grace window for stale tokens", "Tab B's refresh fails with \"Maximum allowed refresh token reuse exceeded,\" but the user's underlying SSO session remains alive and fully active", "Tab B's refresh failing also kills the session for Tab A", "Both tabs are logged out immediately as a security precaution"], answerIndex: 1, explanation: "Reuse-detection under Revoke Refresh Token only rejects the specific stale token \u2014 confirmed live in this chapter by checking the session via GET users/{id}/sessions right after the rejection and finding it still active." },
    { id: "sdd-08", type: "concept", question: "Per Keycloak's own Server Administration Guide, what is the relationship between an SSO (user) session and client sessions?", options: ["A client session is created once per realm, shared across every user", "An SSO session is the parent of zero or more client sessions \u2014 one client session per distinct client app the user has logged into during that SSO session", "Client sessions exist independently of any SSO session", "There is exactly one client session per SSO session, no matter how many apps are used"], answerIndex: 1, explanation: "Confirmed by the guide's own wording and reproduced live in this chapter: one SSO session with two different clients attached produced one session object whose clients map listed both client UUIDs." },
    { id: "sdd-09", type: "scenario", question: "A Riverside Health clinician logs into the clinical charting app, then opens a second, separate clinical app in the same browser and the same Keycloak realm. The second app never shows a login screen. What mechanism, precisely, makes this happen?", options: ["Both apps share the same hardcoded password behind the scenes", "The browser caches the password in autofill and submits it silently", "The browser already holds a KEYCLOAK_SESSION cookie set on Keycloak's own domain; the second app's authorization request is checked silently against it, and Keycloak redirects back with a fresh code with no credentials required", "The second app trusts the first app's access token directly, bypassing Keycloak"], answerIndex: 2, explanation: "This is the real SSO-across-clients mechanism this chapter demonstrated with a curl cookie jar: the same browser-held cookie let a second, independent client get an authorization code with zero credentials submitted." },
    { id: "sdd-10", type: "concept", question: "Which cookie, set on Keycloak's own domain, is the concrete mechanism behind SSO working silently across multiple clients in the same realm?", options: ["KEYCLOAK_SESSION", "JSESSIONID", "client_credentials", "access_token_cookie"], answerIndex: 0, explanation: "Observed directly in this chapter's cookie-jar lab: KEYCLOAK_SESSION (plus KC_AUTH_SESSION_HASH) appeared in the cookie jar after the first login and was what made the second client's silent authorization succeed." },
    { id: "sdd-11", type: "bug", question: "A reader reads clientSessionIdleTimeout: 0 on a fresh realm and concludes client sessions for that realm never idle out. What's wrong with that conclusion?", options: ["Nothing \u2014 0 does mean unlimited for this field", "0 specifically means \"inherit the realm's SSO Session Idle value,\" per Keycloak's own documentation \u2014 confirmed live on a fresh realm in this chapter's lab \u2014 not \"no limit\"", "0 means the field is disabled entirely and has no effect on any session", "0 is not a valid value and Keycloak would reject it"], answerIndex: 1, explanation: "The Server Administration Guide states this explicitly for both Client Session Idle and Client Session Max: a value of 0 means the client session simply uses the SSO session's own idle/max value instead." },
    { id: "sdd-12", type: "compare", question: "How does Front-Channel Logout differ from Back-Channel Logout, per Keycloak's own documentation?", options: ["Front-Channel is server-to-server; Back-Channel relies on browser iframes", "Front-Channel relies on the browser rendering hidden iframes per client (and can be blocked by CSP or an early-closed browser tab); Back-Channel is a direct server-to-server request, which the guide recommends as more reliable", "They are two names for the exact same mechanism", "Front-Channel only works for SAML; Back-Channel only works for OIDC"], answerIndex: 1, explanation: "Per the guide: front-channel logout's iframe dependency makes it vulnerable to CSP blocking and early tab closure; back-channel logout is direct server-to-server and explicitly recommended as the more reliable approach." },
    { id: "sdd-13", type: "scenario", question: "Under PCI-DSS, Meridian Trust's compliance team wants a hard cap on how many concurrent sessions any single banking-console user can have, to limit account sharing. Which Keycloak feature, documented (though not exercised live) in this chapter, is built for exactly this?", options: ["SSO Session Max", "The User Session Count Limiter authentication-flow execution", "Revoke Refresh Token", "Client Session Idle"], answerIndex: 1, explanation: "The User Session Count Limiter is an authentication flow step specifically for capping concurrent sessions per realm and/or per client, with a configurable \"deny new\" or \"terminate oldest\" behavior when the cap is hit." },
    { id: "sdd-14", type: "scenario", question: "Meridian Trust configures the User Session Count Limiter with a maximum of 2 sessions per user and the behavior set to \"Terminate oldest session.\" A teller who already has 2 active sessions logs in a third time. What happens?", options: ["The third login is denied outright", "The oldest of the two existing sessions is terminated, and the new (third) login proceeds, leaving the user with 2 active sessions again", "All three sessions are terminated as a security measure", "Nothing \u2014 the limiter only logs a warning but takes no action"], answerIndex: 1, explanation: "\"Terminate oldest session\" specifically kills the oldest session to make room, rather than blocking the new login outright (which is what \"Deny new session\" would do instead)." },
    { id: "sdd-15", type: "concept", question: "What does RP-Initiated Logout actually do, per Keycloak's documented OIDC logout mechanisms?", options: ["It silently polls for session status in the background with no redirect involved", "It is a browser redirect to Keycloak's own logout endpoint \u2014 typically triggered by a user clicking a Log Out link in an application \u2014 after which Keycloak sends logout requests to every client attached to that browser's SSO session", "It only logs the user out of the one application that initiated it, never other clients", "It requires no interaction with Keycloak at all, only the client's own backend"], answerIndex: 1, explanation: "Per the guide: RP-Initiated Logout is browser-redirect-based, starts from an app's own logout link, and results in Keycloak notifying every client attached to that session, not just the initiating one." },
    { id: "sdd-16", type: "scenario", question: "A Northwind Apps admin, asked to prove a revoked session is truly gone for an internal audit, shows only the 204 response from their original DELETE sessions/{session} call as evidence. What is missing from this proof, per this chapter's own lab discipline?", options: ["Nothing is missing \u2014 a 204 is sufficient proof on its own", "A second, independent GET users/{user-id}/sessions call made afterward, showing an empty array \u2014 the only thing that actually confirms the session is gone rather than merely that the delete request was accepted", "The admin needed to also delete the user account entirely", "A screenshot of the Admin Console, since REST API evidence doesn't count for audits"], answerIndex: 1, explanation: "This chapter's entire discipline, and the point of the Meridian Trust case study: never treat a mutating call's own response as proof. Every revoke was confirmed with a separate, later read in this chapter's real lab." }
  ],

  "password-policies-and-mfa": [
    { id: "ppm-01", type: "concept", question: "What is the real separator Keycloak uses to join clauses inside a realm's passwordPolicy string?", options: ["A semicolon ;", "A comma ,", "The literal word \"and\"", "A pipe |"], answerIndex: 2, explanation: "Confirmed by writing length(12) and digits(1) and ... against a live 26.8.2 realm and reading it back unchanged \u2014 not a semicolon, despite that being a common assumption." },
    { id: "ppm-02", type: "bug", question: "A realm has notUsername(undefined) configured. A user sets the password ppm-test-user1A! where ppm-test-user is their exact username. The password is accepted. What explains this?", options: ["notUsername is broken in this Keycloak version", "notUsername only rejects a password that is EXACTLY equal to the username, not one that merely contains it", "notUsername requires a numeric parameter to activate", "The password policy wasn't actually saved"], answerIndex: 1, explanation: "Confirmed directly in this chapter's lab: the substring-containing password was accepted with exit code 0. Catching that pattern requires the separate notContainsUsername policy type." },
    { id: "ppm-03", type: "scenario", question: "Meridian Trust's compliance team wants to block any password that embeds a customer's username anywhere inside it, not just an exact match. Which password policy type is the documented mechanism for that?", options: ["notUsername", "notContainsUsername", "passwordHistory", "forceExpiredPasswordChange"], answerIndex: 1, explanation: "notContainsUsername checks for the username as a substring; notUsername (the one this chapter's realm actually has) only checks exact equality, a real gap this chapter demonstrated." },
    { id: "ppm-04", type: "concept", question: "Which REST field is the master on/off switch for brute-force detection on a realm?", options: ["failureFactor", "bruteForceProtected", "permanentLockout", "bruteForceStrategy"], answerIndex: 1, explanation: "bruteForceProtected must be true for any of the other brute-force fields to have an effect; confirmed false on a fresh realm in this chapter's baseline read." },
    { id: "ppm-05", type: "scenario", question: "Northwind Apps sets failureFactor=5. A customer fails their password 5 times in a row, then immediately types the CORRECT password. What should they see?", options: ["Immediate success, since the password is correct", "The same generic \"Invalid user credentials\" error a wrong password gets", "A distinct \"your account is locked\" message", "A prompt to reset their password"], answerIndex: 1, explanation: "Confirmed directly in this chapter's lab: the correct password during an active lockout returned the identical generic invalid_grant error as a wrong one \u2014 a deliberate anti-enumeration design choice." },
    { id: "ppm-06", type: "bug", question: "An admin sets waitIncrementSeconds=60 on a Northwind realm. 70 seconds after a lockout, they check the attack-detection endpoint and find disabled:false but numFailures still reads 3, not 0. Is something broken?", options: ["Yes, numFailures should always reset when disabled clears", "No \u2014 the wait timer resets disabled/failedLoginNotBefore only; numFailures itself resets only via maxDeltaTimeSeconds elapsing or an explicit admin DELETE on the attack-detection endpoint", "Yes, this means the lockout never actually happened", "No, but it means the account is now permanently locked"], answerIndex: 1, explanation: "Confirmed directly: after waitIncrementSeconds elapsed, this chapter's lab saw disabled flip back to false while numFailures stayed at 3." },
    { id: "ppm-07", type: "compare", question: "What's the real difference between a brute-force lockout expiring on its own (wait timer) versus an admin clearing it via DELETE on the attack-detection endpoint?", options: ["They're identical in effect and timing", "The wait-timer path resets disabled but leaves numFailures nonzero; the admin DELETE path resets everything (numFailures, numTemporaryLockouts, disabled) immediately with no wait", "DELETE only works if permanentLockout=true", "The wait-timer path requires admin approval too"], answerIndex: 1, explanation: "Both paths were exercised for real in this chapter's lab with visibly different resulting states from GET on the same endpoint." },
    { id: "ppm-08", type: "scenario", question: "Riverside Health's clinicians share busy ward terminals and sometimes mistype a password once or twice between patients. The security team wants brute-force protection to stay active without locking out a rushed-but-genuine clinician for long. Which two fields should they tune together?", options: ["otpPolicyDigits and otpPolicyPeriod", "failureFactor and waitIncrementSeconds \u2014 raise the failure threshold a little and keep the wait short", "passwordHistory and notUsername", "maxTemporaryLockouts alone, with failureFactor left at its default"], answerIndex: 1, explanation: "failureFactor sets how many failures are tolerated before any wait at all, and waitIncrementSeconds sets how long that wait is \u2014 the pair this chapter's lab directly manipulated to produce a fast, demonstrable lockout." },
    { id: "ppm-09", type: "concept", question: "Which field distinguishes an automated, rapid-fire failed login from a normal human-paced one?", options: ["quickLoginCheckMilliSeconds", "maxDeltaTimeSeconds", "waitIncrementSeconds", "otpPolicyPeriod"], answerIndex: 0, explanation: "Failures arriving closer together than quickLoginCheckMilliSeconds are treated as a \"quick\" retry, applying minimumQuickLoginWaitSeconds instead of the normal wait math." },
    { id: "ppm-10", type: "scenario", question: "Meridian Trust's fraud team raises a concern before the security team sets failureFactor as low as possible for every customer account. What documented downside justifies that pushback?", options: ["Low failureFactor slows down the Keycloak server itself", "An attacker who already knows real customer usernames can deliberately trigger lockouts as a denial-of-service tactic against legitimate customers", "Low failureFactor disables password policy enforcement", "Low failureFactor is only relevant if OTP is also enabled"], answerIndex: 1, explanation: "Keycloak's own documentation names this exact trade-off: brute-force detection can itself become an attack surface against known usernames." },
    { id: "ppm-11", type: "concept", question: "What is the otpPolicyLookAheadWindow field specifically compensating for?", options: ["Network latency between client and server", "Clock drift between the user's device and the server", "Multiple users sharing one OTP secret", "Password reuse across accounts"], answerIndex: 1, explanation: "TOTP codes are derived from the current time step; a look-ahead/look-behind window tolerates realistic clock skew between device and server, confirmed against this chapter's live realm read." },
    { id: "ppm-12", type: "scenario", question: "Meridian Trust's online banking sends a customer a one-time code as a step-up check (chapter 3's own AAA example). Which realm tab's fields govern that code's digit count, validity period, and hash algorithm?", options: ["Security Defenses", "OTP Policy", "Login", "Tokens/Sessions"], answerIndex: 1, explanation: "otpPolicyDigits, otpPolicyPeriod, and otpPolicyAlgorithm all live under the OTP Policy tab, confirmed by setting and reading them back in this chapter's lab." },
    { id: "ppm-13", type: "bug", question: "An admin changes otpPolicyAlgorithm from HmacSHA1 to HmacSHA256 on a realm where several users already enrolled OTP under the old algorithm. Those users suddenly can't log in with their existing authenticator app. Why?", options: ["This is a Keycloak bug that needs a patch", "The change governs new code generation/validation going forward; it does not retroactively re-derive already-enrolled users' secrets, so existing enrollments can stop validating", "OTP policy changes require a full server restart that wasn't performed", "Those users got brute-force locked instead of an OTP failure"], answerIndex: 1, explanation: "The same \"doesn't retroactively fix existing records\" pattern this chapter also noted for password-hashing-algorithm changes \u2014 existing OTP enrollments need re-enrollment after a policy change like this." },
    { id: "ppm-14", type: "compare", question: "How does passwordHistory(3) differ in effect from forceExpiredPasswordChange?", options: ["They are two names for the same mechanism", "passwordHistory blocks reusing recent passwords; forceExpiredPasswordChange forces a change after N days regardless of reuse \u2014 different risks, and they can be combined", "forceExpiredPasswordChange automatically checks password history too, making passwordHistory redundant", "passwordHistory only works if forceExpiredPasswordChange is also enabled"], answerIndex: 1, explanation: "passwordHistory (tested live in this chapter, rejecting a reused password) and forceExpiredPasswordChange are independent policy types addressing independent risks \u2014 staleness vs. reuse." },
    { id: "ppm-15", type: "scenario", question: "Northwind Apps's product team is comfortable leaving failureFactor at Keycloak's default (30) for its B2B SaaS dashboard, while Meridian Trust's security team insists on a much lower number for online banking. What's the strongest justification for the two organizations landing on different values for the same field?", options: ["Meridian technically runs different software, so Keycloak's default simply doesn't apply to it", "The two organizations have very different impact profiles for a successful account takeover (dashboard access vs. a bank account), so the same generic default isn't automatically right for both", "A lower failureFactor is objectively always safer, so Northwind is simply making a mistake", "failureFactor only matters for realms that also have OTP enabled"], answerIndex: 1, explanation: "This is the same realm-by-realm judgment call chapter 21 already modeled for session timeouts \u2014 a shared default is a starting point, not a one-size-fits-all policy." },
    { id: "ppm-16", type: "scenario", question: "A Riverside Health engineer creates a new patient-portal test user via kcadm with only username, email, and enabled set, sets a valid password, then tries a direct-access-grant login with that correct password \u2014 and gets \"Account is not fully set up\" instead of a token, even though requiredActions is empty. What's the most likely cause?", options: ["The password doesn't actually meet the realm's password policy", "The client lacks directAccessGrantsEnabled", "Keycloak's declarative User Profile requires attributes like firstName/lastName by default, and the new user has neither set", "The realm's bruteForceProtected flag is blocking the login"], answerIndex: 2, explanation: "This chapter's own lab hit exactly this error for exactly this reason, and fixed it by setting firstName/lastName on the test user before retrying." }
  ],

  "identity-brokering": [
    { id: "idb-01", type: "concept", question: "Ben Carter, an Acme Corp engineer, logs into northwind-apps via the broker. What does the federated-identity record Keycloak creates for him actually pair together?", options: ["His northwind-apps password hash with his Acme Corp password hash", "His local northwind-apps user id with northwind-corporate-idp's alias and his external user id/username", "His IP address with his session id", "His client id with his realm id"], answerIndex: 1, explanation: "A federated identity record pairs the local user's id with a specific external IdP's alias and that IdP's own user id/username \u2014 confirmed live via GET users/{id}/federated-identity. It never involves passwords; the broker never sees or stores Ben's real Acme credential." },
    { id: "idb-02", type: "scenario", question: "Acme Corp's IT team disables a departing engineer's account in their own directory. northwind-apps was configured with Sync Mode: import. What happens to that engineer's existing northwind-apps account automatically?", options: ["It is disabled the next time anyone checks", "Nothing automatic happens \u2014 a separate deprovisioning step is needed on the northwind-apps side", "The federated identity record is deleted immediately", "The user's next login attempt is silently redirected to re-register"], answerIndex: 1, explanation: "Brokering with Sync Mode: import only copies attributes at first login and establishes a federated-identity link; it does not continuously synchronize account status. Northwind needs its own deliberate offboarding mechanism for brokered accounts." },
    { id: "idb-03", type: "bug", question: "A developer sets kc_idp_hint=Northwind-Corporate-IDP (wrong case) expecting an immediate redirect to the external IdP, but the realm's ordinary login picker appears instead, with no error. What's the most likely cause?", options: ["The IdP alias is case-sensitive and this hint doesn't match any configured alias, so Keycloak fails open to the picker", "The IdP is disabled in the realm", "standardFlowEnabled is false on the requesting client", "The redirect_uri wasn't registered"], answerIndex: 0, explanation: "An unrecognized kc_idp_hint value \u2014 including a case mismatch against the real alias \u2014 doesn't error. It silently falls back to the ordinary picker page, confirmed directly in this chapter's lab." },
    { id: "idb-04", type: "compare", question: "An Identity Provider's Sync Mode is set to import versus force. What's the real difference in behavior on a user's second and later logins?", options: ["import re-syncs attributes every login; force never updates them again", "import never updates attributes after first login; force updates them from the external IdP on every login where possible", "Both behave identically after the first login", "import only affects roles; force only affects attributes"], answerIndex: 1, explanation: "Per Keycloak's own Server Administration Guide: import does not update user data after the first login, while force updates user data from the identity provider when possible on subsequent logins." },
    { id: "idb-05", type: "scenario", question: "Meridian Trust wants every brokered login from a partner bank's IdP to require an extra OTP step inside Meridian's own realm, on every login, not just the first. Which Identity Provider setting is the right mechanism?", options: ["Trust Email", "Sync Mode", "Post Login Flow", "Hide on Login Page"], answerIndex: 2, explanation: "Post Login Flow runs after every brokered login finishes, not just the first \u2014 the correct mechanism for demanding a step-up factor on top of an external IdP's own authentication every time. First Login Flow only governs the very first login." },
    { id: "idb-06", type: "concept", question: "Which three fields on a Keycloak Identity Provider concretely implement chapter 7's 'trust is configured, not assumed' principle for an OIDC broker?", options: ["clientId, clientSecret, and syncMode", "authorizationUrl/tokenUrl (metadata), jwksUrl+useJwksUrl (signing-key trust), and the registered broker-endpoint redirect URI", "alias, providerId, and enabled", "firstLoginFlow, postLoginFlow, and trustEmail"], answerIndex: 1, explanation: "These three map directly onto chapter 7's metadata / certificates-and-signing-keys / registered-redirect-URI trio \u2014 every one of them had to be set explicitly in this chapter's lab, none inferred." },
    { id: "idb-07", type: "scenario", question: "A brand-new Acme Corp engineer, never before seen by northwind-apps, logs in via the broker for the first time. Which Keycloak flow actually runs, and what determines its outcome?", options: ["The realm's ordinary Browser flow; outcome is always a password reset prompt", "First Broker Login; outcome depends on whether the returned email matches an existing local user with Trust Email enabled", "The Direct Grant flow; outcome is always rejection on a first attempt", "No flow runs \u2014 the user is rejected until an admin pre-creates the account"], answerIndex: 1, explanation: "Since no federated-identity link exists yet, First Broker Login actually runs. It then checks for a matching existing local account (email + Trust Email); finding none for a brand-new engineer, it JIT-provisions a new local user instead." },
    { id: "idb-08", type: "bug", question: "An admin configures an Identity Provider's browser-facing authorizationUrl through one hostname and its backend-facing tokenUrl/userInfoUrl through a different one (e.g. behind a reverse proxy with split internal/external hostnames). The logs show 'Wrong issuer from token.' What's the real cause?", options: ["An expired client secret", "Clock skew between the two Keycloak nodes", "Keycloak's realm issuer is tied to the hostname the browser's original request used, not to whichever hostname a later backend call resolves through \u2014 the two no longer match", "The external IdP's signing key rotated mid-flow"], answerIndex: 2, explanation: "This is a real finding from this chapter's own authoring process: splitting browser-facing and backend-facing hostnames produces exactly this issuer mismatch, because the realm's issuer is pinned at the point of the browser's original request." },
    { id: "idb-09", type: "scenario", question: "Riverside Health wants visiting specialists from a referring hospital to be redirected straight to that hospital's own IdP on every single login to Riverside's realm, with zero per-request parameters from any calling app. Which mechanism fits?", options: ["Every caller must remember to pass kc_idp_hint", "Marking that IdP as the realm's Default Identity Provider", "Setting Sync Mode to force", "Enabling Trust Email"], answerIndex: 1, explanation: "A realm's Default Identity Provider setting redirects every login to that provider automatically, with no caller needing to pass kc_idp_hint at all \u2014 the right fit when the behavior should be unconditional, not per-request." },
    { id: "idb-10", type: "concept", question: "In this chapter's lab, after Ben Carter's brokered login completes, querying GET users/{id}/federated-identity in northwind-apps returns a record. What does that record prove, precisely, that querying northwind-apps's user list alone would not?", options: ["That Ben's password is stored identically in both realms", "That this specific local user is linked to a specific external IdP alias and external user id \u2014 evidence of how the account came to exist, not just that it exists", "That Ben has administrator rights", "That Sync Mode is set to force"], answerIndex: 1, explanation: "The user list alone just shows a local record exists. The federated-identity record is the only artifact proving it originated from a brokered login against northwind-corporate-idp, tied to that IdP's own user id for Ben." },
    { id: "idb-11", type: "compare", question: "Which statement correctly distinguishes identity brokering (this chapter) from identity federation (chapter 32)?", options: ["Brokering delegates one login event to an external IdP that owns the credential; federation reuses an entire existing directory of accounts queried or bound against directly", "They are two names for the exact same mechanism", "Federation always requires JIT provisioning; brokering never does", "Brokering requires LDAP; federation requires OIDC"], answerIndex: 0, explanation: "Chapter 7's distinction, now concrete: brokering trusts an external IdP's assertion for one login at a time (this chapter's northwind-corporate-idp); federation queries/binds against an existing directory the organization already runs (chapter 32's LDAP/AD)." },
    { id: "idb-12", type: "scenario", question: "Northwind's ops team is confused: Ben Carter's northwind-apps account shows a createdTimestamp matching the exact second he first logged in, but nobody on their team ran kcadm.sh create users for him. What actually happened?", options: ["A scheduled nightly sync job silently created it", "First Broker Login just-in-time provisioned it automatically on his first successful brokered login", "This is a bug \u2014 accounts should never appear without an explicit admin action", "An admin created it and forgot"], answerIndex: 1, explanation: "This is JIT provisioning working exactly as designed, confirmed in this chapter's own lab: First Broker Login creates the local account automatically the first time a genuinely new external identity authenticates, with no admin action required." },
    { id: "idb-13", type: "bug", question: "The client registered inside northwind-corporate-idp for the broker to use has its redirect URI registered as .../broker/northwind-corporate-idp (missing the trailing /endpoint segment). At which step does the flow actually fail?", options: ["At the very first authorize call to northwind-apps", "At northwind-corporate-idp's own authorize step, with an invalid-redirect-uri-style rejection, before any login form is shown", "Silently, only at the final token exchange with northwind-dashboard", "It still works \u2014 the trailing segment is optional"], answerIndex: 1, explanation: "The broker-endpoint URI is a fixed, exact convention. A wrong redirect URI registered on the external IdP's own client is rejected at that external IdP's own authorize step \u2014 the user never even reaches a login form." },
    { id: "idb-14", type: "scenario", question: "A second Acme employee, Priya, already has an existing northwind-apps account created manually before brokering existed, using the same email address Acme's directory has on file for her. Trust Email is enabled on the broker. What happens the first time she logs in via the broker?", options: ["A brand-new, separate local user is JIT-provisioned alongside her old account", "Keycloak links her brokered login to her existing local account instead of creating a duplicate", "The login is rejected as a conflict", "Nothing happens until an admin manually merges the accounts"], answerIndex: 1, explanation: "This is the account-linking branch of First Broker Login: a matching email plus Trust Email enabled links the brokered identity to the existing local account rather than creating a duplicate new user." },
    { id: "idb-15", type: "concept", question: "Why isn't the clientSecret configured on northwind-apps's Identity Provider one of chapter 7's three 'trust' ingredients (metadata, certificates/signing keys, registered redirect URIs)?", options: ["It's unnecessary and can always be omitted", "It's a separate OAuth client-authentication mechanism (chapter 13's client credentials) northwind-apps uses to authenticate itself when calling northwind-corporate-idp's token endpoint \u2014 not part of verifying the external IdP's own assertions", "Because SAML brokers never use secrets", "Because it only applies to federation, not brokering"], answerIndex: 1, explanation: "The clientSecret authenticates northwind-apps TO the external IdP (ordinary OAuth client credentials), a different concern from the three trust ingredients that let northwind-apps verify assertions COMING FROM the external IdP." },
    { id: "idb-16", type: "scenario", question: "In this chapter's lab, the final authorization code that gets exchanged for real, usable tokens is issued by which party, and addressed to which client?", options: ["Issued by northwind-corporate-idp, addressed to northwind-apps-broker", "Issued by northwind-apps, addressed to northwind-dashboard", "Issued by northwind-corporate-idp, addressed to northwind-dashboard", "Issued by northwind-apps, addressed to northwind-apps-broker"], answerIndex: 1, explanation: "There are two separate authorization codes in the full sequence: an inner one from northwind-corporate-idp to the broker, consumed server-side; and the final one, issued by northwind-apps itself, addressed to the originally requesting client, northwind-dashboard \u2014 that's the one exchanged for the tokens this chapter decoded." }
  ],

  "user-federation-ldap": [
    { id: "ldp-01", type: "concept", question: "What is the key difference between identity brokering (chapter 31) and identity federation (this chapter), as Keycloak actually implements them?", options: ["Brokering delegates a single login event to an external IdP; federation reuses an existing directory's whole population and, by default, its credential checks too", "They are two names for the same Keycloak feature", "Federation only works with SAML; brokering only works with OIDC", "Brokering requires a custom SPI; federation never does"], answerIndex: 0, explanation: "Chapter 7 drew this line conceptually and chapters 31/32 implement each side: brokering hands off one login event to an external IdP (Northwind Apps' pattern), while federation (Meridian Trust's pattern here) connects to an existing directory and reuses its whole population, with the directory remaining the authoritative credential store." },
    { id: "ldp-02", type: "scenario", question: "Meridian Trust federates Keycloak against its existing staff LDAP directory in READ_ONLY mode. An admin resets a teller's password through the Keycloak Admin Console. What actually happens?", options: ["The write is rejected; the directory's password is unchanged", "The new password is pushed into the LDAP directory immediately", "Keycloak silently stores a local-only override of the password", "The teller's account is automatically disabled"], answerIndex: 0, explanation: "READ_ONLY mode rejects any write Keycloak attempts to make on a federated attribute \u2014 the directory, owned by a separate team, is fully protected from any Keycloak-originated change. WRITABLE would push the change through; UNSYNCED would store a local override instead." },
    { id: "ldp-03", type: "bug", question: "A full LDAP sync for Meridian Trust reports \"5 imported users, 0 failed,\" but every synced user's firstName field actually contains their full name (e.g. \"Julia Martinez\" instead of \"Julia\"). What's the real cause?", options: ["The built-in \"first name\" LDAP mapper is reading the LDAP cn attribute, which this directory uses for the full display name, not a given name alone", "The sync silently failed despite the 0-failed count", "The user's LDAP entry has no givenName attribute at all", "LDAP federation cannot sync first and last names correctly"], answerIndex: 0, explanation: "This is the real bug this chapter's own lab hit: Keycloak's default first-name mapper reads cn, which many directories (including this one) use for a full display name. A 0-failed sync only means the read/write operation succeeded \u2014 it says nothing about whether the configured mapping was the one intended. The fix was repointing the mapper at givenName and re-syncing." },
    { id: "ldp-04", type: "concept", question: "Why does authenticating a federated LDAP user (in the default import/READ_ONLY setup) not involve checking a password stored inside Keycloak's own database?", options: ["Because Keycloak performs a live LDAP bind against the directory at login time, using whatever credential was just supplied \u2014 there is no password field to check locally", "Because Keycloak caches the password the first time it syncs and checks that cache afterward", "Because federated users are not allowed to log in directly", "Because the password is stored encrypted in Keycloak's user table"], answerIndex: 0, explanation: "Sync only copies profile data; it never copies a password. Every authentication attempt for a federated user triggers a real, live LDAP bind operation against the directory itself \u2014 confirmed in this chapter by a successful direct grant with the real password and a rejected one with a wrong password, exactly the behavior a live bind check produces." },
    { id: "ldp-05", type: "scenario", question: "Riverside Health wants clinicians to reset their own passwords through Keycloak's self-service account console, with the change reflected in the hospital's real directory. Which edit mode do they need, and what's the real trade-off?", options: ["WRITABLE \u2014 convenient, but it gives Keycloak's bind credential genuine write authority over the directory of record", "READ_ONLY \u2014 convenient, and it has no trade-offs", "UNSYNCED \u2014 the change reaches the real directory with no risk at all", "Any edit mode works identically for this use case"], answerIndex: 0, explanation: "Only WRITABLE pushes a Keycloak-originated write through to the real directory record. The trade-off is real: it hands Keycloak's bind credential write authority over a system that may have its own change-control and audit requirements, and a Keycloak misconfiguration could now modify real directory data, not just misread it." },
    { id: "ldp-06", type: "bug", question: "A new LDAP User Federation provider's sync completes successfully every time, reports 0 failed, but always imports exactly zero users. What should be checked first?", options: ["Whether the Users DN (or a Custom User LDAP Filter) actually points at where the real user entries live in the tree", "Whether the Keycloak server has enough disk space", "Whether the realm's SSL certificate has expired", "Whether the admin's own password has expired"], answerIndex: 0, explanation: "A sync with a wrong Users DN (or an overly restrictive custom filter) doesn't fail loudly \u2014 it just performs a successful, authenticated search that legitimately finds nothing under the wrong point in the tree. This looks identical to \"the directory has no users\" rather than an error, which is why it's the first thing to check." },
    { id: "ldp-07", type: "compare", question: "An external store speaks LDAP natively, even if it's an unusual product. Per this chapter's reasoning, should a specialist reach for Keycloak's native LDAP federation provider or chapter 33's custom User Storage SPI?", options: ["The native LDAP provider \u2014 it requires zero custom code and is maintained by the Keycloak project itself", "The custom SPI \u2014 it is always more flexible and future-proof", "Neither \u2014 LDAP-speaking stores require migrating all accounts into Keycloak first", "It depends only on which one the vendor recommends"], answerIndex: 0, explanation: "This chapter's entire lab, including finding and fixing a real mapper bug, was done through the Admin REST API with no Java written at all. A custom SPI is code the adopting organization now owns forever across every future Keycloak upgrade \u2014 chapter 33's own case study is deliberately a store with no LDAP interface at all, which is the real bar for reaching for a custom SPI." },
    { id: "ldp-08", type: "scenario", question: "Meridian Trust's directory holds employeeType (job function) and group membership for its staff. After federating and syncing, neither attribute appears on the synced Keycloak users. Why not, and what fixes it?", options: ["Neither has a mapper configured by default; adding a User Attribute LDAP Mapper and a Group LDAP Mapper (then re-syncing) surfaces both", "LDAP federation cannot carry any attribute beyond username, name, and email", "The directory's schema doesn't support employeeType or group membership", "A full re-import (not a sync) is required to pick up any new attribute"], answerIndex: 0, explanation: "Only five mappers exist by default: username, first name, last name, email, and two timestamps. Anything else \u2014 a custom attribute like employeeType, or group membership \u2014 needs its own explicit mapper. This chapter's own lab added exactly these two mappers and re-synced to make both appear." },
    { id: "ldp-09", type: "concept", question: "What specifically does the Admin REST API's testLDAPConnection endpoint's testAuthentication action check, as distinct from its testConnection action?", options: ["Whether the configured Bind DN and Bind Credential can successfully authenticate to the directory, separately from whether the server is reachable at all", "Whether a specific end user's password is correct", "Whether the realm's SSL certificate is valid", "Whether the sync schedule is configured correctly"], answerIndex: 0, explanation: "testConnection checks basic reachability; testAuthentication checks the bind credential specifically. Confirmed live in this chapter: a deliberately wrong bind credential produced a 400 with {\"errorMessage\":\"AuthenticationFailure\"} from testAuthentication, while testConnection with the same connection URL succeeded independently of that credential." },
    { id: "ldp-10", type: "scenario", question: "Northwind Apps (a B2B SaaS company) wants its enterprise customers to log in with their own corporate identity systems. Meridian Trust wants its own employees to log in against its existing staff directory. Which Keycloak feature fits each, and why are they different?", options: ["Northwind needs identity brokering (delegating each customer's login to their own external IdP); Meridian needs user federation (consuming its own already-owned staff directory)", "Both need user federation, configured identically", "Both need identity brokering, configured identically", "Northwind needs federation; Meridian needs brokering \u2014 the reverse of the real fit"], answerIndex: 0, explanation: "Northwind doesn't own its customers' identity systems \u2014 it needs to delegate each login event to whichever external IdP that customer already uses, which is brokering (chapter 31). Meridian already owns and operates its own staff directory and wants to reuse it directly without migrating it, which is federation (this chapter)." },
    { id: "ldp-11", type: "concept", question: "A federated Keycloak user record has a non-empty federationLink field. What does deleting the LDAP User Federation provider do to that user record?", options: ["It orphans the local synced copy as read-only leftover data \u2014 the real account, and the real credential, were never in Keycloak's own store to begin with", "It deletes the real user account from the external LDAP directory", "It automatically migrates the user into Keycloak's own local store", "It has no effect on anything, including the Keycloak user list"], answerIndex: 0, explanation: "A federated user's Keycloak record is a synced profile copy, not a migrated account. Removing the provider doesn't touch the real directory entry; it just leaves the local copy in Keycloak's database disconnected from the source it used to sync from." },
    { id: "ldp-12", type: "bug", question: "While building this chapter's lab, a plain add-only LDIF seed file was mistakenly loaded with ldapmodify instead of ldapadd by the OpenLDAP container, failing with \"modify operation type is missing.\" What caused the misdetection?", options: ["The bootstrap script's add-vs-modify detection is a plain text search for a specific word anywhere in the file, including comments, not a real LDIF parse", "The LDIF file had invalid syntax", "The file had the wrong file extension", "LDIF files without a changetype attribute always default to ldapmodify"], answerIndex: 0, explanation: "An earlier draft's own explanatory comment happened to contain the literal word LDIF uses to mark a modify-style record. The container's bootstrap script just does a text search for that word anywhere in the file to decide which tool to use, so a comment mentioning it was enough to trigger the wrong branch. Rewording the comment fixed it." },
    { id: "ldp-13", type: "scenario", question: "A specialist mounts a host directory containing a seed LDIF directly into an OpenLDAP container's default custom-bootstrap path. The first `docker compose up` seeds correctly, but a later `down -v && up -d` seeds nothing \u2014 and the seed file is now missing from the host. What happened?", options: ["The container's bootstrap step moves (not copies) a successfully-loaded custom LDIF file out of that directory, which \u2014 through the bind mount \u2014 deletes it from the host too", "Docker Compose deleted the volume along with the file", "The LDIF file was corrupted during the first run", "LDAP directories can only be seeded once per Docker image"], answerIndex: 0, explanation: "This is exactly the gotcha this chapter's own build hit. The fix used in this chapter's compose file is the image's LDAP_SEED_INTERNAL_LDIF_PATH mechanism instead, which copies rather than consumes the source files \u2014 confirmed by re-running from a clean reset and finding the host file untouched." },
    { id: "ldp-14", type: "concept", question: "Why does this chapter's lab use a direct-grant (resource owner password credentials) token request, rather than a browser login, to prove an LDAP-sourced user can authenticate?", options: ["It's a legitimate lab-only verification technique (the same one chapters 13/24 used) for confirming a real token round trip without needing a browser \u2014 never a pattern for a real application", "Direct grant is the recommended production pattern for all federated users", "LDAP-sourced users cannot use a browser-based login at all", "It avoids needing a client to exist in the realm"], answerIndex: 0, explanation: "Chapters 13 and 24 already established direct access grants as a deliberate, disposable lab/testing technique \u2014 convenient for confirming a real credential check without a browser, but explicitly not a recommended pattern for any real application, since it trains users to hand credentials directly to a client app." },
    { id: "ldp-15", type: "compare", question: "What's the real difference between a wrong Users DN and a wrong Bind DN/Bind Credential on an LDAP User Federation provider, in terms of how each fails?", options: ["A wrong Bind DN/Credential fails loudly and specifically as an authentication error; a wrong Users DN fails silently as a sync that succeeds but finds nothing", "Both fail identically, with the same error message", "A wrong Users DN always crashes the Keycloak server; a wrong Bind DN never does", "Neither can actually cause a real failure \u2014 both are cosmetic fields"], answerIndex: 0, explanation: "The Bind DN/Credential is checked up front as a precondition for Keycloak talking to the directory at all, so a wrong value is caught immediately and specifically (confirmed live via testLDAPConnection returning an AuthenticationFailure error). The Users DN only controls where an otherwise-successful search looks, so a wrong value just finds nothing, with no error at all." },
    { id: "ldp-16", type: "scenario", question: "Meridian Trust's directory-operations team insists Keycloak must never be able to modify a single record in their LDAP directory, under any circumstances, including by accident. Which LDAP federation edit mode satisfies that requirement, and why not the other two?", options: ["READ_ONLY \u2014 writes are rejected outright; WRITABLE can genuinely modify the real directory, and UNSYNCED (while not touching LDAP either) is a different guarantee aimed at letting Keycloak hold its own override, not a hard \"never touches LDAP\" policy stated the same way", "WRITABLE \u2014 it has built-in safeguards against accidental writes", "UNSYNCED \u2014 it is functionally identical to READ_ONLY in every respect", "Any of the three modes satisfies this requirement equally"], answerIndex: 0, explanation: "READ_ONLY is the only mode where a write attempt is rejected outright by Keycloak itself, which is the strongest guarantee against the directory ever being modified from the Keycloak side \u2014 exactly the fit for Meridian Trust's case study and the mode this chapter's lab used throughout." }
  ],

  "custom-user-storage-spi": [
    { id: "spi-01", type: "concept", question: "A minimal custom User Storage SPI provider is built from two classes. What's the core difference in when each is created?", options: ["A Provider is created once at boot; a Factory is created per transaction", "A Factory is discovered once at boot via ServiceLoader; a Provider is created fresh per Keycloak transaction by that factory", "A Controller and a Repository, both created per HTTP request", "A single class both the admin console and kcadm.sh instantiate independently"], answerIndex: 1, explanation: "The Factory is discovered once, at server boot, via Java's ServiceLoader; its create(session, model) is called fresh for every Keycloak transaction to produce a Provider instance, confirmed directly in chapter 33's own code." },
    { id: "spi-02", type: "concept", question: "Which capability interface does a provider need, beyond UserLookupProvider, so the Admin Console's user-search screen can enumerate the users it holds?", options: ["CredentialInputValidator", "UserQueryMethodsProvider", "UserStorageProviderFactory", "SubjectCredentialManager"], answerIndex: 1, explanation: "Chapter 33's own provider implements only UserLookupProvider and CredentialInputValidator \u2014 confirmed live that its users authenticate correctly but don't show up in an admin username search, which requires UserQueryMethodsProvider instead." },
    { id: "spi-03", type: "scenario", question: "Riverside Health's legacy HR staff directory has no LDAP interface at all and can't realistically be migrated overnight. Which mechanism fits, and why doesn't chapter 32's native LDAP federation provider cover it?", options: ["Chapter 32's native LDAP federation provider, because it can connect to any directory format", "A custom User Storage SPI provider, because the legacy system doesn't speak LDAP and native LDAP federation requires an LDAP-speaking server on the other end", "Migrating every staff account into Keycloak's local store immediately", "Keycloak's built-in Kerberos federation provider"], answerIndex: 1, explanation: "LDAP federation (chapter 32) is configuration-only but requires the external store to actually speak LDAP. Riverside Health's proprietary HR system doesn't, so a custom SPI provider (this chapter) is the fitting bridge instead." },
    { id: "spi-04", type: "scenario", question: "Riverside Health's engineer builds and deploys a new provider JAR, runs kc.sh build, and restarts Keycloak \u2014 but the provider never appears in GET /admin/serverinfo's componentTypes, with no error logged anywhere. What's the most likely cause?", options: ["The provider implements too many capability interfaces", "kc.sh build was run twice in a row", "META-INF/services/org.keycloak.storage.UserStorageProviderFactory is missing, misnamed, or lists the wrong fully qualified class name", "The realm wasn't restarted, only the server"], answerIndex: 2, explanation: "ServiceLoader-based registration fails silently: if the service-registration file is absent or wrong, the provider is simply never discovered, with nothing logged pointing at why." },
    { id: "spi-05", type: "concept", question: "As of Keycloak 26.4+, which Maven module actually contains UserStorageProvider and UserStorageProviderFactory?", options: ["keycloak-server-spi", "keycloak-server-spi-private", "keycloak-model-storage", "keycloak-services"], answerIndex: 2, explanation: "Confirmed in chapter 33 by unzipping both jars directly: these classes moved into keycloak-model-storage and are absent from keycloak-server-spi(-private), for the exact 26.8.2 version this course runs." },
    { id: "spi-06", type: "scenario", question: "Meridian Trust deploys a custom SPI provider whose getAttributes() returns a riskTier attribute for each employee. After deploying it, GET /admin/realms/{realm}/users/{id} shows no attributes key at all. What's the most likely fix, per this chapter's own lab finding?", options: ["Rebuild the JAR against a different Keycloak version", "Implement UserQueryMethodsProvider", "Set the realm's Declarative User Profile unmanagedAttributePolicy (e.g. to ADMIN_VIEW), since an attribute not declared in that schema is silently dropped by default", "Add riskTier to the CSV's header row a second time"], answerIndex: 2, explanation: "Chapter 33 hit exactly this: legacyEmployeeId/department vanished from the REST representation purely because unmanagedAttributePolicy was unset \u2014 fixed with a realm configuration change, with zero code changes." },
    { id: "spi-07", type: "bug", question: "A custom SPI provider's mvn clean package fails with a POM parse error pointing at a comment, before compiling any Java. What's the real cause, confirmed in this chapter's own build?", options: ["A missing closing </project> tag", "Two consecutive hyphens (--) inside the body of an XML comment, which XML comments cannot contain anywhere", "A UTF-8 encoding mismatch in the file", "A missing <dependencies> block"], answerIndex: 1, explanation: "XML comments cannot contain -- anywhere in their body, with no escape mechanism \u2014 chapter 33's own pom.xml hit this twice while documenting a shell command inside a comment." },
    { id: "spi-08", type: "compare", question: "Compare AbstractUserAdapter and AbstractUserAdapterFederatedStorage. Which statement is accurate?", options: ["AbstractUserAdapterFederatedStorage is deprecated and should never be used", "AbstractUserAdapter fits a provider whose own store already holds every field it exposes and is purely read-only from Keycloak's side; AbstractUserAdapterFederatedStorage stores profile fields as attributes in Keycloak's own federated-storage tables, useful when the external store can't hold everything Keycloak needs", "They are two names for the exact same class in different Keycloak versions", "AbstractUserAdapter requires implementing credentialManager() while AbstractUserAdapterFederatedStorage does not"], answerIndex: 1, explanation: "Chapter 33 chose AbstractUserAdapter because the legacy HR system is fully authoritative and read-only from Keycloak's side; AbstractUserAdapterFederatedStorage instead leans on Keycloak's own storage for fields an external store can't supply." },
    { id: "spi-09", type: "scenario", question: "Riverside Health's ops team runs docker compose up before the provider JAR has actually been built. Inside the container, /opt/keycloak/providers/ shows the JAR's name with a leading d (a directory) instead of a dash. What caused this, confirmed live in chapter 33?", options: ["The JAR was corrupted during docker compose build", "The bind-mount source path didn't exist as a file on the host when the container was created, so Docker silently created an empty directory at that path on both host and container", "Keycloak automatically extracts provider JARs into directories", "The compose file used COPY instead of a volume"], answerIndex: 1, explanation: "Confirmed directly in this chapter's lab: the JAR path became a root-owned directory on the host too. Fix: build and confirm a real file exists with ls before bringing the stack up." },
    { id: "spi-10", type: "scenario", question: "Riverside Health's provider component is created successfully (HTTP 201), but a direct-grant login for a user who genuinely exists in the legacy directory still returns user_not_found. The component's parentId was set to the string \"riverside-health\". What's the fix?", options: ["Delete the realm and recreate it from scratch", "Set parentId to the realm's actual UUID id value, not its human-readable realm name", "Add a redirect URI to the admin-cli client", "Increase the access token lifespan"], answerIndex: 1, explanation: "A realm's REST id is a generated UUID distinct from its realm name field. Using the name as parentId creates a silently orphaned component Keycloak's federation machinery never consults \u2014 confirmed live in chapter 33." },
    { id: "spi-11", type: "concept", question: "What must CredentialInputValidator.isValid(RealmModel, UserModel, CredentialInput) check, at minimum, for a password-only provider?", options: ["Only that the user account is enabled", "That the credential type is supported, the user exists in the external store, and the submitted challenge response matches that store's recorded value", "That the realm's SSO session is still active", "That the calling client has the right OAuth scope"], answerIndex: 1, explanation: "Chapter 33's isValid() checks supportsCredentialType, looks up the StaffRecord, and compares input.getChallengeResponse() against the stored value \u2014 all three are necessary." },
    { id: "spi-12", type: "scenario", question: "Northwind Apps considers writing a custom SPI provider for its own customer database instead of migrating that data into Keycloak. Which is a genuine con of that choice, per this chapter's pro/con comparison?", options: ["The customer data would no longer be queryable by Northwind's own systems", "There is no admin-console configuration screen built in automatically the way LDAP federation (chapter 32) provides one, unless Northwind builds its own", "Custom SPI providers cannot authenticate users at all", "Keycloak refuses to support more than one custom SPI provider per realm"], answerIndex: 1, explanation: "Chapter 33's pro/con table names exactly this: LDAP federation ships a rich settings UI; a custom SPI provider has no such screen unless you build one yourself." },
    { id: "spi-13", type: "scenario", question: "A Meridian Trust engineer sees mvn clean package print \"uses or overrides a deprecated API\" for their custom SPI provider, but the build still ends with BUILD SUCCESS. What should they do?", options: ["Ignore it \u2014 a deprecation warning never matters", "Treat the build as failed and block the deploy immediately", "Note it, and before extending the provider further, check the current non-deprecated alternative the warning points at, since deprecated methods can be removed in a future Keycloak version", "Rewrite the entire provider under a different Java package"], answerIndex: 2, explanation: "Chapter 33 hit exactly this warning (AbstractUserAdapter.getAttribute(String) is deprecated), kept the build, and flagged the warning honestly rather than treating it as either a failure or something to ignore outright." },
    { id: "spi-14", type: "concept", question: "Why does this chapter's pom.xml declare keycloak-server-spi and keycloak-model-storage with <scope>provided</scope> rather than the default compile scope?", options: ["provided scope makes the Maven build run faster", "provided scope tells Maven the running server already supplies these exact classes at runtime, so the provider JAR shouldn't bundle them and risk a classloading conflict", "provided scope is required for any dependency over 10MB", "provided scope disables unit tests for that dependency"], answerIndex: 1, explanation: "Confirmed directly: the built JAR contains only this chapter's own 5 classes, a CSV resource, and its service-registration file \u2014 no Keycloak classes, because the server supplies those from its own /opt/keycloak/lib." },
    { id: "spi-15", type: "scenario", question: "Riverside Health later wants administrators to reset a staff member's password from the Admin Console, writing the change back into the legacy HR system. Beyond what this chapter's read-only provider implements, what would the provider need to add?", options: ["Nothing \u2014 AbstractUserAdapter already supports writes by default", "UserQueryMethodsProvider only", "CredentialInputUpdater (to accept new credential values), with the adapter no longer relying on AbstractUserAdapter's default ReadOnlyException behavior for that specific operation", "RoleLookupProvider"], answerIndex: 2, explanation: "This chapter's provider is deliberately read-only: every AbstractUserAdapter write method throws ReadOnlyException by default. Supporting a real write-back would require implementing CredentialInputUpdater and overriding the relevant write path instead of leaving the default in place." },
    { id: "spi-16", type: "concept", question: "What does org.keycloak.storage.StorageId.externalId(id) do, and why does this chapter's getUserById(RealmModel, String) call it?", options: ["It converts an internal UUID into a federated id", "It strips the \"f:<componentId>:\" prefix off a federated user's id, recovering the original external username so the provider can delegate to its own getUserByUsername()", "It validates that the id belongs to the correct realm", "It encrypts the user id before storing it"], answerIndex: 1, explanation: "Keycloak hands federated users an id of the form f:<componentId>:<externalId>; StorageId.externalId() strips that prefix back off, which is exactly what chapter 33's getUserById() uses before delegating to getUserByUsername()." }
  ],

  "securing-a-backend-api": [
    { id: "bak-01", type: "concept", question: "What does spring-boot-starter-oauth2-resource-server configure automatically once an issuer-uri is set, with zero custom code?", options: ["Only password hashing for local users", "JWKS fetching/caching, and signature, issuer, and expiry verification of every incoming bearer token", "A login form and session cookie", "Rate limiting per client IP"], answerIndex: 1, explanation: "This is exactly chapters 8 and 16's bearer-token/JWKS-verification model made concrete: three checks happen automatically, with no app code, once issuer-uri is configured." },
    { id: "bak-02", type: "scenario", question: "Northwind Apps' nightly reconciliation job calls the billing API with no human involved. Which grant type did this chapter's lab use to mint that job's test token?", options: ["Authorization code with PKCE", "Implicit grant", "Client credentials grant", "Device authorization grant"], answerIndex: 2, explanation: "Client credentials is exactly chapter 13/14's pure machine-to-machine grant — no browser, no user, just the client authenticating itself, matching a real unattended job." },
    { id: "bak-03", type: "scenario", question: "A caller presents a token that decodes cleanly, has a valid signature, hasn't expired, and genuinely contains the needed Keycloak role — yet the API returns 403 every time. What's the most likely cause?", options: ["The token has expired", "The issuer claim doesn't match issuer-uri", "Spring Security's default JwtGrantedAuthoritiesConverter is reading a scope/scp claim, not Keycloak's realm_access.roles, so zero authorities were extracted", "The client used the wrong grant type"], answerIndex: 2, explanation: "This is this chapter's central gotcha, reproduced live: a perfectly valid token still gets 403 if nothing ever mapped its real role claim into a Spring Security authority." },
    { id: "bak-04", type: "compare", question: "For testing a resource server, what's a genuine advantage of a direct-grant token over a client-credentials token?", options: ["It never expires", "It doesn't require a Keycloak realm at all", "It carries a real sub/preferred_username, letting a test distinguish between two different human identities and their different roles", "It is always issued with more scopes"], answerIndex: 2, explanation: "Client-credentials tokens represent a client identity, not a human one; direct-grant tokens let this chapter's lab prove billing-reader vs. billing-admin actually behave differently for two distinct real users." },
    { id: "bak-05", type: "scenario", question: "amara.reader holds only the billing-reader role. She sends a POST /api/invoices request with a perfectly valid token. What does this chapter's lab show really happens, and why?", options: ["200, because any authenticated caller can write", "403, because billing-reader satisfies the URL-level GET check but not the method-level @PreAuthorize(\"hasRole('billing-admin')\") guarding the write", "401, because her token has the wrong issuer", "201, because reader implies admin"], answerIndex: 1, explanation: "Confirmed with a real curl call in this chapter's lab: her token is valid and authenticated, but lacks the specific authority @PreAuthorize requires for the write endpoint — a clean 403, not a 401." },
    { id: "bak-06", type: "concept", question: "In a resource server's response codes, what is the precise difference between 401 and 403?", options: ["401 is for GET, 403 is for POST", "401 means authentication failed; 403 means authentication succeeded but authorization was refused", "They are interchangeable synonyms in HTTP", "401 is a Keycloak-specific code, 403 is standard HTTP"], answerIndex: 1, explanation: "This chapter's full endpoint-response table demonstrates both outcomes for real, and the common-mistakes section calls out exactly why conflating them wastes debugging time." },
    { id: "bak-07", type: "scenario", question: "A brand-new Keycloak user, created via kcadm with no explicit required actions assigned, fails every direct-grant token request with \"Account is not fully set up\" — and GET-ing that user's representation shows requiredActions: []. What's going on?", options: ["The password was set as temporary", "The realm's Declarative User Profile requires firstName/lastName, and Keycloak computes a VERIFY_PROFILE check dynamically at login rather than storing it in the user's own requiredActions list", "The client doesn't support direct grant", "The user's email isn't verified"], answerIndex: 1, explanation: "This chapter's lab hit this for real and confirmed the fix empirically: adding firstName/lastName immediately resolved it, with no realm-setting change needed." },
    { id: "bak-08", type: "concept", question: "Why does this chapter's SecurityConfig disable CSRF protection?", options: ["CSRF protection is deprecated in Spring Security 7", "This API is a stateless bearer-token resource server with no session cookie for a forged cross-site request to ride on", "CSRF only matters for GET requests", "Because Keycloak already handles CSRF for every connected app"], answerIndex: 1, explanation: "CSRF defends cookie-authenticated requests specifically; a resource server that never authenticates via a cookie has nothing for it to protect — the chapter is explicit this is not a blanket rule." },
    { id: "bak-09", type: "scenario", question: "Meridian Trust (the bank from chapter 2/9) wants its own fraud-detection service's calls to this kind of billing-style API to be distinguishable in an audit log as 'the service account,' not a named employee. Which grant type's token naturally supports that, and why?", options: ["Direct grant, because it always logs a username", "Client credentials, because the resulting token's subject is the client's own identity rather than any human's", "Device authorization grant", "Implicit grant"], answerIndex: 1, explanation: "A client-credentials token carries no preferred_username at all — exactly the service-account shape this chapter's lab used for the client-credentials test, distinct from a human-bound direct-grant token." },
    { id: "bak-10", type: "concept", question: "What does @EnableMethodSecurity actually do, and what breaks silently without it?", options: ["It enables HTTPS", "It turns on enforcement of method-level annotations like @PreAuthorize; without it, those annotations are present in code but never actually checked", "It enables session-based login", "It is required only for reactive (WebFlux) apps"], answerIndex: 1, explanation: "This chapter's POST /api/invoices endpoint relies on @PreAuthorize to restrict writes to billing-admin — without @EnableMethodSecurity on SecurityConfig, that check would never run." },
    { id: "bak-11", type: "scenario", question: "A reader follows this chapter exactly but runs Keycloak and the billing API on the same machine, and the Spring Boot app fails to start on a port-bind error. What's the most likely mistake?", options: ["Keycloak's image is corrupted", "The reader changed server.port back to 8080, colliding with Keycloak's own published 8080", "Java 21 isn't installed", "Maven failed to download dependencies"], answerIndex: 1, explanation: "This chapter's application.properties ships server.port=8081 specifically because Keycloak already owns 8080/9000 in every lab since chapter 20 — changing it back reintroduces exactly the collision the reader-facing default avoids." },
    { id: "bak-12", type: "scenario", question: "A team wires up their own GrantedAuthoritiesConverter but reads the claim path 'realmAccess.roles' (camelCase, no underscore) instead of 'realm_access.roles'. What's the observable symptom?", options: ["A JSON parse error at startup", "Identical to the unfixed default-converter bug: valid tokens, zero authorities, 403 on every role-protected endpoint", "A 500 Internal Server Error", "The app refuses to start"], answerIndex: 1, explanation: "Keycloak's actual claim is named realm_access (snake_case), confirmed directly in this chapter's own decoded token payload — any other spelling silently finds nothing and reproduces the exact same 403 symptom as not having a custom converter at all." },
    { id: "bak-13", type: "compare", question: "This chapter's billing API enforces GET /api/invoices with hasAnyRole(...) in the filter chain, but POST /api/invoices with @PreAuthorize on the method. What's a genuine reason to prefer method-level enforcement for the write endpoint specifically?", options: ["Method-level checks run faster", "It keeps the authorization rule physically next to the code it protects, which matters more as the number of write-sensitive operations grows beyond what one URL pattern can cleanly express", "Filter-chain rules cannot express role checks at all", "@PreAuthorize is required for every POST endpoint in Spring Security"], answerIndex: 1, explanation: "Both are legitimate, complementary enforcement points — this chapter uses both deliberately to show that neither is strictly superior, but co-locating a sensitive write's rule with its method is a real, common reason to reach for @PreAuthorize." },
    { id: "bak-14", type: "scenario", question: "Northwind's finance team asks 'who actually created invoice 1003?' Which part of a direct-grant-issued JWT would a resource server's controller code read to answer that, per this chapter's own BillingController?", options: ["The jti claim", "The preferred_username (or sub) claim, exactly as this chapter's controller echoes back as requestedBy", "The azp claim alone", "There is no way to know; tokens are anonymous"], answerIndex: 1, explanation: "This chapter's own listInvoices() method reads jwt.getClaimAsString(\"preferred_username\") (falling back to sub) — confirmed live in the lab's real curl output showing requestedBy: \"devon.admin\"." },
    { id: "bak-15", type: "concept", question: "Why did this chapter pin Spring Boot to 4.1.2 instead of the newer-looking 4.2.0-RC2 that Maven Central's metadata also listed?", options: ["4.2.0-RC2 doesn't exist on Maven Central", "An -RC suffix means release candidate, not a final release; 4.1.2 was the newest version without a pre-release qualifier at the time this chapter was written", "4.1.2 is required by Java 21", "Spring Security doesn't support 4.2 yet"], answerIndex: 1, explanation: "This chapter live-verified the distinction directly against repo1.maven.org's maven-metadata.xml rather than assuming the newest-looking version number was the right one to pin." },
    { id: "bak-16", type: "bug", question: "A docker compose override file meant to remap Keycloak's ports to an isolated test port is applied with `-f base.yml -f override.yml`, but the container still fails to start with 'port is already allocated.' What happened?", options: ["The override file has a YAML syntax error", "Compose's default list-merge behavior concatenates the ports list across both files instead of replacing it, so the base file's original port mapping is still present alongside the override", "Docker Compose doesn't support multiple -f flags", "The override file was in the wrong directory"], answerIndex: 1, explanation: "This chapter's own test run hit exactly this and fixed it with the Compose Specification's !override YAML tag on the ports field, which forces a full replace instead of a merge." },
    { id: "bak-17", type: "scenario", question: "Riverside Health (the hospital network from chapter 2) wants a read-only reporting dashboard to call a clinical billing API using the same pattern this chapter teaches, but the dashboard's backend should never be able to create or modify records. Which of this chapter's two enforcement mechanisms most directly expresses that boundary?", options: ["A client-credentials grant alone, with no role check at all", "Assigning the dashboard's service account only a billing-reader-equivalent role, and relying on hasAnyRole/@PreAuthorize checks in the API to reject write attempts even if somehow attempted", "Giving the dashboard admin credentials but trusting it not to misuse them", "Disabling the POST endpoint entirely for every caller"], answerIndex: 1, explanation: "Exactly this chapter's billing-reader vs. billing-admin split: the enforcement lives in the API's own role checks, not in hoping a caller behaves — a reader-scoped token simply cannot satisfy the write endpoint's @PreAuthorize no matter what the caller attempts." },
    { id: "bak-18", type: "concept", question: "A resource server's issuer-uri is configured as http://localhost:8080/realms/northwind-apps, but a token was issued by Keycloak reachable at http://localhost:18134/realms/northwind-apps (same realm, different port). What happens when that token is presented?", options: ["It's accepted, since it's the same realm", "401 — the token's iss claim won't match the configured issuer-uri exactly, including the port, so verification fails even though the realm is genuinely the same one", "403 — it's treated as a valid but under-scoped token", "The resource server automatically detects and corrects the port mismatch"], answerIndex: 1, explanation: "This chapter's own isolated test run had to override issuer-uri to its own port specifically because of this — an issuer mismatch is a 401 (authentication failure), not a softer, forgiving match." }
  ],

  "securing-a-frontend-spa": [
    { id: "spa-01", type: "concept", question: "Why is a browser-based SPA always an OAuth public client, never a confidential one, regardless of how carefully a 'secret' is hidden in its source?", options: ["Because OAuth forbids SPAs from using client secrets by protocol rule", "Because everything shipped to the browser, including build-time environment variables, is readable by anyone who opens devtools", "Because SPAs cannot make HTTPS requests to a token endpoint", "Because Keycloak only issues secrets to backend services, never to any client type"], answerIndex: 1, explanation: "A confidential client's secret only provides security if an attacker genuinely cannot read it; a browser SPA's entire shipped bundle, including anything baked in at build time, is readable by the end user's own browser." },
    { id: "spa-02", type: "scenario", question: "Northwind Apps' frontend team wants to add an OAuth client_secret to their React SPA's build config 'so it's not hardcoded in git.' What should an IAM specialist tell them?", options: ["That's a reasonable fix — environment variables are secure as long as they're not committed", "It doesn't solve the actual problem: a frontend build-time environment variable still ends up as a plain string in the shipped JS bundle, readable by anyone", "They should instead rotate the secret daily to limit exposure", "This is fine as long as the secret is base64-encoded before embedding"], answerIndex: 1, explanation: "Where the secret is written in source control is irrelevant; what matters is that it ends up in code the browser executes, where it is always readable. The fix is a public client with PKCE, not hiding the secret differently." },
    { id: "spa-03", type: "concept", question: "What value does PKCE introduce that lets a public client protect its authorization code exchange without ever holding a durable secret?", options: ["A long-lived API key issued once at client registration", "A code_verifier generated fresh in memory for one login attempt and discarded after the token exchange", "A hardware security module embedded in the browser", "A rotating client_secret refreshed every hour"], answerIndex: 1, explanation: "The code_verifier is created at runtime, used once, and never needs to be embedded in shipped code — unlike a client secret, it isn't a value that has to stay hidden over the client's whole lifetime." },
    { id: "spa-04", type: "bug", question: "A reader's Keycloak client is configured as publicClient: true but the admin console form for it still shows a 'Client secret' field populated with a value. What's the likely explanation?", options: ["Keycloak silently ignores the publicClient setting and issues a secret anyway", "The client was previously confidential and had a secret generated before being switched to public; the field may be stale and should be disregarded for a true public client", "This is required and the secret must still be used in the SPA's requests", "publicClient:true only applies to the direct access grant, not the authorization code flow"], answerIndex: 1, explanation: "A client's publicClient flag controls whether Keycloak expects/validates a secret at the token endpoint. A stale secret value left over from a prior confidential configuration is not meaningful once the client is public and should not be shipped to the SPA." },
    { id: "spa-05", type: "compare", question: "Comparing in-memory token storage against localStorage for a browser SPA, what is the main trade-off?", options: ["In-memory is slower to read than localStorage", "In-memory doesn't survive a page reload (requiring re-authentication), while localStorage persists indefinitely but stays readable by any script on the page, including an XSS bug, for as long as it's stored", "localStorage cannot hold JWT-formatted tokens", "There is no real trade-off; in-memory is strictly better in every case"], answerIndex: 1, explanation: "This is a genuine usability-vs-exposure trade-off: in-memory minimizes how long a stolen token stays useful but costs session persistence across reloads; localStorage keeps the user logged in longer at the cost of a longer-lived, script-readable copy of the token." },
    { id: "spa-06", type: "scenario", question: "Riverside Health's security review flagged localStorage specifically because of a compromised third-party analytics script scenario. What about that scenario makes in-memory storage the safer choice for their patient portal?", options: ["In-memory storage encrypts tokens automatically", "A compromised script running on the page can read localStorage directly just as easily as an attacker's own injected script could; an in-memory token is only exposed while that script and the page are both still running, not indefinitely", "localStorage tokens expire faster than in-memory ones", "Analytics scripts cannot execute JavaScript, only send network requests"], answerIndex: 1, explanation: "Any script running in the page's JS context — whether maliciously injected or a compromised legitimate third-party script — has the same read access to localStorage as the app's own code. In-memory storage limits how long a token remains available to be read at all." },
    { id: "spa-07", type: "concept", question: "What does the backend-for-frontend (BFF) pattern change about where an OAuth access token physically lives?", options: ["It encrypts the token before storing it in localStorage", "It moves the token off the browser entirely — a server-side component holds it, and the browser holds only a session cookie", "It stores the token in a browser extension instead of the page", "It splits the token into two halves stored in separate browser APIs"], answerIndex: 1, explanation: "In a BFF architecture, the SPA never receives the access token at all; a server-side component obtains and holds it, and the browser authenticates to that server via a session cookie instead." },
    { id: "spa-08", type: "scenario", question: "Meridian Trust is deciding whether its SPA-direct mobile banking web app should become a BFF. What does that change actually buy them, and what does it cost?", options: ["It eliminates all security risk with no added cost", "It removes the token entirely from the browser's JS context (so an XSS bug has nothing to steal there), at the cost of building and operating an additional server-side component", "It makes login faster by skipping the authorization code exchange", "It allows the app to skip PKCE entirely since the BFF handles authentication"], answerIndex: 1, explanation: "A BFF doesn't eliminate risk — it relocates it to a server-side session store that now needs its own protections (CSRF defenses, secure cookies, session fixation defenses) — but it does remove the specific 'which browser storage API' exposure this chapter spends a full slide on." },
    { id: "spa-09", type: "bug", question: "A SPA's login session randomly expires in Safari after working fine in Chrome for the same user. Using this chapter's reasoning, what's the most likely cause?", options: ["Safari doesn't support the authorization code grant", "Iframe-based silent renewal (prompt=none) depends on third-party cookie behavior that Safari's Intelligent Tracking Prevention restricts more aggressively than Chromium browsers", "Safari caps access token lifetimes to one minute regardless of server configuration", "Safari blocks all redirects to non-HTTPS origins, breaking the flow"], answerIndex: 1, explanation: "Iframe-based silent renewal relies on an existing session cookie being sent inside a hidden, cross-site iframe. Safari's ITP restricts exactly that third-party cookie behavior, which can cause the silent renewal attempt to fail without a clear error — a known, browser-specific failure mode refresh-token-based renewal doesn't share." },
    { id: "spa-10", type: "concept", question: "Why does refresh-token-based silent renewal avoid the failure mode that affects iframe-based silent renewal?", options: ["Refresh tokens never expire", "The SPA's own JavaScript POSTs the refresh token directly to the token endpoint — a same-origin-initiated request, not one routed through a third-party browser context subject to third-party cookie restrictions", "Refresh tokens are stored in a browser extension immune to cookie policy", "It uses a completely different, non-OAuth protocol"], answerIndex: 1, explanation: "Refresh-token renewal is a direct POST from the app's own code to the token endpoint, which doesn't depend on a hidden cross-site iframe or the session cookie being sent in that third-party context the way prompt=none renewal does." },
    { id: "spa-11", type: "scenario", question: "Northwind Apps registers their SPA's Keycloak client with Valid Redirect URIs set to a bare '*' wildcard 'to stop fighting with the dev server's changing port.' What's the concrete risk, and what's the fix?", options: ["There is no real risk; wildcards are the recommended Keycloak default", "A bare wildcard accepts any redirect_uri at all, which (as chapter 13 demonstrated live on a different server) lets an attacker redirect a real user's authorization code to a destination they control; the fix is a path-scoped pattern like http://localhost:5173/*", "The fix is to disable PKCE instead, since wildcards only matter for confidential clients", "Wildcards only affect the logout endpoint, not login, so there's no authentication risk"], answerIndex: 1, explanation: "Keycloak explicitly documents the bare wildcard as a production anti-pattern. A path-scoped wildcard gets the same dev-server convenience without accepting literally any redirect destination." },
    { id: "spa-12", type: "bug", question: "This chapter's lab found that submitting a redirect_uri of https://evil.example.com/callback against a correctly configured Keycloak client returned an immediate HTTP 400 with no redirect at all. What does this demonstrate, and how does it contrast with chapter 13's finding?", options: ["It demonstrates a Keycloak bug that should be reported upstream", "It demonstrates RFC 6749 §3.1.2.4's 'MUST NOT redirect on mismatch' requirement being correctly enforced — directly contrasting with chapter 13's finding that a public demo OAuth server did redirect to an attacker-supplied, unregistered URI", "It demonstrates that Keycloak doesn't support the authorization code grant for public clients", "It demonstrates that PKCE alone is sufficient without any redirect_uri validation"], answerIndex: 1, explanation: "RFC 6749 requires refusing to redirect at all on a redirect_uri mismatch. This local Keycloak enforces that correctly, in direct, honest contrast with chapter 13's live finding that one public demo server did not." },
    { id: "spa-13", type: "compare", question: "This chapter's lab found Keycloak returns a distinct error_description for a wrong PKCE verifier vs. a missing one, while chapter 13's Duende demo server returned the identical generic invalid_grant for every PKCE failure cause. What's the real trade-off between these two behaviors?", options: ["Keycloak's behavior is simply a bug with no trade-off", "A specific error helps a legitimate developer debug faster, but could in principle give an attacker probing a forged request slightly more feedback than a fully generic error would — both are defensible choices depending on which cost matters more to a given deployment", "There is no meaningful difference between the two servers' behavior", "Generic errors are always correct and specific errors are always a security flaw"], answerIndex: 1, explanation: "Chapter 13 reasoned that a specific error can function as an oracle for an attacker. Whether that risk outweighs the debugging benefit is a judgment call, not an absolute rule — both of these two real servers' approaches are defensible, and the chapter reports this honestly rather than declaring a winner." },
    { id: "spa-14", type: "concept", question: "What is the practical effect of setting pkce.code.challenge.method to S256 on a Keycloak client?", options: ["It disables the authorization code grant entirely for that client", "It forces the client to use the plain PKCE method instead of S256", "It requires the client to present a code_verifier matching a SHA-256-derived code_challenge at the token endpoint before any code for that client can be exchanged — without it, the exchange fails even with an otherwise valid code", "It only takes effect for confidential clients, not public ones"], answerIndex: 2, explanation: "This chapter's lab verified directly: a fresh, otherwise-valid authorization code failed the token exchange with a specific 'PKCE code verifier not specified' error when no verifier was supplied at all, confirming PKCE is actually enforced server-side, not merely advisory." },
    { id: "spa-15", type: "scenario", question: "This development machine runs Node 18.20.4. The current Vite major requires Node 20.19+/22.12+. What is the correct way to resolve this, following this chapter's own approach?", options: ["Assume the newest Vite major one version back will work without checking", "Check each candidate major's actual `engines` field via `npm view vite@<version> engines` until finding the newest major that genuinely declares Node-18 support, then verify the matching plugin-react version supports both that Vite major and this Node version before scaffolding anything", "Upgrade the OS's Node installation without checking whether anything else on the machine depends on Node 18", "Ignore the engines field entirely since npm rarely enforces it strictly"], answerIndex: 1, explanation: "This chapter's lab did exactly this: checked vite@7.0.0 (still required Node 20.19+), then vite@6.3.5/6.0.0/5.4.11 (all Node-18-compatible), then separately confirmed @vitejs/plugin-react's current 4.x release supports both Vite 6 and Node 18 — verifying the full chain rather than guessing at any step." },
    { id: "spa-16", type: "bug", question: "A reader's React app renders `auth.isAuthenticated === true` but `auth.user` is briefly `undefined` right after being redirected back from Keycloak, causing a crash reading `auth.user.profile`. What's the likely cause and fix?", options: ["react-oidc-context has a bug that cannot be worked around", "The component is reading auth state before onSigninCallback has finished processing the redirect's ?code=...&state=... query string; guarding rendering on auth.isLoading first (checking it before isAuthenticated) avoids reading incomplete state", "This only happens when PKCE is misconfigured", "The fix is to disable StrictMode, which is unrelated to this behavior"], answerIndex: 1, explanation: "This lab's own App.jsx guards on auth.isLoading before checking isAuthenticated, exactly to avoid rendering a view that assumes auth.user is already populated during the brief window right after the redirect completes." }
  ],

  "service-to-service-auth": [
    { id: "m2m-01", type: "concept", question: "What does enabling \"Service accounts enabled\" on a Keycloak client actually create?", options: ["A new realm", "A dedicated, real user record for that client, named service-account-<clientId>", "A new client scope automatically attached to every other client", "A password credential on the client itself"], answerIndex: 1, explanation: "Confirmed live in this chapter's lab: enabling a client's service account creates a genuine user record (service-account-fraud-detection-service) with its own real internal user id, indistinguishable in shape from a human user's record." },
    { id: "m2m-02", type: "concept", question: "Which OAuth 2.0 grant does a Keycloak service account use to obtain an access token?", options: ["Authorization code", "Resource Owner Password Credentials", "Client credentials", "Device authorization"], answerIndex: 2, explanation: "Chapter 13's client credentials grant (RFC 6749 §4.4) is exactly the mechanism a service account uses: the client authenticates directly to the token endpoint with its own client_id/client_secret, no user or browser involved." },
    { id: "m2m-03", type: "scenario", question: "Meridian Trust's fraud-detection service only ever needs to read account/user data to score risk overnight. Which realm-management client role fits its actual job with the least standing access?", options: ["manage-users", "view-users", "manage-realm", "impersonation"], answerIndex: 1, explanation: "view-users is the narrow, read-only role that matches exactly what a read-only scoring service needs — confirmed in this chapter's lab to successfully read user data while a write attempt with the same token failed with a real 403." },
    { id: "m2m-04", type: "scenario", question: "A new Keycloak service account has a confirmed-correct view-users role mapping, yet GET /admin/realms/.../users with its token returns a flat 401 Unauthorized. What's the most likely cause?", options: ["The role mapping actually failed silently and needs to be redone", "The client's token is missing the kc-admin-api client scope, a separate, earlier check that runs before role mappings are even consulted", "The client secret has expired", "view-users doesn't grant read access to users at all"], answerIndex: 1, explanation: "This is exactly the real finding this chapter's own lab hit: a correct role mapping doesn't help if the token never clears the earlier, scope-gated kc-admin-api check — that failure surfaces as 401, not 403." },
    { id: "m2m-05", type: "scenario", question: "After adding the kc-admin-api scope, the same service account's token now succeeds on GET /admin/realms/.../users but gets a 403 Forbidden on POST /admin/realms/.../users (creating a user). What does the 403 (rather than another 401) confirm?", options: ["The token is invalid", "The token is authenticated and scoped correctly, but its role mappings simply don't cover this write operation", "The realm itself is disabled", "kc-admin-api scope was lost between requests"], answerIndex: 1, explanation: "A 403 means the token already cleared the scope-gated authentication check; it's rejected purely because view-users doesn't include manage-users, confirmed directly in this chapter's lab as a clean authorization failure, not an authentication one." },
    { id: "m2m-06", type: "compare", question: "For a read-only M2M caller, what's the real trade-off between granting view-users versus manage-users on its service account?", options: ["There is no real difference; both behave identically for a read-only caller", "view-users limits a leaked credential's blast radius to read access only; manage-users exposes full create/modify/delete capability even though the caller never intentionally uses it", "manage-users is required for any token request to succeed at all", "view-users requires a client secret while manage-users does not"], answerIndex: 1, explanation: "The caller's own intent doesn't protect anything once a credential leaks — only the actually-granted role does. view-users caps the damage at read access; manage-users doesn't, even if the write capability was never meant to be used." },
    { id: "m2m-07", type: "bug", question: "A teammate runs kcadm.sh add-roles to map view-users onto a service account's user, sees no error, and assumes the mapping is in place. What should they do before trusting that?", options: ["Nothing further — a silent exit with no error always means success", "Restart the Keycloak server to apply the change", "Run a separate GET against that user id's own role-mappings endpoint to confirm the mapping actually took, since add-roles succeeds silently either way", "Re-run add-roles a second time to be sure"], answerIndex: 2, explanation: "add-roles (like most kcadm.sh write subcommands) succeeds silently on the happy path — confirming the result requires a separate read, exactly what this chapter's lab did against users/{id}/role-mappings/clients/{id} before trusting the mapping." },
    { id: "m2m-08", type: "concept", question: "This chapter's lab mapped only view-users onto a service account, yet the resulting token's resource_access.realm-management.roles array also listed query-users and query-groups. Why?", options: ["Keycloak grants every service account those two roles automatically regardless of what's mapped", "view-users is a composite role that bundles query-users and query-groups, which appear in the token automatically once the composite is mapped", "This was a misconfiguration that should be fixed", "query-users and query-groups are realm roles, unrelated to view-users"], answerIndex: 1, explanation: "view-users's own representation shows \"composite\": true — assigning a composite role automatically grants (and surfaces in the token) every role it's associated with, the same mechanic chapter 23 introduced for human users." },
    { id: "m2m-09", type: "bug", question: "A client's service account is granted manage-users \"to save time, in case a future feature needs write access.\" What's wrong with this reasoning from a least-privilege standpoint?", options: ["Nothing — pre-granting access for future features is good planning", "It increases the blast radius of a credential leak today for a capability the service doesn't actually use yet, with no corresponding benefit until that future feature is real", "manage-users doesn't actually grant any additional capability over view-users", "Future-proofing roles is impossible in Keycloak, so this wouldn't work anyway"], answerIndex: 1, explanation: "Least privilege is about the access a credential holds right now, not hypothetical future convenience — an unused manage-users grant only adds risk today, exactly the over-provisioning Meridian Trust's case study corrects." },
    { id: "m2m-10", type: "scenario", question: "Riverside Health runs a nightly job that provisions new patient portal accounts from an intake system, meaning it must create new user records in Keycloak. Would scoping its service account to view-users alone be sufficient?", options: ["Yes, view-users covers both reading and creating user records", "No — view-users is read-only; creating users requires manage-users, a genuinely broader grant this job's actual purpose justifies", "No service account can ever create users, regardless of role", "Yes, because any realm role automatically includes manage-users"], answerIndex: 1, explanation: "Unlike Meridian Trust's read-only fraud-detection service, this job's legitimate purpose actually requires write access — manage-users is the correct, justified grant here, illustrating that least privilege means matching the role to the real job, not always picking the narrowest option regardless of need." },
    { id: "m2m-11", type: "concept", question: "What naming convention does Keycloak use for the dedicated user record it creates behind a service account?", options: ["A random UUID with no readable username", "service-account-<clientId>", "svc_<realm>_<clientId>", "The client's own clientId, unchanged"], answerIndex: 1, explanation: "Confirmed live in this chapter's lab: enabling service accounts on a client named fraud-detection-service produced a real user with username service-account-fraud-detection-service." },
    { id: "m2m-12", type: "scenario", question: "Northwind Apps wants a billing-reconciliation service that only ever reads client/application configuration data, never user records. Would mapping its service account to realm-management's view-users role satisfy least privilege for this job?", options: ["Yes, view-users covers all read-only admin operations regardless of resource type", "No — view-users only covers user data; a job that only touches client/application data should be scoped to a role like view-clients instead, not a broader or mismatched one", "No service account can ever be scoped by resource type", "Yes, because all realm-management roles grant identical access"], answerIndex: 1, explanation: "realm-management's roles are independently grantable per resource type (users, clients, realm settings, and so on) — picking view-users for a job that never touches user data is a mismatched grant, not a least-privilege one, even though it sounds appropriately 'narrow.'" },
    { id: "m2m-13", type: "compare", question: "What's the real difference between master realm's built-in admin-cli client and the custom fraud-detection-service client this chapter built, with respect to calling the Admin REST API?", options: ["There is no difference; both behave identically out of the box", "admin-cli ships with the kc-admin-api client scope by default, so its tokens clear the Admin REST API's authentication gate automatically; a custom client has to be wired up for that scope deliberately", "admin-cli cannot call the Admin REST API at all", "fraud-detection-service has broader access than admin-cli by default"], answerIndex: 1, explanation: "Confirmed live: admin-cli's token decoded with scope: \"email kc-admin-api profile\" with no manual configuration, which is exactly why this chapter's custom client needed that scope added explicitly before its own tokens could clear the same gate." },
    { id: "m2m-14", type: "bug", question: "A developer tries to grant a service account the view-users role with a bare kcadm.sh add-roles --rolename view-users call, with no client specified, and it fails to find the role. What's the likely mistake?", options: ["view-users doesn't exist in this Keycloak version", "view-users is a client role on realm-management, not a realm role — the call needs --cclientid realm-management to locate it in that client's own role namespace", "The service account doesn't exist yet", "add-roles only works for realm roles, never for any kind of role mapping"], answerIndex: 1, explanation: "Client roles live in their owning client's own namespace, separate from realm roles — chapter 24 already established this distinction. Omitting --cclientid realm-management means kcadm.sh is looking for a same-named realm role that doesn't exist." },
    { id: "m2m-15", type: "scenario", question: "A security review at Meridian Trust flags that the fraud-detection service's client secret, if leaked, could be used indefinitely until manually rotated. Scoping the service account to view-users instead of manage-users doesn't fix the leak itself — what does it actually mitigate?", options: ["It prevents the secret from ever being leaked in the first place", "It shrinks the blast radius: the same leaked credential now only grants read access, not the ability to create, modify, or delete users, regardless of how long the leak goes unnoticed", "It automatically rotates the secret on a schedule", "It has no real security benefit until the secret is rotated"], answerIndex: 1, explanation: "Least-privilege scoping doesn't prevent a leak — it limits what a successful leak can actually do, exactly chapter 9's blast-radius reasoning applied to a service account's role mapping rather than to token lifetime." },
    { id: "m2m-16", type: "scenario", question: "A second Meridian Trust service account has the kc-admin-api scope correctly configured but was never given any realm-management role mapping at all. What happens when it calls GET /admin/realms/.../users?", options: ["200 OK, because any authenticated token can read users by default", "401 Unauthorized, identical to a token missing the kc-admin-api scope", "403 Forbidden — the token is authenticated and scoped correctly, but carries zero permissions to act on", "The request hangs indefinitely"], answerIndex: 2, explanation: "Confirmed directly in this chapter's lab with a second, no-role-mappings client: a token that clears the scope-gated authentication check but carries no realm-management roles is cleanly rejected with 403, not 401 — recognized, but granted nothing." }
  ],

  "keycloak-authorization-services": [
    { id: "kas-01", type: "scenario", question: "Northwind Apps wants a customer's user to be able to share one specific document with one specific colleague, without a Northwind admin pre-assigning anything. Why doesn't a static realm role like document-viewer solve this?", options: ["Realm roles can only be assigned to groups, never individual users", "A role is pre-assigned and resource-independent — it can't express \"this one person, for this one document, decided by the document's own owner at runtime\"", "Keycloak doesn't support realm roles for SaaS applications", "Document sharing requires SAML, not OpenID Connect"], answerIndex: 1, explanation: "Roles are assigned in advance and apply uniformly, independent of any specific resource. UMA-style, per-resource delegation — decided by the resource owner, at runtime — is exactly what a static role can't express, which is why Northwind's case needs Authorization Services' resource/scope/policy/permission model instead." },
    { id: "kas-02", type: "scenario", question: "In this chapter's lab, amara.diallo (holding the northwind-editor role) and sam.chen (not holding it) both exchange a permission ticket for the same resource and scope, against the same role-based permission. What are the two outcomes?", options: ["Both succeed, since UMA tickets bypass role checks entirely", "Amara gets a 200 with a real RPT; sam gets a 403 access_denied", "Both are denied, since UMA requires owner-managed access to be enabled", "Amara gets a 403; sam gets a 200, since UMA inverts normal role logic"], answerIndex: 1, explanation: "The permission's role policy votes PERMIT only for subjects holding northwind-editor. Amara holds it and gets a genuine 200 OK with a real Requesting Party Token; sam.chen doesn't hold it and gets a genuine 403 Forbidden — both outcomes were confirmed live with real HTTP responses in this chapter's lab." },
    { id: "kas-03", type: "bug", question: "A scope-based permission creation call fails with \"Scope [view] is not associated with any of the resources set to the permission [invalid_request]\", even though both the resource and the scope were each created successfully beforehand. What's actually missing?", options: ["The scope needs to be created again with a different name", "The resource's own scopes array never listed that scope — creating a resource and a scope separately doesn't implicitly link them", "The client needs serviceAccountsEnabled turned on first", "The realm needs a second resource server configured"], answerIndex: 1, explanation: "This is a real error this chapter's lab hit on its first attempt. A scope-based permission references a resource+scope pair that must already exist on the resource itself — fixed by updating the resource's scopes array to include the scope before retrying the permission creation." },
    { id: "kas-04", type: "compare", question: "How does an OAuth scope (chapters 13, 24) differ from a Keycloak authorization scope (this chapter), despite both being called \"scope\"?", options: ["They are the same mechanism; Keycloak just renamed it for marketing reasons", "An OAuth scope is negotiated when a token is requested, limiting what the token carries up front; an authorization scope is attached to a resource and evaluated by policy at decision time, after the token already exists", "An OAuth scope only applies to SAML; an authorization scope only applies to OIDC", "An authorization scope can only be used with public clients, never confidential ones"], answerIndex: 1, explanation: "OAuth scopes (implemented in Keycloak as client scopes) shape a token's claims/audience at request time, before any specific resource is involved. Authorization scopes name an action on a specific resource and are evaluated by policy at access-decision time — a genuinely different, unrelated mechanism that happens to share the word \"scope.\"" },
    { id: "kas-05", type: "scenario", question: "A permission references a role policy (which sam.chen fails) and a trivially-true client policy (which sam.chen passes), both under decisionStrategy UNANIMOUS. The strategy is then changed to AFFIRMATIVE with no other change. What happens to sam.chen's identical request?", options: ["No change — decision strategy only affects permissions with a single policy", "It flips from 403 Forbidden to 200 OK, because Affirmative only needs one policy to vote PERMIT", "It flips from 200 OK to 403 Forbidden", "The permission becomes invalid and must be recreated"], answerIndex: 1, explanation: "This exact experiment was run live in this chapter's lab. Under Unanimous, the role policy's DENY sinks the whole permission (403). Under Affirmative, the client policy's PERMIT alone is enough, flipping the identical request to 200 OK — with zero change to sam.chen's actual role membership." },
    { id: "kas-06", type: "concept", question: "What is the defining two-step shape of the UMA 2.0 grant, as run live in this chapter's lab?", options: ["A single token-endpoint call that returns an RPT directly, with no prior rejection", "An initial rejection that carries a permission ticket (naming the resource+scope involved), followed by a separate exchange of that ticket for a Requesting Party Token at the token endpoint", "A SAML redirect followed by a browser-based consent screen", "A client-credentials grant followed immediately by a refresh-token grant"], answerIndex: 1, explanation: "UMA 2.0 never collects an unauthenticated resource request and a valid identity in one step. The resource server first obtains a permission ticket naming the specific resource/scope; only a separate exchange — presenting that ticket plus the requesting party's own access token — can turn it into a real RPT." },
    { id: "kas-07", type: "scenario", question: "After amara.diallo successfully redeems a permission ticket for an RPT, a developer tries to reuse that exact same ticket for sam.chen's request a minute later, instead of requesting a fresh one. What does this chapter's lab do instead, and why?", options: ["Reuses the same ticket for both users, since tickets are reusable by design", "Always requests a fresh ticket per exchange, since permission tickets are meant to be redeemed once per request, not shared across different requesting parties", "Only reuses a ticket if both users share the same role", "Tickets can only be reused after the original requester's RPT expires"], answerIndex: 1, explanation: "This chapter's lab deliberately requested a fresh ticket from the Protection API before each separate exchange, treating tickets as single-use per pending request rather than a reusable credential — the same resource and scope can get a new ticket instantly, but the ticket itself isn't meant to be shared across different requesting parties." },
    { id: "kas-08", type: "bug", question: "A denied UMA ticket exchange in this chapter's lab returned 403 with {\"error\":\"access_denied\",\"error_description\":\"request_submitted\"}, even though the resource was not owner-managed and nothing was actually pending for anyone to approve. What should an application's error handling rely on instead of that description text?", options: ["Nothing — the description text is a stable, documented API contract and safe to branch on", "The HTTP status code and the error field (access_denied) — the description string's exact wording isn't a documented, stable contract to build logic against", "The response's Content-Length header", "Whether the resource's ownerManagedAccess flag happens to be true"], answerIndex: 1, explanation: "This chapter's lab found the error_description surprisingly reads \"request_submitted\" even when nothing was genuinely submitted anywhere for approval. Rather than over-interpreting that specific text, application logic should key off the 403 status and the access_denied error code, which are the stable, documented parts of the response." },
    { id: "kas-09", type: "scenario", question: "A reader following an older Keycloak tutorial tries to create a JavaScript (\"script\") authorization policy on a live Keycloak 26.8.2 instance by calling the documented .../policy/js REST endpoint. What actually happens, confirmed live in this chapter's lab?", options: ["It succeeds, but the policy is silently disabled until a feature flag is set", "It returns a 403 Forbidden, since script policies require a separate license", "It returns a flat 404 Resource not found — the endpoint itself doesn't exist in this version, and the live policy-provider list never lists a js/script type either", "It succeeds and creates a role policy instead, silently substituting types"], answerIndex: 2, explanation: "This chapter's lab tested this directly rather than assuming: POST to .../authz/resource-server/policy/js returned \"Resource not found for url,\" a plain 404 — confirming script policies are fully removed from the REST API surface in 26.8.2, not merely deprecated or hidden behind a console toggle." },
    { id: "kas-10", type: "scenario", question: "A developer, after seeing that decisionStrategy=AFFIRMATIVE made their test pass more easily during debugging, considers leaving the permission set to AFFIRMATIVE in production with two policies attached. What's the risk this chapter's own lab specifically warns against?", options: ["AFFIRMATIVE permissions run slower than UNANIMOUS ones in production", "Any single referenced policy voting PERMIT becomes sufficient, quietly weakening every other policy attached to that permission down to \"optional\"", "AFFIRMATIVE permissions cannot be evaluated by the Policy evaluate tool", "AFFIRMATIVE is not a valid decisionStrategy value outside of testing"], answerIndex: 1, explanation: "This chapter's lab demonstrated exactly this risk: once AFFIRMATIVE let a trivially-true client policy carry a request on its own, the genuinely important role policy became effectively optional. The lab explicitly reverted back to UNANIMOUS with a single necessary policy as the real least-privilege baseline before finishing." },
    { id: "kas-11", type: "compare", question: "A permission references two policies that vote PERMIT and DENY respectively. How do Unanimous, Affirmative, and Consensus decision strategies each resolve that pair?", options: ["Unanimous: PERMIT. Affirmative: DENY. Consensus: PERMIT", "Unanimous: DENY (not all voted PERMIT). Affirmative: PERMIT (at least one did). Consensus: DENY (a 1-1 tie denies)", "All three strategies always produce the same result regardless of the vote pattern", "Unanimous and Consensus always agree; only Affirmative can differ"], answerIndex: 1, explanation: "Unanimous requires every policy to vote PERMIT, so one DENY fails it. Affirmative only needs one PERMIT vote, so it passes. Consensus counts votes by majority; a one-to-one tie is treated as a DENY. This is exactly the comparison this chapter's own decision-strategy figure and live lab demonstration walk through." },
    { id: "kas-12", type: "concept", question: "What does a Requesting Party Token's authorization.permissions claim actually contain, as decoded in this chapter's lab?", options: ["A list of every resource and scope that exist anywhere in the realm", "The specific resource id(s) and scope name(s) this exact subject was just granted by the UMA exchange that produced this token", "The requesting party's full role-mapping history", "A cached copy of every permission ticket ever issued to this client"], answerIndex: 1, explanation: "This chapter's lab decoded a real RPT and found authorization.permissions listing exactly [{\"scopes\":[\"view\"],\"rsid\":\"...\",\"rsname\":\"quarterly-report\"}] — precisely what was just granted for this specific request, computed at exchange time from live policy evaluation, not a general role or entitlement listing." },
    { id: "kas-13", type: "scenario", question: "Northwind Apps later wants an actual document owner — not an admin — to personally control who else can view their own document, closer to UMA's full resource-owner-delegation model. Which Keycloak resource setting moves in that direction?", options: ["Setting the resource's ownerManagedAccess to true, so the owning user (not just an admin) can manage access to that specific resource via the Account Console", "Switching the client's protocol from openid-connect to saml", "Disabling serviceAccountsEnabled on the resource server client", "Increasing the permission ticket's expiry time"], answerIndex: 0, explanation: "ownerManagedAccess is the specific per-resource toggle that lets the actual resource owner, not just a realm admin, manage access grants on their own resource through the Account Console — the closest built-in approximation to UMA's full resource-owner-in-the-loop workflow. This chapter's lab left it off and used an admin-managed role policy instead, as a deliberately simpler first cut." },
    { id: "kas-14", type: "concept", question: "What does Keycloak's \"Policy evaluate\" tool let an administrator do, as exercised live in this chapter's lab?", options: ["Issue a real, usable access token for a test user without any login", "Simulate a specific user/resource/scope request against live policies and see the PERMIT/DENY result (with full per-policy reasoning) without running a real UMA ticket exchange or issuing any token", "Permanently disable a policy across every permission that references it", "Automatically generate a decision-strategy recommendation for a new permission"], answerIndex: 1, explanation: "This chapter's lab called the REST endpoint behind this console tool directly and got back the same DENY result (with nested per-policy reasoning) that the real UMA exchange had already proven — without needing to request any token or ticket at all, a genuinely faster debugging loop." },
    { id: "kas-15", type: "scenario", question: "An application team insists on checking the subject's role mapping themselves inside their own backend code, instead of calling Keycloak's Protection/token endpoints for a decision. What role are they taking on by doing this, and what do they lose?", options: ["They become the Policy Decision Point themselves, and lose Keycloak's resource/scope/policy model entirely — every access rule has to be re-implemented and kept in sync in application code instead of centrally in Keycloak", "Nothing changes — Keycloak always evaluates the decision regardless of where the role check happens", "They become a Policy Enforcement Point exactly as intended; this is the recommended pattern", "This only matters for public clients, not confidential ones"], answerIndex: 0, explanation: "Authorization Services' whole value is that Keycloak is the Policy Decision Point — resources, scopes, policies, and permissions live and get evaluated centrally. A team that re-implements the role check itself has quietly taken over the PDP role in application code, losing the centralized, auditable, per-resource policy model this chapter builds, even if they never notice until policies drift out of sync." },
    { id: "kas-16", type: "bug", question: "A team assumes that creating a resource with uris=[\"/documents/quarterly-report\"] and a separate scope named \"view\" automatically means requests to that URI are now protected by a view-scoped permission. What did this chapter's lab prove is actually required first?", options: ["Nothing further — URIs alone are sufficient to wire up enforcement", "The resource's own scopes array must explicitly list the scope, and a permission must then be created referencing that resource+scope pair and at least one policy — none of this happens automatically from URIs or names alone", "The client must be switched to a public client before enforcement activates", "The scope must be renamed to exactly match the URI path"], answerIndex: 1, explanation: "This chapter's lab hit exactly this gap on its first attempt: a resource and a scope existing independently, even with a matching URI, enforces nothing by themselves. The resource must list the scope in its own scopes array, and a permission must tie that resource+scope pair to a policy before any real access decision gets made." }
  ],

  "fine-grained-access-patterns": [
    { id: "fgap-01", type: "concept", question: "Per this chapter, where does Keycloak's NATIVE authorization coverage actually stop on the chapter 6 spectrum?", options: ["At ACL only", "At RBAC only", "At ABAC/PBAC — Authorization Services policies", "At ReBAC — it natively models relationships too"], answerIndex: 2, explanation: "Keycloak's real ceiling is ABAC/PBAC via Authorization Services policies (chapter 37). ReBAC has no first-class support and must be approximated or offloaded to an external engine." },
    { id: "fgap-02", type: "concept", question: "What is missing from Keycloak's data model that makes native ReBAC support impossible without an approximation?", options: ["A role concept", "A group concept", "A first-class relationship-tuple concept (e.g. \"X manager_of Y\") that can be stored and queried as a graph", "A time-based policy type"], answerIndex: 2, explanation: "Keycloak has roles, groups, and attributes, but no native relationship-tuple/graph concept — exactly the gap chapter 6's ReBAC callout and this chapter both name directly." },
    { id: "fgap-03", type: "scenario", question: "Riverside Health requires: a clinician may view a patient record only if their department attribute matches the record's department, and only during their scheduled shift hours. Which authorization model does this requirement belong to?", options: ["RBAC — it's really just a clinician role check", "ABAC — both conditions are attributes evaluated at request time", "ReBAC — department and shift are relationships", "ACL — a per-record permission list"], answerIndex: 1, explanation: "Department and shift-time are both attributes of the subject/request evaluated dynamically, not a role or a relationship edge between two specific entities — textbook ABAC." },
    { id: "fgap-04", type: "scenario", question: "In the Riverside example, the department policy and the time policy are combined with a UNANIMOUS decision strategy rather than the default affirmative one. What does unanimous specifically guarantee here?", options: ["Either policy alone is enough to grant access", "Both policies must independently agree before access is granted", "The department policy always overrides the time policy", "Unanimous has no effect unless there are three or more policies"], answerIndex: 1, explanation: "Unanimous requires every associated policy to vote to grant; under the default affirmative strategy, a department match alone (even outside shift hours) would have been enough to grant access — a real misconfiguration risk this chapter calls out." },
    { id: "fgap-05", type: "scenario", question: "A Riverside clinician is found to be able to view a record outside their shift hours, even though the department-matching policy and the time-window policy were each individually written and tested correctly. What is the most likely root cause?", options: ["A bug inside the time policy's logic itself", "A bug inside the department policy's logic itself", "The permission's decision strategy is affirmative instead of unanimous, so only one policy needs to agree", "Keycloak caching an old token"], answerIndex: 2, explanation: "This chapter's pitfall callout specifically warns that a composition bug — the wrong decision strategy — can produce an incorrect combined result even when every individual policy is correct in isolation." },
    { id: "fgap-06", type: "scenario", question: "Meridian Trust needs: an employee may approve a transaction only if they have a manager-of relationship with the branch that owns the account. Why is this NOT expressible as a Keycloak role or a simple attribute?", options: ["Because Keycloak doesn't support time-based conditions", "Because a role only says \"this person is a manager,\" not \"manager of this specific branch,\" and the fact changes as managers rotate between branches — it's a relationship edge, not a static property", "Because Keycloak doesn't support group membership", "Because transaction approval requires MFA, which is unrelated to roles"], answerIndex: 1, explanation: "This is chapter 6's ReBAC definition exactly: a relationship between two specific entities (this employee, this branch), not a role or attribute value that holds regardless of which branch is in question." },
    { id: "fgap-07", type: "scenario", question: "A team approximates Meridian's manager-of requirement with one Keycloak group per branch (e.g. branch-managers-downtown). What cost does this chapter say to expect as the number of branches and manager rotations grows?", options: ["No meaningful cost — groups scale perfectly for this use case", "A group (and referencing policy) per branch, group-membership-only relationship tracking with no \"since when\" or reverse query, and manual/scripted upkeep every time a manager's branch assignment changes", "Keycloak will automatically reject more than ten groups per realm", "The approach becomes faster as more branches are added"], answerIndex: 1, explanation: "The chapter is explicit that group-per-relationship degrades: more groups to maintain, no native audit trail of the relationship itself, and real friction (often migration scripts) every time a relationship changes." },
    { id: "fgap-08", type: "compare", question: "How does a group-per-relationship approximation in Keycloak differ from a custom Policy SPI that calls an external relationship store, for modeling Meridian's manager-of requirement?", options: ["They are functionally identical with no real trade-off", "Group-per-relationship keeps everything inside Keycloak's native primitives but degrades as relationships multiply or change often; the external-store approach keeps Keycloak issuing the final decision while delegating the actual relationship graph to a system built to store and query it", "The external-store approach requires no network calls at all", "Group-per-relationship is the only approach that supports multi-hop relationships"], answerIndex: 1, explanation: "Both are legitimate approximations with different trade-offs: one stays fully native but scales poorly with relationship churn, the other adds an external dependency but gets a real graph data model — this chapter presents both honestly rather than declaring one strictly superior." },
    { id: "fgap-09", type: "concept", question: "What does Google's Zanzibar paper describe, and what is OpenFGA's relationship to it?", options: ["Zanzibar describes a token-revocation protocol; OpenFGA implements OAuth revocation", "Zanzibar describes a relationship-tuple-based authorization model (object#relation@subject) with multi-hop relationship queries; OpenFGA is a widely used open-source implementation of that model", "Zanzibar is Google's internal name for RBAC; OpenFGA is a Keycloak plugin", "Zanzibar and OpenFGA are unrelated projects that happen to share similar names"], answerIndex: 1, explanation: "Zanzibar is the 2019 paper describing Google's relationship-tuple authorization system; OpenFGA is a Zanzibar-derived open-source engine implementing the same tuple/graph model." },
    { id: "fgap-10", type: "scenario", question: "Meridian Trust's manager-of requirement eventually needs to support managers covering many branches, frequent rotations, and multi-hop checks (manager of the branch that owns this account). Per this chapter's case-study continuation, what is the realistic end state?", options: ["A cleverer single Keycloak policy that encodes all of this natively", "A relationship store (e.g. OpenFGA) holding the manager_of and owns tuples, queried by a custom Keycloak Policy provider or the resource server at approval time — with Keycloak still handling authentication and coarse roles", "Removing Keycloak entirely and replacing it with OpenFGA for authentication too", "Hard-coding the branch list into the application's source code"], answerIndex: 1, explanation: "The chapter is explicit that past a certain scale the honest answer is a dedicated relationship store, not a cleverer Keycloak policy — while Keycloak keeps doing what it's actually good at: authentication and coarse-grained roles." },
    { id: "fgap-11", type: "concept", question: "What CNCF maturity level does Open Policy Agent (OPA) hold, as live-verified for this chapter?", options: ["Sandbox", "Incubating", "Graduated (since January 29, 2021)", "OPA is not a CNCF project"], answerIndex: 2, explanation: "OPA was accepted to CNCF in March 2018, promoted to Incubating in 2019, and promoted to Graduated on January 29, 2021 — the highest CNCF maturity tier, requiring a completed security audit and defined governance." },
    { id: "fgap-12", type: "concept", question: "What language are OPA policies written in, and what is distinctive about it?", options: ["Rego — a declarative, Datalog-flavored language purpose-built for querying nested JSON, not a general-purpose programming language", "Python, using OPA's official SDK", "YAML, with no real logic expressiveness", "Cedar, shared with AWS's policy engine"], answerIndex: 0, explanation: "Rego is OPA's own declarative query language, deliberately not general-purpose, giving it real expressive power over JSON but a real learning curve." },
    { id: "fgap-13", type: "scenario", question: "A colleague states as fact: \"Cedar is currently at version 4.\" Per this chapter's live-verification note, what's the honest response?", options: ["That's fully correct and needs no qualification", "It depends which \"version 4\" is meant — the Cedar language specification version and the cedar-policy SDK/crate version are tracked separately, are both casually called \"version 4,\" and the sources didn't fully reconcile for this course, so the claim needs to specify which numbering scheme it refers to", "Cedar has no version numbers at all", "Cedar's version number is identical to OPA's version number by design"], answerIndex: 1, explanation: "The chapter deliberately flags this exact ambiguity rather than repeating a flattened, confident number — per the course's no-invented-facts rule, when sources disagree you say so." },
    { id: "fgap-14", type: "concept", question: "Who originally built Cedar, and what is it used for in production at AWS?", options: ["Google; used internally for Zanzibar", "AWS; powers Amazon Verified Permissions, a managed authorization service built on Cedar", "An independent nonprofit with no corporate sponsor", "Red Hat; used internally for Keycloak itself"], answerIndex: 1, explanation: "Cedar was built by AWS, open-sourced under Apache 2.0 in May 2023, and AWS's own production use of it is Amazon Verified Permissions." },
    { id: "fgap-15", type: "compare", question: "Comparing Keycloak Authorization Services to OPA on deployment model, which statement is accurate per this chapter's comparison table?", options: ["Keycloak Authorization Services is built into the Keycloak server you already run; OPA typically runs as a sidecar or embedded library, decoupled from any single application", "Both require exactly the same deployment topology with no differences", "OPA can only run as a managed AWS service", "Keycloak Authorization Services requires a separate sidecar process, just like OPA"], answerIndex: 0, explanation: "This is the chapter's comparison table distinction directly: Authorization Services is part of the Keycloak server already in the request path; OPA is deliberately decoupled, commonly deployed as a sidecar or library next to any service." },
    { id: "fgap-16", type: "scenario", question: "A teammate proposes ripping out Keycloak's Authorization Services entirely and replacing every authorization decision in the system — including simple role checks — with OPA. What does this chapter say you should ask first?", options: ["Nothing — wholesale replacement is always the right call for consistency", "What specific decisions actually need OPA's extra expressiveness versus what Keycloak's native RBAC/ABAC/PBAC ceiling already covers natively, since replacing working in-the-box evaluation adds an extra service to deploy and keep in sync for marginal benefit on most decisions", "Whether OPA supports the client credentials grant", "Whether Rego can be compiled to Java bytecode"], answerIndex: 1, explanation: "The chapter's self-check and pitfalls sections both push back on all-or-nothing platform swaps — the comparison should be made decision-by-decision against what's already natively covered." },
    { id: "fgap-17", type: "scenario", question: "A custom Keycloak Policy SPI provider calls an external relationship store on every single authorization request, with no caching. What risk does this chapter flag?", options: ["None — external policy calls are always effectively free", "The external call becomes a network hop added to every authorization decision, requiring the same latency/availability thinking as any other external dependency in a hot request path", "Keycloak automatically caches all Policy SPI calls, so this is a non-issue", "This pattern is only a risk if the external store is also a ReBAC engine"], answerIndex: 1, explanation: "The pitfalls slide calls this out directly: treating an external policy call as free ignores that it's now a live dependency and latency/availability risk on the hot authorization path." }
  ],

  "custom-spis": [
    { id: "cspi-01", type: "concept", question: "What two classes does every Keycloak SPI provider need, and what is the key lifecycle difference between them?", options: [
        "A Factory, discovered once at server boot via ServiceLoader, and a Provider, created fresh per use by the factory",
        "A Controller and a Repository, matching a typical MVC web framework's layering",
        "An Interface and an Implementation, with no meaningful lifecycle difference between them",
        "A Config class, loaded from application.properties, and a Service class that reads it"
      ], answerIndex: 0, explanation: "Chapter 33 already established this for the User Storage SPI; chapter 39 confirms it's the general Keycloak SPI pattern, instantiated for Authenticator and EventListenerProvider as well (with one real exception for Protocol Mapper — see the Factory/Provider collapse question below)." },
    { id: "cspi-02", type: "concept", question: "Which single mechanism is responsible for Keycloak actually finding a third-party provider factory class at boot, given a correctly built and bind-mounted JAR?", options: [
        "A META-INF/services text file naming the factory's fully qualified class name, read via Java's standard ServiceLoader", "An XML descriptor similar to a Java EE web.xml", "Reflection scanning every class on the classpath for a known annotation", "A REST call Keycloak makes to the JAR's own manifest at runtime"
      ], answerIndex: 0, explanation: "The ServiceLoader convention — confirmed again in chapter 39, same mechanism chapter 33 used." },
    { id: "cspi-03", type: "scenario", question: "Meridian Trust's fraud team wants a login attempt outside business hours to be denied outright, not merely flagged after the fact. Which SPI is the right tool, and why not a Required Action instead?", options: [
        "An Authenticator, because it runs during the credential check itself and can prevent the flow from succeeding at all — a Required Action only ever runs after authentication has already succeeded",
        "A Required Action, because required actions always run before credentials are checked",
        "A Protocol Mapper, because it can withhold claims from a denied user's token",
        "An Event Listener, because it can log the denial for later review"
      ], answerIndex: 0, explanation: "This is chapter 39's own concept-recall distinction, foreshadowing chapter 40: an Authenticator can block the flow from completing; a Required Action (chapter 40's subject) only ever runs after authentication has already succeeded." },
    { id: "cspi-04", type: "scenario", question: "Riverside Health wants a HIPAA-relevant audit trail of failed clinician logins specifically, distinguishable in the server's own logs from Keycloak's built-in event logging. Which SPI fits, and which method does the actual filtering?", options: [
        "An EventListenerProvider implementing onEvent(Event), checking event.getType() == EventType.LOGIN_ERROR",
        "A ProtocolMapper, because token claims can encode an audit flag", "An Authenticator, because authenticate() runs on every login attempt", "The Admin REST API's own /events endpoint, polled on a schedule"
      ], answerIndex: 0, explanation: "EventListenerProvider.onEvent(Event) is called for every user event; filtering to LOGIN_ERROR (and, implicitly, to whichever realm has this listener's id enabled) is exactly how chapter 39's Riverside Health lab worked." },
    { id: "cspi-05", type: "scenario", question: "Northwind Apps needs every customer-facing login's access token, ID token, and UserInfo response to carry a tenant_id claim computed from a user attribute. Which three interfaces does a single Protocol Mapper class implement together to cover all three token surfaces?", options: [
        "OIDCAccessTokenMapper, OIDCIDTokenMapper, and UserInfoTokenMapper", "UserLookupProvider, CredentialInputValidator, and UserQueryMethodsProvider", "AuthenticatorFactory, ConfigurableAuthenticatorFactory, and ConfiguredProvider", "EventListenerProvider, EventListenerProviderFactory, and ProviderFactory"
      ], answerIndex: 0, explanation: "Confirmed live in chapter 39's lab: implementing all three on one class let the same tenant_id claim appear in a decoded access token, a decoded ID token, and a real /userinfo call." },
    { id: "cspi-06", type: "scenario", question: "Meridian Trust's business-hours Authenticator calls context.failure(AuthenticationFlowError.ACCESS_DENIED) — the single-argument overload — to deny a Direct Grant login outside business hours. The LOGIN_ERROR event fires correctly, but the client gets back an HTTP 500 \"unknown_error\" instead of a clean OAuth error. What's the real cause, confirmed live in this chapter's own lab?", options: [
        "The single-argument failure() overload throws an uncaught AuthenticationFlowException on the Direct Grant code path specifically; supplying an explicit challenge Response via the two-argument overload fixes it",
        "AuthenticationFlowError.ACCESS_DENIED does not exist in Keycloak 26.8.2 and must be replaced with a custom error code",
        "Direct Grant logins can never be denied by a custom Authenticator, only by built-in ones",
        "The event listener provider crashed, which is unrelated to the authenticator's own failure() call"
      ], answerIndex: 0, explanation: "A real bug this chapter's lab hit and fixed, confirmed via the server's own stack trace (DefaultAuthenticationFlow.processResult, called from ResourceOwnerPasswordCredentialsGrantType.process)." },
    { id: "cspi-07", type: "bug", question: "After running `mvn clean package` to rebuild a provider JAR while its Keycloak container is already running with that file bind-mounted, `docker compose restart` doesn't pick up the new code — the container keeps serving the old class files. What actually happened, and what's the fix?", options: [
        "The bind mount still points at the old file's content because a plain restart doesn't re-resolve it; recreate the container instead (`docker compose up -d --force-recreate <service>`)",
        "Maven silently failed to overwrite the old jar, so the file on disk never actually changed",
        "Keycloak caches compiled provider classes in its database and ignores the filesystem after first boot",
        "The jar needs to be renamed to a new version number every time it's rebuilt, or Keycloak won't reload it"
      ], answerIndex: 0, explanation: "A real, live-confirmed gotcha from chapter 39's lab, distinct from chapter 33's 'bind mount becomes an empty directory' bug — confirmed by comparing file size/timestamp inside vs. outside the container after a rebuild." },
    { id: "cspi-08", type: "bug", question: "In Meridian Trust's test realm, a fresh direct-grant login attempt for a brand-new test user fails with \"Account is not fully set up,\" even though the user has a real password credential set. Disabling the new business-hours Authenticator and retrying produces the exact same error. What's the likely cause?", options: [
        "The realm's Declarative User Profile requires fields (e.g. firstName, lastName, email) the new user doesn't have set yet, triggering a dynamically-computed required action unrelated to the custom authenticator", "The custom authenticator's JAR failed to deploy, so Keycloak fell back to a default-deny authenticator", "The user's password was never actually hashed, so Keycloak treats the account as incomplete", "Direct Grant is disabled by default for every new realm until explicitly turned on"
      ], answerIndex: 0, explanation: "Confirmed live in this chapter's own lab — isolating the issue by temporarily disabling the new authenticator proved it was a pre-existing, unrelated User Profile gap (the same VERIFY_PROFILE-style gotcha chapter 24's lab already documented), not a bug in the new code." },
    { id: "cspi-09", type: "scenario", question: "Testing Northwind Apps' tenant_id mapper, a real UserInfo call against a freshly minted access token returns HTTP 401 with error_description \"Lightweight access token not allowed for userinfo endpoint,\" even though the mapper's config correctly has userinfo.token.claim set to true. What's going on?", options: [
        "The client (admin-cli, by default) has 'Always use lightweight access token' enabled, and Keycloak's UserInfo endpoint refuses lightweight tokens outright — disabling that client setting fixes it", "UserInfo calls require a refresh token, not an access token", "The protocol mapper's config is being ignored entirely for UserInfo responses", "Lightweight tokens were removed in Keycloak 26.8.2 and the client needs to be rebuilt"
      ], answerIndex: 0, explanation: "A real, live-confirmed finding from chapter 39's Northwind Apps lab — the fix was a client setting, not anything about the mapper's own code or config." },
    { id: "cspi-10", type: "compare", question: "Both Authenticator and EventListenerProvider need a separate Factory class; Protocol Mapper does not. Why is Protocol Mapper's SPI shaped differently, confirmed directly from the real interface rather than assumed?", options: [
        "ProtocolMapper itself extends ProviderFactory<ProtocolMapper>, and AbstractOIDCProtocolMapper.create() simply returns `this` — Factory and Provider collapse into one class because a mapper is cheap and stateless enough not to need the split",
        "Protocol mappers don't need to be discovered via ServiceLoader at all, unlike the other two SPIs",
        "Keycloak deprecated the Factory pattern for newer SPIs, and Protocol Mapper was the first one converted",
        "A Protocol Mapper factory exists but is optional, unlike the other two SPIs where it's mandatory"
      ], answerIndex: 0, explanation: "Confirmed directly by inspecting AbstractOIDCProtocolMapper's real `create()` method on the actual 26.8.2 jar before writing the class — a genuine structural asymmetry, not an assumption." },
    { id: "cspi-11", type: "compare", question: "Chapter 24's 'Protocol mapper' glossary entry and chapter 39's 'Protocol Mapper SPI' entry are deliberately NOT merged into one term. What's the real distinction?", options: [
        "'Protocol mapper' is the admin-configured instance of an already-existing mapper type attached to a client scope; 'Protocol Mapper SPI' is the Java interface you implement to create a brand-new mapper type", "They are actually the same concept and should be merged", "'Protocol mapper' only applies to SAML, while 'Protocol Mapper SPI' only applies to OIDC", "'Protocol Mapper SPI' is deprecated in favor of 'Protocol mapper'"
      ], answerIndex: 0, explanation: "Exactly the distinction this chapter's brief asked to call out explicitly — an admin configuring chapter 24's built-in UserAttributeMapper never touches the SPI; Northwind's tenant_id mapper is a new SPI implementation an admin then configures the same way." },
    { id: "cspi-12", type: "scenario", question: "A Riverside Health admin enables the riverside-failed-login-audit listener on the riverside-health realm only. A failed login then occurs against a completely different realm on the same server, meridian-trust. Does the Riverside listener log it?", options: [
        "No — Keycloak only invokes an EventListenerProvider's onEvent() for a realm that has that provider's id enabled under that realm's own Events config", "Yes — event listeners are always global across every realm on a server once registered", "Only if both realms share the same database", "Only if the listener's class explicitly checks the realm name itself"
      ], answerIndex: 0, explanation: "Confirmed live in chapter 39's lab: a failed login against meridian-trust produced zero matching lines in the Riverside audit log, proving realm-scoped enablement, not code-level filtering, is what's doing the scoping." },
    { id: "cspi-13", type: "concept", question: "Why does Meridian Trust's BusinessHoursAuthenticator return `false` from requiresUser()?", options: [
        "Its decision depends only on the current wall-clock time, never on which user is logging in, so it doesn't need the flow to have already resolved a UserModel", "requiresUser() must always be false for any authenticator placed in the Direct Grant flow", "Returning true would have prevented the authenticator from being configurable", "It's a Keycloak requirement for any authenticator that denies access"
      ], answerIndex: 0, explanation: "requiresUser() is an honest signal about what the authenticator's own logic actually needs, not a flow-type restriction — this authenticator's logic genuinely doesn't touch the user at all." },
    { id: "cspi-14", type: "scenario", question: "A Northwind Apps user has no tenant_id attribute set. What does the custom Protocol Mapper do, confirmed by this chapter's own live test?", options: [
        "It omits the tenant_id claim entirely from the token — no claim with a null or empty value appears", "It throws an exception that fails the whole login", "It injects tenant_id with the literal string value \"null\"", "It falls back to a hardcoded default tenant for every unset user"
      ], answerIndex: 0, explanation: "Confirmed live: a second test user with no tenant_id attribute produced a decoded token with no tenant_id key at all, not a null or empty-string claim." },
    { id: "cspi-15", type: "concept", question: "What does Keycloak 26.8.2's boot-time warning \"is implementing the internal SPI ... This SPI is internal and may change without notice\" actually mean for a reader building against the Authenticator or Event Listener SPIs?", options: [
        "Both SPIs are explicitly marked internal in Keycloak's own Server Developer Guide prose, not just in this one boot-time log line — the interfaces are stable and documented enough to build against, but not contractually guaranteed not to change across releases the way a clearly public API would be", "The provider failed to load and must be rewritten against a different package", "The warning is cosmetic and applies to every Keycloak SPI without exception, including the publicly stable User Storage SPI", "It means the provider is disabled by default and must be explicitly re-enabled per realm"
      ], answerIndex: 0, explanation: "Confirmed by cross-checking Keycloak's own official docs: both the Authentication SPI and Event Listener SPI sections carry the identical 'this is an internal SPI' disclaimer in prose, independent of the live boot warning this chapter's lab also triggered." },
    { id: "cspi-16", type: "scenario", question: "Why did this chapter build one Maven project producing one JAR for all three case-study SPIs, rather than three separate Maven modules?", options: [
        "All three SPIs are small, have zero dependencies on each other, and share identical build/deploy mechanics — three separate modules would mean three JARs, three bind mounts, and three separate rebuild-before-restart failure points for no real isolation benefit", "Keycloak requires every provider JAR on the classpath to come from the exact same Maven project", "Three separate projects would have needed three different Keycloak versions", "A single JAR compiles faster regardless of how many unrelated classes it contains"
      ], answerIndex: 0, explanation: "The chapter's own stated rationale — a judgment call, not a Keycloak requirement, explained explicitly rather than left implicit." },
    { id: "cspi-17", type: "concept", question: "Which four Keycloak Maven artifacts, all pinned to the exact same version as the running server, does this chapter's POM declare at scope=provided, and why four rather than the two chapter 33 needed?", options: [
        "keycloak-server-spi, keycloak-server-spi-private, keycloak-services, and keycloak-core — because the Authenticator/EventListenerProvider/base ProtocolMapper interfaces live in server-spi-private, while the OIDC-specific mapper interfaces and token representation classes needed for this chapter's third SPI live one jar over, in keycloak-services and keycloak-core respectively", "The same two artifacts chapter 33 used, keycloak-server-spi and keycloak-model-storage, since every Keycloak SPI lives in the same two jars", "keycloak-core, keycloak-admin-client, keycloak-services, and keycloak-quarkus-server", "Only keycloak-server-spi is needed; the other three are optional conveniences"
      ], answerIndex: 0, explanation: "Confirmed by directly inspecting the real 26.8.2 jars before writing the POM, the same live-verification method chapter 33 used — and a genuinely different, larger dependency list than chapter 33 needed, because this chapter's three SPIs are split across more jars than the User Storage SPI was." },
    { id: "cspi-18", type: "scenario", question: "Meridian Trust's security team asks whether the business-hours authenticator's \"deny\" test in this chapter actually exercised the real server clock, or whether the server's time was artificially mocked to produce the result. What's the honest answer?", options: [
        "The real server clock, unmodified — both the allow and deny outcomes were produced by changing only the authenticator's configured start/end hour window, not the clock, so the exact same conditional logic ran against real wall-clock time both times", "The server's system clock was changed via `date -s` inside the container for the deny test specifically", "A mocked Clock.fixed() was injected into the authenticator's test build only, not its production build", "The deny test used a separate, slower test container running in a different timezone"
      ], answerIndex: 0, explanation: "Exactly the approach this chapter states plainly: real clock throughout, two different configured windows — an honest way to demonstrate both branches without needing to fake the server's time at all." }
  ],

  "custom-idp-and-required-actions": [
    { id: "cida-01", type: "concept", question: "What does AbstractIdentityProvider's performLogin() and callback() return by default, confirmed by decompiling the real 26.8.2 bytecode?", options: ["An HTTP 501 Not Implemented response", "null for both — a subclass must override both to have a working broker", "A redirect back to the realm's ordinary login form", "An empty BrokeredIdentityContext"], answerIndex: 1, explanation: "Both methods' real bytecode is just aconst_null / areturn — a sane-looking signature with no real default behavior, confirmed directly rather than assumed from the method name alone." },
    { id: "cida-02", type: "scenario", question: "Meridian Trust has just acquired Cascade Savings Bank, whose employees still sign in through Cascade's own 20-year-old proprietary SSO system. Why is writing a custom Identity Provider the right tool here rather than configuring one of Keycloak's built-in broker types?", options: ["Built-in broker types are more expensive to license", "None of Keycloak's built-in broker types understand Cascade's proprietary protocol at all", "Custom providers run faster than built-in ones", "Keycloak requires a custom provider for any acquisition scenario"], answerIndex: 1, explanation: "Chapter 31 configured a built-in OIDC broker type — real configuration, zero Java, because Keycloak already shipped code for that protocol. Cascade's protocol has no such built-in equivalent, which is exactly the situation that calls for writing a new broker type from scratch." },
    { id: "cida-03", type: "bug", question: "A new custom Identity Provider is deployed, and its own performLogin() successfully redirects the browser to the external system. After the external system redirects back, the browser lands on a generic Keycloak error page instead of a JIT-provisioned login. The provider's callback() method simply returns `new Endpoint(...)` with no further logic inside Endpoint itself. What's missing?", options: ["The realm needs a second Identity Provider configured", "The Endpoint class needs its own @GET/@Path-annotated method that actually verifies the callback and calls AuthenticationCallback.authenticated(...) — returning a bare, logic-less Endpoint object does nothing on its own", "performLogin() needs to be called twice", "The external system needs its own Keycloak realm"], answerIndex: 1, explanation: "callback() only hands JAX-RS a sub-resource object to dispatch to — the actual verification and the call to callback.authenticated(context) have to live inside that Endpoint's own annotated method, or nothing meaningful happens when the request arrives." },
    { id: "cida-04", type: "scenario", question: "Riverside Health wants every clinician to re-acknowledge its HIPAA data-handling notice once before they can proceed past login. A junior engineer proposes writing a custom authenticator (chapter 39's SPI family) that shows the notice during the credential check. What's the problem with that approach?", options: ["Authenticators cannot render HTML pages at all", "An authenticator runs during authentication and can refuse a correct credential outright — modeling a compliance acknowledgment as part of \"proving who the clinician is\" is conceptually wrong and risks accidentally gating authentication itself on something that isn't actually a credential check", "Authenticators are deprecated in Keycloak 26.8.2", "Authenticators can only run once per realm, not per user"], answerIndex: 1, explanation: "A required action is the right shape precisely because it models \"login succeeded, but one more mandatory step stands between that and a usable session\" — a required action can never cause a correct credential to fail, which is exactly the property a compliance acknowledgment should have." },
    { id: "cida-05", type: "scenario", question: "A custom required action's jar is confirmed present in /opt/keycloak/providers and discovered at server startup (the KC-SERVICES0047 log line appears). A test user's requiredActions list is set to include its provider id via the Admin REST API, but logging in as that user proceeds straight through with no sign of the action at all. What's the most likely cause?", options: ["The user's password is wrong", "The required action was never registered on that specific realm via POST .../authentication/register-required-action — it still sits in that realm's unregistered-required-actions list", "Required actions only work for admin users", "The jar needs to be rebuilt with a different Maven version"], answerIndex: 1, explanation: "Unlike a custom Identity Provider (immediately selectable once deployed), a freshly discovered custom Required Action is not auto-enabled on any realm — confirming it via GET .../unregistered-required-actions and then registering it is the fix, a per-realm switch the Identity Provider SPI has no equivalent of." },
    { id: "cida-06", type: "concept", question: "Which Keycloak artifact actually contains IdentityProvider, IdentityProviderFactory, AbstractIdentityProvider, RequiredActionProvider, and RequiredActionFactory, confirmed live for 26.8.2?", options: ["keycloak-server-spi", "keycloak-server-spi-private", "keycloak-services", "keycloak-model-storage"], answerIndex: 1, explanation: "Grepping the real 26.8.2 jars directly (not assuming any prior chapter's coordinates carry over) showed both SPI contracts live in keycloak-server-spi-private, not keycloak-server-spi alone — a different split than chapter 33's UserStorageProvider, which needed keycloak-model-storage instead." },
    { id: "cida-07", type: "compare", question: "How does a custom Required Action's per-realm enablement differ from a custom Identity Provider's?", options: ["They behave identically — both are usable immediately once deployed", "A custom Identity Provider is immediately selectable in a realm's \"Add provider\" picker once its jar is deployed; a custom Required Action must be explicitly POSTed to a realm's register-required-action endpoint before it does anything there, even if a user's requiredActions list already names it", "A custom Required Action is immediately enabled everywhere; a custom Identity Provider needs explicit per-realm registration", "Neither SPI type requires any registration step at all"], answerIndex: 1, explanation: "Confirmed live: the Identity Provider SPI has no equivalent of the Required Action SPI's per-realm unregistered-required-actions / register-required-action mechanism." },
    { id: "cida-08", type: "scenario", question: "A custom Identity Provider's importNewUser() override calls user.setSingleAttribute(\"legacySource\", \"cascade-sso\") with no exception thrown, but a later GET of that JIT-provisioned user shows no attributes field at all. What's the most likely cause, and what confirms it?", options: ["setSingleAttribute() is deprecated in 26.8.2", "The realm's Declarative User Profile has unmanagedAttributePolicy left at its default (disabled); setting it to ENABLED via PUT .../users/profile and re-provisioning a user confirms the attribute then persists", "The attribute name must be all uppercase", "The user needs an email address set first"], answerIndex: 1, explanation: "This is the same gotcha chapter 33 documented for a completely different SPI family, confirmed to recur here: an unmanaged custom attribute is silently dropped unless the realm's user profile explicitly allows it." },
    { id: "cida-09", type: "concept", question: "Why does this chapter's custom Identity Provider extend AbstractIdentityProvider directly instead of AbstractOAuth2IdentityProvider, the base class every built-in Google/GitHub/OIDC broker extends?", options: ["AbstractOAuth2IdentityProvider doesn't exist in Keycloak 26.8.2", "AbstractOAuth2IdentityProvider lives in the much heavier keycloak-services artifact and bakes in OAuth2-specific assumptions (token endpoints, client secrets) the toy, non-OAuth2 Cascade SSO protocol doesn't have", "AbstractIdentityProvider is newer and officially replaces AbstractOAuth2IdentityProvider", "Only social-login providers may extend AbstractOAuth2IdentityProvider"], answerIndex: 1, explanation: "Cascade SSO is a plain redirect-and-signed-assertion protocol, not OAuth2-shaped — extending the lighter AbstractIdentityProvider directly keeps the dependency footprint to exactly what's actually needed." },
    { id: "cida-10", type: "scenario", question: "Why does the toy legacy IdP server in this chapter's lab run as a plain host process rather than inside the ch40kc Docker Compose stack alongside Keycloak?", options: ["Python cannot run inside Docker containers", "Every redirect in the round trip is followed by the browser (or curl, standing in for one), never by the Keycloak container calling the toy IdP server-to-server, so the toy IdP only needs to be reachable from whatever machine drives the curl commands — no container-to-host network bridging is needed", "Docker Compose doesn't support running two services on different ports", "The toy IdP needs root privileges that containers can't grant"], answerIndex: 1, explanation: "performLogin() only builds a Location header string — it makes no outbound network call itself. The actual request to the toy IdP's authorize endpoint comes from the browser/curl, which runs on the host anyway." },
    { id: "cida-11", type: "scenario", question: "Dr. Chen (a Riverside Health clinician) enters a completely correct password and the realm has no MFA configured. What does the HTTP response actually look like immediately afterward, given her account has the custom riverside-hipaa-ack required action assigned and registered on the realm?", options: ["A 200 response with the application's own dashboard content", "A 302 redirect to /login-actions/required-action?execution=riverside-hipaa-ack&... — not to the application's redirect_uri", "A 401 Unauthorized, because the password doesn't matter once a required action is assigned", "A 500 Internal Server Error"], answerIndex: 1, explanation: "A correct credential check succeeding is not the same as the login being complete — Keycloak routes the browser into the pending required action next, confirmed live in this chapter's lab, and the application's redirect_uri is only reached after that action reports success." },
    { id: "cida-12", type: "bug", question: "Declining the HIPAA acknowledgment required action produces Keycloak's generic \"An error occurred, please login again through your application\" page, even though processAction() calls context.failure(\"riversideHipaaAckDeclined\"). The login attempt did genuinely end (a real 400). What explains the generic wording?", options: ["context.failure() ignores its argument entirely", "The messageCode argument is a realm message-bundle key, not display text — with no matching entry in a theme-resources/messages/ properties file, Keycloak falls back to its own generic error wording", "The realm needs to be restarted for custom error messages to take effect", "Required actions cannot customize error messages, full stop"], answerIndex: 1, explanation: "The call still correctly blocks the session either way; customizing the displayed text is a separate step (a messages_en.properties entry) this lab deliberately left out to keep the two concerns separate." },
    { id: "cida-13", type: "concept", question: "What is the BrokeredIdentityContext object's role in a custom Identity Provider's callback logic?", options: ["It stores the realm's SMTP configuration", "It carries the asserted external identity's fields (id, username, email, name, the IdP config) to hand to Keycloak's own First Broker Login logic via AuthenticationCallback.authenticated(context)", "It is Keycloak's internal representation of a Maven dependency", "It replaces the need for a shared signing secret"], answerIndex: 1, explanation: "Building a BrokeredIdentityContext and passing it to callback.authenticated(...) is what actually hands control back to Keycloak's own account-linking/JIT-provisioning decision tree (chapter 31's First Broker Login flow)." },
    { id: "cida-14", type: "scenario", question: "Without any HMAC signature on the toy legacy IdP's callback, what specific attack becomes possible against the custom Identity Provider's broker endpoint?", options: ["An attacker could read the shared secret directly from Keycloak's admin console", "Anyone who can guess or observe the broker-endpoint URL's publicly knowable shape could craft a query string claiming to be any Cascade user, and Keycloak would JIT-provision or log them in as that user with no real authentication having happened at all", "The toy IdP's login form would stop rendering entirely", "Keycloak would refuse to start the realm"], answerIndex: 1, explanation: "The broker-endpoint URL convention (/realms/{realm}/broker/{alias}/endpoint) is fixed and documented, not secret — the signature, not the URL shape, is what lets Keycloak verify a callback actually came from the trusted external system." },
    { id: "cida-15", type: "concept", question: "What does rejecting a callback whose ts field is more than 300 seconds old actually defend against?", options: ["Clock drift between Keycloak and the database only", "A stale or replayed callback — someone resending a previously captured, validly signed redirect well after the fact", "SQL injection in the legacy_user query parameter", "Cross-site scripting in the login form"], answerIndex: 1, explanation: "A valid signature alone doesn't prove freshness — bounding how old ts is allowed to be closes the window for replaying a captured, genuinely-signed callback long after the original login attempt." },
    { id: "cida-16", type: "scenario", question: "A Northwind Apps engineer reviewing this chapter's pattern for a different acquisition scenario asks whether a custom Identity Provider can skip implementing retrieveToken() entirely, since their own legacy protocol also has no token concept. What's the accurate answer?", options: ["Yes, it can be left unimplemented with no consequence, since Java allows abstract methods to stay unimplemented in a concrete class", "No — retrieveToken() is left fully abstract by AbstractIdentityProvider (unlike performLogin()/callback(), which merely return null by default), so a concrete subclass must provide some implementation, even if it's just an honest, trivial stub for a token-less protocol", "Yes, because retrieveToken() only matters for SAML-based providers", "No — retrieveToken() must always return a real OAuth2 access token"], answerIndex: 1, explanation: "Confirmed directly from AbstractIdentityProvider's real bytecode: retrieveToken() has no implementation at all there, so a concrete subclass is required by the compiler to supply one — this chapter's provider does so with a clearly labeled stub rather than fabricating a fake token." }
  ],

  "high-availability-clustering": [
    { id: "hac-01", type: "scenario", question: "Northwind Apps' platform team adds a second Keycloak node behind their load balancer and asks what genuinely new problems that introduces compared to running one node. What's the accurate answer?", options: ["Only encryption and compression settings change", "Two separate new problems: discovery (the two nodes finding each other at all) and replication (keeping the right in-memory state, like sessions, consistent between them)", "Only billing and licensing change", "Nothing changes functionally, only throughput improves"], answerIndex: 1, explanation: "A single node has no one to find and nothing to keep consistent with anyone else. Adding a second node requires solving both: discovery and replication — exactly the two mechanisms this chapter covers." },
    { id: "hac-02", type: "concept", question: "As confirmed live against Keycloak 26.8.2's own `start --help-all` output, what is the documented default cache-stack (discovery protocol) for a non-Kubernetes deployment?", options: ["tcp", "udp", "jdbc-ping", "kubernetes"], answerIndex: 2, explanation: "The real --cache-stack option's help text states jdbc-ping as the default, with tcp, udp, kubernetes, and several cloud-specific stacks explicitly marked deprecated." },
    { id: "hac-03", type: "scenario", question: "Meridian Trust's infrastructure team is planning a two-node Keycloak cluster and wants to avoid maintaining a hand-edited list of node IP addresses that breaks every time a container restarts with a new address. Which discovery mechanism, confirmed as this version's real default, solves exactly that problem?", options: ["UDP multicast broadcast on the local network", "JDBC_PING — each node writes and reads its own address in a table inside the same database Keycloak already connects to, so there's no static list to maintain", "A hardcoded static list of IP addresses in keycloak.conf", "A dedicated Kubernetes Service object"], answerIndex: 1, explanation: "JDBC_PING uses the already-configured database connection as the discovery mechanism — no static host list, no multicast, no separate discovery service needed, which is exactly the maintenance burden Meridian Trust wants to avoid." },
    { id: "hac-04", type: "bug", question: "A two-node start-dev lab shows no errors, but a session created on node A is never visible on node B. Checking the compose file, no --cache flag was ever passed. What's the most likely cause?", options: ["The Postgres database is corrupted", "start-dev's own default cache mode is `local`, which silently disables clustering outright — --cache=ispn must be passed explicitly to cluster", "Keycloak only supports clustering in Kubernetes", "The two nodes are using different Keycloak versions"], answerIndex: 1, explanation: "start-dev defaults to --cache=local specifically for dev/testing convenience. It is a fully valid, unremarked mode — there's no warning that clustering was silently skipped." },
    { id: "hac-05", type: "scenario", question: "Meridian Trust's online banking platform runs a single Keycloak node. A routine OS patch requires restarting that node. What happens to every customer with an active session during the restart, and why does a cluster change that answer?", options: ["Nothing changes either way, since sessions are stateless", "Every session is lost and every customer must log in again, because the session only ever existed in that one node's memory; a cluster with a replicated sessions cache means another node still holds the session and can keep serving it", "Clustering only improves token-minting speed, not session survivability", "Sessions are automatically backed up to disk every restart regardless of clustering"], answerIndex: 1, explanation: "A single node's session cache is that node's exclusive, non-durable memory. A cluster's replicated sessions cache means a session survives any one node going away — exactly chapter 1's \"new single point of failure\" trade-off, addressed operationally." },
    { id: "hac-06", type: "concept", question: "This chapter's lab confirmed from the real server's own --help-all output that some embedded caches are explicitly annotated \"available only when embedded Infinispan clusters configured\" and others are not. What does that annotation actually distinguish?", options: ["Caches that use more memory versus less memory", "Distributed/replicated caches (sessions, clientSessions, offline variants) versus local caches kept fresh by invalidation (realms, users, keys)", "Caches available only to paying enterprise customers", "Caches that require a restart to clear"], answerIndex: 1, explanation: "The annotated caches are the ones that actually replicate across nodes; the unannotated ones (realms/users/keys/authorization/crl) are local, invalidation-only caches that fall back to the always-authoritative database." },
    { id: "hac-07", type: "scenario", question: "Northwind Apps' platform team clusters two Keycloak nodes and assumes realm configuration changes made via node A's Admin Console will now be instantly, fully replicated into node B's in-memory realm cache the same way a user session would be. Are they right?", options: ["Yes, realms replicate identically to sessions", "Not quite — the realms cache is a local cache kept fresh by cross-node invalidation messages, not full replication; node B's cache entry is invalidated and re-fetched from the always-authoritative database rather than receiving the full updated object directly from node A's cache", "No, realm changes require a full cluster restart to propagate at all", "Realm data isn't cached at all, so this isn't a concern"], answerIndex: 1, explanation: "Session-family caches are genuinely distributed; realms/users/keys are local caches using invalidation. The end-user-visible effect (consistency) is similar, but the mechanism — and what you'd debug if something seemed stale — is different." },
    { id: "hac-08", type: "bug", question: "This chapter's lab's very first cross-node refresh-token attempt returned `invalid_grant` / \"Invalid token issuer. Expected '...:18142/...'\" even though the cluster's own logs already showed a healthy two-member view. What was the actual cause?", options: ["The replicated sessions cache had not finished rebalancing yet", "Each node was computing its own token issuer (iss claim) from its own request Host header, so a token minted via node A's port didn't match what node B expected — a hostname configuration issue, unrelated to clustering health", "The refresh token had already expired", "PostgreSQL rejected the second node's connection"], answerIndex: 1, explanation: "A healthy cluster view only proves JGroups/Infinispan nodes can see each other — it says nothing about hostname/issuer configuration. The fix was forcing one shared KC_HOSTNAME across both nodes, modeling \"behind one load balancer.\"" },
    { id: "hac-09", type: "scenario", question: "Riverside Health's patient-portal cluster puts two Keycloak nodes behind one load balancer with one public hostname, rather than exposing each node's own distinct address to clients. Why does that specific choice matter for session/token correctness, not just simplicity?", options: ["Purely for TLS certificate convenience", "So every node computes the same token issuer (iss claim) regardless of which node actually serves a given request, avoiding issuer-mismatch rejections on cross-node requests like a refresh-token grant", "Because Keycloak requires exactly one IP address per cluster by license", "To reduce the number of Docker containers needed"], answerIndex: 1, explanation: "Keycloak derives the issuer from the request's hostname by default. Without one shared public hostname, a token minted by one node and validated by another will mismatch on iss — exactly the bug this chapter's lab hit and documented, and exactly what Riverside Health's single-hostname load balancer avoids." },
    { id: "hac-10", type: "scenario", question: "Riverside Health's compliance team asks whether this chapter's two-container, one-Docker-host lab is adequate evidence that their clustered Keycloak deployment would survive losing an entire data center. What's the honest answer?", options: ["Yes, two containers clustering successfully is equivalent to surviving a data-center loss", "No — the lab proves cross-node session-cache replication logic works, but both \"nodes\" share one kernel, one Docker network, and one physical machine; it says nothing about real host failure, network partitions, or cross-data-center behavior, which chapter 44's multi-region content addresses separately", "No, because Keycloak cannot be clustered at all without Kubernetes", "Yes, as long as the Postgres container is also replicated"], answerIndex: 1, explanation: "This chapter is explicit about its own honest scope: it proves replication logic on one Docker host, not real multi-host failover or partition tolerance. Overstating that would misrepresent what was actually tested." },
    { id: "hac-11", type: "concept", question: "What does JGroups actually do in Keycloak's clustering architecture, as distinct from Infinispan?", options: ["JGroups stores the realm configuration permanently; Infinispan is only used for logging", "JGroups is the group-communication toolkit handling node discovery and message delivery between cluster members; Infinispan is the cache/data-grid layer built on top of it that actually stores and replicates Keycloak's in-memory data", "JGroups and Infinispan are two names for the exact same library", "JGroups only runs on Kubernetes; Infinispan only runs standalone"], answerIndex: 1, explanation: "Infinispan is the data-grid library Keycloak embeds for caching; JGroups is the lower-level toolkit Infinispan uses underneath for discovery and inter-node messaging — confirmed from the chapter's own log lines referencing both layers distinctly." },
    { id: "hac-12", type: "bug", question: "A fresh direct-grant login attempt in this chapter's lab failed with \"Account is not fully set up\" even though the test user had a password credential and an empty requiredActions array. What was the actual cause, and is it specific to clustering?", options: ["It was a clustering-specific bug unique to multi-node deployments", "The realm's VERIFY_PROFILE required action was dynamically resolving because the user's profile was missing attributes the Declarative User Profile expected — a general Keycloak gotcha unrelated to clustering, already hit independently in chapters 24 and 39", "The user's password had expired", "The two nodes had different realm configurations"], answerIndex: 1, explanation: "VERIFY_PROFILE can fire dynamically without appearing in a user's stored requiredActions list. It's a recurring, general Keycloak gotcha — this chapter is the third to document hitting it independently, and it has nothing to do with clustering." },
    { id: "hac-13", type: "scenario", question: "A Meridian Trust engineer wants to confirm their new two-node Keycloak cluster actually replicates sessions, and proposes just checking that the server logs show \"Received new cluster view\" with both node names listed. Is that sufficient proof?", options: ["Yes, a cluster view listing both nodes is definitive proof session replication works", "No — a cluster view only confirms the JGroups/Infinispan transport layer sees both members; it doesn't confirm application-level session data is actually usable cross-node. A decisive test needs an actual cross-node operation, like presenting one node's refresh token to the other", "No, cluster views are purely cosmetic and don't indicate anything real", "Yes, but only if the view updates within 5 seconds"], answerIndex: 1, explanation: "This chapter's own lab deliberately went further than checking the log line, because a healthy cluster view says nothing about whether application state actually replicates — it still had to run a real refresh-token grant against the other node to get decisive proof." },
    { id: "hac-14", type: "compare", question: "Compare: what does revoking a session through node B's Admin REST API, then checking node A's session listing, actually test that presenting node A's refresh token to node B does not?", options: ["Nothing different — they test the exact same thing", "The refresh-token test proves a read of replicated data on the node that didn't create it; the admin revoke-then-check test proves a write made through one node (B) is visible as absent on the other node (A) — confirming replication works bidirectionally, for both creates and deletes", "The admin test only works if both nodes use the same admin password", "The refresh-token test requires a load balancer; the admin test does not"], answerIndex: 1, explanation: "The chapter deliberately ran both: one proves cross-node read-after-create, the other proves cross-node read-after-delete made through the opposite node — together showing bidirectional replication, not just a single direction." },
    { id: "hac-15", type: "scenario", question: "Northwind Apps is deciding whether to run start-dev or start (production mode) for a staging environment that needs to behave like their real multi-node production cluster. Which mode's cache default actually matches production clustering behavior, and why does that matter for staging fidelity?", options: ["start-dev, because it is simpler to configure", "start (production mode), because its documented default cache is `ispn` (clustering enabled); start-dev defaults to `local`, which would make a staging environment silently never test cross-node session behavior at all", "Neither matters, since --cache is ignored in both modes", "start-dev, because it always clusters by default for safety"], answerIndex: 1, explanation: "start-dev's local default would make a staging environment that's supposed to catch cross-node bugs silently incapable of ever exercising clustering at all, unless --cache=ispn is explicitly passed — exactly the override this chapter's own lab had to make." },
    { id: "hac-16", type: "concept", question: "Why is JGroups traffic between Keycloak's embedded Infinispan nodes encrypted with mTLS by default on a TCP-based stack like jdbc-ping?", options: ["It isn't encrypted by default; encryption must be manually configured", "Keycloak's --cache-embedded-mtls-enabled option defaults to true for TCP-based stacks, and if no keystore/truststore is configured, Keycloak automatically generates and rotates ephemeral certificates — confirmed live in this chapter's lab boot log (\"JGroups Encryption enabled (mTLS)\") with zero extra configuration", "mTLS is only available with a paid Red Hat subscription", "It requires a separate certificate authority to be manually set up first"], answerIndex: 1, explanation: "This chapter's lab saw the mTLS log line appear unprompted, with no keystore/truststore configured at all — confirming the ephemeral, auto-rotating certificate behavior the --help-all text describes as the default." },
    { id: "hac-17", type: "scenario", question: "A Riverside Health engineer reads an older blog post recommending TCPPING with a manually maintained list of node IP addresses for Keycloak clustering, and wants to apply it to a fresh 26.8.2 deployment. What should they be told?", options: ["That's still the current recommended approach for 26.8.2", "That guidance describes a stack (tcp) Keycloak 26.8.2's own help text explicitly marks deprecated, in favor of jdbc-ping as the current non-Kubernetes default — a static host list is no longer how a modern deployment is expected to discover nodes", "TCPPING was never a real Keycloak feature", "TCPPING only works with Kubernetes, not Docker"], answerIndex: 1, explanation: "This chapter live-verified the deprecation directly from the running 26.8.2 image's own help text, rather than assuming older guidance still applies — exactly the discipline the brief called for." },
    { id: "hac-18", type: "concept", question: "What is the practical difference between an authentication/client session (chapter 29) and the embedded Infinispan `sessions` cache this chapter discusses?", options: ["They are unrelated systems with no connection", "The sessions cache (and its siblings like clientSessions) IS the in-memory storage mechanism that holds the session objects chapter 29 described conceptually — chapter 29 explained what a session is and how it behaves; this chapter explains the clustering technology that makes that session visible across more than one server process", "Sessions are stored in the database exclusively and never touch any cache", "The sessions cache only exists for offline sessions, not regular SSO sessions"], answerIndex: 1, explanation: "This chapter is explicitly the point where chapter 29's session concept and chapter 19's Infinispan preview meet: the sessions cache is the concrete mechanism underneath the session behavior chapter 29 already demonstrated on a single node." }
  ],

  "keycloak-on-kubernetes": [
    { id: "k8s-01", type: "concept", question: "In one sentence, what is the Kubernetes Operator pattern?", options: [
        "A controller plus one or more Custom Resource Definitions that continuously reconciles the real cluster toward whatever a custom resource currently declares as desired state",
        "A one-time script that applies a fixed set of YAML manifests and then exits",
        "A Helm chart's post-install hook that runs a smoke test",
        "A Kubernetes-native replacement for Docker Compose's networking layer only"
      ], answerIndex: 0, explanation: "An Operator is the generalized 'controller watching a CRD' pattern every built-in Kubernetes controller already uses, extended to an application-specific resource type — here, Keycloak." },
    { id: "k8s-02", type: "concept", question: "What does a Custom Resource Definition (CRD) actually register with Kubernetes?", options: [
        "A new resource type with the API server, so clients can create/read/update instances of it just like built-in types such as Pod or Service",
        "A scheduled cron job that runs arbitrary shell commands inside the cluster",
        "A new container image repository the cluster is allowed to pull from",
        "A firewall rule restricting which namespaces can talk to each other"
      ], answerIndex: 0, explanation: "The Keycloak Operator's kustomize install registers four CRDs: Keycloak, KeycloakRealmImport, KeycloakOIDCClient, and KeycloakSAMLClient, confirmed live in this chapter's lab output." },
    { id: "k8s-03", type: "compare", question: "As of this chapter's 2026-11-11 live-verification, how do the Keycloak Operator and the Bitnami Keycloak Helm chart actually compare?", options: [
        "The Operator is actively maintained and versioned per Keycloak release (26.8.2 used in this chapter); the Bitnami chart's free images moved to a legacy/paid repository around August 2025 and no longer receive free security updates",
        "They are functionally identical, differing only in YAML syntax",
        "The Bitnami chart is Keycloak's own official project, while the Operator is a third-party community tool",
        "Both were deprecated in favor of a single unified Keycloak CLI installer"
      ], answerIndex: 0, explanation: "This is a real, dated maturity gap this chapter's research turned up, not a style preference — see the chapter's live-verification table." },
    { id: "k8s-04", type: "compare", question: "What's the real trade-off between installing the Keycloak Operator via OLM versus plain kubectl + Kustomize?", options: [
        "OLM is the docs' own 'recommended' path but requires OLM already installed in-cluster and manages upgrades via Subscription/InstallPlan objects; plain kubectl + Kustomize needs no extra component and is equally official, which is why this chapter's kind lab used it",
        "OLM is unsupported and undocumented; only kubectl + Kustomize is officially sanctioned",
        "kubectl + Kustomize can only install a cluster-wide Operator, never namespace-scoped",
        "There is no difference — both commands install the exact same objects under the hood with identical YAML"
      ], answerIndex: 0, explanation: "Both paths are genuinely official. OLM adds real operational weight (it has to be running already) that a one-off teaching cluster has no reason to carry." },
    { id: "k8s-05", type: "scenario", question: "Northwind Apps is moving its growing SaaS platform from chapter 20's single-container Docker Compose Keycloak to a Kubernetes-based production deployment. What single Kubernetes object now plays the role docker-compose.yml used to play — 'the file that declares what should be running'?", options: [
        "The Keycloak custom resource (a YAML object of kind: Keycloak), reconciled by the Operator",
        "A raw Deployment manifest written by hand for the Keycloak container",
        "A ConfigMap containing the old docker-compose.yml verbatim",
        "The kubeconfig file used to authenticate kubectl"
      ], answerIndex: 0, explanation: "You declare desired state in the Keycloak CR; the Operator's reconciliation loop turns that into the actual StatefulSet, Services, and Secrets — the same shape as this chapter's example-kc.yaml, just at production scale." },
    { id: "k8s-06", type: "scenario", question: "Meridian Trust's platform team sets ingress.enabled: false on their pre-prod Keycloak CR, running on a cluster that, like this chapter's kind lab, has no Ingress controller installed. How should an engineer reach the admin console to test a config change?", options: [
        "kubectl port-forward service/<cr-name>-service <local-port>:8443 — the Operator docs' own documented way to reach a deployment for debugging/development",
        "There is no way to reach it without first installing an Ingress controller",
        "SSH into the node and curl localhost directly inside the container's network namespace",
        "Set the Service type to NodePort automatically — the Operator does this by default whenever Ingress is disabled"
      ], answerIndex: 0, explanation: "This is exactly what chapter 42's own lab did against example-kc-service, confirmed with real HTTP 200s and a real issued token." },
    { id: "k8s-07", type: "scenario", question: "Riverside Health's compliance reviewer notices the Operator-deployed Keycloak has no admin/admin-style login the way chapter 20's Docker Compose lab did, and asks if this is a bug. What's the actual, live-confirmed behavior?", options: [
        "Not a bug — the Operator creates a one-time temporary admin (confirmed live: username temp-admin) with a random password delivered only via a generated <cr-name>-initial-admin Secret, rather than a persistent bootstrap account from fixed env vars",
        "It is a bug; the Operator is simply missing the KC_BOOTSTRAP_ADMIN_USERNAME support Docker Compose has",
        "The admin account exists but is disabled by default and must be manually re-enabled via the REST API",
        "Operator-deployed Keycloak has no admin console at all — only the Admin REST API is available"
      ], answerIndex: 0, explanation: "Read directly from the pod's boot log and the generated Secret in this chapter's own lab — a deliberate difference from chapter 20, not a defect." },
    { id: "k8s-08", type: "bug", question: "A reader follows chapter 42's lab and, right after applying the Keycloak CR, sees the Keycloak pod stuck in CrashLoopBackOff, logs complaining it can't reach database host 'postgresql-db'. Inspecting example-postgres.yaml, what's the actual bug?", options: [
        "The StatefulSet is named postgresql-db, but the Service Keycloak actually connects to is named postgres-db — db.host in the Keycloak CR must match the Service name, not the StatefulSet name; a one-letter typo there causes exactly this failure",
        "PostgreSQL 15 is incompatible with Keycloak 26.8.2 and must be downgraded to 14",
        "The Keycloak CR is missing a required replicas field",
        "emptyDir volumes cannot be used by any pod that a StatefulSet manages"
      ], answerIndex: 0, explanation: "This is the official docs' own example's naming quirk, carried into labs/keycloak-on-kubernetes/example-postgres.yaml and called out explicitly in that lab's README." },
    { id: "k8s-09", type: "bug", question: "A reader reuses their host's already-pulled quay.io/keycloak/keycloak:26.8.2 image, expecting their kind cluster to skip downloading it. kubectl describe pod instead shows a fresh 'Pulling image' event taking over 20 seconds. Why?", options: [
        "kind's node runs its own containerd inside the node container, with its own image store separate from the host Docker engine's — host-side caching doesn't help unless the image is explicitly pre-loaded with kind load docker-image",
        "The image tag quay.io/keycloak/keycloak:26.8.2 was retagged by Keycloak upstream between the host pull and the kind pull",
        "kind always force-pulls every image regardless of any local cache, by hardcoded design with no way to avoid it",
        "The host's Docker daemon and kind's node share storage, so this behavior would indicate a corrupted image and should be reported as a bug"
      ], answerIndex: 0, explanation: "Confirmed directly in this chapter's own lab: `docker images` on the host was unaffected, but the operator/Keycloak/Postgres images were all pulled fresh inside the kind node." },
    { id: "k8s-10", type: "concept", question: "Why does this chapter's lab generate its own self-signed TLS certificate with openssl rather than leaving http.tlsSecret unset on the Keycloak CR?", options: [
        "The Operator wires HTTPS through a user-supplied certificate via http.tlsSecret, and the current docs don't document an automatic self-signed fallback — they themselves give the openssl snippet used here as their own documented 'for development purposes' shortcut",
        "Keycloak 26.8.2 cannot start at all without TLS configured, even in non-production clusters, for any reason",
        "Self-signed certificates are required by the CRD schema's validation webhook",
        "http.tlsSecret is deprecated in 26.8.2 in favor of a new http.devCert field"
      ], answerIndex: 0, explanation: "Taken directly from the Operator's own basic-deployment documentation, not invented for this lab." },
    { id: "k8s-11", type: "scenario", question: "Northwind Apps wants Keycloak to scale out horizontally to absorb traffic spikes during a product launch — something chapter 20's single-container Docker Compose setup can't do. What field on the Keycloak CR controls this, and what becomes load-bearing once it's increased?", options: [
        "spec.instances (set above 1); once there's more than one pod, Infinispan (chapter 41) must actually replicate session state across them for SSO to keep working no matter which pod a request lands on",
        "spec.replicaCount, which Kubernetes applies without any session-state implications",
        "spec.db.poolSize, which transparently handles multi-instance coordination on its own",
        "There is no such field; horizontal scaling requires a completely separate CR per instance"
      ], answerIndex: 0, explanation: "This is this chapter's direct callback to chapter 41's clustering material — scaling instances is trivial to declare, but it makes session replication a real concern, not a theoretical one." },
    { id: "k8s-12", type: "concept", question: "What does the 'Ready' condition on a Keycloak custom resource's status actually tell you, compared to what kubectl get pods tells you?", options: [
        "Ready: True is the Operator's own reconciliation-level judgment that the StatefulSet's desired state has been achieved; kubectl get pods shows raw pod/container readiness probe results — related signals, but not identical, and the CR's other conditions (HasErrors, RollingUpdate) carry Operator-specific detail pod status alone doesn't",
        "They are exactly the same signal, just exposed through two different commands",
        "Ready: True only means the container image was successfully pulled, nothing about the application inside it",
        "kubectl get pods is deprecated in favor of reading CR conditions exclusively as of Kubernetes 1.31"
      ], answerIndex: 0, explanation: "Confirmed in this chapter's own lab: the CR's go-template status output surfaced extra context (like the ServiceMonitor warning) that plain pod status wouldn't show." },
    { id: "k8s-13", type: "scenario", question: "Meridian Trust's security review flags this chapter's own lab for using grant_type=password against the master realm's admin-cli client to fetch a verification token. Is that a production anti-pattern, and why was it used here anyway?", options: [
        "Yes, the Resource Owner Password Credentials grant is discouraged for production browser/service clients (chapters 13-14); it was used here purely as the fastest way to prove a freshly Operator-deployed server issues real tokens during a throwaway teaching lab, not as a pattern to replicate in Meridian's own production client configuration",
        "No, the password grant is Keycloak's officially recommended grant for all Kubernetes-hosted deployments",
        "It's not a real concern because Kubernetes Secrets automatically rotate passwords used this way",
        "It's disallowed entirely on Operator-deployed Keycloak and the curl command in the chapter could not have actually worked"
      ], answerIndex: 0, explanation: "Grounded in chapters 13/14's own OAuth grant-type guidance, applied honestly to this chapter's own lab choices rather than pretending the shortcut has no trade-off." },
    { id: "k8s-14", type: "scenario", question: "Northwind Apps' new SRE applies a Keycloak CR for the first time and runs kubectl get all -n keycloak a minute later. Besides the generated initial-admin Secret, which kinds of objects, created and kept in sync by the Operator, should they expect to see pointing back to that one CR?", options: [
        "A StatefulSet (the Keycloak pod(s)) and one or more Services (ClusterIP, exposing the HTTPS and management ports) — plus an Ingress too, if ingress.enabled wasn't set to false",
        "A Deployment and a DaemonSet, since Keycloak always runs one pod per node",
        "Only a ConfigMap — the Operator defers all actual pod creation to a separate Helm release",
        "A CronJob that periodically restarts Keycloak on a fixed schedule"
      ], answerIndex: 0, explanation: "Confirmed directly in chapter 42's own lab: kubectl -n keycloak get svc showed example-kc-service and example-kc-discovery, and the pod was managed by a StatefulSet, not a Deployment." },
    { id: "k8s-15", type: "scenario", question: "Northwind Apps' platform team is choosing between the Operator's 'preview' Helm chart (oci://quay.io/keycloak/keycloak-operator-helm) and the namespace-scoped kubectl/kustomize install this chapter used, for a real staging cluster today (November 2026). What should drive the choice?", options: [
        "The Helm chart is explicitly labeled a preview/experimental, cluster-wide-only install by Keycloak's own current docs; the kubectl/kustomize path is the same official distribution with more operational maturity behind it as of this live-verification, so Northwind should prefer it for anything beyond quick experimentation",
        "Helm charts are always safer than kubectl/kustomize because Helm supports rollback natively",
        "There's no meaningful difference; both are equally mature per the current docs",
        "The kubectl/kustomize path is being deprecated in favor of the Helm chart as of 26.8.2"
      ], answerIndex: 0, explanation: "The Operator's own installation page states the Helm chart is 'an Experimental Operator Helm chart' — a real, current, documented caveat, not a guess." },
    { id: "k8s-16", type: "compare", question: "What's a genuine current limitation of installing the Keycloak Operator cluster-wide versus namespace-scoped?", options: [
        "A cluster-wide install supports only one Keycloak version per Operator instance and ignores spec.podTemplate.spec.serviceAccountName; namespace-scoped (this chapter's choice) has neither limitation, but only reconciles Keycloak CRs within its own namespace",
        "Cluster-wide installs cannot create Secrets, only namespace-scoped installs can",
        "Namespace-scoped installs cannot use PostgreSQL as a database backend",
        "There is no functional difference between the two beyond which namespace the Operator Deployment itself lives in"
      ], answerIndex: 0, explanation: "Directly from the Operator's own installation docs, which still label cluster-wide support as preview." },
    { id: "k8s-17", type: "scenario", question: "Riverside Health is deciding whether a HIPAA-relevant pre-prod cluster should install the Operator cluster-wide (one Operator reconciling every team's Keycloak CRs) or namespace-scoped per team. Given this chapter's live-verified limitations, what's the catch with cluster-wide for an org running mixed Keycloak versions across teams?", options: [
        "Cluster-wide supports only one Keycloak version per Operator instance, so a team mid-upgrade to a newer Keycloak release can't be served by the same cluster-wide Operator already pinned to an older version — namespace-scoped (or multiple separate Operator installs) is needed instead",
        "Cluster-wide installs are blocked entirely on any cluster with more than one namespace",
        "HIPAA compliance specifically forbids cluster-wide Kubernetes Operators by regulation",
        "There is no version constraint either way; this is purely a cost consideration"
      ], answerIndex: 0, explanation: "The 'one Keycloak version per Operator' constraint is a real, current limitation stated on the Operator's own cluster-wide installation docs." },
    { id: "k8s-18", type: "scenario", question: "Meridian Trust's SRE team runs batches of throwaway kind clusters in CI to test Keycloak realm-import changes. A runner starts failing mid-pipeline with disk pressure. Based on what this chapter's own lab actually hit, what's the single most effective, lowest-risk first move?", options: [
        "Run docker builder prune -af first — it reclaims build cache that nothing running depends on, unlike pruning images/volumes which risks breaking something still in use — and always kind delete cluster as soon as verification finishes rather than at the very end of a long pipeline",
        "Immediately run docker system prune -af --volumes without inspecting what's running, since speed matters more than safety in CI",
        "Increase the kind cluster's node count to spread disk usage across more containers",
        "Switch from postgres:15 to a larger database image, since smaller images paradoxically use more disk due to layer caching"
      ], answerIndex: 0, explanation: "This is exactly the real sequence this chapter's own lab followed: pruning build cache first (safe, high-yield) before touching anything else, then deleting the cluster promptly instead of waiting." }
  ]
};
